# ---------- Auth helpers ----------
JWT_ALG = "HS256"


def jwt_secret() -> str:
    return os.environ["JWT_SECRET"]


def hash_password(pw: str) -> str:
    return bcrypt.hashpw(pw.encode(), bcrypt.gensalt()).decode()


def verify_password(pw: str, hashed: str) -> bool:
    try:
        return bcrypt.checkpw(pw.encode(), hashed.encode())
    except Exception:
        return False


def create_access_token(user_id: str, email: str) -> str:
    payload = {
        "sub": user_id,
        "email": email,
        "type": "access",
        "exp": datetime.now(timezone.utc) + timedelta(hours=12),
    }
    return jwt.encode(payload, jwt_secret(), algorithm=JWT_ALG)


def _csrf_token() -> str:
    """One-time random token bound to a session. Kept in a non-httpOnly cookie
    so the SPA can read it and echo it back in the X-CSRF-Token header
    (double-submit cookie pattern)."""
    return secrets.token_urlsafe(32)


def set_auth_cookie(response: Response, token: str):
    """Set the httpOnly access-token cookie AND a paired CSRF token.

    SEC-002 hardening: SameSite is `lax` (not `none`) so browsers refuse to
    send the cookie on cross-site subrequests (blocks CSRF at the transport
    layer). A companion `csrf_token` cookie is set with the same lifetime;
    it is intentionally NOT httpOnly so the SPA can read it and set the
    `X-CSRF-Token` header on state-changing requests. The middleware then
    verifies header == cookie for every POST/PUT/PATCH/DELETE.
    """
    response.set_cookie(
        key="access_token",
        value=token,
        httponly=True,
        secure=True,
        samesite="lax",
        max_age=12 * 3600,
        path="/",
    )
    response.set_cookie(
        key="csrf_token",
        value=_csrf_token(),
        httponly=False,  # SPA reads it via document.cookie
        secure=True,
        samesite="lax",
        max_age=12 * 3600,
        path="/",
    )


async def get_current_user(request: Request) -> dict:
    token = request.cookies.get("access_token")
    if not token:
        auth = request.headers.get("Authorization", "")
        if auth.startswith("Bearer "):
            token = auth[7:]
    if not token:
        raise HTTPException(status_code=401, detail="Not authenticated")
    try:
        payload = jwt.decode(token, jwt_secret(), algorithms=[JWT_ALG])
    except jwt.ExpiredSignatureError:
        raise HTTPException(status_code=401, detail="Token expired")
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail="Invalid token")
    user = await db.users.find_one({"id": payload["sub"]}, {"_id": 0, "password_hash": 0})
    if not user:
        raise HTTPException(status_code=401, detail="User not found")
    return user


def require_role(*roles: str):
    """Role gate with backward-compat aliases:
      * `admin` and `super_admin` are treated as the SAME internal role — so
        every legacy `require_role("admin")` invocation transparently accepts
        the renamed `super_admin` too.
      * When a caller wants to allow the new tenant-scoped Company Admin they
        must pass "company_admin" explicitly.
    """
    allowed = set(roles)
    if "admin" in allowed or "super_admin" in allowed:
        allowed.update({"admin", "super_admin"})
    async def dep(user: dict = Depends(get_current_user)):
        if user.get("role") not in allowed:
            raise HTTPException(status_code=403, detail="Forbidden")
        return user
    return dep


