# -------- Staff CRUD --------
def _center_scope_q(user: dict) -> dict:
    """Return Mongo center-scope filter for center_manager/center_staff roles.
    Returns empty dict (no restriction) for admin and other privileged roles."""
    role = user.get("role")
    if role in ("center_manager", "center_staff"):
        return {"center_id": {"$in": user.get("assigned_center_ids") or []}}
    return {}


@api.get("/staff", response_model=List[StaffOut])
async def list_staff(
    q: Optional[str] = None,
    skip: int = 0,
    limit: int = 1000,
    include_inactive: bool = True,
    include_today_status: bool = True,  # Phase 33 — attach today's attendance
    user=Depends(get_current_user),
):
    """List staff. Supports ?q=<search>, ?skip=, ?limit=, ?include_today_status=false.
    Response includes header `X-Total-Count` for pagination UIs.
    When include_today_status=true (default), each row carries a `today_status`
    field valued "present" | "absent" | "half" | "leave" | null so the HR UI
    can render color-coded chips (green/red/blue/yellow) without a second call.
    """
    query: dict = {}
    # Phase 65 — strict center-based data isolation. Head-level users
    # (admin/senior_manager) see everyone; scoped roles see only staff at
    # their assigned centers. Users with no mapping → empty list.
    scope = _center_scope_query(user, field="center_id")
    if scope.get("_never_"):
        from starlette.responses import JSONResponse
        return JSONResponse(content=[], headers={"X-Total-Count": "0",
            "Access-Control-Expose-Headers": "X-Total-Count"})
    if scope:
        query.update(scope)
    if not include_inactive:
        query["active"] = {"$ne": False}
    if q:
        needle = q.strip()
        if needle:
            rx = {"$regex": needle, "$options": "i"}
            query["$or"] = [
                {"name": rx},
                {"employee_code": rx},
                {"designation": rx},
                {"email": rx},
                {"mobile": rx},
            ]
    total = await db.staff.count_documents(query)
    cursor = db.staff.find(query, {"_id": 0}).sort("name", 1)
    if skip:
        cursor = cursor.skip(skip)
    if limit:
        cursor = cursor.limit(min(limit, 2000))
    docs = await cursor.to_list(min(limit or 2000, 2000))
    # Phase 33 — Bulk-join today's attendance status so the HR list can render
    # color chips without a per-row API roundtrip.
    if include_today_status and docs:
        try:
            today_ist = (datetime.now(timezone.utc) + timedelta(hours=5, minutes=30)).date().isoformat()
        except Exception:
            today_ist = datetime.now(timezone.utc).date().isoformat()
        sids = [d["id"] for d in docs]
        att_rows = await db.attendance.find(
            {"staff_id": {"$in": sids}, "date": today_ist},
            {"_id": 0, "staff_id": 1, "status": 1},
        ).to_list(3000)
        att_map = {r["staff_id"]: r.get("status") for r in att_rows}
        for d in docs:
            d["today_status"] = att_map.get(d["id"])
    from fastapi import Response
    # Emit total via response header so pagination UIs don't need a second call.
    # Return the plain list body (matches historical response_model).
    Response  # keep import used
    from starlette.responses import JSONResponse
    return JSONResponse(
        content=[StaffOut(**d).model_dump() for d in docs],
        headers={"X-Total-Count": str(total), "Access-Control-Expose-Headers": "X-Total-Count"},
    )


async def _next_employee_code() -> str:
    """Allocate a fresh Employee Code — format `EMP-YYYY-NNNN`.

    Scans existing codes for the current calendar year and returns the next
    4-digit sequence. Safe under concurrent adds because the caller inserts
    the doc immediately after — the unique index on `staff.employee_code`
    guarantees no duplicates (the loop retries on the rare collision race).
    """
    year = datetime.now(timezone.utc).year
    prefix = f"EMP-{year}-"
    latest = await db.staff.find_one(
        {"employee_code": {"$regex": f"^{prefix}\\d+$"}},
        {"_id": 0, "employee_code": 1},
        sort=[("employee_code", -1)],
    )
    next_seq = 1
    if latest and latest.get("employee_code"):
        try:
            next_seq = int(latest["employee_code"].split("-")[-1]) + 1
        except (ValueError, IndexError):
            next_seq = 1
    return f"{prefix}{next_seq:04d}"


@api.post("/staff/backfill-employee-codes")
async def backfill_employee_codes(dry_run: bool = True, user=Depends(require_role("admin", "hr"))):
    """Backfill missing/blank `employee_code` values on existing staff rows.

    Format assigned: `EMP-YYYY-NNNN`. Idempotent: rows that already have a code
    are skipped. `dry_run=true` (default) reports the count without writing.
    """
    q = {"$or": [{"employee_code": {"$exists": False}}, {"employee_code": None}, {"employee_code": ""}]}
    rows = await db.staff.find(q, {"_id": 0, "id": 1, "name": 1}).to_list(5000)
    assigned = []
    if not dry_run:
        # Allocate sequentially inside a single call to avoid burning through
        # multiple aggregation queries.
        for r in rows:
            code = await _next_employee_code()
            await db.staff.update_one({"id": r["id"]}, {"$set": {"employee_code": code}})
            assigned.append({"id": r["id"], "name": r.get("name"), "employee_code": code})
    return {"scanned": len(rows), "assigned": len(assigned), "dry_run": dry_run, "samples": assigned[:25]}


@api.get("/staff/template.csv")
async def staff_import_template(_=Depends(require_role("admin", "hr"))):
    """Return an EMPTY CSV template with the correct headers for bulk staff import.
    Users download this to see the exact column names + order expected by /staff/import.
    """
    headers = ["name", "designation", "email", "mobile", "salary", "center_id", "employee_code"]
    example = ["Ram Kumar", "Trainer", "ram@example.com", "9999900001", "15000", "", ""]
    csv_text = ",".join(headers) + "\n" + ",".join(example) + "\n"
    return Response(
        content=csv_text,
        media_type="text/csv",
        headers={"Content-Disposition": 'attachment; filename="staff_bulk_template.csv"'},
    )


@api.get("/staff/export.csv")
async def staff_export_csv(user=Depends(get_current_user)):
    """Export ALL staff (respecting role scoping) as a CSV matching the /staff/import format
    so an admin can round-trip: export → edit in Excel → re-import. Includes bank fields too."""
    import csv, io
    role = user.get("role")
    query: dict = {}
    if role in ("center_manager", "center_staff"):
        query["center_id"] = {"$in": user.get("assigned_center_ids") or []}
    docs = await db.staff.find(query, {"_id": 0}).sort("name", 1).to_list(5000)
    buf = io.StringIO()
    w = csv.writer(buf)
    w.writerow([
        "employee_code", "name", "designation", "email", "mobile",
        "salary", "per_day_rate", "center_id", "active",
        "bank_name", "bank_account_no", "ifsc", "bank_verified",
        "joining_date", "created_at",
    ])
    for d in docs:
        w.writerow([
            d.get("employee_code") or "",
            d.get("name") or "",
            d.get("designation") or "",
            d.get("email") or "",
            d.get("mobile") or "",
            d.get("monthly_salary") or 0,
            d.get("per_day_rate") or 0,
            d.get("center_id") or "",
            "yes" if d.get("active", True) else "no",
            d.get("bank_name") or "",
            d.get("bank_account_no") or "",
            d.get("ifsc") or "",
            "yes" if d.get("bank_verified") else "no",
            d.get("joining_date") or "",
            (d.get("created_at") or "")[:19],
        ])
    return Response(
        content=buf.getvalue(),
        media_type="text/csv",
        headers={
            "Content-Disposition": f'attachment; filename="staff_export_{datetime.now(timezone.utc).date().isoformat()}.csv"',
            "X-Row-Count": str(len(docs)),
        },
    )


@api.post("/staff/import")
async def import_staff(file: UploadFile = File(...), user=Depends(require_role("admin", "hr"))):
    """Bulk-add staff from a CSV. Headers (case-insensitive):
    `name` (required), `designation`, `email`, `mobile`, `salary`, `center_id`, `employee_code` (optional).

    - Rows without a name are skipped.
    - `employee_code` blanks auto-allocate via `_next_employee_code()`.
    - Duplicates (same employee_code OR same email if provided) are skipped with
      a per-row reason returned. Returns `{ created, skipped, errors[] }`.
    """
    import csv, io
    raw = await file.read()
    try:
        text = raw.decode("utf-8-sig")
    except UnicodeDecodeError:
        text = raw.decode("latin-1")
    reader = csv.DictReader(io.StringIO(text))
    if not reader.fieldnames:
        raise HTTPException(400, "CSV must include a header row")
    # Normalise headers to lowercase
    reader.fieldnames = [h.strip().lower() for h in reader.fieldnames]
    created, skipped = 0, 0
    errors = []
    now = datetime.now(timezone.utc).isoformat()
    for idx, row in enumerate(reader, start=2):  # start=2 accounts for header
        row = {(k or "").strip().lower(): (v or "").strip() for k, v in row.items()}
        name = row.get("name")
        if not name:
            errors.append({"row": idx, "reason": "missing name"})
            skipped += 1
            continue
        emp_code = row.get("employee_code") or await _next_employee_code()
        email_lc = (row.get("email") or "").lower() or None
        # Duplicate check
        clash_q: list = []
        clash_q.append({"employee_code": emp_code})
        if email_lc:
            clash_q.append({"email": email_lc})
        if await db.staff.find_one({"$or": clash_q}, {"_id": 0, "id": 1}):
            errors.append({"row": idx, "reason": f"duplicate (employee_code={emp_code} / email={email_lc})"})
            skipped += 1
            continue
        try:
            salary = float(row.get("salary") or 0)
        except ValueError:
            salary = 0.0
        doc = {
            "id": str(uuid.uuid4()),
            "name": name,
            "designation": row.get("designation") or None,
            "email": email_lc,
            "mobile": row.get("mobile") or None,
            "employee_code": emp_code,
            "monthly_salary": salary,
            "center_id": row.get("center_id") or None,
            "active": True,
            "created_at": now,
            "created_by": user["id"],
        }
        try:
            await db.staff.insert_one(doc)
            created += 1
        except Exception as e:
            errors.append({"row": idx, "reason": str(e)[:200]})
            skipped += 1
    return {"created": created, "skipped": skipped, "errors": errors[:50]}


@api.post("/staff")
async def create_staff(body: StaffIn, user=Depends(require_role("admin", "manager", "hr"))):
    doc = body.model_dump()
    # Auto-generate a unique Employee Code if the admin didn't set one.
    if not (doc.get("employee_code") or "").strip():
        doc["employee_code"] = await _next_employee_code()
    # Only admin can assign the reports_to chain (approval hierarchy)
    if user.get("role") != "admin":
        doc["reports_to_id"] = None
    # --- Optional auto-provisioning a user login + credentials email ---
    create_login = bool(doc.pop("create_login", False))
    send_creds = bool(doc.pop("send_credentials_email", True))
    send_offer = bool(doc.pop("send_offer_letter", True))
    # Normalise contact fields (KEEP them on staff doc; do not pop)
    login_email = (doc.get("email") or "").strip().lower() or None
    mobile = (doc.get("mobile") or "").strip() or None
    doc["email"] = login_email
    doc["mobile"] = mobile
    email_result = None
    generated_password: Optional[str] = None
    if create_login:
        if not login_email:
            raise HTTPException(400, "email is required when create_login=true")
        # Idempotent: if a user with this email already exists, link to that user.
        existing_user = await db.users.find_one({"email": login_email}, {"_id": 0})
        if existing_user:
            doc["user_id"] = existing_user["id"]
        else:
            from email_utils import generate_password, send_credentials_email
            new_password = generate_password(12)
            generated_password = new_password
            user_doc = {
                "id": str(uuid.uuid4()),
                "name": doc.get("name") or login_email,
                "email": login_email,
                "password_hash": hash_password(new_password),
                "role": "center_staff",  # default lowest write-capable role for new staff
                "mobile": mobile or None,
                "assigned_center_ids": [doc["center_id"]] if doc.get("center_id") else [],
                "assigned_partner_id": None,
                "created_at": datetime.now(timezone.utc).isoformat(),
            }
            await db.users.insert_one(user_doc)
            doc["user_id"] = user_doc["id"]
            if send_creds:
                public_url = os.environ.get("PUBLIC_APP_URL", "").rstrip("/")
                if not public_url:
                    logger.warning("PUBLIC_APP_URL not set — staff credential email check-in link will be empty")
                check_in_url = (public_url + "/check-in") if public_url else "/check-in"
                email_result = await send_credentials_email(
                    to_email=login_email, name=user_doc["name"], password=new_password, check_in_url=check_in_url,
                )
    if mobile and doc.get("user_id"):
        # Best-effort: store mobile on the linked user record too
        await db.users.update_one({"id": doc["user_id"]}, {"$set": {"mobile": mobile}})
    doc["id"] = str(uuid.uuid4())
    doc["created_at"] = datetime.now(timezone.utc).isoformat()
    await db.staff.insert_one(doc)
    # Offer-letter generation (fire-and-log; never blocks staff creation).
    offer_letter_result = None
    if send_offer and login_email:
        try:
            offer_letter_result = await _generate_and_deliver_offer_letter(
                staff=doc, login_email=login_email, login_password=generated_password,
            )
        except Exception as e:
            logger.exception("Offer letter generation error for staff %s", doc.get("id"))
            offer_letter_result = {"generated": False, "emailed": False, "reason": str(e)[:200]}
        # Reload the staff doc so the response carries the offer_letter_* fields
        refreshed = await db.staff.find_one({"id": doc["id"]}, {"_id": 0})
        if refreshed:
            doc = refreshed
    out = StaffOut(**{k: v for k, v in doc.items() if k in StaffOut.model_fields}).model_dump()
    if email_result is not None:
        out["email_status"] = email_result
    if offer_letter_result is not None:
        out["offer_letter_status"] = offer_letter_result
    return out


@api.put("/staff/{sid}", response_model=StaffOut)
async def update_staff(sid: str, body: StaffIn, user=Depends(require_role("admin", "manager", "hr"))):
    update = body.model_dump()
    # Strip transient login-only fields — never persist them as columns
    update.pop("create_login", None)
    update.pop("send_credentials_email", None)
    # Immutable fields — edit dialog must NEVER change these. If the caller wants to
    # (re)generate a login use `/staff/{sid}/generate-login`; if they need to correct
    # an employee_code, run the backfill endpoint. Silently dropping them here means
    # a partial payload from the frontend can't accidentally null-out these columns
    # (the previous behaviour wiped employee_code on every Edit → Save).
    update.pop("employee_code", None)
    update.pop("user_id", None)
    if user.get("role") != "admin":
        # Preserve existing reports_to_id; only admin may change it
        existing = await db.staff.find_one({"id": sid}, {"_id": 0, "reports_to_id": 1})
        update["reports_to_id"] = (existing or {}).get("reports_to_id")
    # Auto-unverify bank if any bank field changed
    prev = await db.staff.find_one({"id": sid}, {"_id": 0, "bank_account_no": 1, "ifsc": 1, "bank_name": 1, "account_holder_name": 1, "bank_verified": 1})
    if prev and prev.get("bank_verified"):
        bank_changed = any(
            (prev.get(k) or "") != (update.get(k) or "")
            for k in ("bank_account_no", "ifsc", "bank_name", "account_holder_name")
        )
        if bank_changed:
            update["bank_verified"] = False
            update["bank_verified_at"] = None
            update["bank_verified_by"] = None
    # Don't let the client itself flip bank_verified — only the dedicated endpoint may
    if prev and not prev.get("bank_verified"):
        update["bank_verified"] = False
        update["bank_verified_at"] = None
        update["bank_verified_by"] = None
    res = await db.staff.find_one_and_update(
        {"id": sid}, {"$set": update}, return_document=True
    )
    if not res:
        raise HTTPException(404, "Not found")
    res.pop("_id", None)
    # Best-effort: keep linked user's mobile in sync
    if update.get("mobile") and res.get("user_id"):
        await db.users.update_one({"id": res["user_id"]}, {"$set": {"mobile": update["mobile"]}})
    return StaffOut(**res)


@api.delete("/staff/{sid}")
async def delete_staff(sid: str, _=Depends(require_role("admin", "hr"))):
    r = await db.staff.delete_one({"id": sid})
    if r.deleted_count == 0:
        raise HTTPException(404, "Not found")
    return {"ok": True}


@api.post("/staff/{sid}/verify-bank")
async def verify_staff_bank(sid: str, user=Depends(require_role("admin", "hr"))):
    """HR/Admin marks a staff's bank details as verified after manual check."""
    s = await db.staff.find_one({"id": sid}, {"_id": 0, "bank_account_no": 1, "ifsc": 1, "user_id": 1, "name": 1})
    if not s:
        raise HTTPException(404, "Staff not found")
    if not s.get("bank_account_no") or not s.get("ifsc"):
        raise HTTPException(400, "Bank account number and IFSC required before verification")
    now = datetime.now(timezone.utc).isoformat()
    await db.staff.update_one({"id": sid}, {"$set": {
        "bank_verified": True, "bank_verified_at": now, "bank_verified_by": user["id"],
    }})
    # Notify the staff their bank details were approved.
    if s.get("user_id"):
        await _notify(
            s["user_id"], f"Your bank details have been approved by HR.",
            ntype="bank_verified", ref_id=sid, link="/me/profile",
        )
    return {"ok": True, "verified_at": now}


@api.post("/staff/{sid}/generate-login")
async def generate_staff_login(
    sid: str,
    user=Depends(require_role("admin", "hr")),
    send_email: bool = True,
    force_reset: bool = False,
):
    """Phase 35 — Create (or reset) the login account for an existing staff row
    and email the credentials via Resend.

    - Idempotent: if the staff already has a linked user account and `force_reset=false`,
      the existing user is returned; use `force_reset=true` to rotate the password.
    - Requires the staff to have an `email` on the row.
    - Assigns role `center_staff` by default; admin can promote later.
    """
    from email_utils import generate_password, send_credentials_email
    staff = await db.staff.find_one({"id": sid}, {"_id": 0})
    if not staff:
        raise HTTPException(404, "Staff not found")
    login_email = (staff.get("email") or "").strip().lower()
    if not login_email:
        raise HTTPException(400, "Staff has no email — please add one first")

    existing_user = await db.users.find_one({"email": login_email}, {"_id": 0})
    generated_password: Optional[str] = None
    if existing_user and not force_reset:
        # Link only — no new password
        if not staff.get("user_id"):
            await db.staff.update_one({"id": sid}, {"$set": {"user_id": existing_user["id"]}})
        already_linked_msg = "Existing account linked; no new password generated. Pass force_reset=true to rotate."
        return {"ok": True, "user_id": existing_user["id"], "linked": True, "password_rotated": False, "email_sent": False, "note": already_linked_msg}

    new_password = generate_password(12)
    generated_password = new_password
    now = datetime.now(timezone.utc).isoformat()
    if existing_user and force_reset:
        # Rotate password on the existing user record
        await db.users.update_one(
            {"id": existing_user["id"]},
            {"$set": {"password_hash": hash_password(new_password), "password_reset_at": now}},
        )
        user_id = existing_user["id"]
        if not staff.get("user_id"):
            await db.staff.update_one({"id": sid}, {"$set": {"user_id": user_id}})
    else:
        user_doc = {
            "id": str(uuid.uuid4()),
            "name": staff.get("name") or login_email,
            "email": login_email,
            "password_hash": hash_password(new_password),
            "role": "center_staff",
            "mobile": staff.get("mobile"),
            "assigned_center_ids": [staff.get("center_id")] if staff.get("center_id") else [],
            "assigned_partner_id": None,
            "created_at": now,
        }
        await db.users.insert_one(user_doc)
        user_id = user_doc["id"]
        await db.staff.update_one({"id": sid}, {"$set": {"user_id": user_id}})

    email_sent = False
    email_reason = None
    if send_email:
        try:
            public_url = os.environ.get("PUBLIC_APP_URL", "").rstrip("/")
            check_in_url = (public_url + "/check-in") if public_url else "/check-in"
            r = await send_credentials_email(
                to_email=login_email, name=staff.get("name") or login_email,
                password=new_password, check_in_url=check_in_url,
            )
            email_sent = bool((r or {}).get("sent"))
            email_reason = (r or {}).get("reason")
        except Exception as e:
            logger.exception("Failed to send credentials email for staff %s", sid)
            email_reason = str(e)[:200]
    return {
        "ok": True,
        "user_id": user_id,
        "linked": bool(existing_user),
        "password_rotated": bool(existing_user and force_reset),
        "email_sent": email_sent,
        "email_reason": email_reason,
        # Only echo the password back if email failed AND caller is admin — HR can copy it manually.
        "password": (new_password if (not email_sent and user.get("role") == "admin") else None),
    }


@api.get("/me/staff-profile")
async def get_my_staff_profile(user=Depends(get_current_user)):
    """Return the calling user's linked staff row (for the self-service "My Profile" page).

    Phase 37 — if no staff record is linked (e.g. admins, partners), return a
    lightweight stub built from the user record so the profile page still
    renders instead of showing an error.
    """
    s = await db.staff.find_one({"user_id": user["id"]}, {"_id": 0})
    if s:
        return s
    # Fallback stub — same shape so the frontend doesn't need to branch.
    return {
        "id": None,
        "user_id": user["id"],
        "name": user.get("name") or user.get("email"),
        "email": user.get("email"),
        "mobile": user.get("mobile"),
        "designation": {"admin": "Administrator", "hr": "HR Manager", "manager": "Manager",
                        "senior_manager": "Senior Manager", "accountant": "Accountant",
                        "partner": "Partner", "center_manager": "Center Manager",
                        "center_staff": "Center Staff"}.get(user.get("role"), user.get("role")),
        "employee_code": None,
        "photo_url": user.get("photo_url"),
        "bank_name": user.get("bank_name"),
        "bank_account_no": user.get("bank_account_no"),
        "ifsc": user.get("ifsc"),
        "account_holder_name": user.get("account_holder_name"),
        "upi_id": user.get("upi_id"),
        "bank_verified": bool(user.get("bank_verified")),
        "is_user_only": True,   # marker so UI can show a friendly hint
    }


class SelfStaffProfileIn(BaseModel):
    """Self-service fields a staff member can edit for their own profile.
    Explicitly EXCLUDES role/salary/center — those are HR-only.
    """
    model_config = ConfigDict(extra="ignore")
    mobile: Optional[str] = None
    address: Optional[str] = None
    photo_url: Optional[str] = None
    bank_name: Optional[str] = None
    bank_account_no: Optional[str] = None
    ifsc: Optional[str] = None
    account_holder_name: Optional[str] = None
    upi_id: Optional[str] = None


@api.put("/me/staff-profile")
async def update_my_staff_profile(body: SelfStaffProfileIn, user=Depends(get_current_user)):
    """Staff self-fill: update mobile/address/photo AND submit bank details for HR approval.

    Any bank field change automatically **unverifies** the bank so HR must re-approve
    via `/staff/{sid}/verify-bank`. This lets staff fix typos without needing HR to
    manually reset the flag.

    Phase 37 — if the user is NOT linked to a staff record (admin/partner), the
    fields are stored on the `users` collection instead so profile page still works.
    """
    update = {k: v for k, v in body.model_dump().items() if v is not None}
    s = await db.staff.find_one({"user_id": user["id"]}, {"_id": 0})

    # Sync mobile onto the linked user record so login lookups stay consistent.
    if update.get("mobile"):
        await db.users.update_one({"id": user["id"]}, {"$set": {"mobile": update["mobile"]}})

    if not s:
        # No linked staff — persist to user row and return a stub.
        await db.users.update_one({"id": user["id"]}, {"$set": update})
        u = await db.users.find_one({"id": user["id"]}, {"_id": 0, "password_hash": 0})
        return {**(u or {}), "is_user_only": True}

    bank_fields = {"bank_name", "bank_account_no", "ifsc", "account_holder_name"}
    bank_changed = any(k in update and (update[k] or "") != (s.get(k) or "") for k in bank_fields)
    if bank_changed:
        update["bank_verified"] = False
        update["bank_verified_at"] = None
        update["bank_verified_by"] = None
        update["bank_submitted_at"] = datetime.now(timezone.utc).isoformat()
    res = await db.staff.find_one_and_update({"id": s["id"]}, {"$set": update}, return_document=True)
    if not res:
        raise HTTPException(500, "Update failed")
    res.pop("_id", None)
    # Ping HR when bank details submitted / changed so they can approve.
    if bank_changed:
        hr_users = await db.users.find(
            {"role": {"$in": ["admin", "hr"]}}, {"_id": 0, "id": 1},
        ).to_list(100)
        for hr in hr_users:
            await _notify(
                hr["id"],
                f"{s.get('name', 'A staff member')} has submitted bank details for approval.",
                ntype="bank_submitted", ref_id=s["id"], link="/hrms",
            )
    return res


@api.post("/me/staff-profile/photo")
async def upload_my_profile_photo(file: UploadFile = File(...), user=Depends(get_current_user)):
    """Staff self-upload their profile photo. Stores in object storage and updates `photo_url` on the staff row (or user row if not linked)."""
    s = await db.staff.find_one({"user_id": user["id"]}, {"_id": 0, "id": 1, "name": 1})
    raw = await file.read()
    if len(raw) > 3 * 1024 * 1024:
        raise HTTPException(400, "Photo must be under 3 MB")
    if not (file.content_type or "").startswith("image/"):
        raise HTTPException(400, "File must be an image")
    ext = (file.filename or "photo.jpg").split(".")[-1][:5].lower() or "jpg"
    subject_id = (s or {}).get("id") or f"user-{user['id']}"
    key = f"staff-photos/{subject_id}.{ext}"
    try:
        _put_object(key, raw, content_type=file.content_type or "image/jpeg")
    except Exception as e:
        logger.exception("photo upload failed")
        raise HTTPException(502, f"Storage upload failed: {e}")
    _pou = globals().get("_public_object_url")
    url = _pou(key) if callable(_pou) else f"/api/objects/{key}"
    if s:
        await db.staff.update_one({"id": s["id"]}, {"$set": {"photo_url": url, "photo_key": key}})
    else:
        await db.users.update_one({"id": user["id"]}, {"$set": {"photo_url": url, "photo_key": key}})
    return {"ok": True, "photo_url": url}


