# -------- Attendance --------
@api.post("/attendance")
async def mark_attendance(body: AttendanceIn, user=Depends(require_role("admin", "manager", "center_manager", "hr"))):
    """Admin/HR path to create or edit an attendance row for a staff.
    - `center_staff` are intentionally NOT allowed here — they must use
      `/attendance/self` (geofenced + selfie required). Previously, center_staff
      could call this endpoint and pass any `staff_id`, `marked_via`, and
      bypass geofence — a serious spoofing hole (see Phase 30B).
    - `center_manager` is scoped to staff of their assigned centers only.
    - `marked_via` is ALWAYS forced to "admin" server-side — client cannot spoof.
    """
    doc = body.model_dump(exclude_none=True)
    if not doc.get("staff_id"):
        raise HTTPException(400, "staff_id is required")
    if not doc.get("date"):
        raise HTTPException(400, "date is required")
    # Scope check for center_manager — cannot mark for staff outside their centers.
    if user.get("role") == "center_manager":
        allowed_centers = set(user.get("assigned_center_ids") or [])
        staff_row = await db.staff.find_one({"id": doc["staff_id"]}, {"_id": 0, "center_id": 1})
        if not staff_row:
            raise HTTPException(404, "Staff not found")
        if staff_row.get("center_id") not in allowed_centers:
            raise HTTPException(403, "You can only mark attendance for staff at your assigned centers")
    if not doc.get("marked_at"):
        doc["marked_at"] = datetime.now(timezone.utc).isoformat()
    # PHASE 37 — reject absent/half on weekly-off + holiday dates so a mistake
    # can't create a bogus salary deduction on a paid non-working day.
    if doc.get("status") in ("absent", "half", "unpaid_leave"):
        d = doc["date"]
        paid_offs, wo_days = await _paid_off_dates_in(d, d)
        if d in paid_offs:
            raise HTTPException(400, "Cannot mark absent/half on a Holiday. It's a paid day.")
        try:
            wname = datetime.strptime(d, "%Y-%m-%d").strftime("%A").lower()
        except Exception:
            wname = ""
        if wname in wo_days:
            raise HTTPException(400, "Cannot mark absent/half on a Weekly Off. It's a paid day.")
    # Force server-authoritative source — no client-side spoofing of "self".
    doc["marked_via"] = "admin"
    doc["marked_by"] = user["id"]
    doc["marked_by_name"] = user.get("name")
    new_id = str(uuid.uuid4())
    await db.attendance.update_one(
        {"staff_id": doc["staff_id"], "date": doc["date"]},
        {"$set": doc, "$setOnInsert": {"id": new_id}},
        upsert=True,
    )
    return {"ok": True}


class AttendanceEditIn(BaseModel):
    """HR/Admin can retro-edit an existing attendance row. All fields optional."""
    model_config = ConfigDict(extra="ignore")
    status: Optional[Literal["present", "absent", "half", "leave"]] = None
    check_in_at: Optional[str] = None    # ISO ts
    check_out_at: Optional[str] = None   # ISO ts
    remarks: Optional[str] = None


@api.patch("/attendance/{aid}")
async def edit_attendance(aid: str, body: AttendanceEditIn, user=Depends(require_role("admin", "hr", "manager", "center_manager"))):
    """HR / Admin retro-edit of an attendance row.
    Records who edited and when in `edited_by` / `edited_at` for audit.
    """
    row = await db.attendance.find_one({"id": aid}, {"_id": 0})
    if not row:
        raise HTTPException(404, "Attendance row not found")
    # Scope: center_manager can only edit rows for staff at their assigned centers.
    if user.get("role") == "center_manager":
        allowed_centers = set(user.get("assigned_center_ids") or [])
        staff_row = await db.staff.find_one({"id": row.get("staff_id")}, {"_id": 0, "center_id": 1})
        if not staff_row or staff_row.get("center_id") not in allowed_centers:
            raise HTTPException(403, "You can only edit attendance for staff at your assigned centers")
    update = body.model_dump(exclude_none=True)
    if not update:
        return row
    update["edited_by"] = user["id"]
    update["edited_by_name"] = user.get("name")
    update["edited_at"] = datetime.now(timezone.utc).isoformat()
    await db.attendance.update_one({"id": aid}, {"$set": update})
    return await db.attendance.find_one({"id": aid}, {"_id": 0})


async def _shift_end_iso_for(staff: dict, date_str: str) -> str:
    """UTC ISO for the shift-end (or HR day-end fallback) on `date_str` in IST.
    Used as the auto-checkout timestamp for stale (forgot-to-punch-out) rows."""
    end_hhmm = None
    if staff and staff.get("shift_id"):
        sh = await db.shifts.find_one({"id": staff["shift_id"]}, {"_id": 0, "end_time": 1})
        if sh and sh.get("end_time"):
            end_hhmm = sh["end_time"]
    if not end_hhmm:
        pol = await db.hr_policy.find_one({"id": "singleton"}, {"_id": 0, "day_end_time": 1})
        end_hhmm = (pol or {}).get("day_end_time") or "18:00"
    try:
        h, m = (int(x) for x in str(end_hhmm).split(":")[:2])
        y, mo, d = (int(x) for x in date_str.split("-")[:3])
        ist_dt = datetime(y, mo, d, h, m, tzinfo=BUSINESS_TZ)
        return ist_dt.astimezone(timezone.utc).isoformat()
    except (ValueError, AttributeError):
        return datetime.now(timezone.utc).isoformat()


async def _auto_close_stale_attendance(staff: dict) -> int:
    """Finalize any open attendance rows from PREVIOUS IST dates as AUTO_CLOSED so
    a forgotten checkout never carries into the next day. Idempotent; safe to call
    on every attendance read (dashboard/status/check-in/checkout/history).
    Never touches regularised / admin / leave / half rows (authoritative)."""
    if not staff or not staff.get("id"):
        return 0
    today = _today_ist()
    stale = await db.attendance.find(
        {
            "staff_id": staff["id"],
            "date": {"$lt": today},
            "check_in_at": {"$exists": True, "$ne": None},
            "check_out_at": {"$in": [None, ""]},
            "regularised": {"$ne": True},
            "status": {"$nin": ["leave", "half", "auto_closed"]},
            "marked_via": {"$nin": ["regularised", "admin"]},
        },
        {"_id": 0, "id": 1, "date": 1},
    ).to_list(400)
    now_iso = datetime.now(timezone.utc).isoformat()
    for r in stale:
        co = await _shift_end_iso_for(staff, r["date"])
        await db.attendance.update_one(
            {"id": r["id"]},
            {"$set": {
                "status": "auto_closed",
                "check_out_at": co,
                "check_out_via": "auto",
                "auto_closed_at": now_iso,
                "auto_close_note": "Automatically closed because checkout was not completed.",
            }},
        )
    return len(stale)



@api.post("/attendance/self")
async def self_check_in(body: SelfCheckInIn, user=Depends(get_current_user)):
    """Mobile self-check-in: looks up the staff record linked to the current user,
    then upserts today's attendance with location + selfie metadata.
    Enforces geofence if any active fence is configured for the staff's center.
    """
    staff = await db.staff.find_one({"user_id": user["id"]}, {"_id": 0, "id": 1, "name": 1, "center_id": 1, "shift_id": 1})
    if not staff:
        raise HTTPException(400, "Your user is not linked to any staff record. Ask admin to set it up.")
    # Enforce geofence if configured for the staff's center (or global fences exist)
    body_dict = body.model_dump(exclude_none=True)
    lat = body_dict.get("latitude")
    lng = body_dict.get("longitude")
    nearest_dist_m = None
    if lat is not None and lng is not None:
        fence_q: dict = {"active": True}
        if staff.get("center_id"):
            fence_q["$or"] = [{"center_id": staff["center_id"]}, {"center_id": None}]
        fences = await db.geofences.find(fence_q, {"_id": 0}).to_list(50)
        if fences:
            from math import radians, sin, cos, sqrt, atan2
            def _haversine_m(a_lat, a_lng, b_lat, b_lng):
                R = 6_371_000.0
                p1, p2 = radians(a_lat), radians(b_lat)
                dphi = radians(b_lat - a_lat)
                dlam = radians(b_lng - a_lng)
                a = sin(dphi / 2) ** 2 + cos(p1) * cos(p2) * sin(dlam / 2) ** 2
                return 2 * R * atan2(sqrt(a), sqrt(1 - a))
            inside = False
            nearest_name = None
            nearest_dist = None
            nearest_radius = 200.0
            for f in fences:
                d = _haversine_m(lat, lng, f["latitude"], f["longitude"])
                if nearest_dist is None or d < nearest_dist:
                    nearest_dist = d
                    nearest_name = f.get("name")
                    nearest_radius = float(f.get("radius_m", 200))
                if d <= float(f.get("radius_m", 200)):
                    inside = True
                    break
            if not inside:
                # Return structured error so frontend can render "You are Xm away" with a Refresh button.
                raise HTTPException(400, {
                    "code": "outside_geofence",
                    "distance_m": round(nearest_dist or 0, 1),
                    "radius_m": nearest_radius,
                    "site_name": nearest_name or "office",
                    "message": f"You are {round(nearest_dist or 0, 1)}m away from {nearest_name or 'office'}. Please move closer and try again.",
                })
            nearest_dist_m = round(nearest_dist or 0, 1)
    today = (body.date or _today_ist())[:10]
    now_iso = datetime.now(timezone.utc).isoformat()
    # Close any previous-day open rows as AUTO_CLOSED so today starts fresh.
    await _auto_close_stale_attendance(staff)
    doc = {
        "staff_id": staff["id"],
        "date": today,
        "marked_via": "self",
        "marked_at": now_iso,
        "marked_by": user["id"],
        "check_in_at": now_iso,
    }
    for k in ("status", "latitude", "longitude", "accuracy", "address", "selfie_path", "selfie_filename"):
        if k in body_dict:
            doc[k] = body_dict[k]
    if nearest_dist_m is not None:
        doc["office_distance_m"] = nearest_dist_m
    # Compute is_late based on staff's shift start_time + grace_minutes (IST)
    is_late = False
    if staff.get("shift_id"):
        _sh = await db.shifts.find_one({"id": staff["shift_id"]}, {"_id": 0, "start_time": 1, "grace_minutes": 1})
        if _sh and _sh.get("start_time"):
            try:
                _sh_h, _sh_m = (int(x) for x in _sh["start_time"].split(":"))
                _grace = int(_sh.get("grace_minutes") or 0)
                _now_ist = datetime.now(timezone.utc).astimezone(BUSINESS_TZ)
                _ci_min = _now_ist.hour * 60 + _now_ist.minute
                if _ci_min > (_sh_h * 60 + _sh_m + _grace):
                    is_late = True
            except (ValueError, AttributeError):
                pass
    doc["is_late"] = is_late
    new_id = str(uuid.uuid4())
    await db.attendance.update_one(
        {"staff_id": staff["id"], "date": today},
        {"$set": doc, "$setOnInsert": {"id": new_id}},
        upsert=True,
    )
    return {"ok": True, "staff_id": staff["id"], "staff_name": staff.get("name"), "date": today, "marked_at": now_iso}


@api.post("/attendance/checkout")
async def self_check_out(body: CheckOutIn, user=Depends(get_current_user)):
    """Mobile check-out: staff clocks out for the day. Records location + optional selfie.
    Today's attendance row must already exist (i.e. staff checked in first)."""
    staff = await db.staff.find_one({"user_id": user["id"]}, {"_id": 0, "id": 1})
    if not staff:
        raise HTTPException(400, "Your user is not linked to any staff record.")
    await _auto_close_stale_attendance(staff)
    today = _today_ist()
    row = await db.attendance.find_one({"staff_id": staff["id"], "date": today}, {"_id": 0})
    if not row:
        raise HTTPException(400, "Please check in first before checking out.")
    if row.get("check_out_at"):
        raise HTTPException(400, "You have already checked out today.")
    now_iso = datetime.now(timezone.utc).isoformat()
    update = {"check_out_at": now_iso}
    body_dict = body.model_dump(exclude_none=True)
    for k, target in (("latitude", "check_out_latitude"), ("longitude", "check_out_longitude"),
                      ("accuracy", "check_out_accuracy"), ("address", "check_out_address"),
                      ("selfie_path", "check_out_selfie_path"),
                      ("selfie_filename", "check_out_selfie_filename")):
        if k in body_dict:
            update[target] = body_dict[k]
    await db.attendance.update_one(
        {"staff_id": staff["id"], "date": today},
        {"$set": update},
    )
    return {"ok": True, "check_out_at": now_iso}


@api.get("/attendance/my")
async def my_attendance(
    start: Optional[str] = None,
    end: Optional[str] = None,
    user=Depends(get_current_user),
):
    """Current logged-in staff's own attendance history."""
    staff = await db.staff.find_one({"user_id": user["id"]}, {"_id": 0, "id": 1, "shift_id": 1})
    if not staff:
        return []
    await _auto_close_stale_attendance(staff)
    q: dict = {"staff_id": staff["id"]}
    if start or end:
        q["date"] = {}
        if start:
            q["date"]["$gte"] = start
        if end:
            q["date"]["$lte"] = end
    docs = await db.attendance.find(q, {"_id": 0}).sort("date", -1).to_list(500)
    return docs


@api.get("/attendance/today")
async def my_today_attendance(user=Depends(get_current_user)):
    """Return today's attendance row for the current logged-in user (if any)."""
    staff = await db.staff.find_one({"user_id": user["id"]}, {"_id": 0, "id": 1, "name": 1, "shift_id": 1})
    if not staff:
        return {"staff": None, "attendance": None}
    await _auto_close_stale_attendance(staff)
    today = _today_ist()
    row = await db.attendance.find_one({"staff_id": staff["id"], "date": today}, {"_id": 0})
    return {"staff": staff, "attendance": row}


_WEEKDAY_NAMES = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]


@api.get("/attendance/my-monthly")
async def my_attendance_monthly(
    month: int = Query(..., ge=1, le=12),
    year: int = Query(..., ge=2020, le=2100),
    user=Depends(get_current_user),
):
    """Full monthly attendance calendar for the logged-in staff.
    Returns per-day status merged with:
      - attendance rows (present / absent / half / leave / late flag)
      - approved leaves (paid vs unpaid based on leave_type.paid)
      - holidays (name)
      - weekly off (from HR policy `weekly_off_days`, default Sunday)
    Also returns `summary` with counts (Present / Absent / Half / Paid Leave / Week Off).
    """
    staff = await db.staff.find_one({"user_id": user["id"]}, {"_id": 0, "id": 1})
    if not staff:
        return {"days": {}, "summary": {"present": 0, "absent": 0, "half": 0, "paid_leave": 0, "week_off": 0}, "month": month, "year": year, "weekly_off_days": ["sunday"]}
    import calendar as _cal
    last_day = _cal.monthrange(year, month)[1]
    month_start = f"{year:04d}-{month:02d}-01"
    month_end = f"{year:04d}-{month:02d}-{last_day:02d}"
    today_ist = _today_ist()
    # Weekly off policy
    pol = await db.hr_policy.find_one({"id": "singleton"}, {"_id": 0, "weekly_off_days": 1})
    weekly_off_names = [str(d).lower() for d in ((pol or {}).get("weekly_off_days") or ["sunday"])]
    weekly_off_weekday_idx = {_WEEKDAY_NAMES.index(w) for w in weekly_off_names if w in _WEEKDAY_NAMES}
    # Attendance rows
    att_rows = await db.attendance.find(
        {"staff_id": staff["id"], "date": {"$gte": month_start, "$lte": month_end}},
        {"_id": 0},
    ).to_list(400)
    att_by_date = {r["date"]: r for r in att_rows}
    # Approved leaves overlapping the month
    leave_rows = await db.leaves.find(
        {
            "staff_id": staff["id"],
            "status": "approved",
            "start_date": {"$lte": month_end},
            "end_date": {"$gte": month_start},
        },
        {"_id": 0},
    ).to_list(200)
    leave_types = {t["id"]: t for t in await db.leave_types.find({}, {"_id": 0, "id": 1, "paid": 1, "name": 1, "code": 1}).to_list(50)}

    def _is_paid_leave(row):
        lt = leave_types.get(row.get("leave_type_id"))
        # Default to paid=True if not resolvable (matches attendance policy)
        return bool(lt.get("paid", True)) if lt else True

    leaves_by_date = {}
    for lv in leave_rows:
        try:
            ls = datetime.fromisoformat(lv["start_date"]).date()
            le = datetime.fromisoformat(lv["end_date"]).date()
        except (ValueError, KeyError):
            continue
        cur = ls
        while cur <= le:
            iso = cur.isoformat()
            if month_start <= iso <= month_end:
                leaves_by_date[iso] = {"paid": _is_paid_leave(lv), "leave_type_id": lv.get("leave_type_id"), "reason": lv.get("reason")}
            cur = cur + timedelta(days=1)
    # Holidays
    hol_rows = await db.holidays.find(
        {"date": {"$gte": month_start, "$lte": month_end}}, {"_id": 0, "date": 1, "name": 1, "type": 1},
    ).to_list(60)
    holidays_by_date = {h["date"]: h for h in hol_rows}
    # Compose per-day payload
    days = {}
    counts = {"present": 0, "absent": 0, "half": 0, "paid_leave": 0, "week_off": 0}
    for d in range(1, last_day + 1):
        iso = f"{year:04d}-{month:02d}-{d:02d}"
        dt = datetime(year, month, d)
        wd = dt.weekday()  # 0=Mon
        is_future = iso > today_ist
        row = att_by_date.get(iso)
        leave = leaves_by_date.get(iso)
        holiday = holidays_by_date.get(iso)
        is_week_off = wd in weekly_off_weekday_idx
        # Priority: attendance row > approved leave > holiday > week_off > absent/future
        status = None
        is_late = False
        details = {}
        if row:
            st = row.get("status")
            if st in ("present", "auto_closed", "incomplete") and row.get("check_in_at"):
                status = "present"  # attended (even if checkout was auto-closed) → show present on calendar
            else:
                status = st or ("present" if row.get("check_in_at") else "absent")
            is_late = bool(row.get("is_late"))
            details = {
                "check_in_at": row.get("check_in_at") or row.get("marked_at"),
                "check_out_at": row.get("check_out_at"),
                "latitude": row.get("latitude"),
                "longitude": row.get("longitude"),
                "address": row.get("address"),
                "office_distance_m": row.get("office_distance_m"),
                "selfie_path": row.get("selfie_path"),
                "attendance_id": row.get("id"),
            }
        elif leave:
            status = "paid_leave" if leave["paid"] else "leave"
        elif holiday:
            status = "holiday"
        elif is_week_off:
            status = "week_off"
        elif is_future:
            status = "future"
        else:
            status = "absent"
        # Count summary (holiday counted under week_off bucket per screenshot semantics — visually
        # they render like a rest day. Users can adjust later if they want separate holidays).
        if status == "present":
            counts["present"] += 1
        elif status == "absent":
            counts["absent"] += 1
        elif status == "half":
            counts["half"] += 1
        elif status == "paid_leave":
            counts["paid_leave"] += 1
        elif status in ("week_off", "holiday"):
            counts["week_off"] += 1
        days[iso] = {
            "date": iso,
            "day_of_month": d,
            "weekday": _WEEKDAY_NAMES[wd],
            "status": status,
            "is_late": is_late,
            "is_today": iso == today_ist,
            "is_future": is_future,
            "holiday_name": (holiday or {}).get("name"),
            **details,
        }
    return {
        "month": month,
        "year": year,
        "days": days,
        "summary": counts,
        "weekly_off_days": weekly_off_names,
        "total_days": last_day,
    }


@api.get("/attendance")
async def list_attendance(
    staff_id: Optional[str] = None,
    start: Optional[str] = None,
    end: Optional[str] = None,
    user=Depends(get_current_user),
):
    q: dict = {}
    # Phase 65 — center-based scoping via staff_id lookup. Head-level users
    # (admin/senior_manager) see all attendance; scoped roles see only rows
    # for staff at their assigned centers. Self-view (a staff user querying
    # their own attendance via `?staff_id=self`) is preserved.
    allowed = _scoped_center_ids(user)
    if allowed is not None:
        if not allowed:
            return []
        allowed_staff = await db.staff.find(
            {"center_id": {"$in": allowed}}, {"_id": 0, "id": 1},
        ).to_list(10000)
        scoped_ids = {s["id"] for s in allowed_staff}
        if staff_id:
            if staff_id not in scoped_ids:
                raise HTTPException(403, "Not authorised to view this staff's attendance")
        else:
            q["staff_id"] = {"$in": list(scoped_ids)}
    if staff_id:
        q["staff_id"] = staff_id
    if start or end:
        rng: dict = {}
        if start:
            rng["$gte"] = start
        if end:
            rng["$lte"] = end
        q["date"] = rng
    docs = await db.attendance.find(q, {"_id": 0}).sort("date", -1).to_list(5000)
    # Attach `effective_status` so the UI can show "Incomplete" when a staff
    # only punched in but never punched out — instead of misleading "Present".
    for d in docs:
        s = d.get("status")
        if s in ("incomplete", "auto_closed"):
            d["effective_status"] = s
        elif s == "present" and d.get("check_in_at") and not d.get("check_out_at"):
            d["effective_status"] = "incomplete"
        elif s == "present" and d.get("check_in_at") and d.get("check_out_at"):
            d["effective_status"] = "present"
        else:
            d["effective_status"] = s or "absent"
    return docs


@api.get("/attendance/paid-off-days")
async def attendance_paid_off_days(
    start: str, end: str, _=Depends(get_current_user),
):
    """Phase 37 — return the paid-off calendar for a date window.
    Response: `{ weekly_off_weekdays: ["sunday"], paid_off_dates: ["2026-08-15", ...] }`.
    Used by the Attendance UI to auto-set the status chip to "Weekly Off" /
    "Holiday" and to disable the dropdown so those days can't be marked absent.
    """
    paid_offs, weekly_off = await _paid_off_dates_in(start, end)
    return {
        "weekly_off_weekdays": sorted(weekly_off),
        "paid_off_dates": sorted(paid_offs),
    }


# -------- Leaves --------
@api.post("/leaves")
async def apply_leave(body: LeaveIn, user=Depends(get_current_user)):
    doc = body.model_dump()
    doc["id"] = str(uuid.uuid4())
    doc["status"] = "pending"
    doc["created_by"] = user["id"]
    doc["created_at"] = datetime.now(timezone.utc).isoformat()
    # Enrich with the staff's center_id so center-bound approval chains route correctly.
    # Without this, a chain bound to (say) Center-A would be skipped because the leave
    # doc has no center_id of its own.
    staff_doc = await db.staff.find_one({"id": doc["staff_id"]}, {"_id": 0, "center_id": 1, "name": 1})
    if staff_doc:
        doc["center_id"] = staff_doc.get("center_id")
        doc["staff_name"] = staff_doc.get("name")
    await _attach_chain_to_request("leave", doc)
    await db.leaves.insert_one(doc)
    doc.pop("_id", None)
    # Notify L1 approver
    if doc.get("chain_snapshot"):
        first = next((s for s in doc["chain_snapshot"] if s.get("level") == 1), None)
        if first:
            for uid in await _resolve_step_user_ids(first, doc):
                if uid and uid != user["id"]:
                    await _notify(uid, "New leave request awaiting your approval",
                                  ntype="leave_pending", ref_id=doc["id"], link="/hrms")
    return doc


@api.get("/leaves")
async def list_leaves(
    staff_id: Optional[str] = None,
    status: Optional[str] = None,
    user=Depends(get_current_user),
):
    q: dict = {}
    # Phase 65 — center-scoped: only leaves by staff at the user's centers.
    allowed = _scoped_center_ids(user)
    if allowed is not None:
        if not allowed:
            return []
        allowed_staff = await db.staff.find(
            {"center_id": {"$in": allowed}}, {"_id": 0, "id": 1},
        ).to_list(10000)
        scoped_ids = {s["id"] for s in allowed_staff}
        if staff_id:
            if staff_id not in scoped_ids:
                raise HTTPException(403, "Not authorised to view this staff's leaves")
        else:
            q["staff_id"] = {"$in": list(scoped_ids)}
    if staff_id:
        q["staff_id"] = staff_id
    if status:
        q["status"] = status
    docs = await db.leaves.find(q, {"_id": 0}).sort("created_at", -1).to_list(2000)
    for d in docs:
        await _enrich_with_approval_status(d)
    return docs


@api.patch("/leaves/{lid}")
async def decide_leave(lid: str, decision: str = Query(..., pattern="^(approved|rejected)$"),
                       remarks: str = Query(..., min_length=3, description="Mandatory note (min 3 chars)"),
                       user=Depends(require_role("admin", "manager", "center_manager", "hr", "senior_manager"))):
    now = datetime.now(timezone.utc).isoformat()
    res = await db.leaves.find_one_and_update(
        {"id": lid},
        {"$set": {"status": decision, "decided_by": user["id"], "decided_at": now, "decision_remarks": remarks}},
        return_document=True,
    )
    if not res:
        raise HTTPException(404, "Not found")
    res.pop("_id", None)
    return res


# ============================================================================
# Approval Chain Engine — generic configurable multi-level workflows
# ============================================================================
#
# Chains live in `approval_chains` collection. Each request (reimbursement /
# leave / transaction) that uses a chain stores:
#   - chain_id          : reference
#   - current_level     : 1..N while pending, 0 once final-approved, -1 if rejected
#   - chain_history     : list of {level, action, by_user_id, by_user_name, at, remarks}
#   - chain_snapshot    : snapshot of steps at submit-time so later config edits don't break in-flight items
#
# Endpoints exposed:
#   GET    /api/approval-chains
#   POST   /api/approval-chains          (admin, hr)
#   PUT    /api/approval-chains/{id}     (admin, hr)
#   DELETE /api/approval-chains/{id}     (admin, hr)
#   POST   /api/approvals/act            (any user; checked against current step's resolved approvers)
# ============================================================================


