async def _seed_default_chains():
    """Idempotent: ensure at least one active default chain exists per request type."""
    for default in DEFAULT_CHAINS:
        existing = await db.approval_chains.find_one({"type": default["type"], "active": True}, {"_id": 0})
        if existing:
            continue
        doc = {
            **default,
            "id": str(uuid.uuid4()),
            "created_at": datetime.now(timezone.utc).isoformat(),
            "created_by": None,
        }
        await db.approval_chains.insert_one(doc)


async def _find_active_chain(req_type: str, center_id: Optional[str] = None) -> Optional[dict]:
    """Find the most-specific active chain for this request type.
    - Look for an active chain that lists `center_id` in `center_ids` (new
      multi-center schema) OR has `center_id == center_id` (legacy single-center
      docs kept for backward compatibility).
    - Fall back to an active chain with no center scope (global default).
    """
    if center_id:
        specific = await db.approval_chains.find_one(
            {
                "type": req_type, "active": True,
                "$or": [
                    {"center_ids": center_id},
                    {"center_id": center_id},
                ],
            },
            {"_id": 0},
        )
        if specific:
            return specific
    return await db.approval_chains.find_one(
        {
            "type": req_type, "active": True,
            "$and": [
                {"$or": [{"center_id": None}, {"center_id": {"$exists": False}}]},
                {"$or": [{"center_ids": {"$size": 0}}, {"center_ids": {"$exists": False}}]},
            ],
        },
        {"_id": 0},
    )


async def _resolve_reports_to_user_ids(submitter_user_id: str, depth: int) -> List[str]:
    """Walk the reports_to chain `depth` steps up from the submitter's staff record.
    Returns the linked user_id of the resolved staff (list with 0 or 1 entry)."""
    staff = await db.staff.find_one({"user_id": submitter_user_id}, {"_id": 0})
    if not staff:
        return []
    current = staff
    for _ in range(depth):
        boss_id = current.get("reports_to_id")
        if not boss_id:
            return []
        current = await db.staff.find_one({"id": boss_id}, {"_id": 0})
        if not current:
            return []
    target_user_id = current.get("user_id")
    return [target_user_id] if target_user_id else []


async def _resolve_step_user_ids(step: dict, request_doc: dict) -> List[str]:
    """Return list of user_ids who are eligible to act on this step for this request."""
    kind = step.get("kind")
    value = step.get("value", "")
    if kind == "role":
        q: dict = {"role": value}
        # Center-isolation: partner / center_partner / center_manager / center_staff
        # approvers must be MAPPED to the request's center via User Management
        # (assigned_center_ids). Without this, EVERY user of that role in the
        # system would receive every request — leaking unrelated centers'
        # workflow. Other roles (admin, hr, accountant, senior_manager, …)
        # remain GLOBAL by design.
        if value in ("partner", "center_partner", "center_manager", "center_staff"):
            cid = request_doc.get("center_id")
            if cid:
                q["assigned_center_ids"] = cid
            else:
                # No center on the request → fall back to global (admin-only scenarios).
                pass
        users = await db.users.find(q, {"_id": 0, "id": 1}).to_list(2000)
        return [u["id"] for u in users]
    if kind == "user":
        return [value] if value else []
    if kind == "staff":
        if not value:
            return []
        s = await db.staff.find_one({"id": value}, {"_id": 0, "user_id": 1, "email": 1})
        if not s:
            return []
        # Primary: linked user_id stored on the staff record
        if s.get("user_id"):
            return [s["user_id"]]
        # Fallback: resolve via staff.email → users.email (case-insensitive). Many staff are
        # added without an explicit login linkage; if their email matches a registered user
        # we still want approvals to route to that user instead of silently dead-ending.
        if s.get("email"):
            u = await db.users.find_one(
                {"email": {"$regex": f"^{re.escape(s['email'])}$", "$options": "i"}},
                {"_id": 0, "id": 1},
            )
            if u:
                # Self-heal: persist the linkage so future lookups are cheap.
                await db.staff.update_one({"id": value}, {"$set": {"user_id": u["id"]}})
                return [u["id"]]
        return []
    if kind == "reports_to":
        try:
            depth = max(1, int(value or "1"))
        except (ValueError, TypeError):
            depth = 1
        submitter_id = request_doc.get("created_by")
        if not submitter_id:
            return []
        return await _resolve_reports_to_user_ids(submitter_id, depth)
    return []


async def _attach_chain_to_request(req_type: str, request_doc: dict) -> dict:
    """Look up active chain, snapshot it onto the request_doc, set current_level=1.
    Mutates and returns the same doc. If no chain is configured, leaves doc unchanged.

    Center-scoping: if the request_doc has a center_id, prefer a chain bound to that
    center over the global default. Used so each center can have its own approvers."""
    chain = await _find_active_chain(req_type, center_id=request_doc.get("center_id"))
    if not chain or not chain.get("steps"):
        request_doc["chain_id"] = None
        request_doc["current_level"] = None
        request_doc["chain_snapshot"] = []
        request_doc["chain_history"] = []
        return request_doc
    steps = sorted(chain["steps"], key=lambda s: s.get("level", 0))
    request_doc["chain_id"] = chain["id"]
    request_doc["current_level"] = 1
    request_doc["chain_snapshot"] = _json_safe(steps)
    request_doc["chain_history"] = []
    return request_doc


async def _resolve_pending_approvers(request_doc: dict) -> List[dict]:
    """Return the list of users who can act on the CURRENT step of the request.
    Each entry: {id, name, email, role}. Used for creator-visible tracking so
    they can see whose approval is holding up their submission."""
    if request_doc.get("status") not in ("pending", "in_progress", "payment_pending", "pending_approval"):
        return []
    step = await _current_step(request_doc)
    if not step:
        return []
    uids = await _resolve_step_user_ids(step, request_doc)
    if not uids:
        return []
    users = await db.users.find(
        {"id": {"$in": uids}}, {"_id": 0, "id": 1, "name": 1, "email": 1, "role": 1},
    ).to_list(200)
    return users


async def _enrich_with_approval_status(doc: dict) -> dict:
    """Attach `pending_with` (list of approvers), `current_step_label`, and
    `total_steps` fields to a request doc so the creator's UI can show
    'Currently pending with: Rakesh Kumar (Senior Manager)'."""
    if not doc:
        return doc
    # Sanitise any residual ObjectId that may have snuck into legacy docs
    # (particularly nested inside chain_snapshot) so this doc is safe to return.
    if "chain_snapshot" in doc:
        doc["chain_snapshot"] = _json_safe(doc.get("chain_snapshot") or [])
    if "chain_history" in doc:
        doc["chain_history"] = _json_safe(doc.get("chain_history") or [])
    step = await _current_step(doc)
    doc["current_step_label"] = (step or {}).get("label") if step else None
    doc["current_step_kind"] = (step or {}).get("kind") if step else None
    doc["current_step_value"] = (step or {}).get("value") if step else None
    doc["total_steps"] = len(doc.get("chain_snapshot") or [])
    doc["pending_with"] = await _resolve_pending_approvers(doc)
    return doc


async def _current_step(request_doc: dict) -> Optional[dict]:
    snap = request_doc.get("chain_snapshot") or []
    cur = request_doc.get("current_level")
    if not snap or not cur or cur < 1:
        return None
    for s in snap:
        if s.get("level") == cur:
            return s
    return None


async def _user_can_act_on_request(user: dict, request_doc: dict) -> bool:
    # Admin bypass: admin can always act on any pending step
    if user.get("role") == "admin":
        return True
    step = await _current_step(request_doc)
    if not step:
        return False
    eligible = await _resolve_step_user_ids(step, request_doc)
    return user["id"] in eligible


def _history_entry(level: int, action: str, user: dict, remarks: str = "") -> dict:
    return {
        "level": level,
        "action": action,
        "by_user_id": user["id"],
        "by_user_name": user.get("name") or user.get("email"),
        "at": datetime.now(timezone.utc).isoformat(),
        "remarks": remarks or "",
    }


def _approval_link(req_type: str) -> str:
    """Frontend route to open for a given approval request type's notifications."""
    return {
        "transaction":       "/transactions",
        "leave":             "/hrms",
        "reimbursement":     "/hrms",
        "asset_purchase":    "/assets",
        "employee_transfer": "/employee-transfers",
        "regularisation":    "/pending-approvals",
        "quotation":         "/quotations",
        "payment":           "/quotations",
        "advance_request":   "/advances",
        "advance_settlement":"/advances",
    }.get(req_type, "/pending-approvals")


def _count_leave_days(start_date: str, end_date: str) -> float:
    """Inclusive day-count between two YYYY-MM-DD strings. Returns 1 if either parse fails."""
    try:
        s = datetime.fromisoformat(start_date)
        e = datetime.fromisoformat(end_date)
        days = (e.date() - s.date()).days + 1
        return float(max(1, days))
    except (ValueError, TypeError):
        return 1.0


async def _deduct_leave_balance_on_approve(leave_rec: dict) -> None:
    """If the leave request links a leave_type_id and the staff has a balance row for the
    leave's year, increment used + recompute balance. Silently no-ops if no balance row
    is configured (some staff may not have allocations)."""
    lt_id = leave_rec.get("leave_type_id")
    staff_id = leave_rec.get("staff_id")
    start = leave_rec.get("start_date") or ""
    if not (lt_id and staff_id and start):
        return
    try:
        year = int(start[:4])
    except (ValueError, TypeError):
        return
    days = _count_leave_days(start, leave_rec.get("end_date") or start)
    bal = await db.leave_balances.find_one(
        {"staff_id": staff_id, "leave_type_id": lt_id, "year": year}, {"_id": 0},
    )
    if not bal:
        return
    used = (bal.get("used", 0) or 0) + days
    allocated = bal.get("allocated", 0) or 0
    await db.leave_balances.update_one(
        {"id": bal["id"]},
        {"$set": {
            "used": used,
            "balance": max(0, allocated - used),
            "updated_at": datetime.now(timezone.utc).isoformat(),
        }},
    )


# -------- Approval Chain CRUD --------
async def _validate_chain_steps(steps: list) -> None:
    """Validate step values resolve to a real approver. Raise 400 with a helpful message
    if a non-optional step is misconfigured (so admins don't silently dead-end approvals)."""
    for s in steps:
        kind = s.get("kind")
        value = (s.get("value") or "").strip()
        lvl = s.get("level")
        if s.get("optional"):
            continue
        if kind in ("role", "user", "staff") and not value:
            raise HTTPException(400, f"Level {lvl}: please choose a {kind} for the approver")
        if kind == "staff" and value:
            st = await db.staff.find_one({"id": value}, {"_id": 0, "user_id": 1, "email": 1, "name": 1})
            if not st:
                raise HTTPException(400, f"Level {lvl}: selected staff no longer exists")
            if not st.get("user_id"):
                # Try email-based linkage so admins don't have to provision a login first.
                if st.get("email"):
                    u = await db.users.find_one(
                        {"email": {"$regex": f"^{re.escape(st['email'])}$", "$options": "i"}},
                        {"_id": 0, "id": 1},
                    )
                    if u:
                        await db.staff.update_one({"id": value}, {"$set": {"user_id": u["id"]}})
                        continue
                raise HTTPException(
                    400,
                    f"Level {lvl}: staff '{st.get('name')}' has no linked login account. "
                    "Open Users → Add user with their email so approvals can route to them.",
                )
        if kind == "user" and value:
            u = await db.users.find_one({"id": value}, {"_id": 0, "id": 1})
            if not u:
                raise HTTPException(400, f"Level {lvl}: selected user no longer exists")


@api.get("/approval-chains", response_model=List[ApprovalChainOut])
async def list_approval_chains(_=Depends(get_current_user)):
    docs = await db.approval_chains.find({}, {"_id": 0}).sort([("type", 1), ("created_at", 1)]).to_list(200)
    return docs


@api.post("/approval-chains", response_model=ApprovalChainOut)
async def create_approval_chain(body: ApprovalChainIn, user=Depends(require_role("admin", "hr"))):
    doc = body.model_dump()
    if not doc["steps"]:
        raise HTTPException(400, "At least one approval step is required")
    # Normalise step levels: re-index 1..N to avoid duplicates/gaps
    sorted_steps = sorted(doc["steps"], key=lambda s: s.get("level", 0))
    for i, s in enumerate(sorted_steps, 1):
        s["level"] = i
    doc["steps"] = sorted_steps
    # Per-step value validation: 'staff' / 'user' / 'role' MUST have a non-empty value,
    # otherwise the chain silently dead-ends at that level and the request never reaches an approver.
    await _validate_chain_steps(sorted_steps)
    # Normalise center scope: merge legacy `center_id` into `center_ids` list,
    # dedupe, and clear the legacy field so downstream lookups only need to
    # inspect one shape.
    _cids = list(doc.get("center_ids") or [])
    if doc.get("center_id") and doc["center_id"] not in _cids:
        _cids.append(doc["center_id"])
    doc["center_ids"] = _cids
    doc["center_id"] = None  # legacy field cleared once merged
    # If activated, deactivate other active chains of the same type whose center
    # scope overlaps — that way each center still resolves to exactly ONE chain.
    if doc.get("active"):
        overlap_filter: dict = {"type": doc["type"], "active": True}
        if _cids:
            overlap_filter["$or"] = [
                {"center_ids": {"$in": _cids}},
                {"center_id": {"$in": _cids}},
            ]
        else:
            # A global (no-center) chain replaces any other active global chain.
            overlap_filter["$and"] = [
                {"$or": [{"center_ids": {"$size": 0}}, {"center_ids": {"$exists": False}}]},
                {"$or": [{"center_id": None}, {"center_id": {"$exists": False}}]},
            ]
        await db.approval_chains.update_many(overlap_filter, {"$set": {"active": False}})
    doc["id"] = str(uuid.uuid4())
    doc["created_at"] = datetime.now(timezone.utc).isoformat()
    doc["created_by"] = user["id"]
    await db.approval_chains.insert_one(doc)
    doc.pop("_id", None)
    return doc


@api.put("/approval-chains/{cid}", response_model=ApprovalChainOut)
async def update_approval_chain(cid: str, body: ApprovalChainIn, _=Depends(require_role("admin", "hr"))):
    update = body.model_dump()
    if not update["steps"]:
        raise HTTPException(400, "At least one approval step is required")
    sorted_steps = sorted(update["steps"], key=lambda s: s.get("level", 0))
    for i, s in enumerate(sorted_steps, 1):
        s["level"] = i
    update["steps"] = sorted_steps
    await _validate_chain_steps(sorted_steps)
    _cids = list(update.get("center_ids") or [])
    if update.get("center_id") and update["center_id"] not in _cids:
        _cids.append(update["center_id"])
    update["center_ids"] = _cids
    update["center_id"] = None
    if update.get("active"):
        overlap_filter: dict = {"type": update["type"], "active": True, "id": {"$ne": cid}}
        if _cids:
            overlap_filter["$or"] = [
                {"center_ids": {"$in": _cids}},
                {"center_id": {"$in": _cids}},
            ]
        else:
            overlap_filter["$and"] = [
                {"$or": [{"center_ids": {"$size": 0}}, {"center_ids": {"$exists": False}}]},
                {"$or": [{"center_id": None}, {"center_id": {"$exists": False}}]},
            ]
        await db.approval_chains.update_many(overlap_filter, {"$set": {"active": False}})
    res = await db.approval_chains.find_one_and_update(
        {"id": cid}, {"$set": update}, return_document=True,
    )
    if not res:
        raise HTTPException(404, "Not found")
    res.pop("_id", None)
    return res


@api.delete("/approval-chains/{cid}")
async def delete_approval_chain(cid: str, _=Depends(require_role("admin", "hr"))):
    r = await db.approval_chains.delete_one({"id": cid})
    if r.deleted_count == 0:
        raise HTTPException(404, "Not found")
    return {"ok": True}


# -------- Generic act-on-approval endpoint --------
@api.post("/approvals/act")
async def approval_act(body: ApprovalActionIn, user=Depends(get_current_user)):
    """Advance an in-flight reimbursement / leave / transaction along its configured chain.

    On final-approve of a reimbursement, automatically creates the offsetting expense transaction
    (preserving the existing payroll/reimbursement-ledger sync behaviour).

    Idempotency: uses atomic `find_one_and_update` on {id, current_level} to lock the
    request during processing. Concurrent duplicate clicks (double-tap, retry) that
    arrive after the first has flipped current_level will fail with 409 CONFLICT
    instead of creating duplicate transactions.
    """
    coll_name = APPROVAL_TYPE_COLL[body.request_type]
    coll = db[coll_name]
    rec = await coll.find_one({"id": body.request_id}, {"_id": 0})
    if not rec:
        raise HTTPException(404, "Request not found")
    # Already finalised?
    if rec.get("current_level") in (0, -1) or rec.get("status") in ("paid", "approved", "rejected"):
        raise HTTPException(400, f"Already finalised (status={rec.get('status')})")
    if not await _user_can_act_on_request(user, rec):
        raise HTTPException(403, "You are not the configured approver for the current step")

    # Atomic lock: bump to a transient level (negative marker) — any concurrent
    # duplicate click will find no matching {id, current_level: <original>} and
    # will be rejected with 409. We revert current_level in the update block below
    # (either to the next real step or to 0/-1 for terminal states).
    cur_level_at_entry = rec.get("current_level") or 1
    _lock = await coll.find_one_and_update(
        {"id": body.request_id, "current_level": cur_level_at_entry, "status": {"$nin": ["paid", "approved", "rejected"]}},
        {"$set": {"_processing_lock_by": user["id"], "_processing_lock_at": datetime.now(timezone.utc).isoformat()}},
    )
    if not _lock:
        # Another concurrent request beat us; return 409 so the client can refresh.
        raise HTTPException(409, "This request is already being processed or was just actioned. Please refresh.")

    snap = rec.get("chain_snapshot") or []
    cur_level = cur_level_at_entry
    history = list(rec.get("chain_history") or [])
    update: dict = {}

    if body.action == "reject":
        history.append(_history_entry(cur_level, "reject", user, body.remarks or ""))
        update = {
            "current_level": -1,
            "chain_history": history,
            "status": "rejected",
            "rejected_reason": body.remarks or "",
            "rejected_at": datetime.now(timezone.utc).isoformat(),
        }
        await coll.update_one({"id": body.request_id}, {"$set": update, "$unset": {"_processing_lock_by": "", "_processing_lock_at": ""}})
        # If a payment gets rejected, free up the quotation so a fresh payment can be raised.
        if body.request_type == "payment" and rec.get("quotation_id"):
            await db.quotations.update_one(
                {"id": rec["quotation_id"]},
                {"$set": {"payment_id": None, "status": "approved"}},
            )
        # Payroll batch rejection — unlock the underlying payroll rows so HR can edit
        # and re-finalise. Rows stay marked as belonging to this batch until re-finalise
        # (or admin reopen) so HR sees the audit trail.
        if body.request_type == "payroll":
            audit_log = list(rec.get("audit_log") or [])
            audit_log.append({
                "action": "rejected",
                "at": datetime.now(timezone.utc).isoformat(),
                "by": user["id"],
                "by_name": user.get("name"),
                "remarks": body.remarks or "",
                "old_status": rec.get("status"),
                "new_status": "rejected",
            })
            await coll.update_one({"id": body.request_id}, {"$set": {"audit_log": audit_log}})
            await db.payroll.update_many(
                {"batch_id": body.request_id},
                {"$set": {"locked": False, "batch_status": "rejected"}},
            )
        # Notify creator
        if rec.get("created_by") and rec["created_by"] != user["id"]:
            await _notify(rec["created_by"],
                          f"Your {body.request_type} was rejected" + (f": {body.remarks}" if body.remarks else ""),
                          ntype=f"{body.request_type}_rejected", ref_id=body.request_id,
                          link=_approval_link(body.request_type))
        return {"ok": True, "status": "rejected"}

    if body.action == "send_back":
        # Send-back parks the request in a `sent_back` state so the creator can
        # edit as per remarks and resubmit; approval chain will restart from Lv1
        # via the resubmit endpoint. current_level=0 keeps it out of the pending
        # inbox query (which filters current_level > 0) without marking finalised.
        now = datetime.now(timezone.utc).isoformat()
        history.append(_history_entry(cur_level, "send_back", user, body.remarks or ""))
        update = {
            "current_level": 0,
            "chain_history": history,
            "status": "sent_back",
            "sent_back_reason": body.remarks or "",
            "sent_back_at": now,
            "sent_back_by": user["id"],
            "sent_back_by_name": user.get("name") or user.get("email"),
            "sent_back_from_level": cur_level,
        }
        await coll.update_one({"id": body.request_id}, {"$set": update, "$unset": {"_processing_lock_by": "", "_processing_lock_at": ""}})
        # If a payment gets sent back, temporarily park the quotation status too so
        # the creator can update payee details and resubmit; on resubmit the
        # quotation flips back to 'payment_pending'.
        if body.request_type == "payment" and rec.get("quotation_id"):
            await db.quotations.update_one(
                {"id": rec["quotation_id"]},
                {"$set": {"status": "payment_sent_back"}},
            )
        if rec.get("created_by") and rec["created_by"] != user["id"]:
            await _notify(rec["created_by"],
                          f"Your {body.request_type} was sent back for edits: {body.remarks}",
                          ntype=f"{body.request_type}_sent_back", ref_id=body.request_id,
                          link=_approval_link(body.request_type))
        return {"ok": True, "status": "sent_back"}

    # Approve flow
    history.append(_history_entry(cur_level, "approve", user, body.remarks or ""))
    # Determine next level (skipping optional steps with no resolvable approver)
    next_level = cur_level + 1
    while True:
        nxt = next((s for s in snap if s.get("level") == next_level), None)
        if nxt is None:
            break  # past the end
        eligible = await _resolve_step_user_ids(nxt, rec)
        if eligible or not nxt.get("optional"):
            break
        # Optional step with no resolvable approver → auto-skip
        history.append({"level": next_level, "action": "auto-skip", "by_user_id": None,
                        "by_user_name": "system", "at": datetime.now(timezone.utc).isoformat(),
                        "remarks": "No approver resolved; optional step skipped"})
        next_level += 1

    is_last = (next((s for s in snap if s.get("level") == next_level), None)) is None

    if is_last:
        # Final approval — finalise per type
        # For payments and reimbursements the approver MUST tell us who actually
        # released the money so the auto-created transaction shows the payer.
        # Exception: payments funded by an existing advance don't need a fresh payer
        # (the advance itself was the source of cash), so we auto-default paid_by
        # to the advance requester and skip the validation.
        _is_adv_adjust_payment = (
            body.request_type == "payment"
            and bool(rec.get("advance_request_id"))
        )
        if body.request_type in ("payment", "reimbursement") and not _is_adv_adjust_payment:
            if not (body.paid_by_name or "").strip():
                raise HTTPException(400, "Please select who is making the payment (paid_by_name is required for final approval)")
            if not (body.txn_center_id or "").strip():
                raise HTTPException(400, "Please select the center for this payment (txn_center_id is required)")
            # Resolve chosen center's company so the txn dimensions stay consistent.
            _sel_center = await db.centers.find_one({"id": body.txn_center_id}, {"_id": 0, "name": 1, "company_id": 1})
            if not _sel_center:
                raise HTTPException(400, "Selected center not found")
        elif _is_adv_adjust_payment:
            # Auto-fill so downstream code has values to work with
            if not (body.paid_by_name or "").strip():
                body.paid_by_name = rec.get("created_by_name") or "Advance Holder"
            if not body.paid_by_user_id:
                body.paid_by_user_id = rec.get("created_by")
            _sel_center = None
            if body.txn_center_id:
                _sel_center = await db.centers.find_one({"id": body.txn_center_id}, {"_id": 0, "name": 1, "company_id": 1})
        if body.request_type == "reimbursement":
            now = datetime.now(timezone.utc).isoformat()
            staff = await db.staff.find_one({"id": rec["staff_id"]}, {"_id": 0, "name": 1, "center_id": 1})
            # Prefer the approver-picked center/partner; fall back to the staff's
            # linked center for backward compatibility with old chains.
            eff_center_id = body.txn_center_id or (staff or {}).get("center_id")
            eff_partner_id = body.txn_partner_id
            eff_company_id = (_sel_center or {}).get("company_id") if body.txn_center_id else None
            if eff_partner_id is None or eff_company_id is None:
                center_ctx = await _derive_context_for_center(eff_center_id)
                if eff_partner_id is None:
                    eff_partner_id = center_ctx["partner_id"]
                if eff_company_id is None:
                    eff_company_id = center_ctx["company_id"]
            txn = {
                "id": str(uuid.uuid4()),
                "type": "expense",
                "amount": rec["amount"],
                "date": rec["date"],
                "description": f"Reimbursement: {(staff or {}).get('name','')} — {rec.get('description','')}".strip(),
                "company_id": eff_company_id,
                "partner_id": eff_partner_id,
                "center_id": eff_center_id,
                "project_id": None,
                "items": [], "attachments": rec.get("attachments") or [],
                "source": "reimbursement",
                "reimbursement_id": rec.get("id"),
                "paid_by_user_id": body.paid_by_user_id,
                "paid_by_name": body.paid_by_name,
                "created_by": user["id"], "created_at": now,
                "status": "approved", "approved_by": user["id"], "approved_at": now,
                "rejected_reason": None,
            }
            await db.transactions.insert_one(txn)
            update = {
                "current_level": 0,
                "chain_history": history,
                "status": "paid",
                "paid_at": now,
                "paid_by": user["id"],
                "paid_by_user_id": body.paid_by_user_id,
                "paid_by_name": body.paid_by_name,
                "txn_id": txn["id"],
            }
        elif body.request_type == "leave":
            update = {
                "current_level": 0,
                "chain_history": history,
                "status": "approved",
                "decided_by": user["id"],
                "decided_at": datetime.now(timezone.utc).isoformat(),
            }
            # Auto-deduct from the staff's leave balance if a type is linked + balance row exists for that year.
            await _deduct_leave_balance_on_approve(rec)
        elif body.request_type == "asset_purchase":
            # Final-approval converts request → Asset record + offsetting expense transaction.
            now = datetime.now(timezone.utc).isoformat()
            asset = {
                "id": str(uuid.uuid4()),
                "name": rec.get("name") or "Asset",
                "category": rec.get("category"),
                "serial_no": rec.get("serial_no"),
                "vendor": rec.get("vendor"),
                "purchase_amount": float(rec.get("est_amount") or 0),
                "purchase_date": rec.get("required_date") or now[:10],
                "depreciation_rate_pct": float(rec.get("depreciation_rate_pct") or 0),
                "useful_life_years": rec.get("useful_life_years"),
                "center_id": rec.get("center_id"),
                "assigned_to_staff_id": None,
                "status": "active",
                "attachments": rec.get("attachments") or [],
                "purchase_request_id": rec["id"],
                "created_by": user["id"],
                "created_at": now,
            }
            await db.assets.insert_one(asset)
            txn = None
            if asset["purchase_amount"] > 0:
                asset_ctx = await _derive_context_for_center(asset.get("center_id"))
                txn = {
                    "id": str(uuid.uuid4()),
                    "type": "expense",
                    "amount": asset["purchase_amount"],
                    "date": asset["purchase_date"],
                    "description": f"Asset Purchase: {asset['name']}" + (f" (SN {asset['serial_no']})" if asset.get("serial_no") else ""),
                    "company_id": asset_ctx["company_id"],
                    "partner_id": asset_ctx["partner_id"],
                    "center_id": asset.get("center_id"),
                    "project_id": None,
                    "items": [], "attachments": asset.get("attachments") or [],
                    "created_by": user["id"], "created_at": now,
                    "status": "approved", "approved_by": user["id"], "approved_at": now,
                    "rejected_reason": None,
                    "asset_id": asset["id"],
                }
                await db.transactions.insert_one(txn)
                await db.assets.update_one({"id": asset["id"]}, {"$set": {"txn_id": txn["id"]}})
            update = {
                "current_level": 0,
                "chain_history": history,
                "status": "approved",
                "approved_by": user["id"],
                "approved_at": now,
                "asset_id": asset["id"],
                "txn_id": (txn or {}).get("id"),
            }
        elif body.request_type == "employee_transfer":
            # Final-approval applies the transfer: update staff.center_id and stamp transfer doc.
            now = datetime.now(timezone.utc).isoformat()
            if rec.get("staff_id") and rec.get("to_center_id"):
                await db.staff.update_one(
                    {"id": rec["staff_id"]},
                    {"$set": {"center_id": rec["to_center_id"]}},
                )
            update = {
                "current_level": 0,
                "chain_history": history,
                "status": "approved",
                "approved_by": user["id"],
                "approved_at": now,
                "applied_at": now,
            }
        elif body.request_type == "regularisation":
            # Final-approval upserts the attendance row for the staff/date as 'regularised'.
            now = datetime.now(timezone.utc).isoformat()
            new_id = str(uuid.uuid4())
            await db.attendance.update_one(
                {"staff_id": rec["staff_id"], "date": rec["date"]},
                {"$set": {
                    "staff_id": rec["staff_id"], "date": rec["date"],
                    "status": rec.get("attendance_status") or "present",
                    "marked_via": "regularised",
                    "marked_at": now, "marked_by": user["id"],
                    "check_in_at": now,
                    "regularised": True, "regularisation_id": rec["id"],
                }, "$setOnInsert": {"id": new_id}},
                upsert=True,
            )
            update = {
                "current_level": 0,
                "chain_history": history,
                "status": "approved",
                "decided_by": user["id"],
                "decided_at": now,
                "decision_remarks": body.remarks or "",
            }
        elif body.request_type == "quotation":
            # Final-approval: stamp a per-center QRN. Status → 'approved' (payment can now be raised).
            now = datetime.now(timezone.utc).isoformat()
            qrn = await _next_qrn(rec["center_id"])
            update = {
                "current_level": 0,
                "chain_history": history,
                "status": "approved",
                "qrn": qrn,
                "approved_by": user["id"],
                "approved_at": now,
                "rejected_reason": None,
            }
        elif body.request_type == "payment":
            # Final-approval: auto-create the offsetting ledger transaction in the center.
            now = datetime.now(timezone.utc).isoformat()
            # Use approver-picked center + partner (mandatory above) so the dashboard
            # aggregations reflect exactly what the accountant confirmed.
            eff_center_id = body.txn_center_id or rec.get("center_id")
            eff_partner_id = body.txn_partner_id
            eff_company_id = (_sel_center or {}).get("company_id") if body.txn_center_id else None
            if eff_partner_id is None or eff_company_id is None:
                ctx = await _derive_context_for_center(eff_center_id)
                if eff_partner_id is None:
                    eff_partner_id = ctx["partner_id"]
                if eff_company_id is None:
                    eff_company_id = ctx["company_id"]
            # Also refresh center_name if the approver switched centers
            eff_center_name = (_sel_center or {}).get("name") if body.txn_center_id else rec.get("center_name")
            txn_type = rec.get("category") or "expense"
            pay_date = rec.get("payment_date") or now[:10]
            desc = f"Payment · QRN {rec.get('qrn','')} · {rec.get('vendor_name','')} — {rec.get('description','')}".strip(" ·—")
            txn = {
                "id": str(uuid.uuid4()),
                "type": txn_type,
                "amount": float(rec["actual_amount"]),
                "date": pay_date,
                "description": desc,
                "company_id": eff_company_id,
                "partner_id": eff_partner_id,
                "center_id": eff_center_id,
                "project_id": None,
                "items": [], "attachments": rec.get("attachments") or [],
                "source": "quotation_payment",
                "quotation_id": rec.get("quotation_id"),
                "payment_id": rec.get("id"),
                "qrn": rec.get("qrn"),
                "payment_mode": rec.get("payment_mode"),
                "vendor_name": rec.get("vendor_name"),
                "paid_by_user_id": body.paid_by_user_id,
                "paid_by_name": body.paid_by_name,
                "created_by": user["id"], "created_at": now,
                "status": "approved", "approved_by": user["id"], "approved_at": now,
                "rejected_reason": None,
            }
            # Phase-2 Advance Adjustment: when this payment is funded by an earlier
            # released advance, mark the txn as advance-funded so cash-flow reports
            # can net it out (the outflow already happened at advance release time).
            adv_id = rec.get("advance_request_id")
            if adv_id:
                txn["funded_by_advance_id"] = adv_id
                txn["advance_no"] = rec.get("advance_no")
                txn["is_advance_adjustment"] = True
            await db.transactions.insert_one(txn)
            # Bank/Cash Reconciliation (Phase 29): debit the chosen bank/cash
            # account UNLESS this payment is funded by an already-released advance
            # (in which case the outflow was booked at advance-release time).
            if not adv_id:
                acct = await _require_bank_account_if_configured(body.bank_account_id)
                if acct:
                    ledger_row = await _post_bank_ledger(
                        account_id=acct["id"], direction="debit",
                        amount=float(rec["actual_amount"]),
                        source="payment", source_id=rec.get("id"),
                        remarks=(
                            f"Payment · QRN {rec.get('qrn','')} · {rec.get('vendor_name','')}"
                            + (f" · {body.remarks}" if body.remarks else "")
                        ),
                        vendor_name=rec.get("vendor_name"),
                        center_id=eff_center_id, center_name=eff_center_name,
                        date=pay_date, user=user,
                    )
                    txn["bank_account_id"] = acct["id"]
                    txn["bank_txn_id"] = ledger_row["id"]
                    # Also persist on the txn row we just inserted.
                    await db.transactions.update_one(
                        {"id": txn["id"]},
                        {"$set": {"bank_account_id": acct["id"], "bank_txn_id": ledger_row["id"]}},
                    )
            # If this payment adjusts against an advance, reduce the advance balance,
            # append to adjustments log, and flip status → adjusting/settled.
            if adv_id:
                adv = await db.advance_requests.find_one({"id": adv_id}, {"_id": 0})
                if adv:
                    amt = float(rec["actual_amount"])
                    new_adjusted = float(adv.get("adjusted_amount") or 0) + amt
                    new_balance = max(0.0, float(adv.get("balance_amount") or 0) - amt)
                    adjustments = list(adv.get("adjustments") or [])
                    adjustments.append({
                        "payment_id": rec["id"],
                        "quotation_id": rec.get("quotation_id"),
                        "qrn": rec.get("qrn"),
                        "amount": amt,
                        "at": now,
                        "vendor_name": rec.get("vendor_name"),
                        "txn_id": txn["id"],
                    })
                    adv_status = "settled" if new_balance <= 0.01 else "adjusting"
                    adv_update = {
                        "adjusted_amount": round(new_adjusted, 2),
                        "balance_amount": round(new_balance, 2),
                        "adjustments": adjustments,
                        "status": adv_status,
                    }
                    if adv_status == "settled":
                        adv_update["settled_at"] = now
                    await db.advance_requests.update_one({"id": adv_id}, {"$set": adv_update})
                    await _notify(
                        adv.get("created_by"),
                        f"₹{amt:,.0f} adjusted against your advance {adv.get('advance_no')} — balance ₹{new_balance:,.0f}",
                        ntype="advance_adjusted", ref_id=adv_id, link="/advances",
                    )
            # Reflect final state on both payment + quotation
            await db.quotations.update_one(
                {"id": rec.get("quotation_id")},
                {"$set": {"status": "paid", "txn_id": txn["id"], "paid_at": now,
                          "center_id": eff_center_id, "center_name": eff_center_name}},
            )
            update = {
                "current_level": 0,
                "chain_history": history,
                "status": "paid",
                "paid_at": now,
                "paid_by": user["id"],
                "paid_by_user_id": body.paid_by_user_id,
                "paid_by_name": body.paid_by_name,
                "center_id": eff_center_id,
                "center_name": eff_center_name,
                "partner_id_at_pay": eff_partner_id,
                "txn_id": txn["id"],
            }
            # Auto-generate Payment Voucher PDF (trust doc for the vendor).
            # Best-effort: any error is logged but does NOT fail the payment finalisation.
            try:
                voucher = await _generate_payment_voucher(
                    payment_doc={**rec, **update, "actual_amount": rec["actual_amount"]},
                    quotation_id=rec.get("quotation_id"),
                    company_id=eff_company_id, center_id=eff_center_id,
                    txn_ref=body.paid_by_name and (rec.get("notes") or ""),
                    generated_by=user,
                )
                if voucher:
                    update["voucher_id"] = voucher["id"]
                    update["voucher_no"] = voucher["voucher_no"]
                    update["voucher_path"] = voucher["file_path"]
                    update["voucher_generated_at"] = voucher["generated_at"]
            except Exception as _voucher_err:  # noqa: BLE001
                logger.exception("Payment voucher auto-generation failed for payment %s", rec.get("id"))
        elif body.request_type == "payroll":
            # Phase 55 — Payroll batch final approval. Move the batch into "pending_payment"
            # so Accounts can process the disbursement. NO transaction is created here;
            # that happens on POST /payroll-batches/{id}/pay by the accountant.
            now = datetime.now(timezone.utc).isoformat()
            audit_log = list(rec.get("audit_log") or [])
            audit_log.append({
                "action": "approved",
                "at": now,
                "by": user["id"],
                "by_name": user.get("name"),
                "by_role": user.get("role"),
                "level": rec.get("current_level"),
                "step_label": (rec.get("chain_snapshot") or [{}])[max(0, (rec.get("current_level") or 1) - 1)].get("label"),
                "remarks": body.remarks or "",
                "old_status": rec.get("status"),
                "new_status": "pending_payment",
            })
            update = {
                "current_level": 0,
                "chain_history": history,
                "status": "pending_payment",
                "approved_by": user["id"],
                "approved_at": now,
                "rejected_reason": None,
                "audit_log": audit_log,
            }
            # Notify accountants that a batch is ready for payment.
            accs = await db.users.find({"role": "accountant"}, {"_id": 0, "id": 1}).to_list(200)
            for _acc in accs:
                await _notify(
                    _acc["id"],
                    f"Payroll {rec.get('month'):02d}/{rec.get('year')} approved — ₹{float(rec.get('net_payable') or 0):,.0f} ready for payment",
                    ntype="payroll_ready", ref_id=rec["id"], link="/payroll-batches",
                )
        else:  # transaction OR advance_request (both share the generic approved+audit path)
            update = {
                "current_level": 0,
                "chain_history": history,
                "status": "approved",
                "approved_by": user["id"],
                "approved_at": datetime.now(timezone.utc).isoformat(),
                "rejected_reason": None,
            }
            # Advance Request final approval — accounts approver can OPTIONALLY
            # pre-attribute the release txn by picking Center/Partner/Paid-By in
            # the approval dialog itself. Values are stored on the advance row so
            # the Release dialog pre-fills them and the auto-created txn uses them.
            if body.request_type == "advance_request":
                if body.txn_center_id:
                    _sel_center_adv = await db.centers.find_one({"id": body.txn_center_id}, {"_id": 0, "name": 1, "company_id": 1})
                    if not _sel_center_adv:
                        raise HTTPException(400, "Selected center not found")
                    update["approved_center_id"] = body.txn_center_id
                    update["approved_center_name"] = _sel_center_adv.get("name")
                    update["approved_company_id"] = _sel_center_adv.get("company_id")
                if body.txn_partner_id:
                    update["approved_partner_id"] = body.txn_partner_id
                if body.paid_by_user_id or body.paid_by_name:
                    update["approved_paid_by_user_id"] = body.paid_by_user_id
                    update["approved_paid_by_name"] = body.paid_by_name
        await coll.update_one({"id": body.request_id}, {"$set": update, "$unset": {"_processing_lock_by": "", "_processing_lock_at": ""}})
        if rec.get("created_by") and rec["created_by"] != user["id"]:
            verb = "paid" if body.request_type == "reimbursement" else "approved"
            await _notify(rec["created_by"], f"Your {body.request_type} was {verb}",
                          ntype=f"{body.request_type}_{verb}", ref_id=body.request_id,
                          link=_approval_link(body.request_type))
        return {"ok": True, "status": update["status"]}

    # Otherwise advance to next level
    update = {"current_level": next_level, "chain_history": history}
    await coll.update_one({"id": body.request_id}, {"$set": update, "$unset": {"_processing_lock_by": "", "_processing_lock_at": ""}})
    # Notify next approvers
    nxt = next((s for s in snap if s.get("level") == next_level), None)
    if nxt:
        next_uids = await _resolve_step_user_ids(nxt, rec)
        for uid in next_uids:
            if uid != user["id"]:
                await _notify(uid,
                              f"{body.request_type.replace('_',' ').title()} awaiting your approval (Level {next_level}: {nxt.get('label','')})",
                              ntype=f"{body.request_type}_pending", ref_id=body.request_id,
                              link=_approval_link(body.request_type))
    return {"ok": True, "status": "in_progress", "current_level": next_level}


@api.get("/approvals/pending")
async def list_pending_approvals(user=Depends(get_current_user)):
    """Return all requests across types where the current user is the resolved approver
    for the current step. ALSO includes transactions partner-cross-approve-eligible
    for the requesting user (so associated partners see them here).

    PERFORMANCE (Phase 32): Pre-compute the user's context ONCE (role, assigned
    centers, staff record, direct-report subordinates) and do all step-membership
    checks in-memory. Also fetches all approval-type collections in PARALLEL via
    asyncio.gather.
    """
    is_admin = user.get("role") == "admin"
    user_id = user["id"]
    user_role = user.get("role")
    user_center_ids = set(user.get("assigned_center_ids") or [])

    # Fetch the caller's staff record ONCE so `kind=staff` and `kind=reports_to`
    # checks can be resolved with pure-Python comparisons below.
    user_staff = await db.staff.find_one({"user_id": user_id}, {"_id": 0, "id": 1})
    user_staff_id = (user_staff or {}).get("id")

    # Pre-compute the set of subordinate user_ids that report to this user, so
    # reports_to steps route without extra DB lookups per request. Depth ≤ 3 is
    # more than enough for real-world hierarchies.
    subordinate_user_ids: set[str] = set()
    if user_staff_id:
        direct = await db.staff.find(
            {"reports_to_id": user_staff_id},
            {"_id": 0, "id": 1, "user_id": 1},
        ).to_list(2000)
        subordinate_user_ids = {s["user_id"] for s in direct if s.get("user_id")}

    def _fast_can_act(step: dict, doc: dict) -> bool:
        """Purely-in-memory version of _user_can_act_on_request. Returns True iff
        the caller is eligible for the given step of the given request doc.
        Fallback to False (safe — the row simply won't surface)."""
        if is_admin:
            return True
        if not step:
            return False
        kind = step.get("kind")
        value = step.get("value", "")
        if kind == "user":
            return value == user_id
        if kind == "role":
            if value != user_role:
                return False
            # Center-scoped roles need the request's center to match user's assigned centers
            if value in ("partner", "center_partner", "center_manager", "center_staff"):
                cid = doc.get("center_id")
                if cid and cid not in user_center_ids:
                    return False
            return True
        if kind == "staff":
            return bool(user_staff_id) and value == user_staff_id
        if kind == "reports_to":
            submitter_id = doc.get("created_by")
            return bool(submitter_id) and submitter_id in subordinate_user_ids
        return False

    # Kick off every collection scan in parallel.
    async def _fetch(coll_name):
        return await db[coll_name].find(
            {"current_level": {"$gt": 0}}, {"_id": 0},
        ).sort("created_at", -1).to_list(2000)

    coll_names = list(APPROVAL_TYPE_COLL.items())
    fetched = await asyncio.gather(*[_fetch(c) for _, c in coll_names])

    out: List[dict] = []
    seen_txn_ids: set[str] = set()
    for (req_type, _), rows in zip(coll_names, fetched):
        for rec in rows:
            snap = rec.get("chain_snapshot") or []
            cur = rec.get("current_level")
            step = None
            if snap and cur:
                for s in snap:
                    if s.get("level") == cur:
                        step = s
                        break
            if not _fast_can_act(step, rec):
                continue
            max_level = max((s.get("level", 0) for s in snap), default=0)
            is_final_step = (cur == max_level) if snap else False
            out.append({
                "request_type": req_type,
                "request_id": rec["id"],
                "current_level": cur,
                "step_label": (step or {}).get("label"),
                "is_final_step": is_final_step,
                "total_steps": len(snap),
                "requester_id": rec.get("created_by"),
                "_staff_id": rec.get("staff_id"),
                "requester_name": (
                    rec.get("created_by_name")
                    or rec.get("employee_name")
                    or (rec.get("finalised_by_name") if req_type == "payroll" else None)
                ),
                "center_id_of_request": rec.get("center_id"),
                "center_name_of_request": rec.get("center_name"),
                "summary": {
                    "amount": rec.get("amount") or rec.get("est_amount") or rec.get("actual_amount") or rec.get("estimated_amount") or (rec.get("net_payable") if req_type == "payroll" else None),
                    "date": rec.get("date") or rec.get("start_date") or rec.get("required_date") or rec.get("effective_date") or rec.get("payment_date"),
                    "purpose": (
                        rec.get("purpose")
                        or rec.get("reason")
                        or (f"QRN {rec.get('qrn') or ''}"
                            if req_type in ("payment", "quotation") and rec.get("qrn") else None)
                        or (f"Payroll Batch · {int(rec.get('month') or 0):02d}/{rec.get('year')}"
                            if req_type == "payroll" else None)
                        or None
                    ),
                    "description": (
                        rec.get("description")
                        or rec.get("reason")
                        or (f"{rec.get('name','Asset')} → {rec.get('category') or ''}".strip(" →")
                            if req_type == "asset_purchase" else None)
                        or (f"{rec.get('staff_name','Staff')} → center {rec.get('to_center_id','')[:8]}"
                            if req_type == "employee_transfer" else None)
                        or (f"Regularise {rec.get('attendance_status','present').upper()} on {rec.get('date','')}"
                            if req_type == "regularisation" else None)
                        or (f"{rec.get('staff_count') or 0} staff · Net payable ₹{float(rec.get('net_payable') or 0):,.0f}"
                            if req_type == "payroll" else None)
                    ),
                    "vendor_name": rec.get("vendor_name") or (rec.get("employee_name") if req_type == "advance_request" else None),
                    "qrn": rec.get("qrn") or (rec.get("advance_no") if req_type == "advance_request" else None),
                    "payment_mode": rec.get("payment_mode") or rec.get("preferred_payment_mode"),
                    "payee_account_holder": rec.get("payee_account_holder"),
                    "payee_account_no": rec.get("payee_account_no"),
                    "payee_ifsc": rec.get("payee_ifsc"),
                    "payee_bank_name": rec.get("payee_bank_name"),
                    "payee_upi_id": rec.get("payee_upi_id"),
                    "payee_proof_attachments": rec.get("payee_proof_attachments") or [],
                    "attachments": rec.get("attachments") or [],
                    "chain_history": rec.get("chain_history") or [],
                    "center_id": rec.get("center_id"),
                    "center_name": rec.get("center_name"),
                },
                "created_at": rec.get("created_at"),
                "via": "chain",
            })
            if req_type == "transaction":
                seen_txn_ids.add(rec["id"])
    # Add partner-cross-approve-eligible transactions (not already in chain list)
    if user_role == "partner":
        pending_txns = await db.transactions.find(
            {"status": "pending"}, {"_id": 0},
        ).sort("created_at", -1).to_list(2000)
        # Batch-fetch center names + requester names to avoid N+1 lookups.
        _cids = {t.get("center_id") for t in pending_txns if t.get("center_id")}
        _center_map = {}
        if _cids:
            _center_rows = await db.centers.find({"id": {"$in": list(_cids)}}, {"_id": 0, "id": 1, "name": 1}).to_list(500)
            _center_map = {c["id"]: c.get("name") for c in _center_rows}
        _uids = {t.get("created_by") for t in pending_txns if t.get("created_by")}
        _user_map = {}
        if _uids:
            _user_rows = await db.users.find({"id": {"$in": list(_uids)}}, {"_id": 0, "id": 1, "name": 1, "email": 1}).to_list(500)
            _user_map = {u["id"]: (u.get("name") or u.get("email")) for u in _user_rows}
        for t in pending_txns:
            if t["id"] in seen_txn_ids:
                continue
            allowed, _reason = await _can_partner_approve(user, t)
            if allowed:
                _cid = t.get("center_id")
                _cname = t.get("center_name") or _center_map.get(_cid)
                out.append({
                    "request_type": "transaction",
                    "request_id": t["id"],
                    "current_level": t.get("current_level"),
                    "step_label": "Partner cross-approval",
                    "requester_id": t.get("created_by"),
                    "_staff_id": t.get("staff_id"),
                    "requester_name": t.get("created_by_name") or _user_map.get(t.get("created_by")),
                    "center_id_of_request": _cid,
                    "center_name_of_request": _cname,
                    "summary": {
                        "amount": t.get("amount"),
                        "date": t.get("date"),
                        "description": t.get("description"),
                        "center_id": _cid,
                        "center_name": _cname,
                    },
                    "created_at": t.get("created_at"),
                    "via": "partner_cross",
                })
    # ---- Enrich every approval with requester details (name, employee id,
    # department, designation) resolved from the staff record (fallback to the
    # user record). Batched to avoid N+1 lookups. Applies to ALL approval types.
    staff_ids = {o.get("_staff_id") for o in out if o.get("_staff_id")}
    req_uids = {o.get("requester_id") for o in out if o.get("requester_id")}
    staff_proj = {"_id": 0, "id": 1, "user_id": 1, "name": 1, "employee_code": 1, "department": 1, "designation": 1}
    staff_by_id: dict = {}
    staff_by_uid: dict = {}
    users_by_id: dict = {}
    if staff_ids:
        for s in await db.staff.find({"id": {"$in": list(staff_ids)}}, staff_proj).to_list(3000):
            staff_by_id[s["id"]] = s
    if req_uids:
        for s in await db.staff.find({"user_id": {"$in": list(req_uids)}}, staff_proj).to_list(3000):
            staff_by_uid[s["user_id"]] = s
        for u in await db.users.find(
            {"id": {"$in": list(req_uids)}},
            {"_id": 0, "id": 1, "name": 1, "email": 1, "department": 1, "designation": 1, "employee_code": 1},
        ).to_list(3000):
            users_by_id[u["id"]] = u
    for o in out:
        sid = o.pop("_staff_id", None)
        st = (staff_by_id.get(sid) if sid else None) or staff_by_uid.get(o.get("requester_id")) or {}
        usr = users_by_id.get(o.get("requester_id")) or {}
        name = st.get("name") or o.get("requester_name") or usr.get("name") or usr.get("email")
        o["requester_name"] = name
        o["requester"] = {
            "name": name or None,
            "employee_code": st.get("employee_code") or usr.get("employee_code"),
            "department": st.get("department") or usr.get("department"),
            "designation": st.get("designation") or usr.get("designation"),
        }

    # Sort newest first
    out.sort(key=lambda x: x.get("created_at") or "", reverse=True)
    return out


@api.get("/approvals/status/{request_type}/{request_id}")
async def approval_status(request_type: str, request_id: str, user=Depends(get_current_user)):
    """Return the LIVE approval tracking status for any request — current step
    label, pending approvers (name+role), total steps, chain_history — so the
    creator can see 'Pending with: Rakesh Kumar (Senior Manager)' in the UI.
    """
    if request_type not in APPROVAL_TYPE_COLL:
        raise HTTPException(400, "Invalid request_type")
    coll_name = APPROVAL_TYPE_COLL[request_type]
    rec = await db[coll_name].find_one({"id": request_id}, {"_id": 0})
    if not rec:
        raise HTTPException(404, "Not found")
    await _enrich_with_approval_status(rec)
    return {
        "request_type": request_type,
        "request_id": request_id,
        "status": rec.get("status"),
        "current_level": rec.get("current_level"),
        "current_step_label": rec.get("current_step_label"),
        "total_steps": rec.get("total_steps"),
        "pending_with": rec.get("pending_with") or [],
        "chain_snapshot": rec.get("chain_snapshot") or [],
        "chain_history": rec.get("chain_history") or [],
    }


@api.post("/approvals/{request_type}/{request_id}/nudge")
async def nudge_approver(request_type: str, request_id: str, user=Depends(get_current_user)):
    """Send a polite reminder notification to the currently-pending approver(s).
    Only the request submitter (or admin/HR) can nudge."""
    if request_type not in APPROVAL_TYPE_COLL:
        raise HTTPException(400, "Invalid request_type")
    coll_name = APPROVAL_TYPE_COLL[request_type]
    rec = await db[coll_name].find_one({"id": request_id}, {"_id": 0})
    if not rec:
        raise HTTPException(404, "Not found")
    if not (user.get("role") in ("admin", "hr") or rec.get("created_by") == user["id"]):
        raise HTTPException(403, "Only the submitter (or admin/HR) can nudge")
    if not rec.get("current_level") or rec["current_level"] <= 0:
        raise HTTPException(400, "Request is not pending — nothing to nudge")
    step = await _current_step(rec)
    if not step:
        raise HTTPException(400, "No current step resolved")
    approver_ids = await _resolve_step_user_ids(step, rec)
    if not approver_ids:
        raise HTTPException(400, "No approver resolvable for current step")
    submitter = await db.users.find_one({"id": rec.get("created_by")}, {"_id": 0, "name": 1, "email": 1})
    name = (submitter or {}).get("name") or user.get("name") or "A staff member"
    for uid in approver_ids:
        if uid == user["id"]:
            continue
        await _notify(
            uid,
            f"Reminder from {name}: please review their pending {request_type} (Level {rec['current_level']}: {step.get('label','')})",
            ntype=f"{request_type}_nudge", ref_id=request_id,
            link=_approval_link(request_type),
        )
    return {"ok": True, "notified": len(approver_ids)}


@api.get("/approvals/{request_type}/{request_id}/timeline")
async def approval_timeline(request_type: str, request_id: str, _=Depends(get_current_user)):
    """Return a human-readable timeline of this request's approval chain.

    Each step shows:
      - level + label
      - resolved approver name(s) (looked up from staff / users)
      - state: "done" / "current" / "pending"
      - action taken (approve/reject/auto-skip) + by_user_name + at + remarks (from chain_history)
    """
    if request_type not in APPROVAL_TYPE_COLL:
        raise HTTPException(400, "Invalid request_type")
    coll_name = APPROVAL_TYPE_COLL[request_type]
    rec = await db[coll_name].find_one({"id": request_id}, {"_id": 0})
    if not rec:
        raise HTTPException(404, "Request not found")
    snap = rec.get("chain_snapshot") or []
    history = rec.get("chain_history") or []
    cur_level = rec.get("current_level") or 0
    overall_status = rec.get("status")

    # Pre-load users for name lookup
    user_ids: set = set()
    for h in history:
        if h.get("by_user_id"):
            user_ids.add(h["by_user_id"])
    if user_ids:
        users = await db.users.find({"id": {"$in": list(user_ids)}}, {"_id": 0, "id": 1, "name": 1, "email": 1}).to_list(500)
        user_map = {u["id"]: u for u in users}
    else:
        user_map = {}

    timeline: List[dict] = []
    for step in sorted(snap, key=lambda s: s.get("level", 0)):
        lvl = step.get("level")
        # State derivation
        if overall_status in ("rejected",) and any(h.get("level") == lvl and h.get("action") == "reject" for h in history):
            state = "rejected"
        elif cur_level == 0 or (cur_level == -1 and any(h.get("level") == lvl and h.get("action") in ("approve", "auto-skip") for h in history)):
            state = "done" if any(h.get("level") == lvl and h.get("action") in ("approve", "auto-skip") for h in history) else "skipped"
        elif lvl < cur_level:
            state = "done"
        elif lvl == cur_level:
            state = "current"
        else:
            state = "pending"

        # Resolve approver name(s)
        approver_ids = await _resolve_step_user_ids(step, rec)
        approver_names = []
        if approver_ids:
            ulist = await db.users.find({"id": {"$in": approver_ids}}, {"_id": 0, "id": 1, "name": 1, "email": 1}).to_list(50)
            approver_names = [u.get("name") or u.get("email") or u["id"][:8] for u in ulist]
        elif step.get("kind") == "role":
            approver_names = [f"(no user with role: {step.get('value')})"]

        # History entry for this level (if any)
        h_for_level = [h for h in history if h.get("level") == lvl]
        action_log = []
        for h in h_for_level:
            by = h.get("by_user_name") or (user_map.get(h.get("by_user_id"), {}).get("name") if h.get("by_user_id") else "system")
            action_log.append({
                "action": h.get("action"),
                "by": by,
                "at": h.get("at"),
                "remarks": h.get("remarks") or "",
            })

        timeline.append({
            "level": lvl,
            "label": step.get("label") or f"Level {lvl}",
            "kind": step.get("kind"),
            "value": step.get("value"),
            "optional": step.get("optional", False),
            "approver_names": approver_names,
            "state": state,
            "history": action_log,
        })

    return {
        "request_type": request_type,
        "request_id": request_id,
        "status": overall_status,
        "current_level": cur_level,
        "total_levels": len(snap),
        "created_by_id": rec.get("created_by"),
        "created_at": rec.get("created_at"),
        "amount": rec.get("amount"),
        "description": rec.get("description") or rec.get("reason"),
        "timeline": timeline,
    }


# ---------- Reimbursement Claim Templates (HR-managed) ----------
# HR/Admin uploads pre-designed claim format files (PDF/DOCX/XLSX) that staff can
# download from the Reimbursement submenu when preparing manual bills/formats.
class ReimbursementTemplateOut(BaseModel):
    id: str
    name: str
    description: Optional[str] = None
    category: Optional[str] = None
    filename: str
    file_path: str
    content_type: str
    size: int
    uploaded_by: Optional[str] = None
    uploaded_by_name: Optional[str] = None
    uploaded_at: str
    is_active: bool = True


class ReimbursementTemplatePatchIn(BaseModel):
    model_config = ConfigDict(extra="ignore")
    name: Optional[str] = None
    description: Optional[str] = None
    category: Optional[str] = None
    is_active: Optional[bool] = None


@api.post("/reimbursement-templates", response_model=ReimbursementTemplateOut, status_code=201)
async def upload_reimbursement_template(
    file: UploadFile = File(...),
    name: str = Query(..., min_length=1),
    description: Optional[str] = Query(None),
    category: Optional[str] = Query(None),
    user=Depends(require_role("admin", "hr")),
):
    """HR-only: upload a manual claim-form template (PDF/DOCX/XLSX/etc.).
    Staff will see active templates and can download them when raising claims."""
    if not file.filename:
        raise HTTPException(400, "Missing filename")
    ext = file.filename.rsplit(".", 1)[-1].lower() if "." in file.filename else "bin"
    if len(ext) > 10:
        ext = "bin"
    data = await file.read()
    if len(data) > 10 * 1024 * 1024:
        raise HTTPException(413, "Template too large (max 10MB)")
    tid = str(uuid.uuid4())
    path = f"{APP_STORAGE_PREFIX}/reimbursement-templates/{tid}.{ext}"
    content_type = file.content_type or "application/octet-stream"
    try:
        _put_object(path, data, content_type)
    except requests.HTTPError as e:
        raise HTTPException(502, f"Storage upload failed: {e}")
    # Also register in the shared /files collection so /files/view can stream it.
    await db.files.insert_one({
        "id": tid,
        "path": path,
        "filename": file.filename,
        "content_type": content_type,
        "size": len(data),
        "uploaded_by": user["id"],
        "uploaded_at": datetime.now(timezone.utc).isoformat(),
        "is_deleted": False,
    })
    doc = {
        "id": tid,
        "name": name.strip(),
        "description": (description or "").strip() or None,
        "category": (category or "").strip() or None,
        "filename": file.filename,
        "file_path": path,
        "content_type": content_type,
        "size": len(data),
        "uploaded_by": user["id"],
        "uploaded_by_name": user.get("name") or user.get("email"),
        "uploaded_at": datetime.now(timezone.utc).isoformat(),
        "is_active": True,
    }
    await db.reimbursement_templates.insert_one(doc)
    return ReimbursementTemplateOut(**doc)


@api.get("/reimbursement-templates", response_model=List[ReimbursementTemplateOut])
async def list_reimbursement_templates(
    active_only: bool = Query(False),
    user=Depends(get_current_user),
):
    """Any authenticated user can browse templates (staff need this to download
    forms). HR/Admin can toggle `active_only=false` in the manage view to see
    archived templates too."""
    q: dict = {}
    if active_only or user.get("role") not in ("admin", "hr"):
        q["is_active"] = True
    docs = await db.reimbursement_templates.find(q, {"_id": 0}).sort("uploaded_at", -1).to_list(500)
    return [ReimbursementTemplateOut(**d) for d in docs]


@api.patch("/reimbursement-templates/{tid}", response_model=ReimbursementTemplateOut)
async def update_reimbursement_template(
    tid: str,
    body: ReimbursementTemplatePatchIn,
    _=Depends(require_role("admin", "hr")),
):
    upd = {k: v for k, v in body.model_dump().items() if v is not None}
    if not upd:
        raise HTTPException(400, "No fields to update")
    r = await db.reimbursement_templates.update_one({"id": tid}, {"$set": upd})
    if r.matched_count == 0:
        raise HTTPException(404, "Template not found")
    doc = await db.reimbursement_templates.find_one({"id": tid}, {"_id": 0})
    return ReimbursementTemplateOut(**doc)


@api.delete("/reimbursement-templates/{tid}", status_code=204)
async def delete_reimbursement_template(tid: str, _=Depends(require_role("admin", "hr"))):
    doc = await db.reimbursement_templates.find_one({"id": tid}, {"_id": 0})
    if not doc:
        raise HTTPException(404, "Template not found")
    # Soft-remove the underlying object reference; keep the file for audit trail.
    await db.reimbursement_templates.delete_one({"id": tid})
    return None



# -------- Reimbursements (3-stage approval) --------
@api.post("/reimbursements")
async def submit_reimbursement(body: ReimbursementIn, user=Depends(get_current_user)):
    doc = body.model_dump()
    doc["id"] = str(uuid.uuid4())
    doc["status"] = "submitted"
    doc["created_by"] = user["id"]
    doc["created_at"] = datetime.now(timezone.utc).isoformat()
    # snapshot approver chain (legacy fields kept for back-compat with old endpoints)
    staff = await db.staff.find_one({"id": body.staff_id}, {"_id": 0})
    doc["l1_approver_id"] = staff.get("reports_to_id") if staff else None
    # Enrich doc with the staff's center_id so center-bound chains route correctly.
    if staff:
        doc["center_id"] = staff.get("center_id")
        doc["staff_name"] = staff.get("name")
    doc["l1_approved_at"] = None
    doc["l1_approved_by"] = None
    doc["accountant_approved_at"] = None
    doc["accountant_approved_by"] = None
    doc["paid_at"] = None
    doc["paid_by"] = None
    doc["txn_id"] = None
    doc["rejected_reason"] = None
    doc["rejected_at"] = None
    # Attach configurable approval chain
    await _attach_chain_to_request("reimbursement", doc)
    await db.reimbursements.insert_one(doc)
    doc.pop("_id", None)
    # Notify the first-level approver via the chain (fallback to legacy L1 if no chain)
    notified_uids: set = set()
    if doc.get("chain_snapshot"):
        first_step = next((s for s in doc["chain_snapshot"] if s.get("level") == 1), None)
        if first_step:
            for uid in await _resolve_step_user_ids(first_step, doc):
                if uid and uid != user["id"]:
                    notified_uids.add(uid)
    if not notified_uids:
        legacy_uid = await _user_id_for_staff(doc.get("l1_approver_id"))
        if legacy_uid and legacy_uid != user["id"]:
            notified_uids.add(legacy_uid)
    for uid in notified_uids:
        await _notify(uid, f"New reimbursement awaiting your approval (₹{doc.get('amount', 0):,.0f})",
                      ntype="reimb_pending", ref_id=doc["id"], link="/hrms")
    return doc


@api.get("/reimbursements")
async def list_reimbursements(
    staff_id: Optional[str] = None,
    status: Optional[str] = None,
    user=Depends(get_current_user),
):
    q: dict = {}
    role = user.get("role")
    if staff_id:
        q["staff_id"] = staff_id
    if status:
        q["status"] = status
    # If staff (logged-in user maps to a staff record), default-scope to own + ones they need to approve
    if role not in ("admin", "accountant", "manager"):
        my_staff = await _staff_for_user(user["id"])
        my_sid = my_staff["id"] if my_staff else None
        clauses: list = [{"created_by": user["id"]}]
        if my_sid:
            clauses.append({"staff_id": my_sid})
            clauses.append({"l1_approver_id": my_sid})
        q["$or"] = clauses
    docs = await db.reimbursements.find(q, {"_id": 0}).sort("created_at", -1).to_list(5000)
    for d in docs:
        await _enrich_with_approval_status(d)
    return docs


async def _check_l1_approver(rid: str, user: dict) -> dict:
    rec = await db.reimbursements.find_one({"id": rid}, {"_id": 0})
    if not rec:
        raise HTTPException(404, "Not found")
    if user.get("role") in ("admin", "hr"):
        return rec
    # must be the snapshot l1 approver via their linked staff record
    my_staff = await _staff_for_user(user["id"])
    if not my_staff or rec.get("l1_approver_id") != my_staff["id"]:
        raise HTTPException(403, "Only the assigned higher-post approver can act on this request")
    return rec


@api.patch("/reimbursements/{rid}/l1-approve")
async def reimb_l1_approve(rid: str, user=Depends(get_current_user)):
    rec = await _check_l1_approver(rid, user)
    if rec["status"] != "submitted":
        raise HTTPException(400, f"Cannot L1-approve from status={rec['status']}")
    res = await db.reimbursements.find_one_and_update(
        {"id": rid},
        {"$set": {"status": "l1_approved",
                  "l1_approved_at": datetime.now(timezone.utc).isoformat(),
                  "l1_approved_by": user["id"]}},
        return_document=True,
    )
    res.pop("_id", None)
    # Notify all accountants + admins (next stage)
    await _notify(await _accountant_admin_user_ids(),
                  f"Reimbursement L1-approved, awaiting accountant (₹{res.get('amount', 0):,.0f})",
                  ntype="reimb_acct_pending", ref_id=rid, link="/hrms")
    return res


@api.patch("/reimbursements/{rid}/accountant-approve")
async def reimb_accountant_approve(rid: str, user=Depends(require_role("admin", "accountant", "hr"))):
    rec = await db.reimbursements.find_one({"id": rid}, {"_id": 0})
    if not rec:
        raise HTTPException(404, "Not found")
    if rec["status"] != "l1_approved":
        raise HTTPException(400, f"Cannot accountant-approve from status={rec['status']}")
    res = await db.reimbursements.find_one_and_update(
        {"id": rid},
        {"$set": {"status": "accountant_approved",
                  "accountant_approved_at": datetime.now(timezone.utc).isoformat(),
                  "accountant_approved_by": user["id"]}},
        return_document=True,
    )
    res.pop("_id", None)
    # Notify all accountants + admins (next stage: ready to pay)
    await _notify(await _accountant_admin_user_ids(),
                  f"Reimbursement ready to pay (₹{res.get('amount', 0):,.0f})",
                  ntype="reimb_pay_pending", ref_id=rid, link="/hrms")
    return res


@api.patch("/reimbursements/{rid}/pay")
async def reimb_pay(rid: str, user=Depends(require_role("admin", "accountant", "hr"))):
    rec = await db.reimbursements.find_one({"id": rid}, {"_id": 0})
    if not rec:
        raise HTTPException(404, "Not found")
    if rec["status"] != "accountant_approved":
        raise HTTPException(400, "Reimbursement must be accountant-approved before payment")
    now = datetime.now(timezone.utc).isoformat()
    staff = await db.staff.find_one({"id": rec["staff_id"]}, {"_id": 0, "name": 1, "center_id": 1})
    reimb_ctx = await _derive_context_for_center((staff or {}).get("center_id"))
    # Auto-create an expense transaction (approved) for ledger sync
    txn = {
        "id": str(uuid.uuid4()),
        "type": "expense",
        "amount": rec["amount"],
        "date": rec["date"],
        "description": f"Reimbursement: {staff.get('name','') if staff else ''} — {rec.get('description','')}".strip(),
        "company_id": reimb_ctx["company_id"],
        "partner_id": reimb_ctx["partner_id"],
        "center_id": (staff or {}).get("center_id"),
        "project_id": None,
        "items": [], "attachments": rec.get("attachments") or [],
        "created_by": user["id"], "created_at": now,
        "status": "approved", "approved_by": user["id"], "approved_at": now,
        "rejected_reason": None,
    }
    await db.transactions.insert_one(txn)
    res = await db.reimbursements.find_one_and_update(
        {"id": rid},
        {"$set": {"status": "paid", "paid_at": now, "paid_by": user["id"], "txn_id": txn["id"]}},
        return_document=True,
    )
    res.pop("_id", None)
    # Notify creator that reimbursement has been paid
    if res.get("created_by") and res["created_by"] != user["id"]:
        await _notify(res["created_by"], f"Your reimbursement was paid (₹{res.get('amount', 0):,.0f})",
                      ntype="reimb_paid", ref_id=rid, link="/hrms")
    return res


@api.patch("/reimbursements/{rid}/reject")
async def reimb_reject(rid: str, body: RejectIn, user=Depends(get_current_user)):
    rec = await db.reimbursements.find_one({"id": rid}, {"_id": 0})
    if not rec:
        raise HTTPException(404, "Not found")
    role = user.get("role")
    is_admin_or_acct = role in ("admin", "accountant")
    if not is_admin_or_acct:
        # only the L1 approver can reject before they've approved
        my_staff = await _staff_for_user(user["id"])
        if not my_staff or rec.get("l1_approver_id") != my_staff["id"]:
            raise HTTPException(403, "Not allowed")
    res = await db.reimbursements.find_one_and_update(
        {"id": rid},
        {"$set": {"status": "rejected", "rejected_reason": body.reason or "",
                  "rejected_at": datetime.now(timezone.utc).isoformat()}},
        return_document=True,
    )
    res.pop("_id", None)
    # Notify creator that reimbursement was rejected
    if res.get("created_by") and res["created_by"] != user["id"]:
        await _notify(res["created_by"],
                      "Your reimbursement was rejected" + (f": {body.reason}" if body.reason else ""),
                      ntype="reimb_rejected", ref_id=rid, link="/hrms")
    return res


# -------- Payroll --------
class PayrollLineItem(BaseModel):
    label: str
    amount: float


class PayrollEditIn(BaseModel):
    """Admin/HR can override any component; net auto-recalculated server-side."""
    model_config = ConfigDict(extra="ignore")
    days_present: Optional[float] = None
    basic: Optional[float] = None
    hra: Optional[float] = None
    da: Optional[float] = None
    conveyance: Optional[float] = None
    bonus: Optional[float] = None
    incentive: Optional[float] = None
    # Extended earnings introduced in Phase A of the "SalaryBox-style" HRMS.
    overtime_pay: Optional[float] = None
    other_earnings: Optional[float] = None
    reimbursements_paid: Optional[float] = None  # HR can bundle approved claims into the slip
    pf_deduction: Optional[float] = None
    esi_deduction: Optional[float] = None
    late_deduction: Optional[float] = None  # manual override of computed late
    early_fine: Optional[float] = None
    advance: Optional[float] = None          # one-off salary advance being recovered
    loan_deduction: Optional[float] = None   # long-term loan EMI recovery
    other_deductions: Optional[List[PayrollLineItem]] = None
    remarks: Optional[str] = None


def _recalc_payroll(doc: dict) -> dict:
    """Compute gross / total_deductions / net from component fields. Mutates and returns doc."""
    earnings = sum([
        doc.get("basic", 0) or 0, doc.get("hra", 0) or 0, doc.get("da", 0) or 0,
        doc.get("conveyance", 0) or 0, doc.get("bonus", 0) or 0, doc.get("incentive", 0) or 0,
        doc.get("overtime_pay", 0) or 0, doc.get("other_earnings", 0) or 0,
        doc.get("reimbursements_paid", 0) or 0,
    ])
    other_sum = sum((li.get("amount", 0) or 0) for li in (doc.get("other_deductions") or []))
    deductions = sum([
        doc.get("pf_deduction", 0) or 0, doc.get("esi_deduction", 0) or 0,
        doc.get("late_deduction", 0) or 0, doc.get("early_fine", 0) or 0,
        doc.get("advance", 0) or 0, doc.get("loan_deduction", 0) or 0,
        other_sum,
    ])
    doc["gross"] = round(earnings, 2)
    doc["deductions"] = round(deductions, 2)
    doc["net"] = round(earnings - deductions, 2)
    return doc


async def _compute_payroll_for_staff(s: dict, month: int, year: int,
                                       paid_off_dates: set, weekly_off_weekdays: set) -> Optional[dict]:
    """Compute attendance-aware payroll fields for a single staff for a given month.

    Returns a dict of *computed* fields to be merged into a payroll row, or None if
    the staff was not employed in this month. All previous behaviour preserved,
    with one critical bug fix: working days without any attendance record AND no
    approved leave are now correctly treated as ABSENT (unpaid). Before this fix
    such days silently counted as paid, so staff with 0 attendance were being
    paid the full monthly salary.
    """
    import calendar
    last_day = calendar.monthrange(year, month)[1]

    def _parse(d):
        try:
            return datetime.strptime(d, "%Y-%m-%d").date() if d else None
        except (ValueError, TypeError):
            return None
    month_start_d = datetime.strptime(f"{year:04d}-{month:02d}-01", "%Y-%m-%d").date()
    month_end_d = datetime.strptime(f"{year:04d}-{month:02d}-{last_day:02d}", "%Y-%m-%d").date()

    joining = _parse(s.get("joining_date"))
    exit_dt = _parse(s.get("exit_date"))
    if joining and joining > month_end_d:
        return None
    if exit_dt and exit_dt < month_start_d:
        return None

    eff_start = max(joining, month_start_d) if joining else month_start_d
    eff_end = min(exit_dt, month_end_d) if exit_dt else month_end_d
    total_days = (eff_end - eff_start).days + 1
    if total_days <= 0:
        return None

    # Weekly off + holidays inside window (paid, no salary impact)
    window_off_dates = {d for d in paid_off_dates if eff_start.isoformat() <= d <= eff_end.isoformat()}
    weekly_off_count = 0
    holiday_count = 0
    cur = eff_start
    while cur <= eff_end:
        iso = cur.isoformat()
        is_hol = iso in window_off_dates
        is_wo = cur.strftime("%A").lower() in weekly_off_weekdays
        if is_hol:
            holiday_count += 1
        elif is_wo:
            weekly_off_count += 1
        cur = cur + timedelta(days=1)
    working_days = total_days - weekly_off_count - holiday_count

    # Attendance rows (raw)
    att_start = eff_start.isoformat()
    att_end = eff_end.isoformat()
    rows = await db.attendance.find(
        {"staff_id": s["id"], "date": {"$gte": att_start, "$lte": att_end}},
        {"_id": 0},
    ).to_list(1000)
    # Build a date -> status map so we can detect "unmarked working days"
    att_by_date = {}
    for r in rows:
        d = r.get("date")
        if d:
            att_by_date[d] = r

    # Approved leaves overlapping window — resolves paid vs unpaid via leave_type.paid
    leave_docs = await db.leaves.find({
        "staff_id": s["id"],
        "status": "approved",
        "start_date": {"$lte": att_end},
        "end_date": {"$gte": att_start},
    }, {"_id": 0}).to_list(200)
    # Preload leave-type paid flags
    leave_type_paid = {}
    for lv in leave_docs:
        lt_id = lv.get("leave_type_id")
        if lt_id and lt_id not in leave_type_paid:
            lt = await db.leave_types.find_one({"id": lt_id}, {"_id": 0, "paid": 1})
            leave_type_paid[lt_id] = bool((lt or {}).get("paid", True))
    # Expand leave date ranges → date -> "paid_leave" / "unpaid_leave"
    leave_by_date = {}
    for lv in leave_docs:
        lt_id = lv.get("leave_type_id")
        is_paid = leave_type_paid.get(lt_id, True) if lt_id else True
        try:
            s_d = datetime.strptime(lv["start_date"], "%Y-%m-%d").date()
            e_d = datetime.strptime(lv["end_date"], "%Y-%m-%d").date()
        except (KeyError, ValueError, TypeError):
            continue
        d = max(s_d, eff_start)
        stop = min(e_d, eff_end)
        while d <= stop:
            iso = d.isoformat()
            # attendance status wins if present; otherwise fill from leave
            leave_by_date[iso] = "paid_leave" if is_paid else "unpaid_leave"
            d = d + timedelta(days=1)

    # Walk every day in window and classify
    present_days = 0.0
    half_days = 0.0
    paid_leave_days = 0.0
    unpaid_leave_days = 0.0
    absent_days = 0.0
    unmarked_absent_days = 0.0
    cur = eff_start
    while cur <= eff_end:
        iso = cur.isoformat()
        # 1) holidays / weekly off = paid, no counting
        if iso in window_off_dates or cur.strftime("%A").lower() in weekly_off_weekdays:
            cur = cur + timedelta(days=1)
            continue
        # 2) attendance row wins
        att = att_by_date.get(iso)
        if att:
            st = att.get("status")
            if st == "present":
                present_days += 1
            elif st == "half":
                half_days += 1
            elif st == "absent":
                absent_days += 1
            elif st == "unpaid_leave":
                unpaid_leave_days += 1
            elif st in ("leave", "paid_leave"):
                paid_leave_days += 1
            else:
                # Unknown status — treat as absent to be safe
                absent_days += 1
        # 3) approved leave for this date
        elif iso in leave_by_date:
            if leave_by_date[iso] == "paid_leave":
                paid_leave_days += 1
            else:
                unpaid_leave_days += 1
        # 4) no record + working day = UNMARKED ABSENT (the critical bug fix)
        else:
            unmarked_absent_days += 1
        cur = cur + timedelta(days=1)

    total_absent = absent_days + unmarked_absent_days
    unpaid_days = total_absent + unpaid_leave_days + (half_days * 0.5)
    # (payable_days is computed below after per_day, per Phase 45 spec.)

    # Late buckets
    shift = None
    if s.get("shift_id"):
        shift = await db.shifts.find_one({"id": s["shift_id"]}, {"_id": 0})
    buckets = _compute_late_buckets(rows, shift)
    late_days = (buckets["minor"] // 3) + 0.5 * buckets["half_day"] + 1.0 * buckets["full_day"]

    # PHASE 45 — Per-day rate now uses TOTAL DAYS OF THE CALENDAR MONTH
    # (last_day) as the divisor per revised user spec:
    #   Payable Salary = (Monthly Salary ÷ Total Days in the Month) × Payable Days
    # This prevents mid-month joiners from earning more than CTC (previously
    # working_days = 15 for a mid-month joiner made per_day artificially high).
    if s.get("per_day_rate", 0):
        per_day = float(s["per_day_rate"])
    elif last_day > 0:
        per_day = (s.get("monthly_salary", 0) or 0) / last_day
    else:
        per_day = 0
    late_deduction = round(late_days * per_day, 2)

    # PHASE 58 — Payable Days = Present + Half×0.5 + Paid Leave + Weekly Off + Holidays.
    # Per revised policy (Feb 2026): BOTH weekly-off and holidays count toward payable days
    # so an employee who was present every working day is paid for the full calendar month.
    # Working Days (denominator for progress display) stays = total_days − weekly_off − holidays.
    # (Half-day contributes 0.5 because a half-day worked is still partially paid.)
    payable_days = present_days + (half_days * 0.5) + paid_leave_days + weekly_off_count + holiday_count

    # PHASE 47 — Zero-Attendance Rule (highest priority). If the employee has
    # NO valid attendance days in the effective window (no present, no half,
    # no paid leave), their salary must be ₹0 regardless of configured monthly
    # salary or number of holidays in the window. Holidays/weekly-off are only
    # "paid" when the employee is otherwise on the job. This mirrors real HR
    # policy: someone who never showed up doesn't get holiday pay either.
    valid_att_days = present_days + half_days + paid_leave_days
    if valid_att_days <= 0:
        payable_days = 0

    # Earnings = per_day × payable_days.
    # This gives ZERO salary for zero attendance (the critical fix from Phase 43),
    # and caps a mid-month joiner's salary at their proportional share.
    basic = round(per_day * payable_days, 2)
    attendance_deduction = round(per_day * unpaid_days, 2)

    return {
        "days_present": present_days,
        "present_days": present_days,
        "half_days": half_days,
        "paid_leave_days": paid_leave_days,
        "unpaid_leave_days": unpaid_leave_days,
        "absent_days": round(total_absent, 2),
        "unmarked_absent_days": round(unmarked_absent_days, 2),
        "unpaid_days": round(unpaid_days, 2),
        "payable_days": round(payable_days, 2),
        "working_days": working_days,
        "total_days": total_days,
        "weekly_off_days": weekly_off_count,
        "holiday_days": holiday_count,
        "per_day_rate_effective": round(per_day, 2),
        "attendance_deduction_display": attendance_deduction,
        "employment_window": {"start": att_start, "end": att_end},
        "is_partial_month": working_days < last_day,
        "base_salary": s.get("monthly_salary", 0),
        "per_day_rate": s.get("per_day_rate", 0),
        "basic": basic,
        "late_deduction": late_deduction,
        "late_buckets": buckets,
        "late_days": late_days,
    }


def _compute_late_buckets(rows: List[dict], shift: Optional[dict]) -> dict:
    """Walk attendance rows; for each present day compute late_minutes vs shift start+grace.
    Returns {minor: N, half_day: N, full_day: N, total_late_minutes: M} per user-defined rules:
      - <2h late  → minor (every 3 minor = 1 full day deduct)
      - 2h ≤ x < 6h → half_day count
      - ≥6h → full_day count
    If no shift configured for the staff, returns all zeros (no penalty).
    """
    out = {"minor": 0, "half_day": 0, "full_day": 0, "total_late_minutes": 0}
    if not shift or not shift.get("start_time"):
        return out
    try:
        sh_h, sh_m = (int(x) for x in shift["start_time"].split(":"))
    except (ValueError, AttributeError):
        return out
    shift_start_min = sh_h * 60 + sh_m
    grace = int(shift.get("grace_minutes") or 0)
    for r in rows:
        if r.get("status") != "present":
            continue
        check_in = r.get("check_in_at") or r.get("marked_at")
        if not check_in:
            continue
        try:
            dt = datetime.fromisoformat(check_in.replace("Z", "+00:00"))
            ci_min = dt.hour * 60 + dt.minute
        except (ValueError, AttributeError):
            continue
        late = ci_min - shift_start_min - grace
        if late <= 0:
            continue
        out["total_late_minutes"] += late
        if late >= 360:           # ≥ 6 hours
            out["full_day"] += 1
        elif late >= 120:         # 2 – 6 hours
            out["half_day"] += 1
        else:                     # < 2 hours
            out["minor"] += 1
    return out


@api.post("/payroll/run")
async def payroll_run(
    month: int = Query(..., ge=1, le=12),
    year: int = Query(..., ge=2020, le=2100),
    center_id: Optional[str] = Query(None, description="Center to run payroll for. Omit or 'all' for every center."),
    _=Depends(require_role("admin", "accountant", "hr")),
):
    """Generate payroll rows for staff who were actually employed in the given month.

    Phase 60 — Center scoping:
      * `center_id=<id>` → only staff mapped to that center are processed
      * `center_id="all"` or omitted → every active staff record is processed
        (the finalise step later splits them into one batch per center)

    Employment window filter:
      * Skip staff who joined AFTER the month (joining_date > month-end).
      * Skip staff who exited BEFORE the month (exit_date < month-start).
      * For staff joining or exiting mid-month, `working_days` is set to the
        intersection of their employment window with the calendar month, so
        pro-rated basic pay reflects only the days they were actually on payroll.

    Late penalty (existing rules unchanged):
      - <2h late  → minor: every 3 minor counts = 1 day deducted
      - 2h-6h     → half-day (0.5 day deducted)
      - ≥6h       → full-day (1 day deducted)

    PHASE 37 — Weekly Off + Holidays are now PAID days that do NOT reduce salary.
    Working Days = Total Days − Weekly Off − Holidays (info-only).
    Salary deduction happens ONLY for `absent` and `unpaid_leave`, plus the
    late-penalty above. Paid `leave` / `weekly_off` / `holiday` statuses cost
    zero.
    """
    import calendar
    last_day = calendar.monthrange(year, month)[1]
    start = f"{year:04d}-{month:02d}-01"
    end = f"{year:04d}-{month:02d}-{last_day:02d}"

    # PHASE 42 — Load holiday + weekly-off dates for the month ONCE.
    paid_off_dates, weekly_off_weekdays = await _paid_off_dates_in(start, end)

    staff_query: dict = {"active": {"$ne": False}}
    if center_id and center_id not in ("all", ""):
        staff_query["center_id"] = center_id
    staff_docs = await db.staff.find(staff_query, {"_id": 0}).to_list(5000)
    created: list = []
    updated: list = []
    skipped_not_employed = 0
    skipped_locked = 0
    for s in staff_docs:
        computed = await _compute_payroll_for_staff(s, month, year, paid_off_dates, weekly_off_weekdays)
        if computed is None:
            skipped_not_employed += 1
            continue

        # Auto-fill advance deduction (as before)
        adv_rows = await db.advance_requests.find({
            "created_by": s.get("user_id"),
            "status": {"$in": ["released", "adjusting"]},
            "balance_amount": {"$gt": 0},
        }, {"_id": 0}).to_list(50)
        adv_details: list = []
        adv_total = 0.0
        for a in adv_rows:
            scheduled = float(a.get("pending_salary_deduction") or 0)
            bal = float(a.get("balance_amount") or 0)
            take = scheduled if scheduled > 0 else bal
            take = min(take, bal)
            if take <= 0:
                continue
            adv_details.append({
                "advance_id": a["id"],
                "advance_no": a.get("advance_no"),
                "balance_before": bal,
                "amount": round(take, 2),
                "reason": "scheduled" if scheduled > 0 else "auto_full_balance",
            })
            adv_total += take

        existing = await db.payroll.find_one({"staff_id": s["id"], "month": month, "year": year})
        if existing:
            # Update DRAFT rows in-place; locked rows are left untouched.
            if existing.get("status") != "draft":
                skipped_locked += 1
                continue
            merged = {**existing, **computed}
            merged["advance"] = round(adv_total, 2)
            merged["advance_deductions_details"] = adv_details
            _recalc_payroll(merged)
            merged["edited_by"] = "system_recalc"
            merged["edited_at"] = datetime.now(timezone.utc).isoformat()
            await db.payroll.update_one({"id": existing["id"]}, {"$set": {
                k: merged[k] for k in merged if k != "_id"
            }})
            merged.pop("_id", None)
            updated.append(merged)
            continue

        doc = {
            "id": str(uuid.uuid4()),
            "staff_id": s["id"],
            "staff_name": s.get("name"),
            "month": month, "year": year,
            **computed,
            "hra": 0.0, "da": 0.0, "conveyance": 0.0,
            "bonus": 0.0, "incentive": 0.0,
            "overtime_pay": 0.0, "other_earnings": 0.0,
            "reimbursements_paid": 0.0,
            "pf_deduction": 0.0, "esi_deduction": 0.0,
            "early_fine": 0.0,
            "advance": round(adv_total, 2),
            "loan_deduction": 0.0,
            "advance_deductions_details": adv_details,
            "other_deductions": [],
            "gross": 0.0, "deductions": 0.0, "net": 0.0,
            "status": "draft",
            "txn_id": None, "paid_at": None,
            "remarks": None,
            "edited_by": None, "edited_at": None,
            "created_at": datetime.now(timezone.utc).isoformat(),
        }
        _recalc_payroll(doc)
        await db.payroll.insert_one(doc)
        doc.pop("_id", None)
        created.append(doc)
    return {"created": len(created), "updated": len(updated),
            "skipped_not_employed": skipped_not_employed,
            "skipped_locked": skipped_locked, "rows": created + updated}


@api.post("/payroll/{pid}/recalc")
async def recalc_payroll(pid: str, user=Depends(require_role("admin", "hr", "accountant"))):
    """Recalculate a draft/calculated payroll row against the LATEST attendance +
    approved leaves. Locked payrolls (approved/paid) cannot be recalculated."""
    rec = await db.payroll.find_one({"id": pid}, {"_id": 0})
    if not rec:
        raise HTTPException(404, "Payroll not found")
    if rec.get("status") in ("approved", "paid"):
        raise HTTPException(400, "Approved/Paid payroll cannot be recalculated. Reverse first.")
    s = await db.staff.find_one({"id": rec["staff_id"]}, {"_id": 0})
    if not s:
        raise HTTPException(404, "Linked staff not found")
    import calendar
    month, year = int(rec["month"]), int(rec["year"])
    last_day = calendar.monthrange(year, month)[1]
    start = f"{year:04d}-{month:02d}-01"
    end = f"{year:04d}-{month:02d}-{last_day:02d}"
    paid_off_dates, weekly_off_weekdays = await _paid_off_dates_in(start, end)
    computed = await _compute_payroll_for_staff(s, month, year, paid_off_dates, weekly_off_weekdays)
    if computed is None:
        raise HTTPException(400, "Staff was not employed during this month")
    merged = {**rec, **computed}
    _recalc_payroll(merged)
    merged["edited_by"] = user["id"]
    merged["edited_at"] = datetime.now(timezone.utc).isoformat()
    await db.payroll.update_one({"id": pid}, {"$set": {k: merged[k] for k in merged if k != "_id"}})
    return await db.payroll.find_one({"id": pid}, {"_id": 0})


@api.patch("/payroll/{pid}")
async def edit_payroll(pid: str, body: PayrollEditIn, user=Depends(require_role("admin", "hr"))):
    """Admin/HR can override any payroll component. Net auto-recalculated."""
    rec = await db.payroll.find_one({"id": pid}, {"_id": 0})
    if not rec:
        raise HTTPException(404, "Not found")
    if rec.get("status") == "paid":
        raise HTTPException(400, "Cannot edit a paid payslip. Reverse the payment first.")
    update = body.model_dump(exclude_none=True)
    if "other_deductions" in update:
        update["other_deductions"] = [li if isinstance(li, dict) else li.model_dump() for li in update["other_deductions"]]
    merged = {**rec, **update}
    _recalc_payroll(merged)
    merged["edited_by"] = user["id"]
    merged["edited_at"] = datetime.now(timezone.utc).isoformat()
    await db.payroll.update_one({"id": pid}, {"$set": {k: merged[k] for k in (
        "days_present", "basic", "hra", "da", "conveyance", "bonus", "incentive",
        "overtime_pay", "other_earnings", "reimbursements_paid",
        "pf_deduction", "esi_deduction", "late_deduction", "early_fine",
        "advance", "loan_deduction", "other_deductions",
        "gross", "deductions", "net", "remarks", "edited_by", "edited_at",
    ) if k in merged}})
    res = await db.payroll.find_one({"id": pid}, {"_id": 0})
    return res


@api.get("/payroll")
async def list_payroll(
    month: Optional[int] = None, year: Optional[int] = None,
    q: Optional[str] = None,
    status: Optional[str] = None,
    skip: int = 0,
    limit: int = 5000,
    user=Depends(get_current_user),
):
    # Payroll rows are salary-sensitive: only admin/hr/accountant/senior_manager/manager
    # /center_manager/center_staff can see the payroll roster. Staff (or any other role)
    # must use `/payroll/my` which scopes to their own linked staff record.
    if user.get("role") not in ("admin", "hr", "accountant", "senior_manager", "manager", "center_manager", "center_staff"):
        raise HTTPException(403, "Only HR / Accounts / Admin can view the full payroll list. Use /payroll/my for your own salary.")
    query: dict = {}
    # Phase 65 — center-based scoping. Payroll rows carry the staff_id, so we
    # first resolve which staff belong to the user's scope, then filter by
    # staff_id. Head-level users skip this entirely.
    allowed = _scoped_center_ids(user)
    if allowed is not None:
        if not allowed:
            from starlette.responses import JSONResponse
            return JSONResponse(content=[], headers={"X-Total-Count": "0",
                "Access-Control-Expose-Headers": "X-Total-Count"})
        allowed_staff = await db.staff.find(
            {"center_id": {"$in": allowed}}, {"_id": 0, "id": 1},
        ).to_list(10000)
        query["staff_id"] = {"$in": [s["id"] for s in allowed_staff]}
    if month:
        query["month"] = month
    if year:
        query["year"] = year
    if status and status != "all":
        query["status"] = status
    if q:
        needle = q.strip()
        if needle:
            rx = {"$regex": needle, "$options": "i"}
            query["staff_name"] = rx
    total = await db.payroll.count_documents(query)
    cursor = db.payroll.find(query, {"_id": 0}).sort([("year", -1), ("month", -1), ("staff_name", 1)])
    if skip:
        cursor = cursor.skip(skip)
    if limit:
        cursor = cursor.limit(min(limit, 5000))
    docs = await cursor.to_list(min(limit or 5000, 5000))
    from starlette.responses import JSONResponse
    return JSONResponse(
        content=docs,
        headers={"X-Total-Count": str(total), "Access-Control-Expose-Headers": "X-Total-Count"},
    )


@api.get("/payroll/bank-csv")
async def payroll_bank_csv(month: int = Query(..., ge=1, le=12), year: int = Query(..., ge=2020, le=2100),
                           status: str = Query("draft", pattern="^(draft|paid|all)$"),
                           _=Depends(require_role("admin", "accountant", "hr"))):
    """Download a bank-transfer CSV for the given month — one row per staff with
    bank details + net amount. Only includes staff with verified bank + non-zero net.
    """
    import io
    q: dict = {"month": month, "year": year}
    if status != "all":
        q["status"] = status
    rows = await db.payroll.find(q, {"_id": 0}).sort("staff_name", 1).to_list(5000)
    staff_ids = [r["staff_id"] for r in rows]
    staff_map = {s["id"]: s for s in await db.staff.find({"id": {"$in": staff_ids}}, {"_id": 0}).to_list(5000)}
    buf = io.StringIO()
    writer = csv.writer(buf)
    writer.writerow(["Staff Name", "Account Holder", "Bank Name", "Account No", "IFSC", "Verified", "Net Amount (₹)", "Period", "Notes"])
    skipped = 0
    written = 0
    for r in rows:
        s = staff_map.get(r["staff_id"]) or {}
        if not s.get("bank_account_no") or not s.get("ifsc"):
            skipped += 1
            continue
        if (r.get("net") or 0) <= 0:
            skipped += 1
            continue
        writer.writerow([
            r.get("staff_name") or s.get("name") or "",
            s.get("account_holder_name") or s.get("name") or "",
            s.get("bank_name") or "",
            s.get("bank_account_no") or "",
            s.get("ifsc") or "",
            "Yes" if s.get("bank_verified") else "No",
            round(r.get("net") or 0, 2),
            f"{month:02d}/{year}",
            r.get("remarks") or "",
        ])
        written += 1
    csv_bytes = buf.getvalue().encode("utf-8")
    return Response(
        content=csv_bytes,
        media_type="text/csv",
        headers={
            "Content-Disposition": f'attachment; filename="payroll_bank_{year}_{month:02d}.csv"',
            "X-Rows-Written": str(written),
            "X-Rows-Skipped": str(skipped),
        },
    )


@api.get("/payroll/my")
async def my_payroll(year: Optional[int] = None, user=Depends(get_current_user)):
    """Current logged-in staff's own payroll/salary history."""
    staff = await db.staff.find_one({"user_id": user["id"]}, {"_id": 0, "id": 1, "name": 1, "designation": 1, "monthly_salary": 1, "per_day_rate": 1, "bank_name": 1, "bank_account_no": 1, "ifsc": 1, "bank_verified": 1, "bank_verified_at": 1})
    if not staff:
        return {"staff": None, "payroll": []}
    q: dict = {"staff_id": staff["id"]}
    if year:
        q["year"] = year
    docs = await db.payroll.find(q, {"_id": 0}).sort([("year", -1), ("month", -1)]).to_list(120)
    # Mask bank_account_no for safety
    if staff.get("bank_account_no"):
        staff["bank_account_no_masked"] = "****" + staff["bank_account_no"][-4:]
        staff.pop("bank_account_no", None)
    return {"staff": staff, "payroll": docs}


# =========================================================================
# STAFF SALARY DETAIL (SalaryBox-style) + monthly attendance breakdown
# =========================================================================
@api.get("/payroll/staff/{staff_id}/summary")
async def staff_salary_summary(
    staff_id: str,
    month: Optional[int] = Query(None, ge=1, le=12),
    year: Optional[int] = Query(None, ge=2020, le=2100),
    user=Depends(require_role("admin", "hr", "accountant", "senior_manager")),
):
    """Returns a per-employee salary detail sheet for the given month plus
    a rolling history table. Used by the new HR "Salary Detail" screen.
    Structure:
      {
        staff: {..basic + bank..},
        current: {month, year, attendance:{present,half,absent,leave,working_days,late_days,paid_leaves},
                  payroll: {..full payroll doc..}, reimbursements_approved: N},
        history: [{month, year, ctc, payables, total_salary, paid, pending, slip_shared, status}]
      }
    """
    import calendar
    staff = await db.staff.find_one({"id": staff_id}, {"_id": 0})
    if not staff:
        raise HTTPException(404, "Staff not found")

    # Default to current month/year if not passed
    now = datetime.now(timezone.utc)
    m = month or now.month
    y = year or now.year
    last_day = calendar.monthrange(y, m)[1]
    d_start = f"{y:04d}-{m:02d}-01"
    d_end = f"{y:04d}-{m:02d}-{last_day:02d}"

    # Attendance breakdown for the month — enhanced (Phase 44) with paid/unpaid
    # leave, unmarked, weekly-off + holiday classification. Uses the same
    # source-of-truth algorithm as the payroll computation so numbers match.
    paid_off_dates, weekly_off_weekdays = await _paid_off_dates_in(d_start, d_end)
    att_rows = await db.attendance.find(
        {"staff_id": staff_id, "date": {"$gte": d_start, "$lte": d_end}},
        {"_id": 0},
    ).to_list(500)
    att_by_date = {r["date"]: r for r in att_rows}

    # Full-month per-day view (Phase 54) — one row per date so the report shows
    # every day of the selected month, not just days with an attendance record.
    # Priority: attendance row > approved leave > holiday > weekly-off > absent.
    # Regularised rows are ALWAYS treated as present (never "incomplete").
    _WEEKDAY_INT = {"monday":0,"tuesday":1,"wednesday":2,"thursday":3,"friday":4,"saturday":5,"sunday":6}
    weekly_off_ints = {_WEEKDAY_INT[n] for n in (weekly_off_weekdays or set()) if n in _WEEKDAY_INT}
    holidays_rows = await db.holidays.find(
        {"date": {"$gte": d_start, "$lte": d_end}}, {"_id": 0, "date": 1, "name": 1},
    ).to_list(60)
    holidays_by_date = {h["date"]: h for h in holidays_rows}
    leave_rows = await db.leaves.find(
        {
            "staff_id": staff_id, "status": "approved",
            "start_date": {"$lte": d_end}, "end_date": {"$gte": d_start},
        },
        {"_id": 0},
    ).to_list(100)
    leave_days = {}
    for lv in leave_rows:
        try:
            _ls = datetime.fromisoformat(lv["start_date"]).date()
            _le = datetime.fromisoformat(lv["end_date"]).date()
        except (ValueError, KeyError):
            continue
        _cur = _ls
        while _cur <= _le:
            _iso = _cur.isoformat()
            if d_start <= _iso <= d_end:
                leave_days[_iso] = lv
            _cur += timedelta(days=1)

    today_ist = _today_ist()
    daily_rows: List[dict] = []
    for _d in range(1, last_day + 1):
        iso = f"{y:04d}-{m:02d}-{_d:02d}"
        wd = datetime(y, m, _d).weekday()  # 0=Mon
        row = att_by_date.get(iso)
        holiday = holidays_by_date.get(iso)
        leave = leave_days.get(iso)
        is_week_off = wd in weekly_off_ints
        is_future = iso > today_ist
        if row:
            # Effective status — regularised approvals are ALWAYS present, even if
            # the raw row was auto-closed as "incomplete" earlier (fix for Phase 54).
            raw = row.get("status")
            if row.get("regularised") or row.get("marked_via") == "regularised":
                effective = row.get("status") if row.get("status") in ("present", "half") else "present"
            elif raw in ("incomplete", "auto_closed"):
                effective = "incomplete"
            elif raw in ("present", "half", "absent", "leave"):
                effective = raw
            elif row.get("check_in_at") and not row.get("check_out_at"):
                effective = "incomplete"
            else:
                effective = raw or "absent"
            daily_rows.append({
                **row,
                "id": row.get("id") or f"synth-{iso}",
                "date": iso,
                "status": effective,
                "raw_status": raw,
                "synthetic": False,
                "is_regularised": bool(row.get("regularised") or row.get("marked_via") == "regularised"),
                "holiday_name": (holiday or {}).get("name"),
                "is_week_off": is_week_off,
            })
        else:
            # No attendance row → derive from leave / holiday / week-off / future / absent.
            if leave:
                # Distinguish paid vs unpaid leave — attendance report treats both as "leave"
                # for the Status column, but records the leave_type for detail views.
                syn = {"id": f"synth-{iso}", "date": iso, "status": "leave", "synthetic": True,
                       "marked_via": "leave", "leave_id": leave.get("id"),
                       "leave_type_id": leave.get("leave_type_id"), "leave_reason": leave.get("reason")}
            elif holiday:
                syn = {"id": f"synth-{iso}", "date": iso, "status": "holiday", "synthetic": True,
                       "marked_via": "holiday", "holiday_name": holiday.get("name")}
            elif is_week_off:
                syn = {"id": f"synth-{iso}", "date": iso, "status": "week_off", "synthetic": True,
                       "marked_via": "policy"}
            elif is_future:
                syn = {"id": f"synth-{iso}", "date": iso, "status": "upcoming", "synthetic": True,
                       "marked_via": ""}
            else:
                syn = {"id": f"synth-{iso}", "date": iso, "status": "absent", "synthetic": True,
                       "marked_via": ""}
            syn["is_week_off"] = is_week_off
            syn["holiday_name"] = (holiday or {}).get("name")
            syn["is_regularised"] = False
            daily_rows.append(syn)

    # Legacy simple counts (kept for backward compat with existing UI)
    att_breakdown = {"present": 0.0, "half": 0.0, "absent": 0.0, "leave": 0.0,
                     "working_days": last_day, "days_marked": len(att_rows)}
    for r in att_rows:
        s_ = r.get("status")
        if s_ in att_breakdown:
            if s_ == "half":
                att_breakdown["half"] += 1
                att_breakdown["present"] += 0.5  # counted toward pay
            else:
                att_breakdown[s_] += 1

    # Phase 44 — Rich breakdown consistent with payroll math.
    computed_att = await _compute_payroll_for_staff(
        staff, m, y, paid_off_dates, weekly_off_weekdays,
    ) if staff.get("monthly_salary") is not None else None
    att_rich = {}
    if computed_att:
        att_rich = {
            "total_calendar_days": computed_att["total_days"],
            "payroll_working_days": computed_att["working_days"],
            "present_days": computed_att["present_days"],
            "half_days": computed_att["half_days"],
            "paid_leave_days": computed_att["paid_leave_days"],
            "unpaid_leave_days": computed_att["unpaid_leave_days"],
            "absent_days": computed_att["absent_days"],
            "unmarked_absent_days": computed_att["unmarked_absent_days"],
            "weekly_off_days": computed_att["weekly_off_days"],
            "holiday_days": computed_att["holiday_days"],
            "payable_days": computed_att["payable_days"],
            "unpaid_days": computed_att["unpaid_days"],
            "per_day_rate": computed_att["per_day_rate_effective"],
            "attendance_deduction_display": computed_att["attendance_deduction_display"],
            "employment_window": computed_att["employment_window"],
        }
    # Merge rich fields into legacy breakdown so both keys are available.
    att_breakdown.update(att_rich)

    # Payroll doc (may or may not exist yet)
    pr = await db.payroll.find_one({"staff_id": staff_id, "month": m, "year": y}, {"_id": 0})

    # Approved reimbursements this month for context
    approved_reimb = await db.reimbursements.count_documents({
        "staff_id": staff_id, "status": {"$in": ["approved", "paid"]},
        "date": {"$gte": d_start, "$lte": d_end},
    })

    # History (last 12 months, DESC)
    hist_docs = await db.payroll.find({"staff_id": staff_id}, {"_id": 0}) \
        .sort([("year", -1), ("month", -1)]).to_list(24)
    history = []
    for h in hist_docs:
        gross = h.get("gross", 0) or 0
        ded = h.get("deductions", 0) or 0
        net = h.get("net", 0) or 0
        paid = net if h.get("status") == "paid" else 0
        history.append({
            "id": h.get("id"),
            "month": h.get("month"),
            "year": h.get("year"),
            "ctc": staff.get("monthly_salary") or 0,
            "payables": gross,
            "deductions": ded,
            "total_salary": net,
            "paid": paid,
            "pending": max(0, net - paid),
            "status": h.get("status"),
            "slip_shared": bool(h.get("slip_released_at")),
            "paid_at": h.get("paid_at"),
        })

    # Mask account
    if staff.get("bank_account_no"):
        staff["bank_account_no_masked"] = "****" + staff["bank_account_no"][-4:]
        staff.pop("bank_account_no", None)

    return {
        "staff": staff,
        "current": {
            "month": m, "year": y,
            "attendance": att_breakdown,
            "attendance_rows": daily_rows,
            "payroll": pr,
            "reimbursements_approved": approved_reimb,
        },
        "history": history,
        "_editor": user["id"],
    }


