# HRMS DOWNLOADABLE REPORTS
# =========================================================================
def _csv_response(filename: str, rows: List[list], headers: List[str]) -> "Response":
    """Small helper – emits a CSV response with a filename Content-Disposition."""
    import csv, io
    buf = io.StringIO()
    w = csv.writer(buf)
    w.writerow(headers)
    for r in rows:
        w.writerow(r)
    from fastapi.responses import Response as _R
    return _R(
        content=buf.getvalue(),
        media_type="text/csv; charset=utf-8",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )


@api.get("/reports/attendance")
async def report_attendance(
    month: int = Query(..., ge=1, le=12),
    year: int = Query(..., ge=2020, le=2100),
    staff_id: Optional[str] = None,
    center_id: Optional[str] = None,
    user=Depends(require_role("admin", "hr", "accountant", "senior_manager", "manager", "center_manager")),
):
    """Per-day attendance CSV for a month. Filters by staff or center."""
    import calendar
    last_day = calendar.monthrange(year, month)[1]
    d_start = f"{year:04d}-{month:02d}-01"
    d_end = f"{year:04d}-{month:02d}-{last_day:02d}"

    staff_q: dict = {"active": {"$ne": False}}
    if staff_id:
        staff_q["id"] = staff_id
    # SECURITY (center isolation): restrict staff to the user's authorized centers.
    _scope_staff_query(user, staff_q, center_id)
    staff_list = await db.staff.find(staff_q, {"_id": 0, "id": 1, "name": 1, "employee_code": 1, "center_id": 1, "designation": 1}).to_list(2000)
    ids = [s["id"] for s in staff_list]

    att_rows = await db.attendance.find(
        {"staff_id": {"$in": ids}, "date": {"$gte": d_start, "$lte": d_end}},
        {"_id": 0},
    ).to_list(20000)
    by_key = {(r["staff_id"], r["date"]): r for r in att_rows}

    centers = {c["id"]: c.get("name") for c in await db.centers.find(
        {"id": {"$in": list({s.get("center_id") for s in staff_list if s.get("center_id")})}},
        {"_id": 0, "id": 1, "name": 1}).to_list(500)}

    rows = []
    for s in staff_list:
        for day in range(1, last_day + 1):
            date_iso = f"{year:04d}-{month:02d}-{day:02d}"
            att = by_key.get((s["id"], date_iso), {})
            def _fmt(ts):
                if not ts: return ""
                try:
                    dt = datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    # PHASE 46 — Convert UTC → IST so CSV matches the UI clock.
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=timezone.utc)
                    return dt.astimezone(BUSINESS_TZ).strftime("%H:%M")
                except (ValueError, AttributeError):
                    return ""
            ci = att.get("check_in_at")
            co = att.get("check_out_at")
            hours = ""
            if ci and co:
                try:
                    delta = datetime.fromisoformat(co.replace("Z", "+00:00")) - datetime.fromisoformat(ci.replace("Z", "+00:00"))
                    hours = round(delta.total_seconds() / 3600, 2)
                except (ValueError, AttributeError):
                    hours = ""
            rows.append([
                s.get("employee_code") or "",
                s.get("name") or "",
                s.get("designation") or "",
                centers.get(s.get("center_id")) or "",
                date_iso,
                (att.get("status") or "-").upper(),
                _fmt(ci), _fmt(co), hours,
                (att.get("marked_via") or "").upper(),
            ])
    return _csv_response(
        f"attendance_{year:04d}-{month:02d}.csv",
        rows,
        ["Emp Code", "Name", "Designation", "Center", "Date", "Status", "Punch In", "Punch Out", "Hours", "Marked Via"],
    )


@api.get("/reports/payroll")
async def report_payroll(
    month: int = Query(..., ge=1, le=12),
    year: int = Query(..., ge=2020, le=2100),
    staff_id: Optional[str] = None,
    user=Depends(require_role("admin", "hr", "accountant", "senior_manager")),
):
    """Comprehensive payroll CSV (earnings + deductions + bank details) for the month."""
    q: dict = {"month": month, "year": year}
    if staff_id:
        q["staff_id"] = staff_id
    # SECURITY (center isolation): restrict payroll to staff in authorized centers.
    allowed_centers = _scoped_center_ids(user)
    if allowed_centers is not None:
        scoped_staff = await db.staff.find(
            {"center_id": {"$in": list(allowed_centers) if allowed_centers else ["__none__"]}},
            {"_id": 0, "id": 1},
        ).to_list(20000)
        allowed_staff_ids = {s["id"] for s in scoped_staff}
        if staff_id:
            if staff_id not in allowed_staff_ids:
                raise HTTPException(status_code=403, detail="Not authorized for this staff member")
        else:
            q["staff_id"] = {"$in": list(allowed_staff_ids)}
    docs = await db.payroll.find(q, {"_id": 0}).to_list(5000)
    sids = list({d["staff_id"] for d in docs})
    staffs = {s["id"]: s for s in await db.staff.find(
        {"id": {"$in": sids}},
        {"_id": 0, "id": 1, "employee_code": 1, "name": 1, "designation": 1,
         "monthly_salary": 1, "bank_name": 1, "bank_account_no": 1, "ifsc": 1,
         "center_id": 1, "pan": 1},
    ).to_list(5000)}
    centers = {c["id"]: c.get("name") for c in await db.centers.find(
        {"id": {"$in": list({s.get("center_id") for s in staffs.values() if s.get("center_id")})}},
        {"_id": 0, "id": 1, "name": 1}).to_list(500)}

    rows = []
    for p in docs:
        s = staffs.get(p["staff_id"], {})
        rows.append([
            s.get("employee_code") or "",
            p.get("staff_name") or s.get("name") or "",
            s.get("designation") or "",
            centers.get(s.get("center_id")) or "",
            f"{p.get('year')}-{p.get('month'):02d}",
            p.get("days_present") or 0,
            p.get("working_days") or 0,
            s.get("monthly_salary") or 0,
            p.get("basic") or 0,
            p.get("hra") or 0,
            p.get("da") or 0,
            p.get("conveyance") or 0,
            p.get("bonus") or 0,
            p.get("incentive") or 0,
            p.get("overtime_pay") or 0,
            p.get("other_earnings") or 0,
            p.get("reimbursements_paid") or 0,
            p.get("gross") or 0,
            p.get("pf_deduction") or 0,
            p.get("esi_deduction") or 0,
            p.get("late_deduction") or 0,
            p.get("early_fine") or 0,
            p.get("advance") or 0,
            p.get("loan_deduction") or 0,
            p.get("deductions") or 0,
            p.get("net") or 0,
            (p.get("status") or "").upper(),
            p.get("paid_at") or "",
            s.get("bank_name") or "",
            s.get("bank_account_no") or "",
            s.get("ifsc") or "",
            s.get("pan") or "",
        ])
    return _csv_response(
        f"payroll_{year:04d}-{month:02d}.csv",
        rows,
        ["Emp Code", "Name", "Designation", "Center", "Month",
         "Days Present", "Working Days", "CTC",
         "Basic", "HRA", "DA", "Conveyance", "Bonus", "Incentive", "Overtime", "Other Earnings", "Reimb Paid",
         "Gross",
         "PF", "ESI", "Late Fine", "Early Fine", "Advance", "Loan EMI", "Total Deductions",
         "Net", "Status", "Paid At",
         "Bank Name", "Account #", "IFSC", "PAN"],
    )


@api.get("/reports/consolidated")
async def report_consolidated(
    month: int = Query(..., ge=1, le=12),
    year: int = Query(..., ge=2020, le=2100),
    staff_id: Optional[str] = None,
    center_id: Optional[str] = None,
    user=Depends(require_role("admin", "hr", "accountant", "senior_manager")),
):
    """One CSV row per staff for the month: attendance summary + payroll + bank."""
    import calendar
    last_day = calendar.monthrange(year, month)[1]
    d_start = f"{year:04d}-{month:02d}-01"
    d_end = f"{year:04d}-{month:02d}-{last_day:02d}"

    sq: dict = {"active": {"$ne": False}}
    if staff_id:
        sq["id"] = staff_id
    # SECURITY (center isolation): restrict staff to the user's authorized centers.
    _scope_staff_query(user, sq, center_id)
    staff_list = await db.staff.find(sq, {"_id": 0}).to_list(5000)
    sids = [s["id"] for s in staff_list]

    att_rows = await db.attendance.find(
        {"staff_id": {"$in": sids}, "date": {"$gte": d_start, "$lte": d_end}},
        {"_id": 0, "staff_id": 1, "status": 1},
    ).to_list(20000)
    counts: dict = {}
    for r in att_rows:
        c = counts.setdefault(r["staff_id"], {"present": 0.0, "half": 0, "absent": 0, "leave": 0})
        st = r.get("status")
        if st == "half":
            c["half"] += 1
            c["present"] += 0.5
        elif st == "present":
            c["present"] += 1
        elif st == "absent":
            c["absent"] += 1
        elif st == "leave":
            c["leave"] += 1

    payrolls = {p["staff_id"]: p for p in await db.payroll.find(
        {"staff_id": {"$in": sids}, "month": month, "year": year}, {"_id": 0}).to_list(5000)}
    centers = {c["id"]: c.get("name") for c in await db.centers.find(
        {"id": {"$in": list({s.get("center_id") for s in staff_list if s.get("center_id")})}},
        {"_id": 0, "id": 1, "name": 1}).to_list(500)}

    rows = []
    for s in staff_list:
        c = counts.get(s["id"], {"present": 0, "half": 0, "absent": 0, "leave": 0})
        p = payrolls.get(s["id"], {})
        rows.append([
            s.get("employee_code") or "",
            s.get("name") or "",
            s.get("designation") or "",
            centers.get(s.get("center_id")) or "",
            f"{year}-{month:02d}",
            last_day,
            c["present"], c["half"], c["absent"], c["leave"],
            s.get("monthly_salary") or 0,
            p.get("gross") or 0,
            p.get("deductions") or 0,
            p.get("net") or 0,
            (p.get("status") or "unpaid").upper(),
            p.get("paid_at") or "",
            s.get("bank_name") or "",
            s.get("bank_account_no") or "",
            s.get("ifsc") or "",
        ])
    return _csv_response(
        f"consolidated_{year:04d}-{month:02d}.csv",
        rows,
        ["Emp Code", "Name", "Designation", "Center", "Month", "Working Days",
         "Present", "Half", "Absent", "Leave",
         "CTC", "Gross", "Deductions", "Net", "Status", "Paid At",
         "Bank Name", "Account #", "IFSC"],
    )


# =========================================================================
# SALARY SLIP TEMPLATES (Phase B) — upload / list / delete
# =========================================================================
@api.post("/salary-slip-templates", status_code=201)
async def upload_salary_slip_template(
    file: UploadFile = File(...),
    company_id: Optional[str] = Query(None),
    user=Depends(require_role("admin", "hr")),
):
    """Upload a `.docx` salary slip template. Optionally scope to a company —
    generation will pick the template matching the staff's center's Default
    Company (falling back to a global template if none per-company).

    Only ONE template per company is active at a time — uploading a new
    template for the same company deactivates the previous one.
    """
    if not file.filename or not file.filename.lower().endswith(".docx"):
        raise HTTPException(400, "Only .docx files are accepted")
    data = await file.read()
    if len(data) > 5 * 1024 * 1024:
        raise HTTPException(413, "Template too large (max 5MB)")
    if company_id:
        c = await db.companies.find_one({"id": company_id}, {"_id": 0, "name": 1})
        if not c:
            raise HTTPException(404, "Company not found")
        company_name = c.get("name")
    else:
        company_name = None
    tid = str(uuid.uuid4())
    path = f"{APP_STORAGE_PREFIX}/salary-slip-templates/{tid}.docx"
    try:
        _put_object(path, data, "application/vnd.openxmlformats-officedocument.wordprocessingml.document")
    except requests.HTTPError as e:
        raise HTTPException(502, f"Storage upload failed: {e}")
    # Deactivate any existing templates for the same company/scope.
    scope_q = {"company_id": company_id, "is_active": True}
    await db.salary_slip_templates.update_many(scope_q, {"$set": {"is_active": False}})
    doc = {
        "id": tid,
        "company_id": company_id,
        "company_name": company_name,
        "filename": file.filename,
        "file_path": path,
        "uploaded_by": user["id"],
        "uploaded_by_name": user.get("name") or user.get("email"),
        "uploaded_at": datetime.now(timezone.utc).isoformat(),
        "is_active": True,
    }
    await db.salary_slip_templates.insert_one(doc)
    doc.pop("_id", None)
    return doc


@api.get("/salary-slip-templates")
async def list_salary_slip_templates(_=Depends(require_role("admin", "hr", "manager"))):
    docs = await db.salary_slip_templates.find({}, {"_id": 0}).sort("uploaded_at", -1).to_list(500)
    return docs


@api.delete("/salary-slip-templates/{tid}", status_code=204)
async def delete_salary_slip_template(tid: str, _=Depends(require_role("admin", "hr"))):
    r = await db.salary_slip_templates.delete_one({"id": tid})
    if r.deleted_count == 0:
        raise HTTPException(404, "Template not found")
    return None


async def _resolve_salary_slip_template(company_id: Optional[str]) -> Optional[dict]:
    """Return active salary slip template for the given company_id — falling
    back to the global default (`company_id: None`)."""
    if company_id:
        tpl = await db.salary_slip_templates.find_one(
            {"company_id": company_id, "is_active": True}, {"_id": 0},
        )
        if tpl:
            return tpl
    return await db.salary_slip_templates.find_one(
        {"company_id": None, "is_active": True}, {"_id": 0},
    )


# =========================================================================
# SALARY SLIP — generate, release, staff-facing download
# =========================================================================
@api.post("/payroll/{pid}/generate-slip")
async def generate_slip(pid: str, user=Depends(require_role("admin", "hr", "accountant"))):
    """Render the salary slip DOCX/PDF for the given payroll row and stash the
    resulting object in storage. Does NOT release the slip to the staff — HR
    must PATCH /release-slip after previewing the file.
    """
    from salary_slip import render_salary_slip
    payroll = await db.payroll.find_one({"id": pid}, {"_id": 0})
    if not payroll:
        raise HTTPException(404, "Payroll row not found")
    staff = await db.staff.find_one({"id": payroll["staff_id"]}, {"_id": 0})
    if not staff:
        raise HTTPException(404, "Staff not found for this payroll row")
    ctx = await _derive_context_for_center(staff.get("center_id"))
    company = await db.companies.find_one({"id": ctx.get("company_id")}, {"_id": 0}) if ctx.get("company_id") else None
    center = await db.centers.find_one({"id": staff.get("center_id")}, {"_id": 0}) if staff.get("center_id") else None
    tpl = await _resolve_salary_slip_template(ctx.get("company_id"))
    if not tpl:
        raise HTTPException(400, "No salary slip template uploaded. Please upload a template first in HR Settings.")
    try:
        template_bytes, _ = _get_object(tpl["file_path"])
    except Exception as e:
        raise HTTPException(502, f"Template fetch failed: {str(e)[:200]}") from e
    try:
        slip_bytes, content_type, ext = render_salary_slip(
            template_bytes=template_bytes, staff=staff, payroll=payroll,
            company=company or {}, center=center,
        )
    except Exception as e:
        logger.exception("Salary slip render failed for payroll %s", pid)
        raise HTTPException(500, f"Slip render failed: {str(e)[:200]}") from e
    slip_id = str(uuid.uuid4())
    safe = (staff.get("name") or "staff").replace(" ", "_")
    filename = f"SalarySlip_{safe}_{payroll['year']}_{payroll['month']:02d}.{ext}"
    file_path = f"{APP_STORAGE_PREFIX}/salary-slips/{slip_id}.{ext}"
    try:
        _put_object(file_path, slip_bytes, content_type)
    except Exception as e:
        raise HTTPException(502, f"Slip upload failed: {str(e)[:200]}") from e
    await db.payroll.update_one({"id": pid}, {"$set": {
        "slip_id": slip_id,
        "slip_path": file_path,
        "slip_filename": filename,
        "slip_content_type": content_type,
        "slip_extension": ext,
        "slip_generated_at": datetime.now(timezone.utc).isoformat(),
        "slip_generated_by": user["id"],
    }})
    return {"ok": True, "slip_id": slip_id, "filename": filename, "extension": ext}


@api.patch("/payroll/{pid}/release-slip")
async def release_slip(pid: str, released: bool = Query(True), user=Depends(require_role("admin", "hr"))):
    """Release (or un-release) an already-generated slip so the staff can see
    it on their /check-in Salary tab.
    """
    payroll = await db.payroll.find_one({"id": pid}, {"_id": 0})
    if not payroll:
        raise HTTPException(404, "Payroll row not found")
    if released and not payroll.get("slip_id"):
        raise HTTPException(400, "Generate the slip first before releasing")
    update = (
        {"slip_released_at": datetime.now(timezone.utc).isoformat(),
         "slip_released_by": user["id"]}
        if released else
        {"slip_released_at": None, "slip_released_by": None}
    )
    await db.payroll.update_one({"id": pid}, {"$set": update})
    return {"ok": True, "released": released}


@api.get("/payroll/{pid}/slip/download")
async def download_slip(pid: str, user=Depends(get_current_user)):
    """Download the generated salary slip.
    * admin/hr/accountant can download any slip after it's generated.
    * staff can only download their OWN slip AFTER release.
    """
    from fastapi.responses import StreamingResponse
    payroll = await db.payroll.find_one({"id": pid}, {"_id": 0})
    if not payroll or not payroll.get("slip_path"):
        raise HTTPException(404, "Slip not generated yet")
    role = user.get("role")
    if role not in ("admin", "hr", "accountant", "senior_manager"):
        # Staff visibility gate — must be their own AND released.
        staff = await db.staff.find_one({"user_id": user["id"]}, {"_id": 0, "id": 1})
        if not staff or staff["id"] != payroll.get("staff_id"):
            raise HTTPException(403, "You can only download your own salary slip")
        if not payroll.get("slip_released_at"):
            raise HTTPException(403, "This slip has not been released by HR yet")
    try:
        data, ct = _get_object(payroll["slip_path"])
    except Exception as e:
        raise HTTPException(502, f"Slip fetch failed: {str(e)[:200]}") from e
    import io as _io
    return StreamingResponse(
        _io.BytesIO(data),
        media_type=payroll.get("slip_content_type") or ct or "application/octet-stream",
        headers={"Content-Disposition": f'attachment; filename="{payroll.get("slip_filename") or f"slip_{pid}.pdf"}"'},
    )


# -------- Holidays --------

async def _paid_off_dates_in(start: str, end: str) -> tuple[set[str], set[str]]:
    """Phase 37 helper — return `(paid_off_dates, weekly_off_weekdays)` for a
    date window (inclusive YYYY-MM-DD strings).

    `paid_off_dates` = every date in the window that is a declared holiday
    (from the `holidays` collection, including recurring ones matched by
    MM-DD).
    `weekly_off_weekdays` = lower-case weekday names configured in HR policy
    (`hr_policy.weekly_off_days`, default `{'sunday'}`).
    """
    weekly_default = {"sunday"}
    pol = await db.hr_policy.find_one({"id": "singleton"}, {"_id": 0, "weekly_off_days": 1})
    if pol and isinstance(pol.get("weekly_off_days"), list) and pol["weekly_off_days"]:
        weekly_off_weekdays = {str(d).lower() for d in pol["weekly_off_days"]}
    else:
        weekly_off_weekdays = weekly_default

    docs = await db.holidays.find({}, {"_id": 0, "date": 1, "is_recurring": 1}).to_list(1000)
    paid_off: set[str] = set()
    # window bounds for lightweight comparison
    try:
        start_d = datetime.strptime(start, "%Y-%m-%d").date()
        end_d = datetime.strptime(end, "%Y-%m-%d").date()
    except Exception:
        return set(), weekly_off_weekdays
    for d in docs:
        raw = (d.get("date") or "")[:10]
        if not raw or len(raw) != 10:
            continue
        if d.get("is_recurring"):
            # Add every year within the window that matches MM-DD
            mmdd = raw[5:]
            for yr in range(start_d.year, end_d.year + 1):
                iso = f"{yr:04d}-{mmdd}"
                if start <= iso <= end:
                    paid_off.add(iso)
        else:
            if start <= raw <= end:
                paid_off.add(raw)
    return paid_off, weekly_off_weekdays


class HrPolicyIn(BaseModel):
    model_config = ConfigDict(extra="ignore")
    weekly_off_days: List[str] = Field(default_factory=lambda: ["sunday"])


@api.get("/hr-policy")
async def get_hr_policy(_=Depends(get_current_user)):
    """Return the singleton HR policy (weekly-off configuration, etc.).
    Defaults are returned when the document doesn't exist yet."""
    doc = await db.hr_policy.find_one({"id": "singleton"}, {"_id": 0}) or {}
    doc.setdefault("weekly_off_days", ["sunday"])
    return doc


@api.put("/hr-policy")
async def update_hr_policy(body: HrPolicyIn, user=Depends(require_role("admin", "hr"))):
    """Update the HR policy singleton (admin/hr only). Values are lower-cased
    weekday names, e.g. `["sunday"]` or `["saturday", "sunday"]`."""
    days = [str(x).lower() for x in (body.weekly_off_days or ["sunday"]) if x]
    now = datetime.now(timezone.utc).isoformat()
    await db.hr_policy.update_one(
        {"id": "singleton"},
        {"$set": {"id": "singleton", "weekly_off_days": days, "updated_at": now, "updated_by": user["id"]}},
        upsert=True,
    )
    return {"weekly_off_days": days, "updated_at": now}


