@api.get("/dashboard/today-live")
async def dashboard_today_live(_=Depends(get_current_user)):
    """Same-day pulse used on every dashboard: (a) staff on leave today,
    (b) staff joining today. Both are cheap in-memory scans so no cache."""
    today = datetime.now(timezone.utc).date().isoformat()
    # On leave today — either raw attendance marked leave, or an approved leave
    # covering today. We deduplicate by staff_id.
    on_leave: dict = {}
    async for r in db.attendance.find(
        {"date": today, "status": "leave"},
        {"_id": 0, "staff_id": 1},
    ):
        on_leave[r["staff_id"]] = {"reason": "Marked leave"}
    async for l in db.leaves.find(
        {"status": "approved", "start_date": {"$lte": today}, "end_date": {"$gte": today}},
        {"_id": 0, "staff_id": 1, "reason": 1, "leave_type_code": 1},
    ):
        on_leave.setdefault(l["staff_id"], {"reason": l.get("reason") or (l.get("leave_type_code") or "Approved leave")})
    on_leave_list = []
    if on_leave:
        staff_docs = await db.staff.find(
            {"id": {"$in": list(on_leave.keys())}},
            {"_id": 0, "id": 1, "name": 1, "designation": 1, "employee_code": 1, "center_id": 1},
        ).to_list(200)
        for s in staff_docs:
            on_leave_list.append({**s, "reason": on_leave[s["id"]]["reason"]})
    # New joinees today
    new_joinees = await db.staff.find(
        {"joining_date": today},
        {"_id": 0, "id": 1, "name": 1, "designation": 1, "employee_code": 1, "center_id": 1, "joining_date": 1},
    ).to_list(50)
    return {"date": today, "on_leave": on_leave_list, "new_joinees": new_joinees}


@api.get("/dashboard/upcoming")
async def dashboard_upcoming(days: int = 15, _=Depends(get_current_user)):
    """Combined upcoming feed for every dashboard: birthdays (from staff.date_of_birth)
    + holidays within `days` days. Birthdays are calendar-day aware (compares only
    month-day so the query works across year boundaries)."""
    today = datetime.now(timezone.utc).date()
    end = today.fromordinal(today.toordinal() + max(days, 1))
    # Upcoming holidays — simple date range on ISO date strings
    holidays = await db.holidays.find(
        {"date": {"$gte": today.isoformat(), "$lte": end.isoformat()}},
        {"_id": 0},
    ).sort("date", 1).to_list(50)
    # Upcoming birthdays — need to compare only MM-DD, wrap-around year
    all_staff = await db.staff.find(
        {"date_of_birth": {"$exists": True, "$nin": [None, ""]}},
        {"_id": 0, "id": 1, "name": 1, "designation": 1, "date_of_birth": 1, "center_id": 1},
    ).to_list(2000)
    upcoming_birthdays = []
    for s in all_staff:
        try:
            dob = datetime.fromisoformat(s["date_of_birth"]).date()
        except (ValueError, TypeError):
            continue
        # Next birthday in current or next year
        try:
            nxt = dob.replace(year=today.year)
        except ValueError:
            # Feb-29 in non-leap year → shift to Mar-1 so the alert still fires
            nxt = dob.replace(year=today.year, day=28)
        if nxt < today:
            try:
                nxt = dob.replace(year=today.year + 1)
            except ValueError:
                nxt = dob.replace(year=today.year + 1, day=28)
        days_away = (nxt - today).days
        if 0 <= days_away <= days:
            upcoming_birthdays.append({
                "staff_id": s["id"], "name": s["name"],
                "designation": s.get("designation"),
                "date": nxt.isoformat(),
                "days_away": days_away,
                "turning_age": nxt.year - dob.year,
            })
    upcoming_birthdays.sort(key=lambda x: x["days_away"])
    return {"birthdays": upcoming_birthdays[:20], "holidays": holidays}


