@api.patch("/regularisations/{rid}")
async def decide_regularisation(rid: str, decision: str = Query(..., pattern="^(approved|rejected)$"),
                                remarks: Optional[str] = Query(None),
                                user=Depends(require_role("admin", "hr", "manager"))):
    rec = await db.regularisations.find_one({"id": rid}, {"_id": 0})
    if not rec:
        raise HTTPException(404, "Not found")
    if rec.get("status") != "pending":
        raise HTTPException(400, f"Already {rec.get('status')}")
    now = datetime.now(timezone.utc).isoformat()
    update = {
        "status": decision,
        "decided_by": user["id"],
        "decided_at": now,
        "decision_remarks": remarks or "",
    }
    # On approve, upsert into attendance
    if decision == "approved":
        new_id = str(uuid.uuid4())
        await db.attendance.update_one(
            {"staff_id": rec["staff_id"], "date": rec["date"]},
            {"$set": {
                "staff_id": rec["staff_id"], "date": rec["date"],
                "status": rec.get("attendance_status") or rec.get("status") or "present",
                "marked_via": "regularised",
                "marked_at": now,
                "marked_by": user["id"],
                "check_in_at": now,
                "regularised": True,
                "regularisation_id": rid,
            }, "$setOnInsert": {"id": new_id}},
            upsert=True,
        )
    res = await db.regularisations.find_one_and_update({"id": rid}, {"$set": update}, return_document=True)
    res.pop("_id", None)
    if rec.get("created_by") and rec["created_by"] != user["id"]:
        await _notify(rec["created_by"], f"Your regularisation request for {rec['date']} was {decision}",
                      ntype=f"regularisation_{decision}", ref_id=rid, link="/check-in")
    return res


# ============================================================================
# Vendor Master
# ============================================================================
# Reusable vendor directory — GST, PAN, bank details, contact. Referenced by
# quotations (vendor_id) so procurement analytics (Top-N vendors by spend)
# can roll up spend without string-matching typo'd vendor names.
class VendorIn(BaseModel):
    model_config = ConfigDict(extra="ignore")
    name: str
    gst_number: Optional[str] = None
    pan_number: Optional[str] = None
    contact_person: Optional[str] = None
    mobile: Optional[str] = None
    email: Optional[str] = None
    address: Optional[str] = None
    bank_account_no: Optional[str] = None
    bank_name: Optional[str] = None
    ifsc: Optional[str] = None
    account_holder_name: Optional[str] = None
    notes: Optional[str] = None
    active: bool = True
    # Centers this vendor is authorised for. Empty list = global (visible to
    # everyone, editable only by HQ roles). When a center_manager creates a
    # vendor we force this to their assigned centers so scoping stays clean.
    center_ids: List[str] = Field(default_factory=list)


def _vendor_scope_visible(user: dict, vendor: dict) -> bool:
    """Return True when `user` should be able to SEE `vendor` in listings.
    HQ roles see everything. center_manager/center_staff/partner see:
      - vendors that have at least one center overlap, OR
      - legacy vendors with empty center_ids (backwards compat — old vendors were global)."""
    role = user.get("role")
    if role in ("admin", "hr", "manager", "senior_manager", "accountant"):
        return True
    vendor_centers = set(vendor.get("center_ids") or [])
    if not vendor_centers:
        return True  # legacy global vendor
    if role in ("center_manager", "center_staff"):
        my = set(user.get("assigned_center_ids") or [])
        return bool(my & vendor_centers)
    if role == "partner":
        # partners see vendors whose center belongs to their partner scope; keep
        # this permissive for now — partner scoping is enforced at the payment layer.
        return True
    return False


def _vendor_scope_editable(user: dict, vendor: dict) -> bool:
    """Return True when `user` can EDIT this vendor. Center Managers can only
    manage vendors that are scoped to at least one of their centers (and never
    a global vendor — those stay with HQ)."""
    role = user.get("role")
    if role in ("admin", "hr", "manager", "senior_manager", "accountant"):
        return True
    if role == "center_manager":
        vendor_centers = set(vendor.get("center_ids") or [])
        if not vendor_centers:
            return False  # legacy global vendor stays HQ-owned
        my = set(user.get("assigned_center_ids") or [])
        return bool(my & vendor_centers)
    return False


@api.get("/vendors")
async def list_vendors(user=Depends(get_current_user)):
    """All logged-in users can browse the vendor directory (needed for the
    dropdown in the Quotation form). Scoping: center_manager and center_staff
    only see vendors whose `center_ids` overlap their assigned centers OR
    legacy global vendors (empty center_ids). Mutation is enforced separately."""
    docs = await db.vendors.find({}, {"_id": 0}).sort("name", 1).to_list(2000)
    return [v for v in docs if _vendor_scope_visible(user, v)]


@api.get("/vendors/{vid}")
async def get_vendor(vid: str, user=Depends(get_current_user)):
    v = await db.vendors.find_one({"id": vid}, {"_id": 0})
    if not v:
        raise HTTPException(404, "Vendor not found")
    if not _vendor_scope_visible(user, v):
        raise HTTPException(403, "Vendor is not assigned to any of your centers")
    return v


@api.post("/vendors", status_code=201)
async def create_vendor(
    body: VendorIn,
    user=Depends(require_role(
        "admin", "hr", "manager", "senior_manager", "accountant", "center_manager",
    )),
):
    if not (body.name or "").strip():
        raise HTTPException(400, "Vendor name is required")
    doc = body.model_dump()
    doc["id"] = str(uuid.uuid4())
    doc["created_by"] = user["id"]
    doc["created_by_name"] = user.get("name") or user.get("email")
    doc["created_at"] = datetime.now(timezone.utc).isoformat()
    # Center Manager can only create vendors scoped to THEIR assigned centers.
    # Any center_ids they submit outside their scope are stripped; if they submit
    # nothing we auto-populate with all their centers so the vendor is at least
    # visible to their center_staff (and never leaks to other centers as a global).
    if user.get("role") == "center_manager":
        my = set(user.get("assigned_center_ids") or [])
        if not my:
            raise HTTPException(403, "You have no centers assigned — contact admin")
        submitted = set(doc.get("center_ids") or [])
        allowed = list(submitted & my) if submitted else list(my)
        if not allowed:
            raise HTTPException(400, "Please pick at least one of your assigned centers")
        doc["center_ids"] = allowed
    await db.vendors.insert_one(doc)
    doc.pop("_id", None)
    return _json_safe(doc)


@api.put("/vendors/{vid}")
async def update_vendor(
    vid: str, body: VendorIn,
    user=Depends(require_role(
        "admin", "hr", "manager", "senior_manager", "accountant", "center_manager",
    )),
):
    v = await db.vendors.find_one({"id": vid}, {"_id": 0})
    if not v:
        raise HTTPException(404, "Vendor not found")
    if not _vendor_scope_editable(user, v):
        raise HTTPException(403, "This vendor is not scoped to any of your centers")
    update = body.model_dump()
    # Center Manager can't broaden a vendor's scope beyond their centers; also
    # can't unset the scope to make it a global vendor.
    if user.get("role") == "center_manager":
        my = set(user.get("assigned_center_ids") or [])
        submitted = set(update.get("center_ids") or [])
        # Preserve center_ids that already exist for centers the CM doesn't own.
        existing_out_of_scope = set(v.get("center_ids") or []) - my
        allowed = (submitted & my) | existing_out_of_scope
        if not (allowed & my):
            raise HTTPException(400, "At least one of your assigned centers must stay on this vendor")
        update["center_ids"] = list(allowed)
    update["updated_by"] = user["id"]
    update["updated_at"] = datetime.now(timezone.utc).isoformat()
    await db.vendors.update_one({"id": vid}, {"$set": update})
    merged = {**v, **update}
    merged.pop("_id", None)
    return merged


@api.delete("/vendors/{vid}", status_code=204)
async def delete_vendor(vid: str, _=Depends(require_role("admin"))):
    r = await db.vendors.delete_one({"id": vid})
    if r.deleted_count == 0:
        raise HTTPException(404, "Vendor not found")
    return None


@api.get("/reports/top-vendors")
async def top_vendors(
    limit: int = 10,
    days: Optional[int] = None,
    user=Depends(require_finance_visible),
):
    """Aggregate spend per vendor from approved payments (which represent
    real procurement outflows). Returns list sorted by total_spend desc.

    ``days`` filters payments where created_at is within the last N days.
    """
    q: dict = {"status": "paid"}
    if days and days > 0:
        cutoff = (datetime.now(timezone.utc) - timedelta(days=days)).isoformat()
        q["created_at"] = {"$gte": cutoff}
    pipe = [
        {"$match": q},
        {"$group": {
            "_id": {"vendor": "$vendor_name", "vendor_id": "$vendor_id"},
            "total_spend": {"$sum": "$actual_amount"},
            "invoice_count": {"$sum": 1},
            "last_paid_at": {"$max": "$created_at"},
        }},
        {"$sort": {"total_spend": -1}},
        {"$limit": int(limit)},
    ]
    rows = await db.payments.aggregate(pipe).to_list(int(limit))
    return [{
        "vendor_id": r["_id"].get("vendor_id"),
        "vendor_name": r["_id"].get("vendor") or "Unknown",
        "total_spend": round(r["total_spend"] or 0, 2),
        "invoice_count": r["invoice_count"],
        "last_paid_at": r["last_paid_at"],
    } for r in rows]


# ============================================================================
# Quotation → QRN → Payment workflow
# ============================================================================
# Two-stage procurement flow:
#   Stage 1: Any non-partner role raises a QUOTATION with vendor+amount+attachments.
#            Approval flows through the configured `quotation` chain (default 3 levels).
#            On final approve, a per-center QRN (Quotation Request Number) is stamped:
#            e.g. `PALOJORI-QRN-0042`. The QRN is unique per center.
#   Stage 2: Once approved, the initiator (or admin/CM) raises a PAYMENT request that
#            references the QRN. Actual amount is editable. Approval flows through the
#            configured `payment` chain. On final approve, an approved EXPENSE
#            transaction is auto-created in the center's ledger, tagged with the QRN,
#            with company_id/partner_id auto-derived (Phase 13).
QuotationCategory = Literal["expense", "investment", "asset"]


class QuotationIn(BaseModel):
    model_config = ConfigDict(extra="ignore")
    center_id: str
    category: QuotationCategory = "expense"
    description: str
    vendor_id: Optional[str] = None       # optional — auto-fills from Vendor Master
    vendor_name: str
    estimated_amount: float = Field(gt=0)
    expected_delivery_date: Optional[str] = None
    purpose: Optional[str] = None
    attachments: List[AttachmentRef] = Field(default_factory=list)


class PaymentIn(BaseModel):
    model_config = ConfigDict(extra="ignore")
    quotation_id: str
    actual_amount: float = Field(gt=0)
    payment_mode: str = Field(..., description="cash | bank | upi | cheque | card")
    payment_date: Optional[str] = None       # YYYY-MM-DD; defaults to today at approval
    txn_type_override: Optional[QuotationCategory] = None  # overrides quotation.category
    notes: Optional[str] = None
    # Payee details — mandatory for bank/upi/cheque so the approver knows exactly WHERE
    # money will land. Cash/card modes skip these (validated in the endpoint).
    payee_account_holder: Optional[str] = None
    payee_account_no: Optional[str] = None
    payee_ifsc: Optional[str] = None
    payee_bank_name: Optional[str] = None
    payee_upi_id: Optional[str] = None
    # Regular payment supporting docs (invoice / receipt / bank slip).
    attachments: List[AttachmentRef] = Field(default_factory=list)
    # Payee proof: cancelled cheque / QR screenshot / bank passbook — REQUIRED for
    # bank/upi/cheque modes so Finance can cross-verify the account before releasing funds.
    payee_proof_attachments: List[AttachmentRef] = Field(default_factory=list)
    # Phase-2 Advance Adjustment — optional link to a RELEASED advance whose
    # cash-in-hand is being spent on this payment. When set, the payment amount
    # reduces `balance_amount` of the advance on final approval instead of triggering
    # a fresh outflow of cash (advance was already an outflow at release time).
    advance_request_id: Optional[str] = None


def _slug_center_prefix(name: str) -> str:
    """Return an uppercase 8-char alnum prefix of the center name, used inside the QRN."""
    if not name:
        return "CENTER"
    stripped = "".join(ch for ch in name.upper() if ch.isalnum())
    return (stripped or "CENTER")[:8]


async def _next_qrn(center_id: str) -> str:
    """Atomically bump the per-center QRN counter and return the formatted QRN string."""
    doc = await db.qrn_counters.find_one_and_update(
        {"center_id": center_id},
        {"$inc": {"counter": 1},
         "$setOnInsert": {"center_id": center_id, "id": str(uuid.uuid4())}},
        upsert=True, return_document=True,
    )
    counter = doc.get("counter") or 1
    center = await db.centers.find_one({"id": center_id}, {"_id": 0, "name": 1})
    prefix = _slug_center_prefix((center or {}).get("name") or "")
    return f"{prefix}-QRN-{counter:04d}"


QUOTATION_CREATORS = ("admin", "hr", "manager", "senior_manager", "accountant", "center_manager", "center_staff")


@api.post("/quotations")
async def create_quotation(
    body: QuotationIn,
    user=Depends(get_current_user),
    idempotency_key: Optional[str] = Depends(_get_idempotency_key),
):
    """Any non-partner role can raise a quotation request for a center they belong to."""
    if idempotency_key:
        prev = await _check_idempotency(idempotency_key, user["id"])
        if prev is not None:
            return prev
    if user.get("role") not in QUOTATION_CREATORS:
        raise HTTPException(403, "Partners cannot raise quotations")
    # Center-scope check for center_manager / center_staff
    if user.get("role") in ("center_manager", "center_staff"):
        assigned = user.get("assigned_center_ids") or []
        if body.center_id not in assigned:
            raise HTTPException(403, "You can only raise quotations for centers you are assigned to")
    center = await db.centers.find_one({"id": body.center_id}, {"_id": 0, "name": 1})
    if not center:
        raise HTTPException(404, "Center not found")
    doc = body.model_dump()
    doc["id"] = str(uuid.uuid4())
    doc["status"] = "pending"
    doc["center_name"] = center.get("name")
    doc["created_by"] = user["id"]
    doc["created_by_name"] = user.get("name") or user.get("email")
    doc["created_at"] = datetime.now(timezone.utc).isoformat()
    # Do NOT materialise qrn=None here — the unique+sparse index on `qrn` still indexes
    # explicit-null values (sparse only skips *missing* fields), so writing null would
    # cause a duplicate-key error on the 2nd pending quotation. Leaving the field absent
    # lets the sparse index correctly skip pre-approval docs. `$set` stamps it on final approve.
    doc["payment_id"] = None
    doc = await _attach_chain_to_request("quotation", doc)
    await db.quotations.insert_one(doc)
    # Notify first-step approvers
    cur = await _current_step(doc)
    if cur:
        for uid in await _resolve_step_user_ids(cur, doc):
            if uid != user["id"]:
                await _notify(uid,
                              f"New quotation from {doc['created_by_name']} — {doc['vendor_name']} · ₹{doc['estimated_amount']:,.0f}",
                              ntype="quotation_pending", ref_id=doc["id"], link="/quotations")
    doc.pop("_id", None)
    resp = _json_safe(doc)
    await _store_idempotency(idempotency_key, user["id"], resp)
    return resp


@api.get("/quotations")
async def list_quotations(
    status_filter: Optional[str] = Query(None, alias="status"),
    center_id: Optional[str] = None,
    user=Depends(get_current_user),
):
    """List quotations. Role scope:
      • admin/hr/senior_manager/accountant → see everything (with optional filters).
      • center_manager/center_staff → see quotations at their assigned centers only.
      • partner → see quotations at centers mapped to them.
      • Everyone also sees quotations they personally raised.
    """
    q: dict = {}
    if status_filter:
        q["status"] = status_filter
    if center_id:
        q["center_id"] = center_id
    role = user.get("role")
    if role in ("center_manager", "center_staff"):
        assigned = user.get("assigned_center_ids") or []
        q["$or"] = [{"center_id": {"$in": assigned}}, {"created_by": user["id"]}]
    elif role == "partner":
        own_pid = user.get("assigned_partner_id")
        centers = await _centers_for_partner(own_pid) if own_pid else []
        q["$or"] = [{"center_id": {"$in": centers}}, {"created_by": user["id"]}]
    docs = await db.quotations.find(q, {"_id": 0}).sort("created_at", -1).to_list(500)
    for d in docs:
        await _enrich_with_approval_status(d)
    return docs


@api.get("/quotations/{qid}")
async def get_quotation(qid: str, user=Depends(get_current_user)):
    q = await db.quotations.find_one({"id": qid}, {"_id": 0})
    if not q:
        raise HTTPException(404, "Not found")
    await _enrich_with_approval_status(q)
    return q


@api.delete("/quotations/{qid}")
async def delete_quotation(qid: str, user=Depends(get_current_user)):
    """Creator can delete their own PENDING quotation; admin can delete any non-paid quotation."""
    q = await db.quotations.find_one({"id": qid}, {"_id": 0})
    if not q:
        raise HTTPException(404, "Not found")
    role = user.get("role")
    is_owner = q.get("created_by") == user["id"]
    if not (role == "admin" or (is_owner and q.get("status") == "pending")):
        raise HTTPException(403, "Cannot delete this quotation")
    if q.get("status") == "paid":
        raise HTTPException(400, "Cannot delete a quotation with a linked payment — undo the payment first")
    await db.quotations.delete_one({"id": qid})
    return {"ok": True}


class QuotationResubmitIn(BaseModel):
    model_config = ConfigDict(extra="ignore")
    description: Optional[str] = None
    vendor_id: Optional[str] = None
    vendor_name: Optional[str] = None
    estimated_amount: Optional[float] = Field(default=None, gt=0)
    expected_delivery_date: Optional[str] = None
    purpose: Optional[str] = None
    attachments: Optional[List[AttachmentRef]] = None
    edit_note: str = Field(min_length=3, description="What changed as per the send-back remarks")


@api.post("/quotations/{qid}/resubmit")
async def resubmit_quotation(qid: str, body: QuotationResubmitIn, user=Depends(get_current_user)):
    """Creator edits a SENT-BACK quotation as per the approver's remarks and
    re-enters the approval chain from Level 1. Chain history is preserved so
    reviewers can see the full trail (send-back + resubmit + subsequent decisions).
    """
    q = await db.quotations.find_one({"id": qid}, {"_id": 0})
    if not q:
        raise HTTPException(404, "Quotation not found")
    if q.get("status") != "sent_back":
        raise HTTPException(400, f"Only sent-back quotations can be resubmitted (status={q.get('status')})")
    if q.get("created_by") != user["id"] and user.get("role") != "admin":
        raise HTTPException(403, "Only the original raiser (or admin) can resubmit")
    now = datetime.now(timezone.utc).isoformat()
    update: dict = {}
    for f in ("description", "vendor_id", "vendor_name", "expected_delivery_date", "purpose"):
        v = getattr(body, f)
        if v is not None:
            update[f] = v
    if body.estimated_amount is not None:
        update["estimated_amount"] = float(body.estimated_amount)
    if body.attachments is not None:
        update["attachments"] = [a.model_dump() for a in body.attachments]
    history = list(q.get("chain_history") or [])
    history.append({
        "level": 0, "action": "resubmit", "by_user_id": user["id"],
        "by_user_name": user.get("name") or user.get("email"),
        "at": now, "remarks": body.edit_note,
    })
    update.update({
        "status": "pending",
        "current_level": 1,
        "chain_history": history,
        "resubmitted_at": now,
        "resubmitted_by": user["id"],
        # Clear stale rejection/send-back stamps so the UI reflects a fresh cycle
        "sent_back_reason": None, "sent_back_at": None, "sent_back_by": None,
        "sent_back_by_name": None, "sent_back_from_level": None,
        "rejected_reason": None, "rejected_at": None,
    })
    await db.quotations.update_one({"id": qid}, {"$set": update})
    merged = {**q, **update}
    # Notify Lv1 approvers again
    cur = await _current_step(merged)
    if cur:
        for uid in await _resolve_step_user_ids(cur, merged):
            if uid != user["id"]:
                await _notify(uid,
                              f"Resubmitted quotation from {q.get('created_by_name')} — {merged.get('vendor_name')} · ₹{float(merged.get('estimated_amount', 0)):,.0f}",
                              ntype="quotation_pending", ref_id=qid, link="/quotations")
    merged.pop("_id", None)
    return _json_safe(merged)


def _validate_payment_payee(body: "PaymentIn") -> None:
    """Enforce payee details/proof based on payment_mode. Raises HTTPException(400)
    with a user-friendly message when required fields are missing so both the
    create-payment and resubmit-payment paths share identical rules."""
    mode = (body.payment_mode or "").lower().strip()
    if mode == "advance_adjustment":
        return  # advance-funded payment — no fresh outflow, no payee details required
    if mode not in ("cash", "bank", "upi", "cheque", "card"):
        raise HTTPException(400, "Invalid payment_mode — must be cash / bank / upi / cheque / card")
    if mode in ("bank", "cheque"):
        missing = [k for k, v in {
            "Account Holder Name": body.payee_account_holder,
            "Account Number": body.payee_account_no,
            "IFSC Code": body.payee_ifsc,
            "Bank Name": body.payee_bank_name,
        }.items() if not (v or "").strip()]
        if missing:
            raise HTTPException(400, f"Bank / Cheque payment requires: {', '.join(missing)}")
        if len(body.payee_proof_attachments or []) == 0:
            raise HTTPException(400, "Please attach a cancelled cheque / bank passbook as proof for Bank/Cheque payment")
    elif mode == "upi":
        if not (body.payee_upi_id or "").strip():
            raise HTTPException(400, "UPI payment requires a valid UPI ID")
        if len(body.payee_proof_attachments or []) == 0:
            raise HTTPException(400, "Please attach a UPI QR screenshot as proof for UPI payment")


@api.post("/payments")
async def create_payment(
    body: PaymentIn,
    user=Depends(get_current_user),
    idempotency_key: Optional[str] = Depends(_get_idempotency_key),
):
    """Raise a payment request against an APPROVED quotation."""
    if idempotency_key:
        prev = await _check_idempotency(idempotency_key, user["id"])
        if prev is not None:
            return prev
    if user.get("role") not in QUOTATION_CREATORS:
        raise HTTPException(403, "Partners cannot raise payment requests")
    q = await db.quotations.find_one({"id": body.quotation_id}, {"_id": 0})
    if not q:
        raise HTTPException(404, "Quotation not found")
    if q.get("status") != "approved":
        raise HTTPException(400, f"Quotation is not approved (status={q.get('status')})")
    if q.get("payment_id"):
        raise HTTPException(400, "A payment request already exists for this quotation")
    if user.get("role") in ("center_manager", "center_staff"):
        assigned = user.get("assigned_center_ids") or []
        if q["center_id"] not in assigned:
            raise HTTPException(403, "You can only raise payments for centers you are assigned to")
    _validate_payment_payee(body)
    # Optional advance adjustment link — validate ownership + balance up-front so the
    # user gets clear feedback before the payment enters an N-level approval chain.
    linked_advance = None
    if body.advance_request_id:
        linked_advance = await db.advance_requests.find_one({"id": body.advance_request_id}, {"_id": 0})
        if not linked_advance:
            raise HTTPException(404, "Linked advance not found")
        if linked_advance.get("created_by") != user["id"]:
            raise HTTPException(403, "You can only adjust against your own advance")
        if linked_advance.get("status") not in ("released", "adjusting"):
            raise HTTPException(400, f"Advance is not available for adjustment (status={linked_advance.get('status')})")
        bal = float(linked_advance.get("balance_amount") or 0)
        if float(body.actual_amount) > bal + 0.01:
            raise HTTPException(400, f"Actual amount ₹{body.actual_amount:,.2f} exceeds advance balance ₹{bal:,.2f}")
    doc = body.model_dump()
    doc["id"] = str(uuid.uuid4())
    doc["quotation_id"] = q["id"]
    doc["qrn"] = q.get("qrn")
    doc["center_id"] = q["center_id"]
    doc["center_name"] = q.get("center_name")
    doc["category"] = doc.get("txn_type_override") or q.get("category") or "expense"
    doc["description"] = q.get("description")
    doc["vendor_name"] = q.get("vendor_name")
    doc["status"] = "pending"
    doc["created_by"] = user["id"]
    doc["created_by_name"] = user.get("name") or user.get("email")
    doc["created_at"] = datetime.now(timezone.utc).isoformat()
    doc["txn_id"] = None
    if linked_advance:
        doc["advance_no"] = linked_advance.get("advance_no")
    doc = await _attach_chain_to_request("payment", doc)
    await db.payments.insert_one(doc)
    # Link back to quotation
    await db.quotations.update_one({"id": q["id"]}, {"$set": {"payment_id": doc["id"], "status": "payment_pending"}})
    cur = await _current_step(doc)
    if cur:
        for uid in await _resolve_step_user_ids(cur, doc):
            if uid != user["id"]:
                await _notify(uid,
                              f"Payment approval — QRN {doc.get('qrn')} · ₹{doc['actual_amount']:,.0f}",
                              ntype="payment_pending", ref_id=doc["id"], link="/quotations")
    doc.pop("_id", None)
    resp = _json_safe(doc)
    await _store_idempotency(idempotency_key, user["id"], resp)
    return resp


class PaymentResubmitIn(BaseModel):
    model_config = ConfigDict(extra="ignore")
    actual_amount: Optional[float] = Field(default=None, gt=0)
    payment_mode: Optional[str] = None
    payment_date: Optional[str] = None
    txn_type_override: Optional[QuotationCategory] = None
    notes: Optional[str] = None
    payee_account_holder: Optional[str] = None
    payee_account_no: Optional[str] = None
    payee_ifsc: Optional[str] = None
    payee_bank_name: Optional[str] = None
    payee_upi_id: Optional[str] = None
    attachments: Optional[List[AttachmentRef]] = None
    payee_proof_attachments: Optional[List[AttachmentRef]] = None
    edit_note: str = Field(min_length=3, description="What changed as per the send-back remarks")


@api.post("/payments/{pid}/resubmit")
async def resubmit_payment(pid: str, body: PaymentResubmitIn, user=Depends(get_current_user)):
    """Creator edits a SENT-BACK payment as per approver remarks and re-enters
    the approval chain from Level 1. Reuses `_validate_payment_payee` after
    merging the incoming edits over the existing doc so payee rules stay
    identical to the initial create-payment path."""
    p = await db.payments.find_one({"id": pid}, {"_id": 0})
    if not p:
        raise HTTPException(404, "Payment not found")
    if p.get("status") != "sent_back":
        raise HTTPException(400, f"Only sent-back payments can be resubmitted (status={p.get('status')})")
    if p.get("created_by") != user["id"] and user.get("role") != "admin":
        raise HTTPException(403, "Only the original raiser (or admin) can resubmit")
    now = datetime.now(timezone.utc).isoformat()
    # Apply the edits over a working copy so validation sees the FINAL state
    merged = dict(p)
    for f in ("payment_mode", "payment_date", "notes",
              "payee_account_holder", "payee_account_no", "payee_ifsc",
              "payee_bank_name", "payee_upi_id", "txn_type_override"):
        v = getattr(body, f)
        if v is not None:
            merged[f] = v
    if body.actual_amount is not None:
        merged["actual_amount"] = float(body.actual_amount)
    if body.attachments is not None:
        merged["attachments"] = [a.model_dump() for a in body.attachments]
    if body.payee_proof_attachments is not None:
        merged["payee_proof_attachments"] = [a.model_dump() for a in body.payee_proof_attachments]
    # If linked to an advance, re-validate the (possibly-updated) actual_amount fits within
    # the current balance so the resubmit path shares identical guardrails as create_payment.
    if merged.get("advance_request_id"):
        adv = await db.advance_requests.find_one({"id": merged["advance_request_id"]}, {"_id": 0})
        if not adv or adv.get("status") not in ("released", "adjusting"):
            raise HTTPException(400, "Linked advance is no longer adjustable")
        bal = float(adv.get("balance_amount") or 0)
        if float(merged["actual_amount"]) > bal + 0.01:
            raise HTTPException(400, f"Actual amount ₹{float(merged['actual_amount']):,.2f} exceeds advance balance ₹{bal:,.2f}")
    # Reuse the strict payee validation used by create_payment
    class _V:  # lightweight shim satisfying the helper's attribute reads
        pass
    v = _V()
    for f in ("payment_mode", "payee_account_holder", "payee_account_no",
              "payee_ifsc", "payee_bank_name", "payee_upi_id"):
        setattr(v, f, merged.get(f))
    v.payee_proof_attachments = merged.get("payee_proof_attachments") or []
    _validate_payment_payee(v)

    history = list(p.get("chain_history") or [])
    history.append({
        "level": 0, "action": "resubmit", "by_user_id": user["id"],
        "by_user_name": user.get("name") or user.get("email"),
        "at": now, "remarks": body.edit_note,
    })
    update = {k: merged[k] for k in (
        "payment_mode", "payment_date", "notes", "actual_amount",
        "payee_account_holder", "payee_account_no", "payee_ifsc",
        "payee_bank_name", "payee_upi_id", "attachments",
        "payee_proof_attachments", "txn_type_override",
    ) if k in merged}
    update.update({
        "status": "pending",
        "current_level": 1,
        "chain_history": history,
        "resubmitted_at": now,
        "resubmitted_by": user["id"],
        "sent_back_reason": None, "sent_back_at": None, "sent_back_by": None,
        "sent_back_by_name": None, "sent_back_from_level": None,
        "rejected_reason": None, "rejected_at": None,
    })
    await db.payments.update_one({"id": pid}, {"$set": update})
    # Flip the parent quotation back to 'payment_pending' now that the payment
    # is re-entering the chain (it was parked at 'payment_sent_back').
    if p.get("quotation_id"):
        await db.quotations.update_one(
            {"id": p["quotation_id"]}, {"$set": {"status": "payment_pending"}},
        )
    full = {**p, **update}
    cur = await _current_step(full)
    if cur:
        for uid in await _resolve_step_user_ids(cur, full):
            if uid != user["id"]:
                await _notify(uid,
                              f"Resubmitted payment — QRN {full.get('qrn')} · ₹{float(full.get('actual_amount', 0)):,.0f}",
                              ntype="payment_pending", ref_id=pid, link="/quotations")
    full.pop("_id", None)
    return _json_safe(full)


@api.get("/payments")
async def list_payments(
    status_filter: Optional[str] = Query(None, alias="status"),
    center_id: Optional[str] = None,
    quotation_id: Optional[str] = None,
    user=Depends(get_current_user),
):
    q: dict = {}
    if status_filter:
        q["status"] = status_filter
    if center_id:
        q["center_id"] = center_id
    if quotation_id:
        q["quotation_id"] = quotation_id
    role = user.get("role")
    if role in ("center_manager", "center_staff"):
        assigned = user.get("assigned_center_ids") or []
        q["$or"] = [{"center_id": {"$in": assigned}}, {"created_by": user["id"]}]
    elif role == "partner":
        own_pid = user.get("assigned_partner_id")
        centers = await _centers_for_partner(own_pid) if own_pid else []
        q["$or"] = [{"center_id": {"$in": centers}}, {"created_by": user["id"]}]
    docs = await db.payments.find(q, {"_id": 0}).sort("created_at", -1).to_list(500)
    for d in docs:
        await _enrich_with_approval_status(d)
    return docs


@api.get("/payments/{pid}")
async def get_payment(pid: str, user=Depends(get_current_user)):
    p = await db.payments.find_one({"id": pid}, {"_id": 0})
    if not p:
        raise HTTPException(404, "Not found")
    await _enrich_with_approval_status(p)
    return p


# -------- Personal endpoints for mobile staff app --------
@api.get("/leaves/my")
async def my_leaves(user=Depends(get_current_user)):
    docs = await db.leaves.find({"created_by": user["id"]}, {"_id": 0}).sort("created_at", -1).to_list(200)
    # Lazy migration: older leaves submitted before an approval chain was configured
    # may lack chain_snapshot. Re-run chain-attach so the requester can now see
    # "pending with X" + track the approval progress in the Staff App.
    for d in docs:
        if d.get("status") == "pending" and not (d.get("chain_snapshot") or []):
            await _attach_chain_to_request("leave", d)
            if d.get("chain_id"):
                await db.leaves.update_one(
                    {"id": d["id"]},
                    {"$set": {
                        "chain_id": d.get("chain_id"),
                        "current_level": d.get("current_level"),
                        "chain_snapshot": d.get("chain_snapshot") or [],
                        "chain_history": d.get("chain_history") or [],
                    }},
                )
    for d in docs:
        await _enrich_with_approval_status(d)
    return docs


@api.get("/reimbursements/my")
async def my_reimbursements(user=Depends(get_current_user)):
    docs = await db.reimbursements.find({"created_by": user["id"]}, {"_id": 0}).sort("created_at", -1).to_list(200)
    # Lazy migration for older reimbursements missing chain snapshot (same rationale
    # as `/leaves/my` above). Non-pending items keep their existing shape so
    # rejected/paid rows still surface their historic chain_history / snapshot.
    for d in docs:
        if d.get("status") in ("pending", "in_progress", "submitted") and not (d.get("chain_snapshot") or []):
            await _attach_chain_to_request("reimbursement", d)
            if d.get("chain_id"):
                await db.reimbursements.update_one(
                    {"id": d["id"]},
                    {"$set": {
                        "chain_id": d.get("chain_id"),
                        "current_level": d.get("current_level"),
                        "chain_snapshot": d.get("chain_snapshot") or [],
                        "chain_history": d.get("chain_history") or [],
                    }},
                )
    # Enrich with pending_with + step label so the requester sees exactly who to nudge.
    for d in docs:
        await _enrich_with_approval_status(d)
    return docs


@api.get("/me/summary")
async def my_summary(user=Depends(get_current_user)):
    """Combined dashboard data for the mobile staff app home tab."""
    staff = await db.staff.find_one({"user_id": user["id"]}, {"_id": 0})
    if not staff:
        # Non-staff user (e.g. admin viewing /check-in): keep response shape stable so the
        # frontend can iterate over the arrays without optional-chaining everywhere.
        return {
            "staff": None, "today": None, "month_stats": {}, "pending_counts": {},
            "upcoming_holidays": [], "all_holidays": [], "leave_balances": [],
            "weekly_off_days": ["sunday"],
        }
    # Auto-close any stale previous-day open sessions before computing "today".
    await _auto_close_stale_attendance(staff)
    today = _today_ist()  # IST calendar date (never UTC — fixes next-day carry-over)
    today_row = await db.attendance.find_one({"staff_id": staff["id"], "date": today}, {"_id": 0})
    # This month stats — "complete present" = has both check_in_at + check_out_at
    yyyy_mm = today[:7]
    month_rows = await db.attendance.find({"staff_id": staff["id"], "date": {"$regex": f"^{yyyy_mm}"}}, {"_id": 0}).to_list(40)

    def _effective_status(r):
        s = r.get("status")
        if s in ("absent", "leave", "half"):
            return s
        if s == "auto_closed":
            return "incomplete"
        if s == "present" and r.get("check_in_at") and r.get("check_out_at"):
            return "present"
        if s == "present" and r.get("check_in_at") and not r.get("check_out_at"):
            return "incomplete"
        return s or "absent"

    counts = {"present": 0, "absent": 0, "half": 0, "leave": 0, "incomplete": 0}
    for r in month_rows:
        eff = _effective_status(r)
        counts[eff] = counts.get(eff, 0) + 1
    month_stats = {**counts, "total_days": len(month_rows)}
    # Build day-keyed attendance map for the mini calendar (day "01" → "present").
    month_attendance_by_day = {r["date"][-2:]: _effective_status(r) for r in month_rows}
    # Decorate today's row with effective status
    if today_row:
        today_row["effective_status"] = _effective_status(today_row)
    # Pending counts
    pending_leaves = await db.leaves.count_documents({"created_by": user["id"], "status": "pending"})
    pending_reimb = await db.reimbursements.count_documents({"created_by": user["id"], "status": {"$nin": ["paid", "rejected"]}})
    pending_reg = await db.regularisations.count_documents({"created_by": user["id"], "status": "pending"})
    upcoming = await db.holidays.find({"date": {"$gte": today}}, {"_id": 0}).sort("date", 1).to_list(3)
    # Full holiday list for the current calendar year (used by mobile Holidays section)
    yyyy = today[:4]
    all_holidays = await db.holidays.find(
        {"date": {"$regex": f"^{yyyy}"}}, {"_id": 0},
    ).sort("date", 1).to_list(120)
    # Leave balances for the current year + the type definitions (mobile staff app dashboard).
    current_year = int(yyyy)
    raw_balances = await db.leave_balances.find(
        {"staff_id": staff["id"], "year": current_year}, {"_id": 0},
    ).to_list(50)
    leave_types_list = await db.leave_types.find({}, {"_id": 0}).to_list(50)
    types_by_id = {t["id"]: t for t in leave_types_list}
    leave_balances = [
        {**b,
         "leave_type_name": (types_by_id.get(b.get("leave_type_id")) or {}).get("name"),
         "leave_type_color": (types_by_id.get(b.get("leave_type_id")) or {}).get("color")}
        for b in raw_balances
    ]
    # Shift info if assigned
    shift = None
    if staff.get("shift_id"):
        shift = await db.shifts.find_one({"id": staff["shift_id"]}, {"_id": 0})
    # Resolve center_name once so the mobile header can render "Ranchi, Jharkhand"
    # style locations without an extra roundtrip from the client.
    center_name = None
    if staff.get("center_id"):
        c = await db.centers.find_one({"id": staff["center_id"]}, {"_id": 0, "name": 1})
        center_name = (c or {}).get("name")
    # ------------------------------------------------------------------
    # Manager/Approver flags — used by mobile Staff App to decide whether
    # to show the "My Team" and "Pending Approvals" menu entries.
    # ------------------------------------------------------------------
    team_size = await db.staff.count_documents({"reports_to_id": staff["id"]})
    is_manager = team_size > 0
    # Cheap probe: is this user configured as an approver anywhere?
    approver_configured = False
    try:
        approver_configured = bool(await db.approval_chains.find_one(
            {"$or": [
                {"steps.approver_ids": user["id"]},
                {"steps.value": user["id"]},
            ]},
            {"_id": 1},
        ))
    except Exception:
        approver_configured = False
    # Weekly-off weekdays configured in HR policy (default: Sunday).
    weekly_default = ["sunday"]
    pol = await db.hr_policy.find_one({"id": "singleton"}, {"_id": 0, "weekly_off_days": 1})
    if pol and isinstance(pol.get("weekly_off_days"), list) and pol["weekly_off_days"]:
        weekly_off_days = sorted({str(d).lower() for d in pol["weekly_off_days"]})
    else:
        weekly_off_days = weekly_default
    return {
        "staff": {**{k: staff.get(k) for k in ("id", "name", "designation", "monthly_salary", "per_day_rate", "joining_date", "center_id", "bank_name", "shift_id")}, "center_name": center_name},
        "shift": shift,
        "today": today_row,
        "month_stats": month_stats,
        "month_attendance_by_day": month_attendance_by_day,
        "pending_counts": {"leaves": pending_leaves, "reimbursements": pending_reimb, "regularisations": pending_reg},
        "upcoming_holidays": upcoming,
        "all_holidays": all_holidays,
        "leave_balances": leave_balances,
        "is_manager": is_manager,
        "team_size": team_size,
        "is_approver": approver_configured or is_manager,
        "weekly_off_days": weekly_off_days,
    }


@api.get("/staff/my-team")
async def my_team(user=Depends(get_current_user)):
    """Return the list of staff records that report directly to the current user.
    Salary fields are stripped out — the Staff App only surfaces contact/attendance.
    Also augments each team member with today's attendance status.
    """
    me = await db.staff.find_one({"user_id": user["id"]}, {"_id": 0, "id": 1})
    if not me:
        return {"team": [], "team_size": 0}
    rows = await db.staff.find(
        {"reports_to_id": me["id"], "active": {"$ne": False}},
        {"_id": 0, "monthly_salary": 0, "per_day_rate": 0,
         "bank_account_no": 0, "ifsc": 0, "account_holder_name": 0,
         "bank_name": 0, "bank_verified": 0, "bank_verified_at": 0, "bank_verified_by": 0,
         "pan": 0, "aadhaar_last4": 0},
    ).sort("name", 1).to_list(500)
    # Resolve center names in one shot
    cids = list({r.get("center_id") for r in rows if r.get("center_id")})
    centers = {c["id"]: c.get("name")
               for c in await db.centers.find({"id": {"$in": cids}}, {"_id": 0, "id": 1, "name": 1}).to_list(500)}
    today = datetime.now(timezone.utc).date().isoformat()
    att_rows = await db.attendance.find(
        {"staff_id": {"$in": [r["id"] for r in rows]}, "date": today},
        {"_id": 0, "staff_id": 1, "status": 1, "check_in_at": 1, "check_out_at": 1},
    ).to_list(2000)
    att_by = {a["staff_id"]: a for a in att_rows}
    team = []
    for r in rows:
        a = att_by.get(r["id"]) or {}
        if a.get("status") in ("absent", "leave", "half"):
            eff = a["status"]
        elif a.get("check_in_at") and a.get("check_out_at"):
            eff = "present"
        elif a.get("check_in_at"):
            eff = "incomplete"
        else:
            eff = "absent"
        team.append({
            "id": r["id"],
            "name": r.get("name"),
            "employee_code": r.get("employee_code"),
            "designation": r.get("designation"),
            "center_id": r.get("center_id"),
            "center_name": centers.get(r.get("center_id")) if r.get("center_id") else None,
            "email": r.get("email"),
            "mobile": r.get("mobile"),
            "joining_date": r.get("joining_date"),
            "attendance_today": eff,
            "check_in_at": a.get("check_in_at"),
            "check_out_at": a.get("check_out_at"),
        })
    return {"team": team, "team_size": len(team)}


@api.patch("/payroll/{pid}/pay")
async def payroll_pay(pid: str, user=Depends(require_role("admin", "accountant"))):
    """Segregation of Duties (Phase 59): HR CANNOT hit this endpoint directly.
    HR must use POST /payroll/finalise → Approval workflow → accountant `/payroll-batches/{id}/pay`.
    Admin retains this legacy per-row Pay path as an emergency fallback only.
    """
    rec = await db.payroll.find_one({"id": pid}, {"_id": 0})
    if not rec:
        raise HTTPException(404, "Not found")
    if rec["status"] == "paid":
        raise HTTPException(400, "Already paid")
    now = datetime.now(timezone.utc).isoformat()
    # Extract advance-deduction plan so we can run it even in the zero-net short-circuit path
    _adv_dets = list(rec.get("advance_deductions_details") or [])

    async def _consume_advance_deductions(txn_id_for_settlement):
        """Reduce open advance balances by the planned deductions and append a
        salary_deduction settlement entry to each linked advance. Idempotent per
        payroll — called from BOTH the zero-net and normal-payment code paths.
        """
        for det in _adv_dets:
            adv = await db.advance_requests.find_one({"id": det.get("advance_id")}, {"_id": 0})
            if not adv:
                continue
            cur_bal = float(adv.get("balance_amount") or 0)
            amt = min(float(det.get("amount") or 0), cur_bal)
            if amt <= 0:
                continue
            new_bal = max(0.0, round(cur_bal - amt, 2))
            new_adj = round(float(adv.get("adjusted_amount") or 0) + amt, 2)
            settlements = list(adv.get("settlements") or [])
            settlements.append({
                "id": str(uuid.uuid4()),
                "settlement_type": "salary_deduction",
                "amount": round(amt, 2),
                "date": f"{rec['year']:04d}-{rec['month']:02d}-01",
                "at": now,
                "by_user_id": user["id"],
                "by_user_name": user.get("name") or user.get("email"),
                "txn_id": txn_id_for_settlement,
                "payroll_id": rec["id"],
                "remarks": f"Recovered via payroll {rec['month']:02d}/{rec['year']}",
            })
            adv_upd = {
                "settlements": settlements,
                "adjusted_amount": new_adj,
                "balance_amount": new_bal,
            }
            pending = float(adv.get("pending_salary_deduction") or 0)
            if pending > 0:
                adv_upd["pending_salary_deduction"] = max(0.0, round(pending - amt, 2))
            if new_bal <= 0.01:
                adv_upd["status"] = "settled"
                adv_upd["settled_at"] = now
                adv_upd["settlement_reason"] = "salary_deduction"
            else:
                adv_upd["status"] = "adjusting"
            await db.advance_requests.update_one({"id": adv["id"]}, {"$set": adv_upd})
            await _notify(
                adv.get("created_by"),
                f"₹{amt:,.0f} recovered from your salary against advance {adv.get('advance_no')} — balance ₹{new_bal:,.0f}",
                ntype="advance_settled" if new_bal <= 0.01 else "advance_settlement_partial",
                ref_id=adv["id"], link="/advances",
            )

    if (rec.get("net") or 0) <= 0:
        # Nothing to pay (0 days_present etc.). Mark paid without creating a zero-amount transaction.
        # Still consume any planned advance deductions so scheduled recoveries aren't silently lost.
        await _consume_advance_deductions(None)
        res = await db.payroll.find_one_and_update(
            {"id": pid},
            {"$set": {"status": "paid", "paid_at": now, "txn_id": None}},
            return_document=True,
        )
        res.pop("_id", None)
        return res
    staff = await db.staff.find_one({"id": rec["staff_id"]}, {"_id": 0, "name": 1, "center_id": 1})
    payroll_ctx = await _derive_context_for_center((staff or {}).get("center_id"))
    txn = {
        "id": str(uuid.uuid4()),
        "type": "expense",
        "amount": rec["net"],
        "date": f"{rec['year']:04d}-{rec['month']:02d}-{rec['working_days']:02d}",
        "description": f"Salary: {staff.get('name','') if staff else ''} {rec['month']}/{rec['year']}",
        "company_id": payroll_ctx["company_id"],
        "partner_id": payroll_ctx["partner_id"],
        "center_id": (staff or {}).get("center_id"),
        "project_id": None,
        "items": [], "attachments": [],
        "created_by": user["id"], "created_at": now,
        "status": "approved", "approved_by": user["id"], "approved_at": now,
        "rejected_reason": None,
    }
    await db.transactions.insert_one(txn)
    # Phase-3 Batch B: reduce open advance balances via the shared helper (same
    # logic used by the zero-net short-circuit path above).
    await _consume_advance_deductions(txn["id"])
    res = await db.payroll.find_one_and_update(
        {"id": pid},
        {"$set": {"status": "paid", "paid_at": now, "txn_id": txn["id"]}},
        return_document=True,
    )
    res.pop("_id", None)
    return res



# =========================================================================
# PAYROLL BATCH WORKFLOW (Phase 55) — Finalise → Approval → Accounts Pay → Transaction.
# Business rule: HR calculates & finalises. Accountant pays. Admin can reopen.
# =========================================================================


class PayrollFinaliseIn(BaseModel):
    month: int = Field(ge=1, le=12)
    year: int = Field(ge=2020, le=2100)
    remarks: Optional[str] = None
    # None or "all" → split by staff.center_id and create one batch per center
    # (staff without a center are grouped into an "Unassigned" batch).
    # Any specific ID → single batch for that center only.
    center_id: Optional[str] = None


class PayrollBatchPayIn(BaseModel):
    method: Literal["bank_transfer", "neft", "rtgs", "imps", "cheque", "cash", "upi", "other"] = "bank_transfer"
    bank_account_id: Optional[str] = None
    payment_date: str  # YYYY-MM-DD
    utr: Optional[str] = None
    remarks: Optional[str] = None
    attachment_path: Optional[str] = None
    attachment_filename: Optional[str] = None


class PayrollBatchReopenIn(BaseModel):
    reason: Optional[str] = None
    reverse_transaction: bool = True  # If batch was already paid, reverse the txn too.


async def _derive_pending_at(batch: dict) -> dict:
    """Compute a dynamic 'Pending At' label + role for a payroll batch.

    Fully driven by the configured Approval Workflow — no hardcoded stage names.
    Falls back gracefully when the chain has no active step (accounts-payment
    stage, terminal states, or when no chain was configured at all).

    Returns a dict with keys: `pending_at_label`, `pending_at_role`,
    `pending_at_names`, `is_terminal`.
    """
    status = batch.get("status")
    # Terminal states — no pending action.
    if status == "paid":
        return {"pending_at_label": "Paid", "pending_at_role": None,
                "pending_at_names": [], "is_terminal": True}
    if status == "rejected":
        return {"pending_at_label": "Rejected", "pending_at_role": None,
                "pending_at_names": [], "is_terminal": True}
    if status in ("draft", "reopened", None):
        return {"pending_at_label": "Draft — awaiting finalisation",
                "pending_at_role": "hr", "pending_at_names": [], "is_terminal": False}

    # Active workflow states.
    if status == "pending_approval":
        # Chain step is the authoritative source. `pending_with` was populated
        # by `_enrich_with_approval_status`; names come from user resolution.
        step_label = batch.get("current_step_label") or "Approver"
        pw = batch.get("pending_with") or []
        names = [(u.get("name") or u.get("email")) for u in pw if u]
        if names:
            label = f"Pending at {step_label}: {', '.join(names[:3])}"
            if len(names) > 3:
                label += f" +{len(names) - 3}"
        else:
            label = f"Pending at {step_label}"
        # Best-effort role tag from the first approver.
        role = pw[0].get("role") if pw else None
        return {"pending_at_label": label, "pending_at_role": role,
                "pending_at_names": names, "is_terminal": False}

    if status == "pending_payment":
        # Post-approval stage — Accounts must disburse. Not part of the
        # configured chain (payment is out-of-band by design), so this label
        # is deterministic across every deployment.
        return {"pending_at_label": "Pending at Accounts (Final Payment)",
                "pending_at_role": "accountant", "pending_at_names": [],
                "is_terminal": False}

    # Unknown status — expose it as-is.
    return {"pending_at_label": f"Pending — {status}", "pending_at_role": None,
            "pending_at_names": [], "is_terminal": False}


@api.post("/payroll/finalise")
async def payroll_finalise(body: PayrollFinaliseIn, user=Depends(require_role("admin", "hr"))):
    """HR (or admin) locks the month's Draft payroll rows into a batch and pushes
    it into the approval workflow.

    Phase 60 — Center scoping:
      * body.center_id="<id>" → creates ONE batch for that center only.
        Duplicate guard on (center_id, month, year, active_status).
      * body.center_id=None or "all" → splits draft rows by staff.center_id and
        creates ONE batch per unique center (staff without a center land in an
        "Unassigned" batch with center_id=None).

    Existing rows already in a batch (finalised/approved/paid) are ignored.
    """
    m, y = body.month, body.year
    center_id = body.center_id if (body.center_id and body.center_id != "all") else None

    # Load draft rows for the month.
    draft_rows = await db.payroll.find(
        {"month": m, "year": y, "status": {"$in": [None, "draft", "reopened"]}},
        {"_id": 0},
    ).to_list(5000)
    if not draft_rows:
        raise HTTPException(400, f"No Draft payroll rows found for {m:02d}/{y}. Run Payroll first.")

    # Enrich rows with their staff.center_id + center_name so we can group.
    staff_ids = list({r["staff_id"] for r in draft_rows if r.get("staff_id")})
    staff_by_id = {}
    if staff_ids:
        for s in await db.staff.find({"id": {"$in": staff_ids}}, {"_id": 0, "id": 1, "center_id": 1}).to_list(5000):
            staff_by_id[s["id"]] = s
    center_ids_used = {(staff_by_id.get(r["staff_id"]) or {}).get("center_id") for r in draft_rows}
    center_ids_used = {c for c in center_ids_used}
    center_name_by_id: dict = {}
    real_ids = [c for c in center_ids_used if c]
    if real_ids:
        for c in await db.centers.find({"id": {"$in": real_ids}}, {"_id": 0, "id": 1, "name": 1}).to_list(2000):
            center_name_by_id[c["id"]] = c.get("name")

    # Decide which center → rows mapping to finalise.
    grouped: dict = {}  # center_id (or None) -> list of rows
    if body.center_id and body.center_id != "all":
        # Single-center finalisation — only rows whose staff belong to that center.
        for r in draft_rows:
            s = staff_by_id.get(r["staff_id"]) or {}
            if s.get("center_id") == body.center_id:
                grouped.setdefault(body.center_id, []).append(r)
        if not grouped:
            raise HTTPException(400, f"No Draft payroll rows for center {body.center_id} in {m:02d}/{y}.")
    else:
        # All-centers finalisation — split by staff.center_id.
        for r in draft_rows:
            s = staff_by_id.get(r["staff_id"]) or {}
            grouped.setdefault(s.get("center_id"), []).append(r)

    now = datetime.now(timezone.utc).isoformat()
    created_batches: list = []
    skipped_dupes: list = []

    for cid, rows_for_center in grouped.items():
        # Duplicate guard — enforced per (center_id, month, year, active_status).
        dup = await db.payroll_batches.find_one(
            {"month": m, "year": y, "center_id": cid,
             "status": {"$in": ["pending_approval", "approved", "pending_payment", "processing", "paid"]}},
            {"_id": 0, "id": 1, "status": 1},
        )
        if dup:
            skipped_dupes.append({"center_id": cid, "existing_batch_id": dup["id"], "status": dup["status"]})
            continue

        payroll_ids = [r["id"] for r in rows_for_center]
        gross = sum(float(r.get("gross") or 0) for r in rows_for_center)
        deductions = sum(float(r.get("deductions") or 0) for r in rows_for_center)
        net_payable = sum(float(r.get("net") or 0) for r in rows_for_center)
        c_name = center_name_by_id.get(cid) if cid else "Unassigned"

        batch_id = str(uuid.uuid4())
        doc = {
            "id": batch_id,
            "month": m, "year": y,
            "center_id": cid,
            "center_name": c_name,
            "staff_count": len(payroll_ids),
            "payroll_ids": payroll_ids,
            "gross": round(gross, 2),
            "deductions": round(deductions, 2),
            "net_payable": round(net_payable, 2),
            "amount": round(net_payable, 2),  # used by amount-based chain matching
            "status": "pending_approval",
            "created_by": user["id"], "created_at": now,
            "created_by_name": user.get("name") or user.get("email"),
            "finalised_by": user["id"], "finalised_at": now,
            "finalised_by_name": user.get("name") or user.get("email"),
            "remarks": body.remarks or "",
            "audit_log": [
                {"action": "finalised", "at": now, "by": user["id"],
                 "by_name": user.get("name") or user.get("email"),
                 "by_role": user.get("role"),
                 "old_status": "draft", "new_status": "pending_approval",
                 "remarks": body.remarks or ""},
            ],
        }
        # Attach approval chain (falls back to admin auto-approve if none configured).
        await _attach_chain_to_request("payroll", doc)
        await db.payroll_batches.insert_one(doc)

        # Lock all included payroll rows against edit.
        await db.payroll.update_many(
            {"id": {"$in": payroll_ids}},
            {"$set": {"batch_id": batch_id, "batch_status": "pending_approval", "locked": True,
                      "finalised_at": now, "finalised_by": user["id"]}},
        )

        # If chain resolved to auto-approve at Lv1 (no approvers), flip straight to pending_payment.
        if not doc.get("chain_snapshot") and doc.get("status") == "pending_approval":
            await db.payroll_batches.update_one(
                {"id": batch_id},
                {"$set": {"status": "pending_payment", "approved_at": now, "approved_by": user["id"],
                          "audit_log": doc["audit_log"] + [{"action": "auto_approved", "at": now,
                                                           "by": user["id"], "by_name": user.get("name") or user.get("email"),
                                                           "by_role": user.get("role"),
                                                           "remarks": "No approval chain configured — auto-approved",
                                                           "old_status": "pending_approval", "new_status": "pending_payment"}]}},
            )
        created_batches.append(await _payroll_batch_out(batch_id))

    return {"batches": created_batches, "skipped_duplicates": skipped_dupes}


async def _payroll_batch_out(batch_id: str) -> dict:
    """Fetch a batch + inline its payroll rows for the UI.

    Phase 60 — always enriched with `pending_at_label`, `pending_at_role`,
    `pending_with` (when in an approval-based state), `center_name` and the
    full `audit_log` so HR sees a consistent workflow view regardless of
    which stage the batch is in.
    """
    b = await db.payroll_batches.find_one({"id": batch_id}, {"_id": 0})
    if not b:
        raise HTTPException(404, "Payroll batch not found")
    rows = await db.payroll.find({"batch_id": batch_id}, {"_id": 0}).to_list(2000)
    # Enrich rows with staff name/emp_code for the review UI.
    sids = list({r.get("staff_id") for r in rows if r.get("staff_id")})
    if sids:
        srows = await db.staff.find({"id": {"$in": sids}}, {"_id": 0, "id": 1, "name": 1, "employee_code": 1, "bank_account_no": 1, "ifsc": 1}).to_list(2000)
        by_id = {s["id"]: s for s in srows}
        for r in rows:
            s = by_id.get(r.get("staff_id"))
            if s:
                r["staff_name"] = s.get("name")
                r["employee_code"] = s.get("employee_code")
                r["bank_account_no_masked"] = ("****" + (s.get("bank_account_no") or "")[-4:]) if s.get("bank_account_no") else None
                r["ifsc"] = s.get("ifsc")
    b["rows"] = rows
    # Backfill center_name for legacy batches created before Phase 60.
    if b.get("center_id") and not b.get("center_name"):
        c = await db.centers.find_one({"id": b["center_id"]}, {"_id": 0, "name": 1})
        b["center_name"] = (c or {}).get("name") or None
    if not b.get("center_id"):
        b.setdefault("center_name", "Unassigned")
    # Pending-approval batches carry live chain-resolution info; other statuses
    # get a static label from `_derive_pending_at`.
    if b.get("status") == "pending_approval":
        await _enrich_with_approval_status(b)
    b.update(await _derive_pending_at(b))
    return b


@api.get("/payroll-batches")
async def list_payroll_batches(
    status: Optional[str] = None,
    month: Optional[int] = None,
    year: Optional[int] = None,
    center_id: Optional[str] = None,
    pending_at_role: Optional[str] = None,
    user=Depends(require_role("admin", "hr", "accountant", "senior_manager", "manager", "center_manager", "center_staff")),
):
    q: dict = {}
    # Phase 65 — strict center-based data isolation. Head-level users
    # (admin/senior_manager) see everything; scoped users see only their
    # assigned centers. `center_id=null` batches are visible only to head-level.
    scope = _center_scope_query(user, field="center_id")
    if scope.get("_never_"):
        return []
    if scope:
        q.update(scope)
    if status:
        q["status"] = status
    if month:
        q["month"] = month
    if year:
        q["year"] = year
    if center_id == "unassigned":
        # Only head-level users can filter for unassigned (center_id=null).
        if _scoped_center_ids(user) is not None:
            return []
        q["center_id"] = None
    elif center_id and center_id != "all":
        # Requested center MUST be within the caller's scope.
        allowed = _scoped_center_ids(user)
        if allowed is not None and center_id not in allowed:
            return []
        q["center_id"] = center_id
    rows = await db.payroll_batches.find(q, {"_id": 0}).sort([("year", -1), ("month", -1), ("created_at", -1)]).to_list(500)
    # Enrich every batch with dynamic pending_at so filters + list rendering
    # can drive off a single, stable field.
    for r in rows:
        if r.get("center_id") and not r.get("center_name"):
            c = await db.centers.find_one({"id": r["center_id"]}, {"_id": 0, "name": 1})
            r["center_name"] = (c or {}).get("name") or None
        if not r.get("center_id"):
            r.setdefault("center_name", "Unassigned")
        if r.get("status") == "pending_approval":
            await _enrich_with_approval_status(r)
        r.update(await _derive_pending_at(r))
    if pending_at_role:
        rows = [r for r in rows if (r.get("pending_at_role") or "") == pending_at_role]
    return rows


@api.get("/payroll-batches/{batch_id}")
async def get_payroll_batch(batch_id: str, user=Depends(require_role("admin", "hr", "accountant", "senior_manager", "manager", "center_manager", "center_staff"))):
    b = await _payroll_batch_out(batch_id)
    # Phase 65 — IDOR guard. Scoped users MUST be mapped to the batch's center.
    allowed = _scoped_center_ids(user)
    if allowed is not None:
        if b.get("center_id") and b["center_id"] not in allowed:
            raise HTTPException(403, "Not authorised to view this payroll batch")
        if not b.get("center_id"):
            # center_id=null (Unassigned) → head-level only.
            raise HTTPException(403, "Not authorised to view this payroll batch")
    return b


@api.post("/payroll-batches/{batch_id}/pay")
async def pay_payroll_batch(batch_id: str, body: PayrollBatchPayIn, user=Depends(require_role("admin", "accountant"))):
    """Accountant marks the approved batch as paid — creates ONE Transaction entry
    (type=expense, source=payroll_batch, amount=net_payable) and flips every payroll
    row + the batch to `paid`. Idempotent: guards against double-payment.
    """
    batch = await db.payroll_batches.find_one({"id": batch_id}, {"_id": 0})
    if not batch:
        raise HTTPException(404, "Batch not found")
    if batch.get("status") == "paid":
        raise HTTPException(400, "Batch already paid — cannot pay twice")
    if batch.get("status") != "pending_payment":
        raise HTTPException(400, f"Batch is in status '{batch.get('status')}' — payment requires 'pending_payment' (approved) state")
    # Guard: refuse to pay a batch whose net is <= 0. Negative nets mean advance recoveries
    # exceed gross — that scenario is a bookkeeping adjustment, not a payment. HR must
    # correct the underlying rows (or exclude those staff via reopen) first. Zero-net
    # batches would create a ₹0 transaction which is noise; also refuse.
    net_pay = float(batch.get("net_payable") or 0)
    if net_pay <= 0:
        raise HTTPException(
            400,
            f"Cannot pay a batch with non-positive net (₹{net_pay:,.2f}). Reopen the batch and correct payroll rows first — negative nets usually mean advance recoveries exceed gross for some staff.",
        )

    # Optionally require a configured bank account for the debit. Same behaviour as vendor payments.
    acct = None
    if body.bank_account_id:
        acct = await db.bank_accounts.find_one({"id": body.bank_account_id, "active": True}, {"_id": 0})
        if not acct:
            raise HTTPException(400, "Bank account not found or inactive")

    now = datetime.now(timezone.utc).isoformat()
    # Set processing early so the UI can show intermediate state (idempotency window).
    await db.payroll_batches.update_one({"id": batch_id}, {"$set": {"status": "processing"}})

    payroll_rows = await db.payroll.find({"batch_id": batch_id}, {"_id": 0}).to_list(2000)
    # Derive company / partner context from first staff's center for the txn attribution.
    first_sid = payroll_rows[0]["staff_id"] if payroll_rows else None
    first_staff = await db.staff.find_one({"id": first_sid}, {"_id": 0, "center_id": 1}) if first_sid else None
    ctx = await _derive_context_for_center((first_staff or {}).get("center_id"))
    txn_amount = float(batch.get("net_payable") or 0)
    txn = {
        "id": str(uuid.uuid4()),
        "type": "expense",
        "amount": txn_amount,
        "date": body.payment_date or now[:10],
        "description": f"Payroll {batch['month']:02d}/{batch['year']} · {batch['staff_count']} staff · Net ₹{txn_amount:,.0f}",
        "company_id": ctx["company_id"],
        "partner_id": ctx["partner_id"],
        "center_id": (first_staff or {}).get("center_id"),
        "project_id": None,
        "items": [], "attachments": [{"path": body.attachment_path, "filename": body.attachment_filename}] if body.attachment_path else [],
        "source": "payroll_batch",
        "payroll_batch_id": batch_id,
        "payment_mode": body.method,
        "utr": body.utr,
        "bank_account_id": body.bank_account_id,
        "remarks": body.remarks,
        "created_by": user["id"], "created_at": now,
        "status": "approved", "approved_by": user["id"], "approved_at": now,
        "rejected_reason": None,
    }
    await db.transactions.insert_one(txn)
    # Also debit the bank account ledger if configured.
    if acct and txn_amount > 0:
        await _post_bank_ledger(
            account_id=acct["id"], direction="debit", amount=txn_amount,
            source="payroll_batch", source_id=batch_id,
            remarks=f"Payroll {batch['month']:02d}/{batch['year']} · {batch['staff_count']} staff" + (f" · UTR {body.utr}" if body.utr else ""),
            vendor_name=None, center_id=(first_staff or {}).get("center_id"),
            center_name=None, date=body.payment_date or now[:10], user=user,
        )

    # Mark each payroll row as paid + link to the transaction (kept per-row for legacy queries).
    await db.payroll.update_many(
        {"batch_id": batch_id},
        {"$set": {"status": "paid", "paid_at": now, "txn_id": txn["id"], "batch_status": "paid"}},
    )

    # Also emit a staff_payments row per employee so Staff Financial History aggregator picks them up.
    for r in payroll_rows:
        sp = {
            "id": str(uuid.uuid4()),
            "employee_id": r["staff_id"],
            "transaction_type": "salary",
            "source_module": "payroll_batch",
            "source_id": r["id"],
            "amount": float(r.get("net") or 0),
            "net_amount": float(r.get("net") or 0),
            "status": "paid",
            "payment_date": body.payment_date or now[:10],
            "payment_mode": body.method,
            "utr": body.utr,
            "batch_id": batch_id,
            "txn_id": txn["id"],
            "month": batch["month"],
            "year": batch["year"],
            "created_by": user["id"],
            "created_at": now,
        }
        await db.staff_payments.insert_one(sp)
        # Notify staff (best-effort).
        _u = await db.staff.find_one({"id": r["staff_id"]}, {"_id": 0, "user_id": 1, "name": 1})
        if _u and _u.get("user_id"):
            await _notify(_u["user_id"],
                          f"Salary ₹{float(r.get('net') or 0):,.0f} paid for {batch['month']:02d}/{batch['year']}",
                          ntype="salary_paid", ref_id=r["id"], link="/check-in")

    audit_log = list(batch.get("audit_log") or [])
    audit_log.append({
        "action": "paid", "at": now, "by": user["id"],
        "by_name": user.get("name") or user.get("email"),
        "old_status": "pending_payment", "new_status": "paid",
        "remarks": body.remarks or "",
        "payment": {"method": body.method, "utr": body.utr, "date": body.payment_date, "bank_account_id": body.bank_account_id},
    })
    await db.payroll_batches.update_one(
        {"id": batch_id},
        {"$set": {
            "status": "paid",
            "paid_at": now, "paid_by": user["id"],
            "paid_by_name": user.get("name") or user.get("email"),
            "transaction_id": txn["id"],
            "payment": {
                "method": body.method, "bank_account_id": body.bank_account_id,
                "payment_date": body.payment_date, "utr": body.utr,
                "remarks": body.remarks, "attachment_path": body.attachment_path,
                "attachment_filename": body.attachment_filename,
            },
            "audit_log": audit_log,
        }},
    )
    return await _payroll_batch_out(batch_id)


@api.post("/payroll-batches/{batch_id}/reopen")
async def reopen_payroll_batch(batch_id: str, body: PayrollBatchReopenIn, user=Depends(require_role("admin"))):
    """Admin-only escape hatch. Reverses a paid batch's transaction (if requested)
    and unlocks the underlying payroll rows so HR can re-edit them.
    """
    batch = await db.payroll_batches.find_one({"id": batch_id}, {"_id": 0})
    if not batch:
        raise HTTPException(404, "Batch not found")

    now = datetime.now(timezone.utc).isoformat()
    old_status = batch.get("status")
    # Reverse the linked transaction only if the batch was actually paid.
    if old_status == "paid" and body.reverse_transaction and batch.get("transaction_id"):
        rev_id = str(uuid.uuid4())
        # Create a reversal transaction (type=income) to net out the original expense.
        orig = await db.transactions.find_one({"id": batch["transaction_id"]}, {"_id": 0})
        if orig:
            rev = {
                "id": rev_id,
                "type": "income",
                "amount": float(orig.get("amount") or 0),
                "date": now[:10],
                "description": f"REVERSAL — {orig.get('description','')} (reopened by admin)",
                "company_id": orig.get("company_id"),
                "partner_id": orig.get("partner_id"),
                "center_id": orig.get("center_id"),
                "project_id": None, "items": [], "attachments": [],
                "source": "payroll_batch_reversal",
                "payroll_batch_id": batch_id,
                "reverses_txn_id": batch["transaction_id"],
                "created_by": user["id"], "created_at": now,
                "status": "approved", "approved_by": user["id"], "approved_at": now,
                "rejected_reason": body.reason or "Admin reopened payroll batch",
            }
            await db.transactions.insert_one(rev)
            # Mark original transaction as reversed for audit clarity.
            await db.transactions.update_one(
                {"id": batch["transaction_id"]},
                {"$set": {"reversed_by_txn_id": rev_id, "reversed_at": now, "reversed_by": user["id"]}},
            )
            # Also reverse the bank ledger row if one was posted.
            if orig.get("bank_account_id"):
                await _post_bank_ledger(
                    account_id=orig["bank_account_id"], direction="credit",
                    amount=float(orig.get("amount") or 0),
                    source="payroll_batch_reversal", source_id=batch_id,
                    remarks=f"REVERSAL of payroll {batch['month']:02d}/{batch['year']}: {body.reason or 'admin reopen'}",
                    vendor_name=None, center_id=orig.get("center_id"),
                    center_name=None, date=now[:10], user=user,
                )
        # Also flip the staff_payments rows to "cancelled" so Financial History reflects the reversal.
        await db.staff_payments.update_many(
            {"batch_id": batch_id, "status": "paid"},
            {"$set": {"status": "cancelled", "cancelled_at": now, "cancel_reason": body.reason or "admin reopen"}},
        )

    # Return payroll rows to Draft so HR can edit + re-finalise. Preserve batch_id
    # so admins can see the history until the next re-finalise overwrites it.
    await db.payroll.update_many(
        {"batch_id": batch_id},
        {"$set": {"status": "draft", "locked": False, "batch_status": "reopened", "reopened_at": now},
         "$unset": {"paid_at": "", "txn_id": ""}},
    )

    audit_log = list(batch.get("audit_log") or [])
    audit_log.append({
        "action": "reopened", "at": now, "by": user["id"],
        "by_name": user.get("name") or user.get("email"),
        "old_status": old_status, "new_status": "reopened",
        "remarks": body.reason or "",
    })
    await db.payroll_batches.update_one(
        {"id": batch_id},
        {"$set": {"status": "reopened", "reopened_at": now, "reopened_by": user["id"], "audit_log": audit_log}},
    )
    return await _payroll_batch_out(batch_id)


@api.patch("/payroll/{pid}/reopen")
async def reopen_payroll_row(pid: str, user=Depends(require_role("admin"))):
    """Admin can reopen a single paid payroll row (fine-grained). Reverses the linked
    transaction (if any) and flips status back to Draft. If the row belongs to a
    Paid batch, the batch is also flipped to 'reopened' so it can be re-finalised.
    """
    rec = await db.payroll.find_one({"id": pid}, {"_id": 0})
    if not rec:
        raise HTTPException(404, "Not found")
    if rec.get("status") != "paid":
        raise HTTPException(400, "Only Paid payroll rows can be reopened")
    now = datetime.now(timezone.utc).isoformat()
    if rec.get("batch_id"):
        # Reopen the whole batch to keep totals consistent.
        return await reopen_payroll_batch(rec["batch_id"], PayrollBatchReopenIn(reason="Row-level admin reopen"), user)
    # Legacy per-row Pay All path — reverse just this row's transaction.
    if rec.get("txn_id"):
        orig = await db.transactions.find_one({"id": rec["txn_id"]}, {"_id": 0})
        if orig:
            rev = {
                "id": str(uuid.uuid4()), "type": "income", "amount": float(orig.get("amount") or 0),
                "date": now[:10], "description": f"REVERSAL — {orig.get('description','')}",
                "company_id": orig.get("company_id"), "partner_id": orig.get("partner_id"),
                "center_id": orig.get("center_id"), "project_id": None,
                "items": [], "attachments": [], "source": "payroll_row_reversal",
                "payroll_id": pid, "reverses_txn_id": rec["txn_id"],
                "created_by": user["id"], "created_at": now,
                "status": "approved", "approved_by": user["id"], "approved_at": now,
                "rejected_reason": "Admin reopened payroll row",
            }
            await db.transactions.insert_one(rev)
            await db.transactions.update_one(
                {"id": rec["txn_id"]}, {"$set": {"reversed_by_txn_id": rev["id"], "reversed_at": now, "reversed_by": user["id"]}},
            )
    await db.payroll.update_one(
        {"id": pid},
        {"$set": {"status": "draft", "locked": False, "reopened_at": now, "reopened_by": user["id"]},
         "$unset": {"paid_at": "", "txn_id": ""}},
    )
    return {"ok": True, "id": pid, "status": "draft"}


@api.delete("/payroll/{pid}")
async def delete_payroll_row(pid: str, user=Depends(require_role("admin"))):
    """Admin escape-hatch: delete a payroll row entirely. If the row is Paid, reverses
    the linked transaction (income offset) and cancels the staff_payments row.
    If the row is part of an active batch, decrements batch totals so the batch stays
    consistent. Emits an audit trail row in `payroll_deletions` for compliance.
    """
    rec = await db.payroll.find_one({"id": pid}, {"_id": 0})
    if not rec:
        raise HTTPException(404, "Not found")
    now = datetime.now(timezone.utc).isoformat()

    # If paid → reverse the linked transaction and cancel staff_payments.
    if rec.get("status") == "paid" and rec.get("txn_id"):
        orig = await db.transactions.find_one({"id": rec["txn_id"]}, {"_id": 0})
        if orig and not orig.get("reversed_by_txn_id"):
            # Only reverse the SLICE that belongs to this row (batch txn covers all rows).
            row_net = float(rec.get("net") or 0)
            if row_net > 0:
                rev = {
                    "id": str(uuid.uuid4()), "type": "income",
                    "amount": row_net,
                    "date": now[:10],
                    "description": f"REVERSAL (row delete) — {orig.get('description','')} · staff {rec.get('staff_id')}",
                    "company_id": orig.get("company_id"), "partner_id": orig.get("partner_id"),
                    "center_id": orig.get("center_id"), "project_id": None,
                    "items": [], "attachments": [], "source": "payroll_row_delete_reversal",
                    "payroll_id": pid, "reverses_txn_id": rec["txn_id"],
                    "created_by": user["id"], "created_at": now,
                    "status": "approved", "approved_by": user["id"], "approved_at": now,
                    "rejected_reason": "Admin deleted payroll row",
                }
                await db.transactions.insert_one(rev)
        # Also cancel any staff_payments row linked to this payroll id
        await db.staff_payments.update_many(
            {"source_id": pid, "status": "paid"},
            {"$set": {"status": "cancelled", "cancelled_at": now, "cancel_reason": "payroll row deleted by admin"}},
        )

    # If part of a batch, update batch counters + audit log so nothing goes stale.
    if rec.get("batch_id"):
        batch = await db.payroll_batches.find_one({"id": rec["batch_id"]}, {"_id": 0})
        if batch:
            audit_log = list(batch.get("audit_log") or [])
            audit_log.append({
                "action": "row_deleted", "at": now,
                "by": user["id"], "by_name": user.get("name") or user.get("email"),
                "old_status": rec.get("status"), "new_status": "deleted",
                "remarks": f"Admin deleted row for staff {rec.get('staff_id')}",
            })
            new_ids = [x for x in (batch.get("payroll_ids") or []) if x != pid]
            await db.payroll_batches.update_one(
                {"id": rec["batch_id"]},
                {"$set": {
                    "payroll_ids": new_ids,
                    "staff_count": len(new_ids),
                    "gross": round(float(batch.get("gross") or 0) - float(rec.get("gross") or 0), 2),
                    "deductions": round(float(batch.get("deductions") or 0) - float(rec.get("deductions") or 0), 2),
                    "net_payable": round(float(batch.get("net_payable") or 0) - float(rec.get("net") or 0), 2),
                    "amount": round(float(batch.get("amount") or 0) - float(rec.get("net") or 0), 2),
                    "audit_log": audit_log,
                }},
            )

    # Snapshot the row for compliance (payroll can be re-run to regenerate).
    await db.payroll_deletions.insert_one({
        "id": str(uuid.uuid4()),
        "deleted_at": now,
        "deleted_by": user["id"],
        "deleted_by_name": user.get("name") or user.get("email"),
        "snapshot": {k: v for k, v in rec.items() if k != "_id"},
    })
    await db.payroll.delete_one({"id": pid})
    return {"ok": True, "id": pid, "deleted": True}

# ---------- Stock View ----------
@api.get("/stock")
async def list_stock(
    center_id: Optional[str] = None,
    txn_type: Optional[str] = None,
    start: Optional[str] = None,
    end: Optional[str] = None,
    search: Optional[str] = None,
    user=Depends(get_current_user),
):
    """Flatten transaction line-items into a stock-view list.

    Returns one row per item across every transaction (filtered by center / type / date).
    Adds a `is_duplicate` flag = True if the same lowercased item-name appears in
    an earlier transaction (globally, across all centers — chronological by date+created_at).
    The earliest occurrence per name is marked is_duplicate=False ("First").
    """
    q: dict = {}
    if center_id:
        q["center_id"] = center_id
    # Center-manager / center-staff scoping
    role = user.get("role")
    if role in ("center_manager", "center_staff"):
        scoped_ids = user.get("assigned_center_ids") or []
        if center_id and center_id not in scoped_ids:
            return []
        q["center_id"] = {"$in": scoped_ids}
    if txn_type:
        q["type"] = txn_type
    if start or end:
        rng: dict = {}
        if start:
            rng["$gte"] = start
        if end:
            rng["$lte"] = end
        q["date"] = rng

    # Need *all* transactions globally (regardless of center filter) to compute duplicates
    # but we only emit rows for the filtered set. Strategy: load all matching + a separate
    # pass to find first-occurrence-per-name across the *entire* collection (ignoring filters
    # so duplicate flag stays stable across views).
    docs = await db.transactions.find(q, {"_id": 0}).sort([("date", 1), ("created_at", 1)]).to_list(20000)

    # First-occurrence lookup: scan transactions in chronological order (bounded to 50000
    # to keep memory + time predictable on large datasets — the goal is just to find the
    # earliest occurrence per item name, so a sorted scan within this bound is sufficient
    # for any realistic finance-tracker volume).
    seen_first = {}
    cursor = db.transactions.find(
        {}, {"_id": 0, "id": 1, "date": 1, "created_at": 1, "items": 1}
    ).sort([("date", 1), ("created_at", 1)]).limit(50000)
    async for d in cursor:
        for it in (d.get("items") or []):
            n = (it.get("name") or "").strip().lower()
            if not n:
                continue
            if n not in seen_first:
                seen_first[n] = (d.get("date"), d.get("created_at"), d.get("id"))

    # Centers map for names
    cdocs = await db.centers.find({}, {"_id": 0, "id": 1, "name": 1}).to_list(2000)
    cname_by_id = {c["id"]: c["name"] for c in cdocs}

    rows: list = []
    needle = (search or "").strip().lower()
    for d in docs:
        for it in (d.get("items") or []):
            name = (it.get("name") or "").strip()
            if needle and needle not in name.lower():
                continue
            n_low = name.lower()
            first = seen_first.get(n_low)
            is_first_here = first and first[2] == d.get("id") and \
                (first[0] == d.get("date") and first[1] == d.get("created_at"))
            rows.append({
                "txn_id": d.get("id"),
                "txn_type": d.get("type"),
                "txn_status": d.get("status"),
                "date": d.get("date"),
                "center_id": d.get("center_id"),
                "center_name": cname_by_id.get(d.get("center_id")) if d.get("center_id") else None,
                "name": name,
                "quantity": it.get("quantity") or 0,
                "rate": it.get("rate") or 0,
                "amount": it.get("amount") or 0,
                "is_duplicate": bool(first) and not is_first_here,
            })
    # Sort newest first for display
    rows.sort(key=lambda r: (r.get("date") or "", r.get("txn_id") or ""), reverse=True)
    return rows


# ---------- Item Suggestions (autocomplete) ----------
@api.get("/items/suggestions")
async def item_suggestions(q: Optional[str] = None, limit: int = 50, _=Depends(get_current_user)):
    """Return distinct item names previously used in any transaction (case-insensitive prefix match)."""
    pipeline = [
        {"$unwind": "$items"},
        {"$match": {"items.name": {"$ne": ""}}},
        {"$group": {"_id": {"$toLower": "$items.name"}, "name": {"$first": "$items.name"}, "count": {"$sum": 1}}},
    ]
    if q and q.strip():
        rx = {"$regex": re.escape(q.strip()), "$options": "i"}
        pipeline.append({"$match": {"name": rx}})
    pipeline += [
        {"$sort": {"count": -1, "name": 1}},
        {"$limit": max(1, min(limit, 500))},
        {"$project": {"_id": 0, "name": 1, "count": 1}},
    ]
    out = await db.transactions.aggregate(pipeline).to_list(500)
    return out


# ---------- Approval Log (admin-only) ----------
@api.get("/approval-log")
async def approval_log(
    type_filter: Optional[str] = None,  # 'transaction', 'reimbursement', 'leave', 'payroll'
    action: Optional[str] = None,        # 'approved', 'rejected', 'paid', 'l1_approved', 'accountant_approved'
    start: Optional[str] = None,
    end: Optional[str] = None,
    limit: int = 500,
    _=Depends(require_role("admin")),
):
    """Unified final-approval feed across transactions, reimbursements, leaves, payroll."""
    rows: list = []

    # User name lookup
    users = await db.users.find({}, {"_id": 0, "id": 1, "name": 1, "email": 1}).to_list(2000)
    uname = {u["id"]: (u.get("name") or u.get("email") or "—") for u in users}

    def _in_range(iso: Optional[str]) -> bool:
        if not iso:
            return False
        d = iso[:10]
        if start and d < start:
            return False
        if end and d > end:
            return False
        return True

    # Transactions: approved/rejected
    if not type_filter or type_filter == "transaction":
        async for d in db.transactions.find(
            {"status": {"$in": ["approved", "rejected"]}}, {"_id": 0}
        ).sort("approved_at", -1).limit(2000):
            ts = d.get("approved_at") or d.get("created_at")
            if (start or end) and not _in_range(ts):
                continue
            act = d.get("status")
            if action and action != act:
                continue
            rows.append({
                "type": "transaction",
                "action": act,
                "ref_id": d.get("id"),
                "at": ts,
                "by": uname.get(d.get("approved_by")) or "—",
                "amount": d.get("amount"),
                "summary": f"{d.get('type','').title()} — {d.get('description','') or ''}".strip(" —"),
                "remarks": d.get("rejected_reason") or "",
            })

    # Pre-load staff names once for both reimbursement and leave blocks (avoids N+1)
    sdocs = await db.staff.find({}, {"_id": 0, "id": 1, "name": 1}).to_list(5000)
    sname_by_id = {s["id"]: s.get("name", "") for s in sdocs}

    # Reimbursements: emit a row for each completed stage
    if not type_filter or type_filter == "reimbursement":
        async for d in db.reimbursements.find({}, {"_id": 0}).sort("created_at", -1).limit(2000):
            sname = sname_by_id.get(d.get("staff_id"), "")
            base = {"type": "reimbursement", "ref_id": d.get("id"), "amount": d.get("amount"),
                    "summary": f"Reimbursement — {sname}".strip(" —")}
            stages = [
                ("l1_approved",      d.get("l1_approved_at"),       d.get("l1_approved_by")),
                ("accountant_approved", d.get("accountant_approved_at"), d.get("accountant_approved_by")),
                ("paid",             d.get("paid_at"),              d.get("paid_by")),
            ]
            if d.get("status") == "rejected":
                stages.append(("rejected", d.get("rejected_at"), None))
            for act, at, by in stages:
                if not at:
                    continue
                if (start or end) and not _in_range(at):
                    continue
                if action and action != act:
                    continue
                rows.append({**base, "action": act, "at": at,
                             "by": uname.get(by) or "—",
                             "remarks": d.get("rejected_reason", "") if act == "rejected" else ""})

    # Leaves (approved/rejected)
    if not type_filter or type_filter == "leave":
        async for d in db.leaves.find({"status": {"$in": ["approved", "rejected"]}}, {"_id": 0}).sort("decided_at", -1).limit(2000):
            sname = sname_by_id.get(d.get("staff_id"), "")
            at = d.get("decided_at") or d.get("created_at")
            if (start or end) and not _in_range(at):
                continue
            act = d.get("status")
            if action and action != act:
                continue
            rows.append({
                "type": "leave", "action": act, "ref_id": d.get("id"),
                "at": at, "by": uname.get(d.get("decided_by")) or "—", "amount": None,
                "summary": f"Leave — {sname} ({d.get('start_date')} → {d.get('end_date')})",
                "remarks": d.get("reason", "") or "",
            })

    # Payroll (paid)
    if not type_filter or type_filter == "payroll":
        async for d in db.payroll.find({"status": "paid"}, {"_id": 0}).sort("paid_at", -1).limit(2000):
            at = d.get("paid_at")
            if (start or end) and not _in_range(at):
                continue
            if action and action != "paid":
                continue
            rows.append({
                "type": "payroll", "action": "paid", "ref_id": d.get("id"),
                "at": at, "by": uname.get(d.get("paid_by")) or "—",
                "amount": d.get("net"),
                "summary": f"Payroll — {d.get('staff_name','')} {d.get('month')}/{d.get('year')}",
                "remarks": "",
            })

    rows.sort(key=lambda r: r.get("at") or "", reverse=True)
    return rows[: max(1, min(limit, 2000))]


# ---------- Programs (Batches + Milestone Payments) ----------
class BatchIn(BaseModel):
    model_config = ConfigDict(extra="ignore")
    project_id: str
    center_id: Optional[str] = None
    # Phase 37: link to the allocated target that seeded this batch. Legacy
    # batches (created before Batch Management module) leave this None and are
    # grandfathered. New batches created via /batch-management MUST supply this.
    target_id: Optional[str] = None
    # Company under which this batch's company-share income will be tagged on every
    # milestone receive. Can be overridden at receive-time per milestone.
    company_id: Optional[str] = None
    partner_ids: List[str] = Field(default_factory=list)
    name: str = Field(min_length=1)
    start_date: Optional[str] = ""
    end_date: Optional[str] = ""
    total_beneficiaries: int = 0
    description: Optional[str] = ""
    # Job-role rows drive the batch role-total: rows of {category 1/2/3, job_role, candidates, hours}
    job_roles: List[dict] = Field(default_factory=list)
    # Outcome counters used for 2nd / 3rd milestone proportional splits + failed-candidate recovery
    passed_candidates: int = Field(default=0, ge=0)
    placed_candidates: int = Field(default=0, ge=0)
    # Partner profit-share % of GROSS milestone income that goes to partners (split equally among
    # partner_ids). Company keeps (100 − this). Default 0 = no partner share (all to company).
    partner_share_percent: float = Field(default=0, ge=0, le=100)
    # When True, batch is closed — no new fooding entries can be created.
    # Set/unset via /batches/{id}/close and /batches/{id}/reopen endpoints.
    closed: bool = False
    # ---- MIS overlay fields (Phase 36B — Single Source of Truth) ----
    # Lifecycle. See BATCH_LIFECYCLE_STATES (10-state machine). Defaults to "Draft".
    lifecycle_status: Optional[str] = "Draft"
    # Geo / plan
    state: Optional[str] = ""
    territory: Optional[str] = ""
    target_year: Optional[str] = ""             # e.g. "2025-26"
    training_type: Optional[str] = ""           # "STT" | "RPL"
    total_target: int = 0                       # target enrolments (separate from total_beneficiaries)
    sdms_batch_id: Optional[str] = ""
    # Attendance / dropout
    attendance_pct: float = Field(default=0, ge=0, le=100)
    total_dropout: int = 0
    # Assessment
    assessment_date: Optional[str] = ""
    assessment_agency: Optional[str] = ""
    assessor_name: Optional[str] = ""
    assessor_contact: Optional[str] = ""
    total_certified: int = 0
    assessment_status: Optional[str] = ""       # Pending | Conducted | Result Awaited | Result Declared
    actual_present: int = 0
    pass_count: int = 0
    fail_count: int = 0
    absent_count: int = 0
    billing_status: Optional[str] = ""
    # Placement
    num_placement: int = 0
    offer_letter_status: Optional[str] = ""
    placement_month_1: Optional[str] = ""
    placement_month_2: Optional[str] = ""
    placement_month_3: Optional[str] = ""
    # ---- Phase 38 · Work Order Allocation ----
    # Rate engine inputs. category ∈ {I, II, III}; fy_year e.g. '2026-27'.
    fy_year: Optional[str] = ""
    category: Optional[str] = ""             # I | II | III
    job_role_master_id: Optional[str] = None  # FK to db.job_role_master (Phase 38)
    job_role_hours: float = Field(default=0, ge=0)
    num_candidates: int = Field(default=0, ge=0)
    # Derived (backend-authoritative — frontend value ignored on save).
    is_lwe: Optional[bool] = None
    base_rate: float = 0
    final_rate: float = 0
    work_order_value: float = 0
    # Phase 81 · Link to the Work Order master (source of truth for WO Value/PBG).
    work_order_id: Optional[str] = None


class BatchOut(BatchIn):
    id: str
    created_at: str
    # Lifecycle-derived lock flags (auto-set by /batches/{id}/lifecycle)
    basic_locked: Optional[bool] = False
    attendance_locked: Optional[bool] = False
    assessment_locked: Optional[bool] = False
    placement_locked: Optional[bool] = False
    # Audit trail of lifecycle transitions
    lifecycle_history: List[dict] = Field(default_factory=list)
    # Timestamp set by the daily auto-close scheduler when it closes an expired batch.
    auto_closed_at: Optional[str] = None
    # Phase 81 · enriched Work Order number for display (from linked work_order_id)
    work_order_no: Optional[str] = None
    # Live enrolled count (Σ active candidate records for this batch). Computed
    # on read from db.candidates — never a stored/manual value.
    enrolled: Optional[int] = 0


# Category hourly rates (fixed business config — change here if statutory rates revise).
# Category "other" is a custom-rate row — admin enters the rate manually per row (stored
# in r["custom_rate"]). JOB_CATEGORY_RATES lookup returns 0.0 for "other"; effective rate
# is resolved in _compute_batch_milestones.
JOB_CATEGORY_RATES = {"1": 56.35, "2": 52.50, "3": 36.85}
UNIFORM_PER_CANDIDATE = 1000.0  # one-time uniform allowance, applied ONLY on 1st milestone

# Milestone shares of role_total (Σ candidates × rate × hours). Uniform is added on top of 1st only.
MILESTONE_SHARES = {"1st": 0.30, "2nd": 0.40, "3rd": 0.30}


def _compute_batch_milestones(job_roles: list, passed: int = 0, placed: int = 0) -> dict:
    """Return per-milestone breakdown.

    Formula (per user spec):
      role_total      = Σ(candidates × CATEGORY_RATE × hours)
      uniform_total   = total_candidates × ₹1000     (1st milestone only)
      1st_amount      = 30% × role_total + uniform_total
      2nd_gross       = 40% × role_total × (passed / total)
      2nd_recovery    = 30% × role_total × (failed / total)   # already-disbursed for failed
      2nd_net         = 2nd_gross − 2nd_recovery
      3rd_amount      = 30% × role_total × (placed / total)
    """
    rows_out = []
    role_total = 0.0
    total_candidates = 0
    for r in (job_roles or []):
        cat = str(r.get("category", "")).strip()
        # "other" → use per-row custom_rate (default 0 if not set). Cat 1/2/3 use the fixed table.
        if cat == "other":
            rate = float(r.get("custom_rate") or 0)
        else:
            rate = JOB_CATEGORY_RATES.get(cat, 0.0)
        candidates = int(r.get("candidates") or 0)
        hours = float(r.get("hours") or 0)
        row_total = round(candidates * rate * hours, 2)
        role_total += row_total
        total_candidates += candidates
        rows_out.append({
            "category": cat, "job_role": r.get("job_role", "") or "",
            "candidates": candidates, "hours": hours, "rate": rate,
            "row_total": row_total,
            "custom_rate": float(r.get("custom_rate") or 0) if cat == "other" else None,
        })
    role_total = round(role_total, 2)
    uniform_total = round(total_candidates * UNIFORM_PER_CANDIDATE, 2)
    total_candidates = int(total_candidates or 0)
    passed = max(0, min(int(passed or 0), total_candidates))
    placed = max(0, min(int(placed or 0), total_candidates))
    failed = max(0, total_candidates - passed)

    # Compute explicit milestone amounts
    first_amount = round(role_total * MILESTONE_SHARES["1st"] + uniform_total, 2)
    second_gross = round(role_total * MILESTONE_SHARES["2nd"] * (passed / total_candidates), 2) if total_candidates else 0.0
    second_recovery = round(role_total * MILESTONE_SHARES["1st"] * (failed / total_candidates), 2) if total_candidates else 0.0
    second_net = round(second_gross - second_recovery, 2)
    third_amount = round(role_total * MILESTONE_SHARES["3rd"] * (placed / total_candidates), 2) if total_candidates else 0.0

    return {
        "rows": rows_out,
        "role_total": role_total,
        "uniform_total": uniform_total,
        "total_candidates": total_candidates,
        "passed_candidates": passed,
        "failed_candidates": failed,
        "placed_candidates": placed,
        "shares": MILESTONE_SHARES,
        "rates": JOB_CATEGORY_RATES,
        "uniform_per_candidate": UNIFORM_PER_CANDIDATE,
        "by_milestone": {
            "1st": {
                "share_of_role": MILESTONE_SHARES["1st"],
                "role_portion": round(role_total * MILESTONE_SHARES["1st"], 2),
                "uniform": uniform_total,
                "amount": first_amount,
                "based_on": total_candidates,
                "based_on_label": "total candidates",
            },
            "2nd": {
                "share_of_role": MILESTONE_SHARES["2nd"],
                "gross": second_gross,
                "recovery": second_recovery,
                "amount": second_net,
                "based_on": passed,
                "based_on_label": f"{passed}/{total_candidates} passed",
                "failed_count": failed,
            },
            "3rd": {
                "share_of_role": MILESTONE_SHARES["3rd"],
                "amount": third_amount,
                "based_on": placed,
                "based_on_label": f"{placed}/{total_candidates} placed",
            },
        },
    }


# Backward-compat alias for the older endpoint name
def _compute_1st_milestone(job_roles: list) -> dict:
    """Legacy: returns the 1st-milestone-only breakdown (role + uniform). Retained for back-compat."""
    bd = _compute_batch_milestones(job_roles, passed=0, placed=0)
    first = bd["by_milestone"]["1st"]
    return {
        "rows": bd["rows"],
        "role_total": bd["role_total"],
        "uniform_total": bd["uniform_total"],
        "total": first["amount"],
        "total_candidates": bd["total_candidates"],
    }


MilestoneType = Literal["1st", "2nd", "3rd", "other"]


class BatchPaymentIn(BaseModel):
    model_config = ConfigDict(extra="ignore")
    batch_id: str
    milestone: MilestoneType
    amount: float = Field(gt=0)
    expected_date: Optional[str] = ""
    description: Optional[str] = ""
    # Company under which this milestone's company-share income will be recorded.
    # Optional; if None, the income txn is created without a company tag.
    company_id: Optional[str] = None
    # Uniform amount portion (only relevant on 1st milestone). Excluded from TDS.
    uniform_amount: float = Field(default=0, ge=0)
    # Recovery (only relevant on 2nd milestone): the portion of already-disbursed 1st milestone
    # being claw-backed for candidates who failed the exam. Reduces credited income.
    recovery_amount: float = Field(default=0, ge=0)
    # Assessment fee per passed candidate (only relevant on 2nd milestone, variable per batch
    # so admin enters manually). Total assessment expense = this × passed_candidates.
    assessment_fee_per_candidate: float = Field(default=0, ge=0)
    assessment_fee_total: float = Field(default=0, ge=0)


class BatchPaymentOut(BatchPaymentIn):
    id: str
    status: Literal["pending", "received"] = "pending"
    received_date: Optional[str] = None
    received_by: Optional[str] = None
    txn_id: Optional[str] = None
    txn_ids: List[str] = Field(default_factory=list)
    tds_percent: float = 0
    tds_amount: float = 0
    tds_txn_id: Optional[str] = None
    recovery_txn_id: Optional[str] = None
    assessment_fee_txn_id: Optional[str] = None
    net_amount: Optional[float] = None  # gross − tds − recovery − assessment_fee
    created_at: str


class ReceivePaymentIn(BaseModel):
    """Body for marking a milestone payment as received."""
    model_config = ConfigDict(extra="ignore")
    tds_percent: Literal[0, 2, 10] = 0
    # Optional company override at receive-time. If provided, the company-share income
    # txn is tagged with this company. Falls back to BatchPayment.company_id when omitted.
    company_id: Optional[str] = None


@api.get("/batches", response_model=List[BatchOut])
async def list_batches(project_id: Optional[str] = None, center_id: Optional[str] = None,
                       user=Depends(require_role("admin", "manager", "senior_manager", "hr", "accountant", "partner", "center_manager", "center_staff"))):
    q: dict = {}
    if project_id:
        q["project_id"] = project_id
    if center_id:
        q["center_id"] = center_id
    role = user.get("role")
    if role in ("center_manager", "center_staff"):
        scoped_ids = user.get("assigned_center_ids") or []
        if center_id:
            if center_id not in scoped_ids:
                return []
            # Specific center requested — keep the exact filter set above.
        else:
            q["center_id"] = {"$in": scoped_ids}
    elif role == "partner":
        # Partner sees only batches at centers where they are mapped.
        await _enrich_user_with_associations(user)
        scoped_ids = user.get("_associated_center_ids") or []
        if not scoped_ids:
            return []
        if center_id:
            if center_id not in scoped_ids:
                return []
        else:
            q["center_id"] = {"$in": scoped_ids}
    docs = await db.batches.find(q, {"_id": 0}).sort("created_at", -1).to_list(2000)
    # Phase 81 — attach linked Work Order number for display (batch-load, no N+1).
    wo_ids = list({d.get("work_order_id") for d in docs if d.get("work_order_id")})
    wo_map = {}
    if wo_ids:
        async for w in db.work_orders.find({"id": {"$in": wo_ids}}, {"_id": 0, "id": 1, "wo_number": 1}):
            wo_map[w["id"]] = w.get("wo_number")
    # Live enrolled count per batch (from actual active candidate records — never
    # a stored/display-only value). Single aggregation, no N+1.
    batch_ids = [d["id"] for d in docs]
    enrolled_map: dict = {}
    if batch_ids:
        async for g in db.candidates.aggregate([
            {"$match": {"batch_id": {"$in": batch_ids}, "is_deleted": {"$ne": True}}},
            {"$group": {"_id": "$batch_id", "n": {"$sum": 1}}},
        ]):
            enrolled_map[g["_id"]] = g["n"]
    for d in docs:
        if d.get("work_order_id"):
            d["work_order_no"] = wo_map.get(d["work_order_id"])
        d["enrolled"] = enrolled_map.get(d["id"], 0)
    return [BatchOut(**d) for d in docs]


@api.post("/batches", response_model=BatchOut)
async def create_batch(body: BatchIn, user=Depends(require_role("admin", "manager", "senior_manager", "center_manager"))):
    # Validate referenced project / center actually exist
    if not await db.projects.find_one({"id": body.project_id}, {"_id": 0, "id": 1}):
        raise HTTPException(400, "project_id does not exist")
    if body.center_id and not await db.centers.find_one({"id": body.center_id}, {"_id": 0, "id": 1}):
        raise HTTPException(400, "center_id does not exist")
    # Center manager can only create batches at their assigned centers.
    if user.get("role") == "center_manager":
        assigned = set(user.get("assigned_center_ids") or [])
        if not body.center_id:
            raise HTTPException(400, "center_id is required for center_manager")
        if body.center_id not in assigned:
            raise HTTPException(403, "center_manager can only create batches at assigned centers")
    # Validate all partner_ids
    if body.partner_ids:
        cnt = await db.partners.count_documents({"id": {"$in": body.partner_ids}})
        if cnt != len(set(body.partner_ids)):
            raise HTTPException(400, "one or more partner_ids do not exist")
    # Phase 81: validate optional Work Order linkage (must exist).
    if body.work_order_id and not await db.work_orders.find_one({"id": body.work_order_id}, {"_id": 0, "id": 1}):
        raise HTTPException(400, "work_order_id does not exist")
    # Phase 37/84: target-gated creation. If target_id is provided we validate
    # coherence and enforce the target limit against the LIVE allocated capacity
    # (derived from actual batches — never a drift-prone counter).
    if body.target_id:
        tgt = await db.batch_targets.find_one({"id": body.target_id}, {"_id": 0})
        if not tgt:
            raise HTTPException(400, "target_id does not exist")
        # Enforce project/center coherence with the target for data integrity.
        if tgt.get("project_id") and tgt["project_id"] != body.project_id:
            raise HTTPException(400, "Batch project_id must match the target's project_id")
        if tgt.get("center_id") and body.center_id and tgt["center_id"] != body.center_id:
            raise HTTPException(400, "Batch center_id must match the target's center_id")
        cap = int(body.total_beneficiaries or 0)
        if cap <= 0:
            raise HTTPException(400, "Batch capacity must be > 0 to consume from target")
        live_alloc = await _target_allocated_single(tgt)
        remaining = int(tgt.get("total_target") or 0) - live_alloc
        if cap > remaining:
            raise HTTPException(400, f"Insufficient target remaining ({remaining}) for batch capacity {cap}")
    doc = body.model_dump()
    # Phase 38: authoritative rate calculation. Frontend-supplied rates ignored.
    # Rate calc runs only when the caller provided both FY + Category.
    if doc.get("fy_year") and doc.get("category"):
        is_lwe = doc.get("is_lwe")
        if is_lwe is None and doc.get("center_id"):
            c = await db.centers.find_one({"id": doc["center_id"]}, {"_id": 0, "is_lwe": 1})
            is_lwe = bool(c.get("is_lwe")) if c else False
        rc = await _compute_wo_rate(doc["fy_year"], doc["category"], bool(is_lwe))
        doc["is_lwe"] = rc["is_lwe"]
        doc["base_rate"] = rc["base_rate"]
        doc["final_rate"] = rc["final_rate"]
        doc["work_order_value"] = round(
            int(doc.get("num_candidates") or 0) * rc["final_rate"] * float(doc.get("job_role_hours") or 0),
            2,
        )
    doc["id"] = str(uuid.uuid4())
    doc["created_at"] = datetime.now(timezone.utc).isoformat()
    await db.batches.insert_one(doc)
    # Re-sync every target this batch contributes to (explicit + key-matched).
    await _recompute_targets_for_batch(doc)
    return BatchOut(**doc)


@api.put("/batches/{bid}", response_model=BatchOut)
async def update_batch(bid: str, body: BatchIn, user=Depends(require_role("admin", "manager", "senior_manager", "accountant", "hr", "center_manager"))):
    # Re-validate same FKs as create (project/center/partners)
    if not await db.projects.find_one({"id": body.project_id}, {"_id": 0, "id": 1}):
        raise HTTPException(400, "project_id does not exist")
    if body.center_id and not await db.centers.find_one({"id": body.center_id}, {"_id": 0, "id": 1}):
        raise HTTPException(400, "center_id does not exist")
    if body.partner_ids:
        cnt = await db.partners.count_documents({"id": {"$in": body.partner_ids}})
        if cnt != len(set(body.partner_ids)):
            raise HTTPException(400, "one or more partner_ids do not exist")
    if body.work_order_id and not await db.work_orders.find_one({"id": body.work_order_id}, {"_id": 0, "id": 1}):
        raise HTTPException(400, "work_order_id does not exist")
    # Lifecycle-based lock enforcement (admin bypasses locks).
    existing = await db.batches.find_one({"id": bid}, {"_id": 0})
    if not existing:
        raise HTTPException(404, "Not found")
    role = user.get("role")
    if role == "center_manager":
        assigned = set(user.get("assigned_center_ids") or [])
        if existing.get("center_id") not in assigned:
            raise HTTPException(403, "Center manager can only edit batches at own centers")
    if role != "admin":
        cur_locks = _lifecycle_locks(existing.get("lifecycle_status") or "Draft")
        BASIC_FIELDS = {"project_id", "center_id", "company_id", "partner_ids", "name",
                        "start_date", "end_date", "total_beneficiaries", "total_target",
                        "state", "territory", "target_year", "training_type", "job_roles",
                        "sdms_batch_id"}
        ATTENDANCE_FIELDS = {"attendance_pct", "total_dropout"}
        ASSESSMENT_FIELDS = {"assessment_date", "assessment_agency", "assessor_name",
                             "assessor_contact", "total_certified", "assessment_status",
                             "actual_present", "pass_count", "fail_count", "absent_count",
                             "billing_status", "passed_candidates"}
        PLACEMENT_FIELDS = {"num_placement", "offer_letter_status", "placement_month_1",
                            "placement_month_2", "placement_month_3", "placed_candidates"}
        new_data = body.model_dump()
        def _changed(fset):
            return [f for f in fset
                    if str(new_data.get(f, "") or "") != str(existing.get(f, "") or "")
                    and new_data.get(f) != existing.get(f)]
        if cur_locks["basic_locked"] and _changed(BASIC_FIELDS):
            raise HTTPException(400, f"Basic info is locked (lifecycle: {existing.get('lifecycle_status')}). Ask admin to unlock.")
        if cur_locks["attendance_locked"] and _changed(ATTENDANCE_FIELDS):
            raise HTTPException(400, "Attendance is locked at this lifecycle stage.")
        if cur_locks["assessment_locked"] and _changed(ASSESSMENT_FIELDS):
            raise HTTPException(400, "Assessment fields are locked at this lifecycle stage.")
        if cur_locks["placement_locked"] and _changed(PLACEMENT_FIELDS):
            raise HTTPException(400, "Placement fields are locked (batch is Closed). Ask admin to reopen.")

    upd = body.model_dump()
    # Phase 38: recompute WO rate/value authoritatively on every PUT if FY+Category present.
    if upd.get("fy_year") and upd.get("category"):
        is_lwe = upd.get("is_lwe")
        if is_lwe is None and upd.get("center_id"):
            c = await db.centers.find_one({"id": upd["center_id"]}, {"_id": 0, "is_lwe": 1})
            is_lwe = bool(c.get("is_lwe")) if c else False
        rc = await _compute_wo_rate(upd["fy_year"], upd["category"], bool(is_lwe))
        upd["is_lwe"] = rc["is_lwe"]
        upd["base_rate"] = rc["base_rate"]
        upd["final_rate"] = rc["final_rate"]
        upd["work_order_value"] = round(
            int(upd.get("num_candidates") or 0) * rc["final_rate"] * float(upd.get("job_role_hours") or 0),
            2,
        )
    # Keep locks in sync with lifecycle_status if it changed via PUT.
    upd.update(_lifecycle_locks(upd.get("lifecycle_status") or "Draft"))
    # Phase 84: enforce target limit against LIVE allocation when a target is
    # linked (or being changed). Exclude THIS batch's own current contribution so
    # editing capacity doesn't double-count against itself.
    new_tid = body.target_id
    if new_tid:
        tgt = await db.batch_targets.find_one({"id": new_tid}, {"_id": 0})
        if not tgt:
            raise HTTPException(400, "target_id does not exist")
        if tgt.get("project_id") and tgt["project_id"] != body.project_id:
            raise HTTPException(400, "Batch project_id must match the target's project_id")
        if tgt.get("center_id") and body.center_id and tgt["center_id"] != body.center_id:
            raise HTTPException(400, "Batch center_id must match the target's center_id")
        cap = int(body.total_beneficiaries or 0)
        live_alloc = await _target_allocated_single(tgt, exclude_batch_id=bid)
        remaining = int(tgt.get("total_target") or 0) - live_alloc
        if cap > remaining:
            raise HTTPException(400, f"Insufficient target remaining ({remaining}) for batch capacity {cap}")
    res = await db.batches.find_one_and_update({"id": bid}, {"$set": upd}, return_document=True)
    if not res:
        raise HTTPException(404, "Not found")
    res.pop("_id", None)
    # Re-sync counters for both the OLD and NEW target linkage (capacity, target
    # or FY/centre may have changed).
    await _recompute_targets_for_batch(existing)
    await _recompute_targets_for_batch(res)
    return BatchOut(**res)


@api.delete("/batches/{bid}")
async def delete_batch(bid: str, _=Depends(require_role("admin"))):
    # Cascade delete: auto-generated transactions (milestone income + recovery + assessment
    # fee + TDS) AND batch_payments — otherwise Milestone Income dashboard keeps
    # showing orphaned totals from deleted batches.
    existing = await db.batches.find_one({"id": bid}, {"_id": 0})
    txn_del = await db.transactions.delete_many({"batch_id": bid})
    await db.batch_payments.delete_many({"batch_id": bid})
    r = await db.batches.delete_one({"id": bid})
    if r.deleted_count == 0:
        raise HTTPException(404, "Not found")
    # Phase 84: release seats by recomputing every affected target from live records.
    if existing:
        await _recompute_targets_for_batch(existing)
    return {"ok": True, "transactions_deleted": txn_del.deleted_count}


@api.post("/batches/cleanup-orphan-txns")
async def cleanup_orphan_milestone_txns(
    _=Depends(require_role("admin")),
    dry_run: bool = True,
    confirm: bool = False,
    max_delete: int = 100,
):
    """Backfill batch_id/batch_payment_id on legacy milestone txns, then delete
    milestone-family transactions that no longer correspond to any live batch.

    ⚠️  PHASE 34 — HARDENED: this endpoint now REFUSES to delete anything unless
    the caller passes BOTH `dry_run=false` AND `confirm=true`. It also refuses
    to proceed when the number of would-be-deleted rows exceeds `max_delete`
    (default 100) — pass a higher value only when you have manually reviewed
    the dry-run output. These guards protect valid manual milestone txns from
    being wiped in one shot.

    Rationale: before Aug 2026, `receive_batch_payment` did NOT store `batch_id`
    or `batch_payment_id` on the auto-generated income/recovery/assessment/TDS
    transactions. So when a batch was deleted, those txns were orphaned and kept
    inflating the Milestone Income dashboard. This admin one-shot cleans them up.

    Two phases:
      1. **Backfill** — for each milestone-family txn that has neither batch_id
         nor batch_payment_id, find a live `batch_payments` row matching
         (center_id, project_id, milestone, amount, status="received"). If found,
         tag the txn with the batch/payment IDs so future cascade delete works.
      2. **Prune** — delete milestone-family txns whose batch_id/batch_payment_id
         no longer point to a live batch/payment (either previously-tagged rows
         pointing to deleted batches, or legacy rows with no correlate).

    `dry_run=true` (default) reports the counts without modifying data.

    Returns: `{ scanned, backfilled, orphans, deleted, duplicates_deleted, dry_run, refused_reason? }`.
    """
    MILESTONE_SOURCES = ["milestone", "candidate_recovery", "assessment_fee", "tds_deduction"]
    # Preload live sets for O(1) checks
    live_batch_ids = set()
    async for b in db.batches.find({}, {"_id": 0, "id": 1}):
        live_batch_ids.add(b["id"])
    live_bp_ids = set()
    async for p in db.batch_payments.find({}, {"_id": 0, "id": 1}):
        live_bp_ids.add(p["id"])

    scanned = 0
    backfilled = 0
    orphan_ids: list[str] = []

    async for txn in db.transactions.find(
        {"source": {"$in": MILESTONE_SOURCES}},
        {"_id": 0, "id": 1, "batch_id": 1, "batch_payment_id": 1,
         "center_id": 1, "project_id": 1, "milestone": 1, "amount": 1},
    ):
        scanned += 1
        bid = txn.get("batch_id")
        bpid = txn.get("batch_payment_id")

        # Case A: already linked → check live
        if bid or bpid:
            batch_live = bid in live_batch_ids if bid else True
            bp_live = bpid in live_bp_ids if bpid else True
            if not batch_live or not bp_live:
                orphan_ids.append(txn["id"])
            continue

        # Case B: legacy txn — try to backfill via STRICT structural match on
        # (center_id, project_id, milestone, amount) with status='received'. The
        # earlier permissive query (milestone+amount only) could backfill onto an
        # unrelated batch and inflate live totals; that path is removed.
        match = None
        if txn.get("center_id") and txn.get("project_id") and txn.get("milestone"):
            candidate_batches = await db.batches.find(
                {"center_id": txn["center_id"], "project_id": txn["project_id"]},
                {"_id": 0, "id": 1},
            ).to_list(50)
            candidate_batch_ids = [b["id"] for b in candidate_batches]
            if candidate_batch_ids:
                match = await db.batch_payments.find_one(
                    {
                        "batch_id": {"$in": candidate_batch_ids},
                        "milestone": txn["milestone"],
                        "amount": txn["amount"],
                        "status": "received",
                    },
                    {"_id": 0, "id": 1, "batch_id": 1},
                )
        if match:
            if not dry_run:
                await db.transactions.update_one(
                    {"id": txn["id"]},
                    {"$set": {"batch_id": match["batch_id"], "batch_payment_id": match["id"]}},
                )
            backfilled += 1
        else:
            orphan_ids.append(txn["id"])

    deleted = 0
    refused_reason = None
    # PHASE 34 SAFETY GUARDS:
    #  • dry_run must be explicitly false
    #  • confirm must be explicitly true
    #  • orphan count must be ≤ max_delete (default 100) — protects against
    #    accidental mass-wipe of valid manual milestone txns.
    will_delete = bool(orphan_ids) and (not dry_run) and confirm
    if orphan_ids and not dry_run and not confirm:
        refused_reason = "confirm=true not passed — call with dry_run=false&confirm=true to actually delete"
        will_delete = False
    if will_delete and len(orphan_ids) > max_delete:
        refused_reason = f"orphans ({len(orphan_ids)}) exceed max_delete ({max_delete}) — review dry-run and re-run with a higher max_delete if intended"
        will_delete = False
    if will_delete:
        r = await db.transactions.delete_many({"id": {"$in": orphan_ids}})
        deleted = r.deleted_count

    # ---- Phase 3: De-duplicate ----
    # If a single batch_payment produced multiple identical txns (e.g. from rapid
    # double-click before the idempotency lock was in place), keep the earliest
    # and remove the rest. Group by (batch_payment_id, source, partner_id, milestone)
    # — the same tuple that our new unique index enforces going forward.
    dup_deleted = 0
    if not dry_run and confirm:
        pipeline = [
            {"$match": {
                "source": {"$in": MILESTONE_SOURCES + ["fooding"]},
                "batch_payment_id": {"$type": "string"},
            }},
            {"$group": {
                "_id": {"bp": "$batch_payment_id", "src": "$source",
                        "pid": "$partner_id", "ms": "$milestone"},
                "ids": {"$push": {"id": "$id", "created_at": "$created_at"}},
                "count": {"$sum": 1},
            }},
            {"$match": {"count": {"$gt": 1}}},
        ]
        async for group in db.transactions.aggregate(pipeline):
            # Sort by created_at ascending; keep index 0, delete the rest.
            rows = sorted(group["ids"], key=lambda r: r.get("created_at") or "")
            to_delete = [r["id"] for r in rows[1:]]
            if to_delete:
                r = await db.transactions.delete_many({"id": {"$in": to_delete}})
                dup_deleted += r.deleted_count

    return {
        "scanned": scanned,
        "backfilled": backfilled,
        "orphans": len(orphan_ids),
        "deleted": deleted,
        "duplicates_deleted": dup_deleted,
        "dry_run": dry_run,
        "refused_reason": refused_reason,
    }


@api.post("/batches/regenerate-missing-milestone-txns")
async def regenerate_missing_milestone_txns(user=Depends(require_role("admin")), dry_run: bool = False):
    """Reconstruct auto-generated milestone income/recovery/assessment/TDS
    transactions for any `batch_payments` row that is currently status='received'
    but has no matching entries in `transactions` (source in the milestone family).

    Why this exists: an earlier cleanup pass wrongly attributed some legacy
    milestone txns to unrelated batches (permissive backfill), which then made
    the de-duplicate step delete otherwise-valid income rows for their original
    batches. This endpoint rebuilds those missing rows using the persisted data
    on the batch_payment row (amount, milestone, tds_percent, recovery_amount,
    assessment_fee_total, company_id) plus the parent batch's partner_ids and
    partner_share_percent — same math as `receive_batch_payment`.

    Skips any batch_payment that already has at least one milestone-source txn
    (idempotent — safe to re-run).

    `dry_run=true` reports what WOULD be regenerated without writing.

    Returns: `{ scanned, regenerated_payments, transactions_created, skipped, dry_run }`.
    """
    scanned = 0
    regenerated = 0
    txns_created = 0
    skipped = 0
    now = datetime.now(timezone.utc).isoformat()

    async for bp in db.batch_payments.find({"status": "received"}, {"_id": 0}):
        scanned += 1
        pid = bp["id"]
        # Skip if this bp already has ANY milestone-family txn.
        existing = await db.transactions.count_documents({
            "batch_payment_id": pid,
            "source": {"$in": ["milestone", "candidate_recovery", "assessment_fee", "tds_deduction"]},
        })
        if existing > 0:
            skipped += 1
            continue

        batch = await db.batches.find_one({"id": bp["batch_id"]}, {"_id": 0})
        if not batch:
            # Parent batch is gone — cannot reconstruct; leave as-is for the
            # cleanup endpoint to prune. Not counted as regenerated.
            continue

        proj = await db.projects.find_one({"id": batch.get("project_id")}, {"_id": 0, "name": 1})
        project_name = (proj or {}).get("name", "")
        today = (bp.get("received_date") or now)[:10]
        partner_ids = list(batch.get("partner_ids") or [])
        partner_share_pct = float(batch.get("partner_share_percent") or 0)
        gross = float(bp["amount"])
        description_base = f"{project_name} — {batch.get('name','')} — {bp['milestone']} milestone"
        company_id_resolved = bp.get("company_id") or batch.get("company_id")
        recovery_amount = float(bp.get("recovery_amount") or 0)
        assessment_fee_total = float(bp.get("assessment_fee_total") or 0)
        assessment_fee_per = float(bp.get("assessment_fee_per_candidate") or 0)
        tds_percent = float(bp.get("tds_percent") or 0)
        uniform_amount = float(bp.get("uniform_amount") or 0)
        batch_partner_id = partner_ids[0] if len(partner_ids) == 1 else None
        received_by = bp.get("received_by") or user["id"]

        partner_pool = round(gross * partner_share_pct / 100.0, 2) if partner_ids and partner_share_pct > 0 else 0.0
        company_amount = round(gross - partner_pool, 2)
        splits: list[tuple[Optional[str], float, str]] = []
        if company_amount > 0:
            sfx = f" (company {round(100.0 - partner_share_pct, 2)}% share)" if partner_pool > 0 else ""
            splits.append((None, company_amount, sfx))
        if partner_pool > 0:
            per_partner = round(partner_pool / len(partner_ids), 2)
            last = round(partner_pool - per_partner * (len(partner_ids) - 1), 2)
            for idx, pid_split in enumerate(partner_ids):
                amt = last if idx == len(partner_ids) - 1 else per_partner
                sfx = f" (partner share {partner_share_pct}% ÷ {len(partner_ids)} = {round(partner_share_pct / len(partner_ids), 2)}%)"
                splits.append((pid_split, amt, sfx))

        this_created: list[dict] = []
        for pid_split, amt, sfx in splits:
            if amt <= 0:
                continue
            this_created.append({
                "id": str(uuid.uuid4()), "type": "income", "amount": amt,
                "date": today, "description": description_base + sfx,
                "company_id": company_id_resolved if pid_split is None else None,
                "partner_id": pid_split,
                "center_id": batch.get("center_id"), "project_id": batch.get("project_id"),
                "items": [], "attachments": [],
                "source": "milestone", "milestone": bp["milestone"],
                "batch_id": bp["batch_id"], "batch_payment_id": pid,
                "created_by": received_by, "created_at": now,
                "status": "approved", "approved_by": received_by, "approved_at": now,
                "rejected_reason": None,
                "_regenerated": True,
            })

        if recovery_amount > 0:
            this_created.append({
                "id": str(uuid.uuid4()), "type": "expense", "amount": recovery_amount,
                "date": today,
                "description": f"Candidate-failure recovery (claw-back of 1st-milestone) on {description_base}",
                "company_id": company_id_resolved, "partner_id": batch_partner_id,
                "center_id": batch.get("center_id"), "project_id": batch.get("project_id"),
                "items": [], "attachments": [],
                "source": "candidate_recovery", "milestone": bp["milestone"],
                "batch_id": bp["batch_id"], "batch_payment_id": pid,
                "created_by": received_by, "created_at": now,
                "status": "approved", "approved_by": received_by, "approved_at": now,
                "rejected_reason": None, "_regenerated": True,
            })

        if assessment_fee_total > 0:
            passed_n = int(batch.get("passed_candidates") or 0)
            this_created.append({
                "id": str(uuid.uuid4()), "type": "expense", "amount": assessment_fee_total,
                "date": today,
                "description": (
                    f"Assessment fee on {description_base} (₹{assessment_fee_per:,.2f} × {passed_n} passed)"
                    if assessment_fee_per > 0 else f"Assessment fee on {description_base}"
                ),
                "company_id": company_id_resolved, "partner_id": batch_partner_id,
                "center_id": batch.get("center_id"), "project_id": batch.get("project_id"),
                "items": [], "attachments": [],
                "source": "assessment_fee", "milestone": bp["milestone"],
                "batch_id": bp["batch_id"], "batch_payment_id": pid,
                "created_by": received_by, "created_at": now,
                "status": "approved", "approved_by": received_by, "approved_at": now,
                "rejected_reason": None, "_regenerated": True,
            })

        if tds_percent > 0:
            taxable = max(0.0, gross - uniform_amount - recovery_amount)
            tds_amount = round(taxable * tds_percent / 100.0, 2)
            if tds_amount > 0:
                this_created.append({
                    "id": str(uuid.uuid4()), "type": "expense", "amount": tds_amount,
                    "date": today,
                    "description": f"TDS {tds_percent}% deducted by department on {description_base} (taxable ₹{taxable:,.2f})",
                    "company_id": company_id_resolved, "partner_id": batch_partner_id,
                    "center_id": batch.get("center_id"), "project_id": batch.get("project_id"),
                    "items": [], "attachments": [],
                    "source": "tds_deduction", "milestone": bp["milestone"],
                    "batch_id": bp["batch_id"], "batch_payment_id": pid,
                    "created_by": received_by, "created_at": now,
                    "status": "approved", "approved_by": received_by, "approved_at": now,
                    "rejected_reason": None, "_regenerated": True,
                })

        if this_created:
            if not dry_run:
                await db.transactions.insert_many(this_created)
            regenerated += 1
            txns_created += len(this_created)

    return {
        "scanned": scanned,
        "regenerated_payments": regenerated,
        "transactions_created": txns_created,
        "skipped": skipped,
        "dry_run": dry_run,
    }


@api.get("/batch-payments", response_model=List[BatchPaymentOut])
async def list_batch_payments(batch_id: Optional[str] = None, user=Depends(require_finance_visible)):
    q: dict = {}
    if batch_id:
        q["batch_id"] = batch_id
    # Partner: restrict to batches at centers where they are mapped.
    if user.get("role") == "partner":
        await _enrich_user_with_associations(user)
        center_ids = user.get("_associated_center_ids") or []
        if not center_ids:
            return []
        scoped_batches = await db.batches.find(
            {"center_id": {"$in": center_ids}}, {"_id": 0, "id": 1},
        ).to_list(5000)
        allowed = [b["id"] for b in scoped_batches]
        if batch_id:
            # A specific batch was requested — keep the exact filter (already
            # set above); only enforce authorization.
            if batch_id not in allowed:
                return []
        else:
            # No specific batch requested — scope to ALL allowed batches.
            q["batch_id"] = {"$in": allowed}
    docs = await db.batch_payments.find(q, {"_id": 0}).sort([("batch_id", 1), ("milestone", 1)]).to_list(5000)
    return [BatchPaymentOut(**d) for d in docs]


@api.get("/batches/{bid}/compute-1st-milestone")
async def compute_first_milestone(bid: str, _=Depends(get_current_user)):
    """Returns the auto-computed 1st milestone breakdown for the batch's job_roles.
    (Legacy endpoint — for full 3-milestone breakdown use /compute-milestones.)"""
    batch = await db.batches.find_one({"id": bid}, {"_id": 0})
    if not batch:
        raise HTTPException(404, "Batch not found")
    breakdown = _compute_1st_milestone(batch.get("job_roles") or [])
    breakdown["rates"] = JOB_CATEGORY_RATES
    breakdown["uniform_per_candidate"] = UNIFORM_PER_CANDIDATE
    return breakdown


@api.get("/batches/{bid}/compute-milestones")
async def compute_milestones(bid: str, _=Depends(get_current_user)):
    """Full 3-milestone breakdown including 2nd-milestone recovery for failed candidates.

    Formula (per spec):
      1st = 30% × role_total + uniform_total
      2nd = (40% × role_total × passed/total) − (30% × role_total × failed/total)  ← recovery
      3rd = 30% × role_total × placed/total
    """
    batch = await db.batches.find_one({"id": bid}, {"_id": 0})
    if not batch:
        raise HTTPException(404, "Batch not found")
    return _compute_batch_milestones(
        batch.get("job_roles") or [],
        passed=int(batch.get("passed_candidates") or 0),
        placed=int(batch.get("placed_candidates") or 0),
    )


@api.post("/batch-payments", response_model=BatchPaymentOut)
async def create_batch_payment(body: BatchPaymentIn, _=Depends(require_role("admin", "manager", "senior_manager", "accountant"))):
    # Enforce one-row-per (batch_id, milestone)
    existing = await db.batch_payments.find_one({"batch_id": body.batch_id, "milestone": body.milestone})
    if existing:
        raise HTTPException(400, f"{body.milestone} milestone already exists for this batch")
    doc = body.model_dump()
    doc["id"] = str(uuid.uuid4())
    doc["status"] = "pending"
    doc["received_date"] = None
    doc["received_by"] = None
    doc["txn_id"] = None
    doc["created_at"] = datetime.now(timezone.utc).isoformat()
    await db.batch_payments.insert_one(doc)
    return BatchPaymentOut(**doc)


@api.put("/batch-payments/{pid}", response_model=BatchPaymentOut)
async def update_batch_payment(pid: str, body: BatchPaymentIn, _=Depends(require_role("admin", "manager", "senior_manager", "accountant"))):
    res = await db.batch_payments.find_one_and_update(
        {"id": pid},
        {"$set": {"amount": body.amount, "expected_date": body.expected_date, "description": body.description}},
        return_document=True,
    )
    if not res:
        raise HTTPException(404, "Not found")
    res.pop("_id", None)
    return BatchPaymentOut(**res)


@api.patch("/batch-payments/{pid}/receive", response_model=BatchPaymentOut)
async def receive_batch_payment(pid: str, body: ReceivePaymentIn = ReceivePaymentIn(),
                                 user=Depends(require_role("admin", "accountant", "senior_manager"))):
    """Mark a milestone payment as received and auto-create approved transactions.

    Behaviour:
    - Income transaction(s) created at the GROSS milestone amount (per partner split if applicable).
    - If recovery_amount > 0 (only relevant on 2nd milestone): an additional EXPENSE transaction
      (source='candidate_recovery') is created — represents the claw-back of 1st-milestone money
      already paid for candidates who failed the exam. Reduces net P&L.
    - If tds_percent > 0: an additional EXPENSE transaction (source='tds_deduction') is created.
      Taxable base = (gross − uniform_amount − recovery_amount). Uniform (1st milestone only) and
      recovery (2nd milestone) are both excluded from the taxable base by spec.
    - If assessment_fee_total > 0 (2nd milestone only): a separate EXPENSE transaction
      (source='assessment_fee') is recorded for the per-passed-candidate assessment fee.
    - net_amount on the payment row = gross − tds_amount − recovery_amount − assessment_fee_total.
    """
    # STEP 1 — Atomic idempotency lock: set status to an INTERMEDIATE '_receiving'
    # state (flipping FROM pending). If the update matches 0 documents, someone
    # else is already receiving or the payment has already been received — bail.
    # This closes the duplicate-receive race that was inflating Milestone Income
    # totals when the same milestone was mark-received twice.
    #
    # PHASE 34 — we now only flip to the FINAL 'received' state at the END, once
    # all transactions have been persisted successfully. If any insert fails, we
    # roll back: delete already-inserted txns AND reset the payment status back
    # to 'pending' so the user can retry cleanly.
    lock = await db.batch_payments.find_one_and_update(
        {"id": pid, "status": "pending"},
        {"$set": {
            "status": "_receiving",
            "_receive_lock_by": user["id"],
            "_receive_lock_at": datetime.now(timezone.utc).isoformat(),
        }},
    )
    if not lock:
        existing = await db.batch_payments.find_one({"id": pid}, {"_id": 0})
        if not existing:
            raise HTTPException(404, "Not found")
        if existing.get("status") == "_receiving":
            raise HTTPException(409, "Another receive is in progress — try again in a moment")
        raise HTTPException(400, "Already received")
    rec = lock  # snapshot pre-update
    all_created_ids: list[str] = []  # tracks EVERY txn we insert so rollback is complete on failure

    async def _rollback(reason: str):
        """Undo the partial receive: delete any txns we managed to insert and revert
        the payment status back to 'pending' so the user can retry cleanly."""
        try:
            if all_created_ids:
                await db.transactions.delete_many({"id": {"$in": all_created_ids}})
            await db.batch_payments.update_one(
                {"id": pid},
                {"$set": {"status": "pending"},
                 "$unset": {"_receive_lock_by": "", "_receive_lock_at": ""}},
            )
        except Exception:
            logger.exception("receive_batch_payment rollback failed for pid=%s (%s)", pid, reason)

    batch = await db.batches.find_one({"id": rec["batch_id"]}, {"_id": 0})
    project_name = ""
    if batch:
        proj = await db.projects.find_one({"id": batch.get("project_id")}, {"_id": 0, "name": 1})
        project_name = (proj or {}).get("name", "")
    now = datetime.now(timezone.utc).isoformat()
    today = now[:10]
    partner_ids = list((batch or {}).get("partner_ids") or [])
    partner_share_pct = float((batch or {}).get("partner_share_percent") or 0)
    gross = float(rec["amount"])
    description_base = f"{project_name} — {batch.get('name','') if batch else ''} — {rec['milestone']} milestone"
    created_txn_ids: list[str] = []

    # Income split: partners get partner_share_pct% of gross (split equally among them),
    # company keeps the rest. If no partners OR partner_share_pct == 0, the whole amount
    # is recorded as company income (partner_id=null).
    partner_pool = round(gross * partner_share_pct / 100.0, 2) if partner_ids and partner_share_pct > 0 else 0.0
    company_amount = round(gross - partner_pool, 2)
    # Resolve company tag for the company-share txn (priority: body override → BatchPayment → Batch)
    company_id_resolved = body.company_id or rec.get("company_id") or (batch or {}).get("company_id")
    splits: list[tuple[Optional[str], float, str]] = []  # (partner_id, amount, suffix)
    if company_amount > 0:
        suffix = f" (company {round(100.0 - partner_share_pct, 2)}% share)" if partner_pool > 0 else ""
        splits.append((None, company_amount, suffix))
    if partner_pool > 0:
        per_partner = round(partner_pool / len(partner_ids), 2)
        # Distribute rounding tail to last partner so the sum is exact
        last = round(partner_pool - per_partner * (len(partner_ids) - 1), 2)
        for idx, pid_split in enumerate(partner_ids):
            amt = last if idx == len(partner_ids) - 1 else per_partner
            sfx = f" (partner share {partner_share_pct}% ÷ {len(partner_ids)} = {round(partner_share_pct / len(partner_ids), 2)}%)"
            splits.append((pid_split, amt, sfx))

    for pid_split, amt, sfx in splits:
        if amt <= 0:
            continue
        txn = {
            "id": str(uuid.uuid4()),
            "type": "income",
            "amount": amt,
            "date": today,
            "description": description_base + sfx,
            # Only the company-share txn carries the company_id; partner txns leave it null
            "company_id": company_id_resolved if pid_split is None else None,
            "partner_id": pid_split,
            "center_id": (batch or {}).get("center_id"),
            "project_id": (batch or {}).get("project_id"),
            "items": [], "attachments": [],
            "source": "milestone",
            "milestone": rec["milestone"],
            # Cascade-delete linkage: cleanup uses these to remove orphaned income
            # transactions when the parent batch or batch_payment is deleted.
            "batch_id": rec["batch_id"],
            "batch_payment_id": pid,
            "created_by": user["id"], "created_at": now,
            "status": "approved", "approved_by": user["id"], "approved_at": now,
            "rejected_reason": None,
        }
        try:
            await db.transactions.insert_one(txn)
        except Exception as e:
            await _rollback(f"income insert failed: {e}")
            raise HTTPException(500, f"Failed to save income transactions — rolled back. {e}")
        created_txn_ids.append(txn["id"])
        all_created_ids.append(txn["id"])

    # Candidate-failure recovery (2nd milestone): separate expense to claw back 1st-milestone
    recovery_amount = float(rec.get("recovery_amount") or 0)
    recovery_txn_id = None
    # For non-income auto-txns tagged to this batch, tag with batch's company + first partner
    # (if only one) so they don't dangle in the ledger.
    batch_partner_id = partner_ids[0] if len(partner_ids) == 1 else None
    if recovery_amount > 0:
        rec_txn = {
            "id": str(uuid.uuid4()),
            "type": "expense",
            "amount": recovery_amount,
            "date": today,
            "description": f"Candidate-failure recovery (claw-back of 1st-milestone) on {description_base}",
            "company_id": company_id_resolved,
            "partner_id": batch_partner_id,
            "center_id": (batch or {}).get("center_id"),
            "project_id": (batch or {}).get("project_id"),
            "items": [], "attachments": [],
            "source": "candidate_recovery",
            "milestone": rec["milestone"],
            "batch_id": rec["batch_id"],
            "batch_payment_id": pid,
            "created_by": user["id"], "created_at": now,
            "status": "approved", "approved_by": user["id"], "approved_at": now,
            "rejected_reason": None,
        }
        try:
            await db.transactions.insert_one(rec_txn)
        except Exception as e:
            await _rollback(f"recovery insert failed: {e}")
            raise HTTPException(500, f"Failed to save recovery transaction — rolled back. {e}")
        recovery_txn_id = rec_txn["id"]
        all_created_ids.append(rec_txn["id"])

    # Assessment fee (2nd milestone): per-passed-candidate fee, manually entered
    assessment_fee_total = float(rec.get("assessment_fee_total") or 0)
    assessment_fee_per = float(rec.get("assessment_fee_per_candidate") or 0)
    assessment_fee_txn_id = None
    if assessment_fee_total > 0:
        passed_n = int((batch or {}).get("passed_candidates") or 0)
        af_txn = {
            "id": str(uuid.uuid4()),
            "type": "expense",
            "amount": assessment_fee_total,
            "date": today,
            "description": f"Assessment fee on {description_base} "
                           f"(₹{assessment_fee_per:,.2f} × {passed_n} passed)" if assessment_fee_per > 0
                           else f"Assessment fee on {description_base}",
            "company_id": company_id_resolved,
            "partner_id": batch_partner_id,
            "center_id": (batch or {}).get("center_id"),
            "project_id": (batch or {}).get("project_id"),
            "items": [], "attachments": [],
            "source": "assessment_fee",
            "milestone": rec["milestone"],
            "batch_id": rec["batch_id"],
            "batch_payment_id": pid,
            "created_by": user["id"], "created_at": now,
            "status": "approved", "approved_by": user["id"], "approved_at": now,
            "rejected_reason": None,
        }
        try:
            await db.transactions.insert_one(af_txn)
        except Exception as e:
            await _rollback(f"assessment_fee insert failed: {e}")
            raise HTTPException(500, f"Failed to save assessment fee transaction — rolled back. {e}")
        assessment_fee_txn_id = af_txn["id"]
        all_created_ids.append(af_txn["id"])

    # TDS deduction: calculated on (gross − uniform − recovery) per spec.
    # Uniform (1st milestone only) and recovery (2nd milestone) are both excluded from
    # the taxable base. Assessment fee is a separate post-TDS expense.
    tds_percent = float(body.tds_percent or 0)
    uniform_amount = float(rec.get("uniform_amount") or 0)
    tds_amount = 0.0
    tds_txn_id = None
    if tds_percent > 0:
        taxable = max(0.0, gross - uniform_amount - recovery_amount)
        tds_amount = round(taxable * tds_percent / 100.0, 2)
        if tds_amount > 0:
            tds_txn = {
                "id": str(uuid.uuid4()),
                "type": "expense",
                "amount": tds_amount,
                "date": today,
                "description": f"TDS {tds_percent}% deducted by department on {description_base} (taxable ₹{taxable:,.2f})",
                "company_id": company_id_resolved,
                "partner_id": batch_partner_id,
                "center_id": (batch or {}).get("center_id"),
                "project_id": (batch or {}).get("project_id"),
                "items": [], "attachments": [],
                "source": "tds_deduction",
                "milestone": rec["milestone"],
                "batch_id": rec["batch_id"],
                "batch_payment_id": pid,
                "created_by": user["id"], "created_at": now,
                "status": "approved", "approved_by": user["id"], "approved_at": now,
                "rejected_reason": None,
            }
            try:
                await db.transactions.insert_one(tds_txn)
            except Exception as e:
                await _rollback(f"tds insert failed: {e}")
                raise HTTPException(500, f"Failed to save TDS transaction — rolled back. {e}")
            tds_txn_id = tds_txn["id"]
            all_created_ids.append(tds_txn["id"])

    net_amount = round(gross - tds_amount - recovery_amount - assessment_fee_total, 2)
    # PHASE 34 — Final commit: NOW flip from '_receiving' → 'received' with all
    # aggregated metadata. If this step somehow fails, roll everything back so
    # the ledger stays consistent.
    try:
        res = await db.batch_payments.find_one_and_update(
            {"id": pid},
            {"$set": {
                "status": "received", "received_date": today, "received_by": user["id"],
                "txn_id": created_txn_ids[0] if created_txn_ids else None,
                "txn_ids": created_txn_ids,
                "tds_percent": tds_percent,
                "tds_amount": tds_amount,
                "tds_txn_id": tds_txn_id,
                "recovery_amount": recovery_amount,
                "recovery_txn_id": recovery_txn_id,
                "assessment_fee_total": assessment_fee_total,
                "assessment_fee_per_candidate": assessment_fee_per,
                "assessment_fee_txn_id": assessment_fee_txn_id,
                "company_id": company_id_resolved,
                "net_amount": net_amount,
            }, "$unset": {"_receive_lock_by": "", "_receive_lock_at": ""}},
            return_document=True,
        )
    except Exception as e:
        await _rollback(f"final status commit failed: {e}")
        raise HTTPException(500, f"Failed to finalize receive — rolled back. {e}")
    if not res:
        await _rollback("final commit returned no doc")
        raise HTTPException(500, "Failed to finalize receive — rolled back")
    res.pop("_id", None)
    # Phase 40 integration: auto-sync the linked invoice to Stage 5 (Disbursed).
    await _sync_invoice_on_receive(res, user)
    return BatchPaymentOut(**res)


@api.delete("/batch-payments/{pid}")
async def delete_batch_payment(pid: str, _=Depends(require_role("admin"))):
    # Cascade delete: auto-generated milestone-family transactions tied to this payment.
    txn_del = await db.transactions.delete_many({"batch_payment_id": pid})
    r = await db.batch_payments.delete_one({"id": pid})
    if r.deleted_count == 0:
        raise HTTPException(404, "Not found")
    return {"ok": True, "transactions_deleted": txn_del.deleted_count}


