# ============================================================================
# Leave Allocation (HR provisioning)
# ----------------------------------------------------------------------------
# HR/Admin defines leave types (CL/SL/PL/COMP_OFF) with annual quotas, then allocates
# day-balances to individual staff or in bulk by center. Used balance is auto-incremented
# when a leave request is final-approved (links via leaves.leave_type_id).
# ============================================================================


DEFAULT_LEAVE_TYPES = [
    {"code": "CL",   "name": "Casual Leave",  "annual_quota": 12, "paid": True,  "carry_forward": False, "color": "blue"},
    {"code": "SL",   "name": "Sick Leave",    "annual_quota": 10, "paid": True,  "carry_forward": False, "color": "amber"},
    {"code": "PL",   "name": "Privilege/Earned Leave", "annual_quota": 15, "paid": True, "carry_forward": True, "color": "emerald"},
    {"code": "COMP", "name": "Comp-off",      "annual_quota": 0,  "paid": True,  "carry_forward": True,  "color": "purple"},
    {"code": "LWP",  "name": "Leave Without Pay", "annual_quota": 0, "paid": False, "carry_forward": False, "color": "rose"},
]


async def _seed_default_leave_types() -> None:
    """Idempotent: ensure default leave-type rows exist (CL/SL/PL/COMP/LWP)."""
    for d in DEFAULT_LEAVE_TYPES:
        if await db.leave_types.find_one({"code": d["code"]}, {"_id": 0}):
            continue
        doc = {**d, "id": str(uuid.uuid4()), "active": True,
               "created_at": datetime.now(timezone.utc).isoformat()}
        try:
            await db.leave_types.insert_one(doc)
        except Exception:
            # benign race on dup-key during concurrent reloads — ignore
            pass


@api.get("/leave-types")
async def list_leave_types(_=Depends(get_current_user)):
    # Lazy-seed on first call so we don't have to forward-declare in startup hook
    if await db.leave_types.count_documents({}) == 0:
        await _seed_default_leave_types()
    docs = await db.leave_types.find({}, {"_id": 0}).sort("name", 1).to_list(200)
    return docs


@api.post("/leave-types")
async def create_leave_type(body: LeaveTypeIn, user=Depends(require_role("admin", "hr"))):
    doc = body.model_dump()
    doc["code"] = doc["code"].upper().strip()
    if await db.leave_types.find_one({"code": doc["code"]}, {"_id": 0}):
        raise HTTPException(400, f"Leave type with code '{doc['code']}' already exists")
    doc["id"] = str(uuid.uuid4())
    doc["created_at"] = datetime.now(timezone.utc).isoformat()
    doc["created_by"] = user["id"]
    await db.leave_types.insert_one(doc)
    doc.pop("_id", None)
    return doc


@api.put("/leave-types/{lt_id}")
async def update_leave_type(lt_id: str, body: LeaveTypeIn, _=Depends(require_role("admin", "hr"))):
    upd = body.model_dump()
    upd["code"] = upd["code"].upper().strip()
    # ensure code uniqueness against other docs
    dup = await db.leave_types.find_one({"code": upd["code"], "id": {"$ne": lt_id}}, {"_id": 0})
    if dup:
        raise HTTPException(400, f"Another leave type already uses code '{upd['code']}'")
    res = await db.leave_types.find_one_and_update({"id": lt_id}, {"$set": upd}, return_document=True)
    if not res:
        raise HTTPException(404, "Leave type not found")
    res.pop("_id", None)
    return res


@api.delete("/leave-types/{lt_id}")
async def delete_leave_type(lt_id: str, _=Depends(require_role("admin", "hr"))):
    # Soft-protect: refuse if any balance refers to this type
    if await db.leave_balances.find_one({"leave_type_id": lt_id}, {"_id": 0, "id": 1}):
        raise HTTPException(400, "This leave type is used in staff balances — deactivate instead of deleting")
    r = await db.leave_types.delete_one({"id": lt_id})
    if r.deleted_count == 0:
        raise HTTPException(404, "Leave type not found")
    return {"ok": True}


# -------- Leave Balances --------
@api.get("/leave-balances")
async def list_leave_balances(
    staff_id: Optional[str] = None,
    year: Optional[int] = None,
    center_id: Optional[str] = None,
    user=Depends(get_current_user),
):
    """List balances. HR/Admin see all; center_manager sees own centers; others see only own row."""
    role = user.get("role")
    q: dict = {}
    if year:
        q["year"] = year
    # Scope by role
    if role in ("admin", "hr"):
        if staff_id:
            q["staff_id"] = staff_id
        if center_id:
            staff_in_center = await db.staff.find({"center_id": center_id}, {"_id": 0, "id": 1}).to_list(5000)
            q["staff_id"] = {"$in": [s["id"] for s in staff_in_center]}
    elif role in ("senior_manager", "manager", "accountant", "center_manager"):
        # See balances of staff in centers they manage (and any specific staff filter)
        cids = user.get("assigned_center_ids") or []
        if role == "senior_manager" and not cids:
            # senior_manager without explicit center assignment → see all
            pass
        else:
            staff_in_centers = await db.staff.find({"center_id": {"$in": cids}}, {"_id": 0, "id": 1}).to_list(5000)
            q["staff_id"] = {"$in": [s["id"] for s in staff_in_centers]}
        if staff_id:
            q["staff_id"] = staff_id
    else:
        # All other roles: scope to own staff record
        own = await db.staff.find_one({"user_id": user["id"]}, {"_id": 0, "id": 1})
        if not own:
            return []
        q["staff_id"] = own["id"]
    docs = await db.leave_balances.find(q, {"_id": 0}).sort([("year", -1), ("staff_id", 1)]).to_list(10000)
    return docs


@api.get("/leave-balances/my")
async def my_leave_balances(year: Optional[int] = None, user=Depends(get_current_user)):
    own = await db.staff.find_one({"user_id": user["id"]}, {"_id": 0, "id": 1, "name": 1})
    if not own:
        return {"staff": None, "balances": [], "types": []}
    q: dict = {"staff_id": own["id"]}
    if year:
        q["year"] = year
    balances = await db.leave_balances.find(q, {"_id": 0}).sort("year", -1).to_list(200)
    types = await db.leave_types.find({}, {"_id": 0}).to_list(50)
    return {"staff": own, "balances": balances, "types": types}


@api.post("/leave-balances/allocate")
async def allocate_leaves(body: LeaveAllocateIn, user=Depends(require_role("admin", "hr"))):
    """Bulk-allocate days to selected staff (or all staff in a center / globally).
    `mode=set` overwrites the allocated column; `mode=add` adds to existing allocated."""
    lt = await db.leave_types.find_one({"id": body.leave_type_id}, {"_id": 0})
    if not lt:
        raise HTTPException(404, "Leave type not found")

    # Build target staff list
    target_q: dict = {}
    if body.staff_ids:
        target_q["id"] = {"$in": body.staff_ids}
    elif body.center_id:
        target_q["center_id"] = body.center_id
    # else: all staff (no extra filter)
    targets = await db.staff.find(target_q, {"_id": 0, "id": 1, "name": 1}).to_list(10000)
    if not targets:
        raise HTTPException(400, "No staff matched the allocation filter")

    now = datetime.now(timezone.utc).isoformat()
    upserts = 0
    for s in targets:
        existing = await db.leave_balances.find_one(
            {"staff_id": s["id"], "leave_type_id": body.leave_type_id, "year": body.year},
            {"_id": 0},
        )
        if existing:
            allocated = existing.get("allocated", 0)
            new_allocated = body.days if body.mode == "set" else (allocated + body.days)
            await db.leave_balances.update_one(
                {"id": existing["id"]},
                {"$set": {
                    "allocated": new_allocated,
                    "balance": max(0, new_allocated - (existing.get("used", 0) or 0)),
                    "updated_at": now,
                    "updated_by": user["id"],
                    "last_remarks": body.remarks or "",
                }},
            )
        else:
            doc = {
                "id": str(uuid.uuid4()),
                "staff_id": s["id"],
                "leave_type_id": body.leave_type_id,
                "leave_type_code": lt["code"],
                "year": body.year,
                "allocated": body.days,
                "used": 0,
                "balance": body.days,
                "created_at": now,
                "created_by": user["id"],
                "last_remarks": body.remarks or "",
            }
            await db.leave_balances.insert_one(doc)
        upserts += 1
    return {"ok": True, "updated": upserts, "leave_type": lt["code"], "year": body.year}


@api.patch("/leave-balances/{bid}")
async def adjust_leave_balance(bid: str, body: LeaveBalanceAdjustIn, user=Depends(require_role("admin", "hr"))):
    rec = await db.leave_balances.find_one({"id": bid}, {"_id": 0})
    if not rec:
        raise HTTPException(404, "Balance not found")
    allocated = (rec.get("allocated", 0) or 0) + body.delta_allocated
    used = max(0, (rec.get("used", 0) or 0) + body.delta_used)
    balance = max(0, allocated - used)
    upd = {
        "allocated": allocated,
        "used": used,
        "balance": balance,
        "updated_at": datetime.now(timezone.utc).isoformat(),
        "updated_by": user["id"],
        "last_remarks": body.remarks,
    }
    await db.leave_balances.update_one({"id": bid}, {"$set": upd})
    rec.update(upd)
    return rec


# =========================================================================
# ADVANCE PAYMENT & ADJUSTMENT — Phase 1 (Advance Request → Approval → Release)
# =========================================================================
# Lifecycle: draft → pending (approvals) → approved → released → adjusting → settled
#
# Numbering scheme: ADV-YY-<counter> generated at submission time (per financial year).
# Approval chain uses the existing approval_chains system (type="advance_request").
# Release step is Finance-only and creates a linked transaction row automatically
# so cash-flow / reports pick up the outflow like any other payment.

class AdvanceRequestIn(BaseModel):
    model_config = ConfigDict(extra="ignore")
    center_id: Optional[str] = None
    project_id: Optional[str] = None
    company_id: Optional[str] = None
    purpose: str = Field(min_length=2)
    category: Optional[str] = None
    amount: float = Field(gt=0)
    required_till: Optional[str] = None  # YYYY-MM-DD due-back date
    description: Optional[str] = None
    attachments: Optional[List[AttachmentRef]] = None
    # Payee bank/UPI details captured at request time — flow through to the Release
    # dialog + auto-created transaction so accounts don't have to re-key anything.
    # All optional at creation; enforced (if payment_mode requires) at release time.
    preferred_payment_mode: Optional[Literal["bank", "upi", "cash", "cheque"]] = None
    payee_account_holder: Optional[str] = None
    payee_account_no: Optional[str] = None
    payee_ifsc: Optional[str] = None
    payee_bank_name: Optional[str] = None
    payee_upi_id: Optional[str] = None
    # Cancelled cheque / UPI QR / passbook proof — same convention as Payment Request
    payee_proof_attachments: Optional[List[AttachmentRef]] = None


class AdvanceReleaseIn(BaseModel):
    model_config = ConfigDict(extra="ignore")
    payment_mode: Literal["bank", "upi", "cash", "cheque"] = "bank"
    payment_date: Optional[str] = None  # YYYY-MM-DD
    transaction_ref: Optional[str] = None
    paid_amount: Optional[float] = Field(default=None, gt=0)  # defaults to approved amount
    paid_by_user_id: Optional[str] = None
    remarks: Optional[str] = None
    attachments: Optional[List[AttachmentRef]] = None
    # Bank/Cash Reconciliation (Phase 29) — required if any bank_account is
    # configured. Debits the chosen account by paid_amount.
    bank_account_id: Optional[str] = None


class AdvanceSettleIn(BaseModel):
    """Payload for standalone advance settlement (not via Payment adjustment).
    - `cash_repayment` — employee returned cash → creates income txn + reduces balance.
    - `write_off`      — admin writes off unrecoverable balance (bad-debt style expense adj.).
    - `salary_deduction` — schedule this amount to auto-deduct from the next unpaid payroll.
    - `manual_adjustment` — free-form accounting adjustment (audit-logged only, no txn).
    """
    model_config = ConfigDict(extra="ignore")
    settlement_type: Literal["cash_repayment", "write_off", "salary_deduction", "manual_adjustment"]
    amount: float = Field(gt=0)
    date: Optional[str] = None  # YYYY-MM-DD
    payment_mode: Optional[Literal["bank", "upi", "cash", "cheque"]] = None  # for cash_repayment
    transaction_ref: Optional[str] = None
    remarks: Optional[str] = None
    attachments: Optional[List[AttachmentRef]] = None


async def _next_advance_no() -> str:
    """Generate ADV-YY-N sequential number based on financial year (Apr-Mar)."""
    now = datetime.now(timezone.utc)
    fy = now.year if now.month >= 4 else now.year - 1
    prefix = f"ADV-{str(fy)[-2:]}-"
    last = await db.advance_requests.find(
        {"advance_no": {"$regex": f"^{prefix}"}}, {"_id": 0, "advance_no": 1},
    ).sort("advance_no", -1).limit(1).to_list(1)
    counter = 1
    if last:
        try:
            counter = int(last[0]["advance_no"].split("-")[-1]) + 1
        except (ValueError, IndexError):
            counter = 1
    return f"{prefix}{counter:04d}"


async def _next_voucher_no() -> str:
    now = datetime.now(timezone.utc)
    fy = now.year if now.month >= 4 else now.year - 1
    prefix = f"ADV-VCHR-{str(fy)[-2:]}-"
    last = await db.advance_requests.find(
        {"voucher_no": {"$regex": f"^{prefix}"}}, {"_id": 0, "voucher_no": 1},
    ).sort("voucher_no", -1).limit(1).to_list(1)
    counter = 1
    if last and last[0].get("voucher_no"):
        try:
            counter = int(last[0]["voucher_no"].split("-")[-1]) + 1
        except (ValueError, IndexError):
            counter = 1
    return f"{prefix}{counter:04d}"


def _advance_scope_filter(user: dict) -> dict:
    """Return a Mongo filter clause restricting which advance rows a user can see."""
    role = user.get("role")
    if role in ("admin", "hr", "accountant", "senior_manager", "manager"):
        return {}
    if role in ("center_manager", "center_staff"):
        centers = user.get("assigned_center_ids") or []
        return {"center_id": {"$in": centers}}
    if role == "partner":
        return {"partner_id": user.get("assigned_partner_id")}
    # regular staff → only their own
    return {"created_by": user["id"]}


def _annotate_overdue(row: dict) -> None:
    """Attach `is_overdue` + `days_overdue` fields to an advance row (in place).
    Considered overdue when status is released/adjusting, required_till is set, and
    today > required_till."""
    row["is_overdue"] = False
    row["days_overdue"] = 0
    if row.get("status") not in ("released", "adjusting"):
        return
    rt = row.get("required_till")
    if not rt or len(rt) < 10:
        return
    try:
        rt_date = datetime.strptime(rt[:10], "%Y-%m-%d").date()
    except (ValueError, TypeError):
        return
    today = datetime.now(timezone.utc).date()
    if today > rt_date:
        row["is_overdue"] = True
        row["days_overdue"] = (today - rt_date).days


@api.post("/advance-requests", status_code=201)
async def create_advance_request(
    body: AdvanceRequestIn,
    user=Depends(get_current_user),
    idempotency_key: Optional[str] = Depends(_get_idempotency_key),
):
    """Create a new Advance Request. Staff / center_manager / manager / admin / hr can raise one for themselves."""
    if idempotency_key:
        prev = await _check_idempotency(idempotency_key, user["id"])
        if prev is not None:
            return prev
    doc = body.model_dump()
    now_iso = datetime.now(timezone.utc).isoformat()
    staff = await db.staff.find_one({"user_id": user["id"]}, {"_id": 0}) or {}
    doc.update({
        "id": str(uuid.uuid4()),
        "advance_no": await _next_advance_no(),
        "date": now_iso[:10],
        "created_by": user["id"],
        "created_by_name": user.get("name") or user.get("email"),
        "employee_staff_id": staff.get("id"),
        "employee_code": staff.get("employee_code"),
        "employee_name": staff.get("name") or user.get("name") or user.get("email"),
        "designation": staff.get("designation"),
        "status": "pending",
        "adjusted_amount": 0.0,
        "balance_amount": 0.0,
        "paid_amount": 0.0,
        "released_at": None,
        "released_by": None,
        "voucher_no": None,
        "created_at": now_iso,
    })
    # Attach approval chain — same helper reused, `type=advance_request` picks matching chain
    doc = await _attach_chain_to_request("advance_request", doc)
    await db.advance_requests.insert_one(doc)
    doc.pop("_id", None)
    # Notify first-step approvers
    cur = await _current_step(doc)
    if cur:
        for uid in await _resolve_step_user_ids(cur, doc):
            if uid != user["id"]:
                await _notify(
                    uid,
                    f"Advance approval — {doc['advance_no']} · {doc['employee_name']} · ₹{doc['amount']:,.0f}",
                    ntype="advance_pending", ref_id=doc["id"], link="/advances",
                )
    resp = _json_safe(doc)
    await _store_idempotency(idempotency_key, user["id"], resp)
    return resp


@api.get("/advance-requests")
async def list_advance_requests(
    status: Optional[str] = None,
    q: Optional[str] = None,
    skip: int = 0,
    limit: int = 200,
    user=Depends(get_current_user),
):
    """List advance requests scoped by role.
    Admin/HR/Accountant/Sr Mgr/Manager: everything.
    center_manager/center_staff: only their assigned centers.
    partner: their partner scope.
    regular staff: their own requests only.
    """
    query: dict = _advance_scope_filter(user)
    if status and status != "all":
        query["status"] = status
    if q:
        needle = q.strip()
        if needle:
            rx = {"$regex": needle, "$options": "i"}
            query["$or"] = [
                {"advance_no": rx},
                {"employee_name": rx},
                {"employee_code": rx},
                {"purpose": rx},
                {"voucher_no": rx},
            ]
    total = await db.advance_requests.count_documents(query)
    cursor = db.advance_requests.find(query, {"_id": 0}).sort("created_at", -1)
    if skip:
        cursor = cursor.skip(skip)
    if limit:
        cursor = cursor.limit(min(limit, 1000))
    rows = await cursor.to_list(min(limit or 500, 1000))
    for r in rows:
        await _enrich_with_approval_status(r)
        _annotate_overdue(r)
    from starlette.responses import JSONResponse
    return JSONResponse(
        content=_json_safe(rows),
        headers={"X-Total-Count": str(total), "Access-Control-Expose-Headers": "X-Total-Count"},
    )


@api.get("/advance-requests/my")
async def my_advance_requests(user=Depends(get_current_user)):
    """Current user's own advance requests (Staff App)."""
    rows = await db.advance_requests.find(
        {"created_by": user["id"]}, {"_id": 0},
    ).sort("created_at", -1).to_list(200)
    for r in rows:
        await _enrich_with_approval_status(r)
        _annotate_overdue(r)
    return _json_safe(rows)


@api.get("/advance-requests/overdue")
async def overdue_advance_requests(user=Depends(get_current_user)):
    """List advances that are overdue (past required_till without settlement).
    Scoped by role: staff → own; center_manager/staff → their centers; partner → own scope;
    admin/hr/accountant/manager/sr-mgr → all.
    Returns rows enriched with `days_overdue`.
    """
    today = datetime.now(timezone.utc).date().isoformat()
    query = _advance_scope_filter(user)
    query["status"] = {"$in": ["released", "adjusting"]}
    query["required_till"] = {"$lt": today, "$ne": None}
    rows = await db.advance_requests.find(query, {"_id": 0}).sort("required_till", 1).to_list(500)
    for r in rows:
        _annotate_overdue(r)
    # only return truly-overdue ones
    rows = [r for r in rows if r.get("is_overdue")]
    return _json_safe(rows)


@api.post("/advance-requests/overdue/notify")
async def notify_overdue_holders(
    user=Depends(require_role("admin", "accountant", "hr", "senior_manager", "manager")),
):
    """Send an email + in-app notification to every employee whose advance is
    overdue past its `required_till`. Idempotent — repeat calls just re-nudge.
    Returns { notified, skipped_no_email }.
    """
    from email_utils import send_email_with_attachment
    today = datetime.now(timezone.utc).date().isoformat()
    rows = await db.advance_requests.find({
        "status": {"$in": ["released", "adjusting"]},
        "required_till": {"$lt": today, "$ne": None},
    }, {"_id": 0}).sort("required_till", 1).to_list(1000)

    notified = 0
    skipped = 0
    for r in rows:
        _annotate_overdue(r)
        if not r.get("is_overdue"):
            continue
        uid = r.get("created_by")
        if not uid:
            skipped += 1
            continue
        u = await db.users.find_one({"id": uid}, {"_id": 0, "email": 1, "name": 1})
        emp_email = (u or {}).get("email")
        # In-app notification (always)
        await _notify(
            uid,
            f"Reminder: advance {r.get('advance_no')} is overdue by {r['days_overdue']} day(s). Balance ₹{r.get('balance_amount', 0):,.0f}",
            ntype="advance_overdue", ref_id=r.get("id"), link="/advances",
        )
        # Email (best-effort)
        if emp_email:
            subject = f"Overdue Advance {r.get('advance_no')} — please settle"
            html = (
                f"<p>Namaste {(u or {}).get('name') or 'Team'},</p>"
                f"<p>Aapka advance <b>{r.get('advance_no')}</b> ({r.get('purpose') or 'purpose'}) "
                f"jiska Required Till <b>{r.get('required_till')}</b> tha, wo <b>{r['days_overdue']} din</b> se overdue hai.</p>"
                f"<p>Balance outstanding: <b>₹{r.get('balance_amount', 0):,.2f}</b></p>"
                f"<p>Please settle karein — either by raising expense against this advance (Adjust in Payment Request), or by depositing back to accounts.</p>"
                f"<p>Regards,<br/>Accounts Team</p>"
            )
            # send_email_with_attachment supports None attachment via empty bytes trick — but keep it clean
            # Reuse a minimal Resend send here.
            try:
                import resend
                key = os.environ.get("RESEND_API_KEY", "").strip()
                if key:
                    resend.api_key = key
                    sender = os.environ.get("SENDER_EMAIL", "onboarding@resend.dev").strip() or "onboarding@resend.dev"
                    await asyncio.to_thread(resend.Emails.send, {
                        "from": sender, "to": [emp_email], "subject": subject, "html": html,
                    })
            except Exception:  # noqa: BLE001
                pass
            notified += 1
        else:
            skipped += 1
    return {"total_overdue": len(rows), "notified": notified, "skipped_no_email": skipped}


@api.post("/advance-requests/reroute-pending")
async def reroute_pending_advances(user=Depends(require_role("admin"))):
    """Re-attach the currently-active advance_request approval chain to every
    pending/in_progress/sent_back advance whose snapshot doesn't match the
    newly-configured chain. Useful right after an admin configures a new
    multi-level Advance Request chain (e.g. Reporting Manager → Sr Mgr → Accountant)
    so all in-flight requests immediately re-route.

    Only reroutes rows where:
      - status ∈ {pending, in_progress, sent_back}
      - the chain currently attached is different from the one the resolver would pick now
    Rows already partially approved keep their audit trail but jump back to level=1 on the
    NEW chain and append a system `rerouted` history entry.
    """
    rows = await db.advance_requests.find({
        "status": {"$in": ["pending", "in_progress", "sent_back"]},
    }, {"_id": 0}).to_list(1000)
    rerouted = 0
    already_on_current = 0
    for r in rows:
        chain = await _find_active_chain("advance_request", center_id=r.get("center_id"))
        if not chain or not chain.get("steps"):
            continue
        old_chain_id = r.get("chain_id")
        # If it's the same chain and same step count, skip (no reroute needed)
        if old_chain_id == chain.get("id") and len(r.get("chain_snapshot") or []) == len(chain.get("steps") or []):
            already_on_current += 1
            continue
        # Build fresh snapshot from the new chain (reuse _attach helper by copying its logic)
        steps = sorted(chain["steps"], key=lambda s: s.get("level", 0))
        snap = _json_safe(steps)
        now_iso = datetime.now(timezone.utc).isoformat()
        history = list(r.get("chain_history") or [])
        history.append({
            "level": 0, "action": "rerouted", "by_user_id": user["id"],
            "by_user_name": user.get("name") or user.get("email"),
            "at": now_iso,
            "remarks": f"Rerouted from chain {old_chain_id or 'none'} to {chain.get('id')} by admin",
        })
        await db.advance_requests.update_one({"id": r["id"]}, {"$set": {
            "chain_id": chain.get("id"),
            "chain_name": chain.get("name"),
            "chain_snapshot": snap,
            "current_level": 1,
            "status": "pending",
            "chain_history": history,
            "rerouted_at": now_iso,
            "rerouted_by": user["id"],
        }})
        # Notify the new first-step approvers
        cur = snap[0] if snap else None
        if cur:
            fresh = {**r, "chain_id": chain.get("id"), "chain_snapshot": snap, "current_level": 1}
            for uid in await _resolve_step_user_ids(cur, fresh):
                if uid != user["id"]:
                    await _notify(
                        uid,
                        f"Advance approval — {r.get('advance_no')} · {r.get('employee_name')} · ₹{r.get('amount', 0):,.0f} (rerouted)",
                        ntype="advance_pending", ref_id=r["id"], link="/advances",
                    )
        rerouted += 1
    return {"scanned": len(rows), "rerouted": rerouted, "already_on_current_chain": already_on_current}


