@api.get("/advance-requests/{aid}")
async def get_advance_request(aid: str, user=Depends(get_current_user)):
    row = await db.advance_requests.find_one({"id": aid}, {"_id": 0})
    if not row:
        raise HTTPException(404, "Advance request not found")
    # Access check: owner, admin/hr/accountant/sr-mgr always; else must match scope filter.
    if row.get("created_by") != user["id"] and user.get("role") not in ("admin", "hr", "accountant", "senior_manager", "manager"):
        scope = _advance_scope_filter(user)
        if scope and not all(row.get(k) in (v.get("$in", []) if isinstance(v, dict) else [v]) for k, v in scope.items()):
            raise HTTPException(403, "You cannot view this advance request")
    await _enrich_with_approval_status(row)
    _annotate_overdue(row)
    return _json_safe(row)


@api.patch("/advance-requests/{aid}")
async def edit_advance_request(aid: str, body: AdvanceRequestIn, user=Depends(get_current_user)):
    """Requester can edit while status is draft or after a send_back."""
    row = await db.advance_requests.find_one({"id": aid}, {"_id": 0})
    if not row:
        raise HTTPException(404, "Not found")
    if row.get("created_by") != user["id"] and user.get("role") != "admin":
        raise HTTPException(403, "Only the requester or admin can edit an advance")
    if row.get("status") not in ("draft", "sent_back", "pending"):
        raise HTTPException(400, f"Cannot edit an advance in status={row.get('status')}")
    update = body.model_dump(exclude_unset=True)
    update["edited_at"] = datetime.now(timezone.utc).isoformat()
    update["edited_by"] = user["id"]
    await db.advance_requests.update_one({"id": aid}, {"$set": update})
    return await get_advance_request(aid, user)


@api.post("/advance-requests/{aid}/release")
async def release_advance(aid: str, body: AdvanceReleaseIn, user=Depends(require_role("admin", "accountant"))):
    """Finance releases the approved advance:
       - Sets status → 'released', assigns voucher number
       - Creates a linked transaction row (expense / advance-out) so cash-flow dashboards
         pick it up.
    """
    row = await db.advance_requests.find_one({"id": aid}, {"_id": 0})
    if not row:
        raise HTTPException(404, "Advance not found")
    if row.get("status") != "approved":
        raise HTTPException(400, f"Advance must be fully approved before release (status={row.get('status')})")
    if row.get("released_at"):
        raise HTTPException(400, "Advance already released")
    voucher_no = await _next_voucher_no()
    now_iso = datetime.now(timezone.utc).isoformat()
    paid_amount = body.paid_amount or row.get("amount") or 0
    # Prefer the approver-picked attribution (captured at final approval) → this way
    # accounts can pick Center/Partner/Paid-By at approval time and Release just
    # picks up those values automatically. Fallbacks: release body, then advance row.
    eff_paid_by_user_id = body.paid_by_user_id or row.get("approved_paid_by_user_id")
    eff_paid_by_name = row.get("approved_paid_by_name")
    payer = None
    if eff_paid_by_user_id:
        p = await db.users.find_one({"id": eff_paid_by_user_id}, {"_id": 0, "name": 1, "email": 1})
        payer = (p or {}).get("name") or (p or {}).get("email") or eff_paid_by_name
    else:
        payer = eff_paid_by_name
    eff_center_id = row.get("approved_center_id") or row.get("center_id")
    eff_partner_id = row.get("approved_partner_id")
    eff_company_id = row.get("approved_company_id") or row.get("company_id")
    if eff_partner_id is None or eff_company_id is None:
        ctx = await _derive_context_for_center(eff_center_id) if eff_center_id else {}
        if eff_partner_id is None:
            eff_partner_id = (ctx or {}).get("partner_id")
        if eff_company_id is None:
            eff_company_id = (ctx or {}).get("company_id")
    # Create a corresponding transaction for cash-flow visibility.
    # Payee bank/UPI details captured at request-time flow through here so accounts
    # doesn't have to re-key them, and the ledger row shows exactly where the money went.
    txn_id = str(uuid.uuid4())
    txn_doc = {
        "id": txn_id,
        "date": body.payment_date or now_iso[:10],
        "type": "expense",
        "category": "advance",
        "amount": paid_amount,
        "description": f"Advance {row['advance_no']} released to {row['employee_name']}",
        "company_id": eff_company_id,
        "center_id": eff_center_id,
        "project_id": row.get("project_id"),
        "partner_id": eff_partner_id,
        "payment_mode": body.payment_mode,
        "paid_by_user_id": eff_paid_by_user_id,
        "paid_by_name": payer,
        "transaction_ref": body.transaction_ref,
        "advance_request_id": row["id"],
        "advance_no": row.get("advance_no"),
        # Payee details captured on the advance request → stamped on the txn
        "payee_account_holder": row.get("payee_account_holder"),
        "payee_account_no": row.get("payee_account_no"),
        "payee_ifsc": row.get("payee_ifsc"),
        "payee_bank_name": row.get("payee_bank_name"),
        "payee_upi_id": row.get("payee_upi_id"),
        "vendor_name": row.get("employee_name"),  # for the ledger UI to render a payee label
        "attachments": [a.model_dump() if hasattr(a, "model_dump") else a for a in (body.attachments or [])],
        # Bring the original request-time attachments + payee proof onto the txn for audit continuity
        "payee_proof_attachments": row.get("payee_proof_attachments") or [],
        "request_attachments": row.get("attachments") or [],
        "created_by": user["id"],
        "created_by_name": user.get("name") or user.get("email"),
        "created_at": now_iso,
        "status": "approved",
        "approved_by": user["id"],
        "approved_at": now_iso,
        "source": "advance_release",
    }
    await db.transactions.insert_one(txn_doc)
    # Bank/Cash Reconciliation (Phase 29): debit the chosen account for this
    # advance release. Backward compat: if no bank_accounts configured, skip.
    acct = await _require_bank_account_if_configured(body.bank_account_id)
    bank_txn_id = None
    if acct:
        ledger_row = await _post_bank_ledger(
            account_id=acct["id"], direction="debit", amount=float(paid_amount),
            source="advance", source_id=row["id"],
            remarks=f"Advance release · {row['advance_no']} · {row['employee_name']}"
                    + (f" · {body.remarks}" if body.remarks else ""),
            vendor_name=row.get("employee_name"),
            center_id=eff_center_id, center_name=None,
            date=body.payment_date or now_iso[:10], user=user,
        )
        bank_txn_id = ledger_row["id"]
        await db.transactions.update_one(
            {"id": txn_id},
            {"$set": {"bank_account_id": acct["id"], "bank_txn_id": bank_txn_id}},
        )
    await db.advance_requests.update_one({"id": aid}, {"$set": {
        "status": "released",
        "voucher_no": voucher_no,
        "released_at": now_iso,
        "released_by": user["id"],
        "released_by_name": user.get("name") or user.get("email"),
        "payment_mode": body.payment_mode,
        "payment_date": body.payment_date or now_iso[:10],
        "transaction_ref": body.transaction_ref,
        "paid_amount": paid_amount,
        "paid_by_user_id": eff_paid_by_user_id,
        "paid_by_name": payer,
        "release_remarks": body.remarks,
        "release_attachments": [a.model_dump() if hasattr(a, "model_dump") else a for a in (body.attachments or [])],
        "linked_transaction_id": txn_id,
        "bank_account_id": (acct or {}).get("id"),
        "bank_txn_id": bank_txn_id,
        "balance_amount": paid_amount,   # initially = paid; will decrease as expenses adjust in Phase 2
    }})
    # Notify requester
    await _notify(
        row["created_by"],
        f"Your advance {row['advance_no']} · ₹{paid_amount:,.0f} has been released",
        ntype="advance_released", ref_id=row["id"], link="/advances",
    )
    updated = await db.advance_requests.find_one({"id": aid}, {"_id": 0})
    updated.pop("_id", None)
    return _json_safe(updated)


@api.post("/advance-requests/{aid}/settle")
async def settle_advance(
    aid: str, body: AdvanceSettleIn,
    user=Depends(require_role("admin", "accountant")),
):
    """Standalone Settlement Module — settle an open advance balance without going
    through a Payment Request. Supports four types:
      - cash_repayment: creates an income transaction, reduces balance.
      - write_off:      writes off outstanding balance as expense adjustment.
      - salary_deduction: flags amount for next payroll auto-pickup (no txn now).
      - manual_adjustment: no-txn audit entry (for corrections).
    Balance updates + status flip (adjusting → settled) mirror the payment-adjustment path.
    """
    row = await db.advance_requests.find_one({"id": aid}, {"_id": 0})
    if not row:
        raise HTTPException(404, "Advance not found")
    if row.get("status") not in ("released", "adjusting"):
        raise HTTPException(400, f"Cannot settle — advance status is {row.get('status')}")
    balance = float(row.get("balance_amount") or 0)
    if balance <= 0.01:
        raise HTTPException(400, "Advance balance is already zero — nothing to settle")
    amt = round(float(body.amount), 2)
    if amt > balance + 0.01:
        raise HTTPException(400, f"Settlement amount ₹{amt:,.2f} exceeds outstanding balance ₹{balance:,.2f}")
    now_iso = datetime.now(timezone.utc).isoformat()
    settle_date = body.date or now_iso[:10]

    # Build settlement log entry (always appended, regardless of type)
    settlement_id = str(uuid.uuid4())
    entry = {
        "id": settlement_id,
        "settlement_type": body.settlement_type,
        "amount": amt,
        "date": settle_date,
        "payment_mode": body.payment_mode,
        "transaction_ref": body.transaction_ref,
        "remarks": body.remarks,
        "attachments": [a.model_dump() if hasattr(a, "model_dump") else a for a in (body.attachments or [])],
        "at": now_iso,
        "by_user_id": user["id"],
        "by_user_name": user.get("name") or user.get("email"),
        "txn_id": None,
    }

    # Create a transaction for real-cash-movement types
    ctx = await _derive_context_for_center(row.get("center_id")) if row.get("center_id") else {}
    txn = None
    if body.settlement_type == "cash_repayment":
        txn = {
            "id": str(uuid.uuid4()),
            "type": "income",
            "amount": amt,
            "date": settle_date,
            "description": f"Advance repayment · {row['advance_no']} · {row.get('employee_name') or row.get('created_by_name') or ''}",
            "company_id": ctx.get("company_id"),
            "partner_id": ctx.get("partner_id"),
            "center_id": row.get("center_id"),
            "project_id": None,
            "items": [],
            "attachments": entry["attachments"],
            "payment_mode": body.payment_mode,
            "source": "advance_settlement",
            "settlement_id": settlement_id,
            "advance_request_id": aid,
            "advance_no": row["advance_no"],
            "is_advance_settlement": True,
            "created_by": user["id"],
            "created_by_name": user.get("name") or user.get("email"),
            "created_at": now_iso,
            "status": "approved",
            "approved_by": user["id"],
            "approved_at": now_iso,
        }
    elif body.settlement_type == "write_off":
        # Write-off: recognise the outstanding as a loss (expense adjustment).
        txn = {
            "id": str(uuid.uuid4()),
            "type": "expense",
            "amount": amt,
            "date": settle_date,
            "description": f"Advance write-off · {row['advance_no']} · {row.get('employee_name') or ''}",
            "company_id": ctx.get("company_id"),
            "partner_id": ctx.get("partner_id"),
            "center_id": row.get("center_id"),
            "project_id": None,
            "items": [],
            "attachments": entry["attachments"],
            "source": "advance_writeoff",
            "settlement_id": settlement_id,
            "advance_request_id": aid,
            "advance_no": row["advance_no"],
            "is_advance_writeoff": True,
            "created_by": user["id"],
            "created_by_name": user.get("name") or user.get("email"),
            "created_at": now_iso,
            "status": "approved",
            "approved_by": user["id"],
            "approved_at": now_iso,
        }
    if txn:
        await db.transactions.insert_one(txn)
        entry["txn_id"] = txn["id"]

    # Recompute balances
    new_adjusted = float(row.get("adjusted_amount") or 0)
    if body.settlement_type in ("cash_repayment", "salary_deduction", "manual_adjustment", "write_off"):
        # All settlement types reduce the outstanding balance (write_off closes the
        # accounting hole even though the cash never returns; the txn on the other
        # side keeps the P&L honest).
        new_adjusted += amt
    new_balance = max(0.0, round(balance - amt, 2))
    settlements = list(row.get("settlements") or [])
    settlements.append(entry)

    update = {
        "settlements": settlements,
        "adjusted_amount": round(new_adjusted, 2),
        "balance_amount": new_balance,
    }

    # salary_deduction only *schedules* the recovery — book it as pending
    if body.settlement_type == "salary_deduction":
        pending = float(row.get("pending_salary_deduction") or 0)
        update["pending_salary_deduction"] = round(pending + amt, 2)

    # Status: fully-settled if balance closes; otherwise stays adjusting.
    if new_balance <= 0.01:
        update["status"] = "settled"
        update["settled_at"] = now_iso
        update["settlement_reason"] = body.settlement_type
    else:
        update["status"] = "adjusting"

    await db.advance_requests.update_one({"id": aid}, {"$set": update})

    # Notify the requester
    label = {
        "cash_repayment": "Cash repayment received",
        "write_off": "Advance written off",
        "salary_deduction": "Salary deduction scheduled",
        "manual_adjustment": "Manual adjustment posted",
    }.get(body.settlement_type, "Settlement posted")
    await _notify(
        row.get("created_by"),
        f"{label} ₹{amt:,.0f} against advance {row['advance_no']} — balance ₹{new_balance:,.0f}",
        ntype="advance_settled" if new_balance <= 0.01 else "advance_settlement_partial",
        ref_id=aid, link="/advances",
    )

    updated = await db.advance_requests.find_one({"id": aid}, {"_id": 0})
    updated.pop("_id", None)
    return _json_safe(updated)


@api.delete("/advance-requests/{aid}", status_code=204)
async def cancel_advance_request(aid: str, user=Depends(get_current_user)):
    """Requester can withdraw a draft/pending advance; admin can withdraw anything not yet released."""
    row = await db.advance_requests.find_one({"id": aid}, {"_id": 0})
    if not row:
        raise HTTPException(404, "Not found")
    is_admin = user.get("role") == "admin"
    if row.get("created_by") != user["id"] and not is_admin:
        raise HTTPException(403, "Only the requester or admin can cancel")
    if row.get("status") in ("released", "adjusting", "settled") and not is_admin:
        raise HTTPException(400, f"Advance already {row.get('status')} — cannot cancel")
    await db.advance_requests.update_one({"id": aid}, {"$set": {
        "status": "cancelled",
        "cancelled_at": datetime.now(timezone.utc).isoformat(),
        "cancelled_by": user["id"],
    }})
    return None


# =========================================================================
# PAYMENT VOUCHER — auto-generated proof of payment (PDF) for vendors
# =========================================================================
# Trigger: on final approval of a payment (in /api/approvals/act payment
# branch). The voucher is stored in object storage and its metadata lives on
# the payment doc itself (voucher_id / voucher_no / voucher_path) so the
# frontend can offer download / email-to-vendor buttons.

async def _next_voucher_pv_no() -> str:
    """Return next PV-YY-NNNN voucher number for the current financial year."""
    now = datetime.now(timezone.utc)
    fy = now.year if now.month >= 4 else now.year - 1
    prefix = f"PV-{str(fy)[-2:]}-"
    last = await db.payment_vouchers.find(
        {"voucher_no": {"$regex": f"^{prefix}"}}, {"_id": 0, "voucher_no": 1},
    ).sort("voucher_no", -1).limit(1).to_list(1)
    counter = 1
    if last:
        try:
            counter = int(last[0]["voucher_no"].split("-")[-1]) + 1
        except (ValueError, IndexError):
            counter = 1
    return f"{prefix}{counter:04d}"


async def _generate_payment_voucher(
    payment_doc: dict,
    quotation_id: Optional[str],
    company_id: Optional[str],
    center_id: Optional[str],
    txn_ref: Optional[str],
    generated_by: dict,
) -> Optional[dict]:
    """Render + store a Payment Voucher PDF. Returns the persisted voucher doc
    (id, voucher_no, file_path, generated_at) or None on failure.
    """
    from payment_voucher import (
        build_payment_voucher_pdf, storage_path_for_voucher,
    )
    quotation = None
    if quotation_id:
        quotation = await db.quotations.find_one({"id": quotation_id}, {"_id": 0})
    company = await db.companies.find_one({"id": company_id}, {"_id": 0}) if company_id else None
    center = await db.centers.find_one({"id": center_id}, {"_id": 0}) if center_id else None
    voucher_no = await _next_voucher_pv_no()
    voucher_id = str(uuid.uuid4())
    chain = payment_doc.get("chain_history") or []
    pdf_bytes = build_payment_voucher_pdf(
        payment=payment_doc, quotation=quotation, company=company,
        center=center, voucher_no=voucher_no, approval_chain=chain,
        txn_ref=txn_ref,
    )
    # Try object-storage first; fall back to local disk if unavailable.
    file_path = f"{APP_STORAGE_PREFIX}/payment-vouchers/{voucher_id}.pdf"
    try:
        _put_object(file_path, pdf_bytes, "application/pdf")
    except Exception:  # noqa: BLE001
        file_path = storage_path_for_voucher(voucher_id, voucher_no)
        with open(file_path, "wb") as fh:
            fh.write(pdf_bytes)
    now_iso = datetime.now(timezone.utc).isoformat()
    voucher = {
        "id": voucher_id,
        "voucher_no": voucher_no,
        "payment_id": payment_doc.get("id"),
        "quotation_id": quotation_id,
        "amount": float(payment_doc.get("actual_amount") or 0),
        "vendor_name": payment_doc.get("vendor_name") or (quotation or {}).get("vendor_name"),
        "qrn": payment_doc.get("qrn") or (quotation or {}).get("qrn"),
        "center_id": center_id, "company_id": company_id,
        "file_path": file_path,
        "content_type": "application/pdf",
        "generated_at": now_iso,
        "generated_by": generated_by.get("id"),
        "generated_by_name": generated_by.get("name") or generated_by.get("email"),
        "emailed_to_vendor_at": None,
        "emailed_to": None,
    }
    await db.payment_vouchers.insert_one(voucher)
    voucher.pop("_id", None)
    return voucher


@api.get("/payments/{pid}/voucher/download")
async def download_payment_voucher(pid: str, user=Depends(get_current_user)):
    """Stream the payment voucher PDF for a paid payment.
    Access: creator, admin, hr, accountant, senior_manager, manager, or partners of the center.
    """
    from starlette.responses import Response
    p = await db.payments.find_one({"id": pid}, {"_id": 0})
    if not p:
        raise HTTPException(404, "Payment not found")
    if p.get("status") != "paid":
        raise HTTPException(400, "Voucher available only after final approval")
    voucher = await db.payment_vouchers.find_one({"payment_id": pid}, {"_id": 0})
    if not voucher:
        # Late-generate if missing (e.g. legacy payments paid before this feature)
        quotation = await db.quotations.find_one({"id": p.get("quotation_id")}, {"_id": 0}) if p.get("quotation_id") else None
        eff_center_id = p.get("center_id")
        eff_company_id = (quotation or {}).get("company_id")
        if not eff_company_id:
            ctx = await _derive_context_for_center(eff_center_id) if eff_center_id else {}
            eff_company_id = ctx.get("company_id") if ctx else None
        voucher = await _generate_payment_voucher(
            payment_doc=p, quotation_id=p.get("quotation_id"),
            company_id=eff_company_id, center_id=eff_center_id,
            txn_ref=p.get("notes"), generated_by=user,
        )
        if not voucher:
            raise HTTPException(500, "Voucher generation failed")
        await db.payments.update_one({"id": pid}, {"$set": {
            "voucher_id": voucher["id"], "voucher_no": voucher["voucher_no"],
            "voucher_path": voucher["file_path"], "voucher_generated_at": voucher["generated_at"],
        }})
    # Fetch bytes
    file_path = voucher["file_path"]
    try:
        pdf_bytes, ct = _get_object(file_path)
    except Exception:
        # Local-disk fallback
        try:
            with open(file_path, "rb") as fh:
                pdf_bytes = fh.read()
            ct = "application/pdf"
        except Exception as e:  # noqa: BLE001
            raise HTTPException(404, f"Voucher file not found: {str(e)[:120]}") from e
    from payment_voucher import build_payment_voucher_filename
    fname = build_payment_voucher_filename(voucher["voucher_no"], voucher.get("vendor_name"))
    return Response(
        content=pdf_bytes, media_type=ct or "application/pdf",
        headers={"Content-Disposition": f'attachment; filename="{fname}"'},
    )


class VoucherEmailIn(BaseModel):
    model_config = ConfigDict(extra="ignore")
    to_email: str
    subject: Optional[str] = None
    body: Optional[str] = None
    cc: Optional[List[str]] = None


@api.post("/payments/{pid}/voucher/email")
async def email_payment_voucher(pid: str, body: VoucherEmailIn,
                                user=Depends(require_role("admin", "accountant", "hr", "senior_manager"))):
    """Email the payment voucher PDF to the vendor (or any address).
    Uses the same Resend backend as other transactional mail.
    """
    p = await db.payments.find_one({"id": pid}, {"_id": 0})
    if not p:
        raise HTTPException(404, "Payment not found")
    if p.get("status") != "paid":
        raise HTTPException(400, "Voucher can be emailed only after final approval")
    voucher = await db.payment_vouchers.find_one({"payment_id": pid}, {"_id": 0})
    if not voucher:
        raise HTTPException(400, "Voucher not yet generated. Try Download first to regenerate.")
    # Load PDF bytes
    try:
        pdf_bytes, _ct = _get_object(voucher["file_path"])
    except Exception:
        try:
            with open(voucher["file_path"], "rb") as fh:
                pdf_bytes = fh.read()
        except Exception as e:  # noqa: BLE001
            raise HTTPException(404, f"Voucher file missing: {str(e)[:120]}") from e
    from payment_voucher import build_payment_voucher_filename
    from email_utils import send_email_with_attachment
    fname = build_payment_voucher_filename(voucher["voucher_no"], voucher.get("vendor_name"))
    subject = body.subject or f"Payment Voucher {voucher['voucher_no']} · ₹{voucher.get('amount', 0):,.2f}"
    html_body = body.body or (
        f"<p>Dear {voucher.get('vendor_name') or 'Vendor'},</p>"
        f"<p>Please find attached the Payment Voucher for your reference:</p>"
        f"<ul>"
        f"<li><b>Voucher No.:</b> {voucher['voucher_no']}</li>"
        f"<li><b>Amount:</b> ₹{voucher.get('amount', 0):,.2f}</li>"
        f"<li><b>QRN:</b> {voucher.get('qrn') or '—'}</li>"
        f"</ul>"
        f"<p>Regards,<br/>Accounts Team</p>"
    )
    ok = await send_email_with_attachment(
        to=body.to_email, subject=subject, html=html_body,
        attachment_bytes=pdf_bytes, attachment_filename=fname,
        content_type="application/pdf", cc=body.cc or [],
    )
    await db.payment_vouchers.update_one({"id": voucher["id"]}, {"$set": {
        "emailed_to_vendor_at": datetime.now(timezone.utc).isoformat(),
        "emailed_to": body.to_email,
        "emailed_by": user["id"],
    }})
    return {"ok": True, "emailed": bool(ok), "voucher_no": voucher["voucher_no"], "to": body.to_email}


@api.get("/payment-vouchers")
async def list_payment_vouchers(
    q: Optional[str] = None, skip: int = 0, limit: int = 100,
    user=Depends(require_role("admin", "accountant", "hr", "senior_manager", "manager")),
):
    """Admin/Finance list of all generated payment vouchers with search on voucher_no or vendor."""
    query: dict = {}
    if q:
        rx = {"$regex": q.strip(), "$options": "i"}
        query["$or"] = [{"voucher_no": rx}, {"vendor_name": rx}, {"qrn": rx}]
    total = await db.payment_vouchers.count_documents(query)
    rows = await db.payment_vouchers.find(query, {"_id": 0}).sort("generated_at", -1).skip(skip).limit(min(limit, 500)).to_list(min(limit, 500))
    from starlette.responses import JSONResponse
    return JSONResponse(content=_json_safe(rows), headers={"X-Total-Count": str(total), "Access-Control-Expose-Headers": "X-Total-Count"})


# ============================================================================
# Bank / Cash Reconciliation Module (Phase 29, Aug 2026)
# ----------------------------------------------------------------------------
# Tracks real-money balances across bank accounts, cash-in-hand, and UPI wallets.
# Every outflow (payment approve, advance release, reimbursement approve,
# payroll disburse) atomically debits the chosen account; manual deposits credit.
# An append-only `bank_transactions` ledger records each movement with a
# `balance_after` snapshot for audit-safe running balance.
# ============================================================================

BANK_ACCESS_ROLES = ("admin", "accountant")


class BankAccountIn(BaseModel):
    model_config = ConfigDict(extra="ignore")
    name: str = Field(min_length=1, max_length=80)  # e.g. "SBI Current 1234"
    type: Literal["bank", "cash", "upi_wallet"]
    bank_name: Optional[str] = None
    account_no: Optional[str] = None
    ifsc: Optional[str] = None
    upi_id: Optional[str] = None
    opening_balance: float = Field(default=0, ge=0)
    is_active: bool = True
    remarks: Optional[str] = None


class BankAccountOut(BankAccountIn):
    id: str
    current_balance: float
    created_by: str
    created_by_name: Optional[str] = None
    created_at: str


class BankDepositIn(BaseModel):
    model_config = ConfigDict(extra="ignore")
    amount: float = Field(gt=0)
    date: Optional[str] = None  # YYYY-MM-DD, defaults to today
    remarks: str = Field(min_length=1, max_length=500)
    source_label: Optional[str] = Field(default=None, max_length=120)  # e.g. "Milestone received — BOCWW batch A"


class BankAdjustIn(BaseModel):
    model_config = ConfigDict(extra="ignore")
    delta: float  # signed — positive credits, negative debits
    remarks: str = Field(min_length=3, max_length=500)


async def _post_bank_ledger(*, account_id: str, direction: Literal["credit", "debit"],
                            amount: float, source: str, source_id: Optional[str],
                            remarks: str, vendor_name: Optional[str] = None,
                            center_id: Optional[str] = None, center_name: Optional[str] = None,
                            date: Optional[str] = None, user: dict) -> dict:
    """Atomic balance mutation + append-only ledger row.

    Raises 400 if the account is missing/inactive or a debit would overdraw.
    Returns the persisted `bank_transactions` row.
    """
    if amount <= 0:
        raise HTTPException(400, "amount must be > 0")
    acct = await db.bank_accounts.find_one({"id": account_id}, {"_id": 0})
    if not acct:
        raise HTTPException(404, "Bank account not found")
    if not acct.get("is_active", True):
        raise HTTPException(400, "Bank account is inactive")

    delta = amount if direction == "credit" else -amount
    # Guard against overdraft on debit — atomic conditional update.
    filter_ = {"id": account_id, "is_active": True}
    if direction == "debit":
        filter_["current_balance"] = {"$gte": amount}
    updated = await db.bank_accounts.find_one_and_update(
        filter_, {"$inc": {"current_balance": delta}}, return_document=True,
    )
    if not updated:
        if direction == "debit":
            raise HTTPException(400, f"Insufficient balance in {acct.get('name')} — available ₹{acct.get('current_balance',0):,.2f}, needed ₹{amount:,.2f}")
        raise HTTPException(400, "Account update failed")

    now = datetime.now(timezone.utc).isoformat()
    row = {
        "id": str(uuid.uuid4()),
        "account_id": account_id,
        "account_name": acct.get("name"),
        "account_type": acct.get("type"),
        "direction": direction,
        "amount": round(float(amount), 2),
        "balance_after": round(float(updated.get("current_balance") or 0), 2),
        "source": source,       # payment | advance | reimbursement | payroll | deposit | adjustment
        "source_id": source_id,
        "remarks": remarks,
        "vendor_name": vendor_name,
        "center_id": center_id,
        "center_name": center_name,
        "date": date or now[:10],
        "created_by": user["id"],
        "created_by_name": user.get("name"),
        "created_at": now,
    }
    await db.bank_transactions.insert_one(row)
    row.pop("_id", None)
    return row


@api.get("/bank-accounts", response_model=List[BankAccountOut])
async def list_bank_accounts(active_only: bool = False,
                             user=Depends(require_role(*BANK_ACCESS_ROLES))):
    q = {"is_active": True} if active_only else {}
    docs = await db.bank_accounts.find(q, {"_id": 0}).sort([("is_active", -1), ("name", 1)]).to_list(500)
    return [BankAccountOut(**d) for d in docs]


@api.post("/bank-accounts", response_model=BankAccountOut)
async def create_bank_account(body: BankAccountIn, user=Depends(require_role("admin"))):
    if body.type == "bank" and not (body.account_no and body.ifsc):
        raise HTTPException(400, "Bank type requires account_no and IFSC")
    if body.type == "upi_wallet" and not body.upi_id:
        raise HTTPException(400, "UPI Wallet type requires upi_id")
    doc = body.model_dump()
    doc["id"] = str(uuid.uuid4())
    doc["current_balance"] = float(body.opening_balance)
    doc["created_by"] = user["id"]
    doc["created_by_name"] = user.get("name")
    doc["created_at"] = datetime.now(timezone.utc).isoformat()
    await db.bank_accounts.insert_one(doc)
    # If opening_balance > 0, seed an "opening" credit in the ledger so the audit
    # trail explains where the initial balance came from.
    if float(body.opening_balance) > 0:
        await db.bank_transactions.insert_one({
            "id": str(uuid.uuid4()),
            "account_id": doc["id"], "account_name": doc["name"], "account_type": doc["type"],
            "direction": "credit", "amount": round(float(body.opening_balance), 2),
            "balance_after": round(float(body.opening_balance), 2),
            "source": "opening_balance", "source_id": None,
            "remarks": "Opening balance at account creation",
            "vendor_name": None, "center_id": None, "center_name": None,
            "date": doc["created_at"][:10],
            "created_by": user["id"], "created_by_name": user.get("name"),
            "created_at": doc["created_at"],
        })
    return BankAccountOut(**doc)


@api.patch("/bank-accounts/{aid}", response_model=BankAccountOut)
async def update_bank_account(aid: str, body: BankAccountIn, user=Depends(require_role("admin"))):
    """Edit metadata only — current_balance is never modified through this path."""
    update = body.model_dump(exclude={"opening_balance"})
    r = await db.bank_accounts.find_one_and_update(
        {"id": aid}, {"$set": update}, return_document=True,
    )
    if not r:
        raise HTTPException(404, "Not found")
    return BankAccountOut(**{k: v for k, v in r.items() if k != "_id"})


@api.delete("/bank-accounts/{aid}")
async def delete_bank_account(aid: str, _=Depends(require_role("admin"))):
    n = await db.bank_transactions.count_documents({"account_id": aid})
    if n > 0:
        raise HTTPException(400, f"Cannot delete — {n} ledger entries exist. Deactivate the account instead.")
    r = await db.bank_accounts.delete_one({"id": aid})
    if r.deleted_count == 0:
        raise HTTPException(404, "Not found")
    return {"ok": True}


@api.post("/bank-accounts/{aid}/deposit")
async def deposit_to_bank_account(aid: str, body: BankDepositIn,
                                  user=Depends(require_role(*BANK_ACCESS_ROLES))):
    row = await _post_bank_ledger(
        account_id=aid, direction="credit", amount=body.amount,
        source="deposit", source_id=None,
        remarks=body.remarks + (f" · {body.source_label}" if body.source_label else ""),
        date=body.date, user=user,
    )
    return {"ok": True, "transaction": row}


@api.post("/bank-accounts/{aid}/adjust")
async def adjust_bank_account(aid: str, body: BankAdjustIn,
                              user=Depends(require_role("admin"))):
    if body.delta == 0:
        raise HTTPException(400, "delta must be non-zero")
    direction = "credit" if body.delta > 0 else "debit"
    row = await _post_bank_ledger(
        account_id=aid, direction=direction, amount=abs(body.delta),
        source="adjustment", source_id=None,
        remarks=f"Admin adjustment: {body.remarks}", user=user,
    )
    return {"ok": True, "transaction": row}


@api.get("/bank-transactions")
async def list_bank_transactions(
    account_id: Optional[str] = None,
    source: Optional[str] = None,
    center_id: Optional[str] = None,
    from_date: Optional[str] = Query(default=None, alias="from"),
    to_date: Optional[str] = Query(default=None, alias="to"),
    q: Optional[str] = None,
    skip: int = 0,
    limit: int = 100,
    user=Depends(require_role(*BANK_ACCESS_ROLES)),
):
    query: dict = {}
    if account_id:
        query["account_id"] = account_id
    if source:
        query["source"] = source
    if center_id:
        query["center_id"] = center_id
    if from_date or to_date:
        drange: dict = {}
        if from_date:
            drange["$gte"] = from_date
        if to_date:
            drange["$lte"] = to_date
        query["date"] = drange
    if q:
        rx = {"$regex": q.strip(), "$options": "i"}
        query["$or"] = [{"vendor_name": rx}, {"remarks": rx}, {"center_name": rx}, {"account_name": rx}]
    total = await db.bank_transactions.count_documents(query)
    rows = await db.bank_transactions.find(query, {"_id": 0}).sort([
        ("date", -1), ("created_at", -1),
    ]).skip(skip).limit(min(limit, 500)).to_list(min(limit, 500))
    from starlette.responses import JSONResponse
    # Sum totals for the current filter — useful for header KPIs.
    tot_credit = 0.0; tot_debit = 0.0
    async for row in db.bank_transactions.aggregate([
        {"$match": query},
        {"$group": {"_id": "$direction", "sum": {"$sum": "$amount"}}},
    ]):
        if row["_id"] == "credit":
            tot_credit = float(row["sum"])
        else:
            tot_debit = float(row["sum"])
    return JSONResponse(
        content=_json_safe({
            "rows": rows,
            "total_credit": round(tot_credit, 2),
            "total_debit": round(tot_debit, 2),
            "net": round(tot_credit - tot_debit, 2),
        }),
        headers={"X-Total-Count": str(total), "Access-Control-Expose-Headers": "X-Total-Count"},
    )


# ---- Integration hooks ----------------------------------------------------
# Below sections extend existing endpoints (payment approval, advance release,
# reimbursement, payroll) to accept an optional `bank_account_id` and post a
# debit ledger row.  The bank_account_id becomes MANDATORY once at least one
# bank_account exists in the DB — this is enforced at each hook site.


async def _require_bank_account_if_configured(bank_account_id: Optional[str]) -> Optional[dict]:
    """If any bank account exists, callers must pass a bank_account_id. Returns
    the resolved account doc (or None if no accounts configured yet — backwards
    compatible for brand-new deployments).
    """
    n = await db.bank_accounts.count_documents({"is_active": True})
    if n == 0:
        return None  # No accounts yet — skip debit; user hasn't onboarded module.
    if not bank_account_id:
        raise HTTPException(400, "bank_account_id is required — pick which account to debit")
    acct = await db.bank_accounts.find_one({"id": bank_account_id, "is_active": True}, {"_id": 0})
    if not acct:
        raise HTTPException(400, "Selected bank account not found or inactive")
    return acct


# =====================================================================
#                CANDIDATE DATA MANAGEMENT (BOCWW / JSDMS)
# =====================================================================
# Project-wise candidate CRUD + bulk Excel upload/download + soft-delete.
# Access: admin, hr, manager, center_manager, partner.
# Duplicate check: per project on (aadhaar) and per project on (candidate_id).

from openpyxl import Workbook, load_workbook  # noqa: E402
from openpyxl.styles import Font, PatternFill, Alignment  # noqa: E402
from io import BytesIO  # noqa: E402

CANDIDATE_ROLES = ("admin", "hr", "manager", "center_manager", "partner")

# (field_key, excel_header) — order = column order.
BOCWW_COLUMNS = [
    ("fy", "Financial Year"),
    ("center_id", "Center ID"),
    ("s_no", "S.No."),
    ("batch_id", "Batch ID"),
    ("candidate_id", "Candidate ID"),
    ("name", "Candidate Name"),
    ("father_or_husband_name", "Father's Name / Husband Name"),
    ("mother_name", "Mother's Name"),
    ("aadhaar", "Candidate Aadhaar No."),
    ("registered_labour_name", "Registered Labour Name"),
    ("registered_labour_aadhaar", "Registered Labour Aadhaar No."),
    ("relation_with_labour", "Relation with Candidate & Registered Labour"),
    ("labour_reg_no", "Labour Registration No."),
    ("id_card_valid_upto", "ID Card Valid Upto"),
    ("labour_card_issue_date", "Labour Card Issue Date"),
    ("date_of_birth", "Date of Birth"),
    ("gender", "Gender"),
    ("category", "Category"),
    ("address", "Full Address"),
    ("mobile", "Mobile No."),
    ("education", "Education"),
    ("physically_handicapped", "Physically Handicapped"),
    ("course_code", "Course Code"),
    ("course_duration_hours", "Course Duration (Hours)"),
    ("end_time", "End Time"),
    ("state", "State"),
    ("district", "District"),
    ("batch", "Batch"),
    ("course", "Course"),
]

JSDMS_COLUMNS = [
    ("fy", "Financial Year"),
    ("center_id", "Center ID"),
    ("name", "Candidate Name"),
    ("father_name", "Father's Name"),
    ("aadhaar", "Aadhaar Number"),
    ("mobile", "Mobile Number"),
    ("aadhaar_linked_mobile", "Aadhaar Linked Mobile Number"),
    ("date_of_birth", "Date of Birth"),
    ("course_name", "Course Name"),
    ("education", "Education"),
    ("address", "Full Address"),
    ("batch", "Batch"),
    ("district", "District"),
]

REQUIRED_FIELDS = {
    "BOCWW": {k for k, _ in BOCWW_COLUMNS} - {"center_id"},
    "JSDMS": {k for k, _ in JSDMS_COLUMNS} - {"center_id"},
}

# Relation values that indicate the candidate IS the spouse of the registered
# labour. Business rule: such candidates should NOT be enrolled — reject with a
# human-friendly error at both the manual-add and bulk-upload paths.
BLOCKED_RELATIONS = {"wife", "husband"}


def _validate_relation(payload: dict) -> Optional[str]:
    """Return an error string if the BOCWW relation is 'wife' or 'husband'
    (case-insensitive, exact word). Otherwise None."""
    rel = str(payload.get("relation_with_labour") or "").strip().lower()
    if rel in BLOCKED_RELATIONS:
        return f"Relation cannot be '{rel.title()}' — candidate cannot be the labour's spouse"
    return None


async def _candidate_scope_filter(user: dict) -> dict:
    """Center-scope filter for candidate reads.
       - admin / hr / manager / senior_manager: see everything
       - center_manager / center_staff: only records in assigned_center_ids
       - partner: only records at centers where the partner is associated
    """
    role = user.get("role")
    if role in ("admin", "hr", "manager", "senior_manager"):
        return {}
    if role in ("center_manager", "center_staff"):
        return {"center_id": {"$in": user.get("assigned_center_ids") or ["__none__"]}}
    if role == "partner":
        centers = user.get("_associated_center_ids")
        if not centers:
            return {"_never_": True}
        return {"center_id": {"$in": list(centers)}}
    return {"_never_": True}


def _user_scoped_center_ids(user: dict) -> list:
    """Small helper — used by the create endpoint to enforce that a partner /
    center_manager can only create candidates for a center they own."""
    role = user.get("role")
    if role in ("center_manager", "center_staff"):
        return user.get("assigned_center_ids") or []
    if role == "partner":
        return list(user.get("_associated_center_ids") or [])
    return []  # admin/hr/manager/senior_manager — no restriction


def _cand_columns(project: str) -> list:
    if project == "BOCWW":
        return BOCWW_COLUMNS
    if project == "JSDMS":
        return JSDMS_COLUMNS
    raise HTTPException(400, "Unsupported project. Use BOCWW or JSDMS.")


def _stringify_cell(v) -> str:
    """Best-effort convert an openpyxl cell value to a clean string."""
    if v is None:
        return ""
    if isinstance(v, datetime):
        return v.date().isoformat()
    if hasattr(v, "isoformat"):
        try:
            return v.isoformat()
        except Exception:
            pass
    return str(v).strip()


def _normalise_candidate_payload(project: str, data: dict) -> dict:
    """Strip whitespace on string fields and normalise digits-only fields
    (aadhaar / mobile) to numbers-only. Kept lenient — do NOT reject on length
    to allow HR to upload messy legacy data; but expose validation warnings."""
    out = {}
    for k, v in (data or {}).items():
        if isinstance(v, str):
            out[k] = v.strip()
        else:
            out[k] = v
    for f in ("aadhaar", "mobile", "registered_labour_aadhaar", "aadhaar_linked_mobile"):
        if out.get(f):
            out[f] = "".join(ch for ch in str(out[f]) if ch.isdigit())
    if project == "BOCWW":
        # BOCWW-specific soft normalisation
        g = (out.get("gender") or "").upper().strip()
        if g in ("MALE", "M"): out["gender"] = "M"
        elif g in ("FEMALE", "F"): out["gender"] = "F"
        elif g in ("TRANSGENDER", "T", "TRANS"): out["gender"] = "T"
        ph = str(out.get("physically_handicapped") or "").strip().lower()
        if ph in ("yes", "y", "true", "1"): out["physically_handicapped"] = "Yes"
        elif ph in ("no", "n", "false", "0", ""): out["physically_handicapped"] = "No"
    return out


class _CandDupResult(BaseModel):
    duplicate: bool
    on: Optional[str] = None  # "aadhaar" | "candidate_id"


async def _find_duplicate(project: str, payload: dict, exclude_id: Optional[str] = None) -> _CandDupResult:
    """Duplicate rules PER PROJECT:
       - aadhaar (candidate aadhaar): NEVER repeat (both projects)
       - candidate_id: NEVER repeat (BOCWW only)
       - labour_reg_no (BOCWW Reg No.): NEVER repeat (BOCWW only)
       - registered_labour_aadhaar (labour's own aadhaar): allowed for at most 2
         candidates under the same labour; the 3rd is blocked (BOCWW only).
    """
    aadhaar = (payload.get("aadhaar") or "").strip()
    cid = (payload.get("candidate_id") or "").strip()
    lrn = (payload.get("labour_reg_no") or "").strip()
    laa = (payload.get("registered_labour_aadhaar") or "").strip()
    q_base = {"project": project, "is_deleted": {"$ne": True}}
    if exclude_id:
        q_base["id"] = {"$ne": exclude_id}
    if aadhaar:
        hit = await db.candidates.find_one({**q_base, "aadhaar": aadhaar}, {"_id": 0, "id": 1})
        if hit:
            return _CandDupResult(duplicate=True, on="aadhaar")
    if project == "BOCWW":
        if cid:
            hit = await db.candidates.find_one({**q_base, "candidate_id": cid}, {"_id": 0, "id": 1})
            if hit:
                return _CandDupResult(duplicate=True, on="candidate_id")
        if lrn:
            hit = await db.candidates.find_one({**q_base, "labour_reg_no": lrn}, {"_id": 0, "id": 1})
            if hit:
                return _CandDupResult(duplicate=True, on="labour_reg_no")
        if laa:
            # Max 2 candidates per registered labour aadhaar.
            count = await db.candidates.count_documents({**q_base, "registered_labour_aadhaar": laa})
            if count >= 2:
                return _CandDupResult(duplicate=True, on="registered_labour_aadhaar_limit_2")
    return _CandDupResult(duplicate=False)


@api.post("/candidates", status_code=201)
async def create_candidate(payload: dict = Body(...), user=Depends(require_role(*CANDIDATE_ROLES))):
    project = (payload.get("project") or "").upper()
    if project not in ("BOCWW", "JSDMS"):
        raise HTTPException(400, "project must be BOCWW or JSDMS")
    data = _normalise_candidate_payload(project, payload)
    # Required-field check
    missing = [f for f in REQUIRED_FIELDS[project] if not data.get(f)]
    if missing:
        raise HTTPException(400, f"Missing required fields: {', '.join(missing)}")
    # Relation validation — BOCWW cannot enrol the labour's spouse
    if project == "BOCWW":
        rel_err = _validate_relation(data)
        if rel_err:
            raise HTTPException(400, rel_err)
    # Center scoping — enforce that partner / center_manager can only add to
    # their own centers.
    await _enrich_user_with_associations(user)
    scoped = _user_scoped_center_ids(user)
    if scoped:
        cid = str(data.get("center_id") or "").strip()
        if not cid:
            raise HTTPException(400, "Center is required for your role")
        if cid not in scoped:
            raise HTTPException(403, "You can only add candidates for your assigned center(s)")
    dup = await _find_duplicate(project, data)
    if dup.duplicate:
        friendly = {
            "aadhaar": "same Candidate Aadhaar",
            "candidate_id": "same Candidate ID",
            "labour_reg_no": "same BOCWW Registration No.",
            "registered_labour_aadhaar_limit_2": "Labour Aadhaar already has 2 candidates — 3rd not allowed",
        }.get(dup.on, dup.on)
        raise HTTPException(409, f"Duplicate candidate — {friendly} in {project}")
    now = datetime.now(timezone.utc).isoformat()
    doc = {
        **{k: data.get(k) for k, _ in _cand_columns(project) if data.get(k) is not None},
        "id": str(uuid.uuid4()),
        "project": project,
        "created_by": user["id"],
        "created_at": now,
        "updated_at": now,
        "is_deleted": False,
    }
    await db.candidates.insert_one(doc)
    doc.pop("_id", None)
    return doc


@api.get("/candidates")
async def list_candidates(
    project: Optional[str] = Query(None),
    batch: Optional[str] = Query(None),
    district: Optional[str] = Query(None),
    course: Optional[str] = Query(None),
    fy: Optional[str] = Query(None),
    search: Optional[str] = Query(None),
    date_from: Optional[str] = Query(None),
    date_to: Optional[str] = Query(None),
    include_deleted: bool = Query(False),
    page: int = Query(1, ge=1),
    page_size: int = Query(50, ge=1, le=500),
    user=Depends(require_role(*CANDIDATE_ROLES)),
):
    await _enrich_user_with_associations(user)
    scope = await _candidate_scope_filter(user)
    if scope.get("_never_"):
        return {"total": 0, "page": page, "page_size": page_size, "items": []}
    q: dict = dict(scope)
    if not include_deleted:
        q["is_deleted"] = {"$ne": True}
    if project:
        q["project"] = project.upper()
    if batch:
        q["batch"] = batch
    if district:
        q["district"] = district
    if fy:
        q["fy"] = fy
    if course:
        q["$or"] = [{"course": course}, {"course_name": course}, {"course_code": course}]
    if date_from or date_to:
        rng: dict = {}
        if date_from: rng["$gte"] = date_from
        if date_to: rng["$lte"] = date_to + "T23:59:59"
        q["created_at"] = rng
    if search:
        s = search.strip()
        s_or = [
            {"name": {"$regex": s, "$options": "i"}},
            {"father_name": {"$regex": s, "$options": "i"}},
            {"father_or_husband_name": {"$regex": s, "$options": "i"}},
            {"mother_name": {"$regex": s, "$options": "i"}},
            {"candidate_id": {"$regex": s, "$options": "i"}},
            {"aadhaar": {"$regex": s, "$options": "i"}},
            {"mobile": {"$regex": s, "$options": "i"}},
            {"batch_id": {"$regex": s, "$options": "i"}},
            {"fy": {"$regex": s, "$options": "i"}},
            {"labour_reg_no": {"$regex": s, "$options": "i"}},
        ]
        # merge with existing $or from course (project=all case). Use $and to combine.
        if "$or" in q:
            q = {"$and": [{"$or": q.pop("$or")}, {"$or": s_or}], **q}
        else:
            q["$or"] = s_or
    total = await db.candidates.count_documents(q)
    docs = await db.candidates.find(q, {"_id": 0}).sort("created_at", -1).skip((page - 1) * page_size).limit(page_size).to_list(page_size)
    return {"total": total, "page": page, "page_size": page_size, "items": docs}


@api.get("/candidates/filter-options")
async def candidate_filter_options(
    project: Optional[str] = Query(None),
    user=Depends(require_role(*CANDIDATE_ROLES)),
):
    """Return distinct batches / districts / courses / fys so the UI's filter dropdowns
    can be populated from real data (free-text fields, so we just distinct)."""
    await _enrich_user_with_associations(user)
    scope = await _candidate_scope_filter(user)
    if scope.get("_never_"):
        return {"batches": [], "districts": [], "courses": [], "fys": []}
    q: dict = {**scope, "is_deleted": {"$ne": True}}
    if project: q["project"] = project.upper()
    batches = await db.candidates.distinct("batch", q)
    districts = await db.candidates.distinct("district", q)
    courses1 = await db.candidates.distinct("course", q)
    courses2 = await db.candidates.distinct("course_name", q)
    fys = await db.candidates.distinct("fy", q)
    return {
        "batches": sorted([b for b in batches if b]),
        "districts": sorted([d for d in districts if d]),
        "courses": sorted({c for c in courses1 + courses2 if c}),
        "fys": sorted([f for f in fys if f]),
    }


@api.get("/candidates/sample-excel")
async def candidate_sample_excel(
    project: str = Query(...),
    _=Depends(require_role(*CANDIDATE_ROLES)),
):
    project = project.upper()
    cols = _cand_columns(project)
    wb = Workbook()
    ws = wb.active
    ws.title = f"{project}-Sample"
    header_font = Font(bold=True, color="FFFFFF")
    header_fill = PatternFill(start_color="1E4EAB", end_color="1E4EAB", fill_type="solid")
    for idx, (_key, header) in enumerate(cols, start=1):
        cell = ws.cell(row=1, column=idx, value=header)
        cell.font = header_font
        cell.fill = header_fill
        cell.alignment = Alignment(horizontal="center", vertical="center")
        ws.column_dimensions[cell.column_letter].width = max(14, len(header) + 4)
    # Add a sample row with placeholder guidance
    if project == "BOCWW":
        sample = ["2024-25", "", "1", "BATCH-01", "CAND-0001", "Rahul Kumar", "Ramesh Kumar", "Sita Devi",
                  "123412341234", "Ramesh Kumar", "987698769876", "Father", "LR-0001",
                  "2027-12-31", "2024-01-15", "2002-05-15", "M", "General",
                  "Village Xyz, Ranchi, Jharkhand", "9876543210", "12th", "No",
                  "CC-EL-01", "300", "18:00", "Jharkhand", "Ranchi", "BATCH-01", "Electrician"]
    else:
        sample = ["2024-25", "", "Anita Devi", "Suresh Yadav", "112211221122", "9876543210", "9876543210",
                  "2000-07-20", "Data Entry Operator", "12th", "Village Abc, Gumla", "JSDMS-BATCH-01", "Gumla"]
    for i, v in enumerate(sample, start=1):
        ws.cell(row=2, column=i, value=v)
    ws.freeze_panes = "A2"
    buf = BytesIO()
    wb.save(buf)
    buf.seek(0)
    fname = f"{project}_candidate_sample.xlsx"
    return Response(
        content=buf.read(),
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f'attachment; filename="{fname}"'},
    )


@api.post("/candidates/bulk-upload")
async def candidate_bulk_upload(
    project: str = Query(...),
    file: UploadFile = File(...),
    user=Depends(require_role(*CANDIDATE_ROLES)),
):
    project = project.upper()
    cols = _cand_columns(project)
    header_to_key = {header: key for key, header in cols}
    data_bytes = await file.read()
    if len(data_bytes) > 20 * 1024 * 1024:
        raise HTTPException(413, "File too large (max 20MB)")
    try:
        wb = load_workbook(BytesIO(data_bytes), data_only=True, read_only=True)
    except Exception as e:
        raise HTTPException(400, f"Invalid Excel file: {e}")
    ws = wb.active
    rows_iter = ws.iter_rows(values_only=True)
    try:
        header_row = next(rows_iter)
    except StopIteration:
        raise HTTPException(400, "Excel is empty")
    headers = [(_stringify_cell(h) if h is not None else "") for h in header_row]
    # STRICT: every expected header must be present (case-sensitive, exact)
    expected = [h for _, h in cols]
    missing_headers = [h for h in expected if h not in headers]
    if missing_headers:
        raise HTTPException(400, f"Missing columns in Excel: {', '.join(missing_headers)}")
    header_index = {h: i for i, h in enumerate(headers)}
    now = datetime.now(timezone.utc).isoformat()
    summary = {"uploaded": 0, "failed": 0, "duplicate": 0, "total_rows": 0, "errors": []}
    to_insert: list = []
    # Compute the user's scoped center list ONCE — partner / center_manager
    # bulk uploads must stay within their own centers.
    await _enrich_user_with_associations(user)
    scoped_center_ids = set(_user_scoped_center_ids(user))
    # Track keys that already appear in this same file so we block repeats
    # inside a single upload (in addition to the DB check).
    seen_aadhaar: set = set()
    seen_cid: set = set()      # BOCWW only
    seen_lrn: set = set()      # BOCWW only (labour_reg_no)
    # Labour Aadhaar allows up to 2 candidates — track a running counter that
    # combines DB count + rows already accepted in this same file.
    from collections import defaultdict
    seen_laa_count: dict = defaultdict(int)  # BOCWW only
    db_laa_count_cache: dict = {}            # laa -> initial DB count (cached per upload)
    for r_i, row in enumerate(rows_iter, start=2):
        # skip fully empty rows
        if not row or all(c is None or _stringify_cell(c) == "" for c in row):
            continue
        summary["total_rows"] += 1
        rec: dict = {}
        for key, header in cols:
            idx = header_index.get(header)
            if idx is None or idx >= len(row):
                rec[key] = ""
            else:
                rec[key] = _stringify_cell(row[idx])
        rec = _normalise_candidate_payload(project, rec)
        # Required fields
        missing = [f for f in REQUIRED_FIELDS[project] if not rec.get(f)]
        if missing:
            summary["failed"] += 1
            summary["errors"].append({"row": r_i, "reason": f"Missing required: {', '.join(missing)}"})
            continue
        # Relation validation (BOCWW only) — cannot enrol labour's spouse
        if project == "BOCWW":
            rel_err = _validate_relation(rec)
            if rel_err:
                summary["failed"] += 1
                summary["errors"].append({"row": r_i, "reason": rel_err})
                continue
        # Center scoping enforcement — partner / center_manager can't upload
        # rows for centers they don't own.
        if scoped_center_ids:
            row_center = str(rec.get("center_id") or "").strip()
            if not row_center:
                summary["failed"] += 1
                summary["errors"].append({"row": r_i, "reason": "Center ID is required for your role"})
                continue
            if row_center not in scoped_center_ids:
                summary["failed"] += 1
                summary["errors"].append({"row": r_i, "reason": f"Center ID '{row_center}' is not in your assigned centers"})
                continue
        aadhaar = rec.get("aadhaar") or ""
        cid = rec.get("candidate_id") or ""
        lrn = rec.get("labour_reg_no") or ""
        laa = rec.get("registered_labour_aadhaar") or ""
        # In-file duplicate — key-wise
        if aadhaar and aadhaar in seen_aadhaar:
            summary["duplicate"] += 1
            summary["errors"].append({"row": r_i, "reason": f"Duplicate within upload — same Aadhaar ({aadhaar}) already in row above"})
            continue
        if project == "BOCWW" and cid and cid in seen_cid:
            summary["duplicate"] += 1
            summary["errors"].append({"row": r_i, "reason": f"Duplicate within upload — same Candidate ID ({cid}) already in row above"})
            continue
        if project == "BOCWW" and lrn and lrn in seen_lrn:
            summary["duplicate"] += 1
            summary["errors"].append({"row": r_i, "reason": f"Duplicate within upload — same BOCWW Registration No. ({lrn}) already in row above"})
            continue
        # Duplicate against DB
        dup_db = await _find_duplicate(project, rec)
        if dup_db.duplicate:
            hint = {
                "aadhaar": "Aadhaar",
                "candidate_id": "Candidate ID",
                "labour_reg_no": "BOCWW Registration No.",
                "registered_labour_aadhaar_limit_2": "Labour Aadhaar (max 2 candidates allowed)",
            }.get(dup_db.on, dup_db.on)
            summary["duplicate"] += 1
            summary["errors"].append({"row": r_i, "reason": f"Duplicate in database — {hint} limit reached in {project}"})
            continue
        # Labour Aadhaar cumulative cap of 2 across DB + rows already accepted in this file.
        if project == "BOCWW" and laa:
            if laa not in db_laa_count_cache:
                db_laa_count_cache[laa] = await db.candidates.count_documents({
                    "project": "BOCWW", "is_deleted": {"$ne": True}, "registered_labour_aadhaar": laa,
                })
            projected = db_laa_count_cache[laa] + seen_laa_count[laa]
            if projected >= 2:
                summary["duplicate"] += 1
                summary["errors"].append({"row": r_i, "reason": f"Labour Aadhaar ({laa}) already has 2 candidates — 3rd not allowed"})
                continue
        rec["id"] = str(uuid.uuid4())
        rec["project"] = project
        rec["created_by"] = user["id"]
        rec["created_at"] = now
        rec["updated_at"] = now
        rec["is_deleted"] = False
        to_insert.append(rec)
        if aadhaar: seen_aadhaar.add(aadhaar)
        if project == "BOCWW":
            if cid: seen_cid.add(cid)
            if lrn: seen_lrn.add(lrn)
            if laa: seen_laa_count[laa] += 1
    if to_insert:
        await db.candidates.insert_many(to_insert)
    summary["uploaded"] = len(to_insert)
    # Truncate very long error lists so response stays small
    summary["errors"] = summary["errors"][:200]
    return summary


@api.get("/candidates/export")
async def candidate_export_excel(
    project: Optional[str] = Query(None),
    batch: Optional[str] = Query(None),
    district: Optional[str] = Query(None),
    course: Optional[str] = Query(None),
    fy: Optional[str] = Query(None),
    search: Optional[str] = Query(None),
    date_from: Optional[str] = Query(None),
    date_to: Optional[str] = Query(None),
    user=Depends(require_role(*CANDIDATE_ROLES)),
):
    await _enrich_user_with_associations(user)
    scope = await _candidate_scope_filter(user)
    if scope.get("_never_"):
        # Return an empty spreadsheet if the user's scope resolves to nothing.
        wb0 = Workbook(); ws0 = wb0.active; ws0.title = "Candidates"
        buf0 = BytesIO(); wb0.save(buf0); buf0.seek(0)
        return Response(content=buf0.read(),
            media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            headers={"Content-Disposition": 'attachment; filename="candidates_empty.xlsx"'})
    q: dict = {**scope, "is_deleted": {"$ne": True}}
    proj_key = (project or "").upper() if project else None
    if proj_key: q["project"] = proj_key
    if batch: q["batch"] = batch
    if district: q["district"] = district
    if fy: q["fy"] = fy
    if course: q["$or"] = [{"course": course}, {"course_name": course}, {"course_code": course}]
    if date_from or date_to:
        rng: dict = {}
        if date_from: rng["$gte"] = date_from
        if date_to: rng["$lte"] = date_to + "T23:59:59"
        q["created_at"] = rng
    if search:
        s = search.strip()
        s_or = [
            {"name": {"$regex": s, "$options": "i"}},
            {"candidate_id": {"$regex": s, "$options": "i"}},
            {"aadhaar": {"$regex": s, "$options": "i"}},
            {"mobile": {"$regex": s, "$options": "i"}},
        ]
        if "$or" in q:
            q = {"$and": [{"$or": q.pop("$or")}, {"$or": s_or}], **q}
        else:
            q["$or"] = s_or
    docs = await db.candidates.find(q, {"_id": 0}).sort("created_at", -1).to_list(10000)
    wb = Workbook()
    ws = wb.active
    ws.title = "Candidates"
    header_font = Font(bold=True, color="FFFFFF")
    header_fill = PatternFill(start_color="1E4EAB", end_color="1E4EAB", fill_type="solid")
    if proj_key in ("BOCWW", "JSDMS"):
        cols = _cand_columns(proj_key)
    else:
        # Union view — include an extra Project column at the front
        cols = [("project", "Project")] + BOCWW_COLUMNS  # BOCWW has all fields
    for idx, (_k, header) in enumerate(cols, start=1):
        c = ws.cell(row=1, column=idx, value=header)
        c.font = header_font
        c.fill = header_fill
        c.alignment = Alignment(horizontal="center", vertical="center")
        ws.column_dimensions[c.column_letter].width = max(14, len(header) + 4)
    for r_i, d in enumerate(docs, start=2):
        for c_i, (key, _h) in enumerate(cols, start=1):
            ws.cell(row=r_i, column=c_i, value=d.get(key, ""))
    ws.freeze_panes = "A2"
    buf = BytesIO()
    wb.save(buf)
    buf.seek(0)
    scope = (proj_key or "ALL").lower()
    fname = f"candidates_{scope}_{datetime.now(timezone.utc).strftime('%Y%m%d_%H%M')}.xlsx"
    return Response(
        content=buf.read(),
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f'attachment; filename="{fname}"'},
    )


@api.get("/candidates/{cid}")
async def get_candidate(cid: str, _=Depends(require_role(*CANDIDATE_ROLES))):
    doc = await db.candidates.find_one({"id": cid}, {"_id": 0})
    if not doc:
        raise HTTPException(404, "Candidate not found")
    return doc


@api.patch("/candidates/{cid}")
async def update_candidate(cid: str, payload: dict = Body(...), user=Depends(require_role(*CANDIDATE_ROLES))):
    existing = await db.candidates.find_one({"id": cid}, {"_id": 0})
    if not existing:
        raise HTTPException(404, "Candidate not found")
    project = existing.get("project") or (payload.get("project") or "").upper()
    if project not in ("BOCWW", "JSDMS"):
        raise HTTPException(400, "Missing project")
    # Scope check — partner / center_manager can only edit within their centers.
    await _enrich_user_with_associations(user)
    scoped = _user_scoped_center_ids(user)
    if scoped and existing.get("center_id") not in scoped:
        raise HTTPException(403, "You can only edit candidates for your assigned center(s)")
    data = _normalise_candidate_payload(project, payload)
    if project == "BOCWW":
        rel_err = _validate_relation({**existing, **data})
        if rel_err:
            raise HTTPException(400, rel_err)
    # Duplicate check (exclude self)
    dup = await _find_duplicate(project, data, exclude_id=cid)
    if dup.duplicate:
        friendly = {
            "aadhaar": "same Candidate Aadhaar",
            "candidate_id": "same Candidate ID",
            "labour_reg_no": "same BOCWW Registration No.",
            "registered_labour_aadhaar_limit_2": "Labour Aadhaar already has 2 candidates — 3rd not allowed",
        }.get(dup.on, dup.on)
        raise HTTPException(409, f"Duplicate — {friendly} in {project}")
    upd = {k: v for k, v in data.items() if k not in ("id", "project", "created_by", "created_at", "is_deleted")}
    upd["updated_at"] = datetime.now(timezone.utc).isoformat()
    upd["updated_by"] = user["id"]
    await db.candidates.update_one({"id": cid}, {"$set": upd})
    doc = await db.candidates.find_one({"id": cid}, {"_id": 0})
    return doc


@api.post("/candidates/cleanup-duplicates")
async def candidate_cleanup_duplicates(
    project: Optional[str] = Query(None),
    dry_run: bool = Query(True),
    _=Depends(require_role("admin", "hr")),
):
    """Admin-only utility: for every project+aadhaar combo that has 2+ rows,
    keep the earliest live record and soft-delete the rest.
    Set `dry_run=false` to actually archive."""
    match: dict = {"is_deleted": {"$ne": True}, "aadhaar": {"$nin": [None, ""]}}
    if project: match["project"] = project.upper()
    pipeline = [
        {"$match": match},
        {"$group": {"_id": {"project": "$project", "aadhaar": "$aadhaar"},
                    "count": {"$sum": 1},
                    "items": {"$push": {"id": "$id", "name": "$name", "candidate_id": "$candidate_id",
                                        "created_at": "$created_at"}}}},
        {"$match": {"count": {"$gt": 1}}},
        {"$sort": {"count": -1}},
    ]
    groups = await db.candidates.aggregate(pipeline).to_list(2000)
    to_archive_ids: list = []
    report: list = []
    for g in groups:
        items = sorted(g["items"], key=lambda x: x.get("created_at") or "")
        keep = items[0]
        drop = items[1:]
        to_archive_ids.extend([x["id"] for x in drop])
        report.append({
            "project": g["_id"]["project"], "aadhaar": g["_id"]["aadhaar"],
            "count": g["count"], "keep_id": keep["id"], "keep_name": keep.get("name"),
            "archive_ids": [x["id"] for x in drop],
        })
    if not dry_run and to_archive_ids:
        r = await db.candidates.update_many(
            {"id": {"$in": to_archive_ids}},
            {"$set": {"is_deleted": True, "deleted_at": datetime.now(timezone.utc).isoformat(),
                      "deleted_reason": "auto-cleanup: duplicate candidate aadhaar"}},
        )
        archived = r.modified_count
    else:
        archived = 0
    return {
        "duplicate_groups": len(groups),
        "candidates_to_archive": len(to_archive_ids),
        "archived": archived,
        "dry_run": dry_run,
        "groups": report[:200],
    }



async def delete_candidate(cid: str, user=Depends(require_role("admin", "hr"))):
    r = await db.candidates.update_one(
        {"id": cid, "is_deleted": {"$ne": True}},
        {"$set": {"is_deleted": True, "deleted_at": datetime.now(timezone.utc).isoformat(), "deleted_by": user["id"]}},
    )
    if r.matched_count == 0:
        raise HTTPException(404, "Candidate not found or already deleted")
    return None


@api.patch("/candidates/{cid}/restore")
async def restore_candidate(cid: str, _=Depends(require_role("admin", "hr"))):
    r = await db.candidates.update_one(
        {"id": cid, "is_deleted": True},
        {"$set": {"is_deleted": False}, "$unset": {"deleted_at": "", "deleted_by": ""}},
    )
    if r.matched_count == 0:
        raise HTTPException(404, "Candidate not found or not deleted")
    doc = await db.candidates.find_one({"id": cid}, {"_id": 0})
    return doc




