BG_ROLES = ("admin", "hr", "manager", "senior_manager", "accountant", "center_manager", "partner")
BG_WRITE_ROLES = ("admin", "hr", "manager", "senior_manager", "accountant")


@api.post("/bank-guarantees", status_code=201)
async def create_bank_guarantee(
    letter_of_intent_no: Optional[str] = Query(None),
    work_order_no: Optional[str] = Query(None),
    in_favour_of: Optional[str] = Query(None),
    applicant: Optional[str] = Query(None),
    issued_by: str = Query(...),
    bg_number: str = Query(...),
    amount: float = Query(...),
    date_of_issuance: str = Query(...),
    valid_till: str = Query(...),
    bg_claim_expiry_date: str = Query(...),
    center_id: Optional[str] = Query(None),
    location: Optional[str] = Query(None),
    remarks: Optional[str] = Query(None),
    fy: Optional[str] = Query(None),
    renews_bg_id: Optional[str] = Query(None),
    file: Optional[UploadFile] = File(None),
    user=Depends(require_role(*BG_WRITE_ROLES)),
):
    bg_id = str(uuid.uuid4())
    attachment = None
    if file and file.filename:
        data = await file.read()
        if len(data) > 2 * 1024 * 1024:
            raise HTTPException(413, "Attachment must be less than 2MB")
        ext = file.filename.rsplit(".", 1)[-1].lower() if "." in file.filename else "bin"
        path = f"{APP_STORAGE_PREFIX}/bank-guarantees/{bg_id}.{ext}"
        ct = file.content_type or "application/octet-stream"
        try:
            _put_object(path, data, ct)
        except requests.HTTPError as e:
            raise HTTPException(502, f"Storage upload failed: {e}")
        await db.files.insert_one({
            "id": bg_id, "path": path, "filename": file.filename,
            "content_type": ct, "size": len(data),
            "uploaded_by": user["id"], "uploaded_at": datetime.now(timezone.utc).isoformat(),
            "is_deleted": False,
        })
        attachment = {"path": path, "filename": file.filename, "content_type": ct, "size": len(data)}
    now = datetime.now(timezone.utc).isoformat()
    # Renewal chain — validate that the referenced BG exists and belongs to this system.
    renews_bg_number = None
    if renews_bg_id:
        old = await db.bank_guarantees.find_one({"id": renews_bg_id, "is_deleted": {"$ne": True}}, {"_id": 0, "bg_number": 1})
        if not old:
            raise HTTPException(404, "Referenced BG (renews_bg_id) not found")
        renews_bg_number = old.get("bg_number")
    doc = {
        "id": bg_id,
        "fy": (fy or "").strip() or None,
        "letter_of_intent_no": (letter_of_intent_no or "").strip() or None,
        "work_order_no": (work_order_no or "").strip() or None,
        "in_favour_of": (in_favour_of or "").strip() or None,
        "applicant": (applicant or "").strip() or None,
        "issued_by": issued_by.strip(),
        "bg_number": bg_number.strip(),
        "amount": float(amount),
        "date_of_issuance": date_of_issuance,
        "valid_till": valid_till,
        "bg_claim_expiry_date": bg_claim_expiry_date,
        "center_id": (center_id or "").strip() or None,
        "location": (location or "").strip() or None,
        "remarks": (remarks or "").strip() or None,
        "attachment": attachment,
        "is_renewed": False,
        "is_deleted": False,
        "renews_bg_id": renews_bg_id or None,
        "renews_bg_number": renews_bg_number,
        "created_by": user["id"],
        "created_at": now,
        "updated_at": now,
    }
    await db.bank_guarantees.insert_one(doc)
    # If this new BG renews an old one, flip the old to renewed and stitch the
    # audit chain (`renewed_by_bg_id` on the old row) so history is preserved.
    if renews_bg_id:
        await db.bank_guarantees.update_one(
            {"id": renews_bg_id},
            {"$set": {
                "is_renewed": True,
                "renewed_at": now,
                "renewed_by_bg_id": bg_id,
                "renewed_by_bg_number": bg_number.strip(),
                "renewed_by_user": user["id"],
            }},
        )
    doc.pop("_id", None)
    return doc


# ---------------- Bank Guarantee Bulk Upload ----------------
BG_BULK_COLUMNS = [
    ("fy", "FY"),
    ("letter_of_intent_no", "Letter of Intent (LoI) No"),
    ("work_order_no", "Work Order No"),
    ("in_favour_of", "In Favour Of"),
    ("applicant", "Applicant"),
    ("issued_by", "Issued By"),
    ("bg_number", "Bank Guarantee Number"),
    ("amount", "Amount"),
    ("date_of_issuance", "Date of Issuance"),
    ("valid_till", "Valid Till"),
    ("bg_claim_expiry_date", "BG Claim Expiry Date"),
    ("center_name", "Center"),
    ("location", "Location"),
    ("remarks", "Remarks"),
]
BG_BULK_COLUMNS_MAP = {k: h for k, h in BG_BULK_COLUMNS}
BG_BULK_REQUIRED = {"issued_by", "bg_number", "amount", "date_of_issuance",
                    "valid_till", "bg_claim_expiry_date"}


def _parse_excel_date(v) -> Optional[str]:
    """Accepts datetime, ISO, dd/mm/yyyy, dd-mm-yyyy, yyyy-mm-dd → ISO or None."""
    if v is None or v == "":
        return None
    if isinstance(v, datetime):
        return v.date().isoformat()
    if hasattr(v, "isoformat"):
        try: return v.isoformat()
        except Exception: pass
    s = str(v).strip()
    if not s:
        return None
    for fmt in ("%Y-%m-%d", "%d-%m-%Y", "%d/%m/%Y", "%d.%m.%Y", "%Y/%m/%d"):
        try:
            return datetime.strptime(s, fmt).date().isoformat()
        except Exception:
            continue
    return None


def _parse_bg_amount(v) -> Optional[float]:
    if v is None or v == "":
        return None
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v).strip().replace(",", "").replace("\u20b9", "").replace("Rs.", "").replace("Rs", "").strip()
    try:
        return float(s)
    except Exception:
        return None


async def _bg_validate_bulk_rows(rows_iter, header_index: dict) -> dict:
    """Return {valid_rows:[{row,data}], errors:[{row,reason,data}]}. Duplicate BG
    numbers are checked both within the file and against the live DB. Center
    Name (if provided) is resolved to a center_id via case-insensitive lookup."""
    valid_rows: list = []
    errors: list = []
    seen_in_file: set = set()
    existing_docs = await db.bank_guarantees.find(
        {"is_deleted": {"$ne": True}}, {"_id": 0, "bg_number": 1}
    ).to_list(20000)
    db_bg_numbers = {(d.get("bg_number") or "").strip().lower()
                     for d in existing_docs if d.get("bg_number")}
    # Center lookup — build a lowercase name/city → id map once.
    center_docs = await db.centers.find({"is_deleted": {"$ne": True}},
                                        {"_id": 0, "id": 1, "name": 1}).to_list(5000)
    center_map = {(c.get("name") or "").strip().lower(): c["id"] for c in center_docs if c.get("id")}

    for r_i, row in enumerate(rows_iter, start=2):
        if not row or all(c is None or _stringify_cell(c) == "" for c in row):
            continue
        rec: dict = {}
        for key, header in BG_BULK_COLUMNS:
            idx = header_index.get(header)
            rec[key] = row[idx] if idx is not None and idx < len(row) else None
        cleaned = {
            "fy": _stringify_cell(rec.get("fy")),
            "letter_of_intent_no": _stringify_cell(rec.get("letter_of_intent_no")),
            "work_order_no": _stringify_cell(rec.get("work_order_no")),
            "in_favour_of": _stringify_cell(rec.get("in_favour_of")),
            "applicant": _stringify_cell(rec.get("applicant")),
            "issued_by": _stringify_cell(rec.get("issued_by")),
            "bg_number": _stringify_cell(rec.get("bg_number")),
            "amount": _parse_bg_amount(rec.get("amount")),
            "date_of_issuance": _parse_excel_date(rec.get("date_of_issuance")),
            "valid_till": _parse_excel_date(rec.get("valid_till")),
            "bg_claim_expiry_date": _parse_excel_date(rec.get("bg_claim_expiry_date")),
            "center_name": _stringify_cell(rec.get("center_name")),
            "location": _stringify_cell(rec.get("location")),
            "remarks": _stringify_cell(rec.get("remarks")),
        }
        preview_data = {k: _stringify_cell(v) for k, v in rec.items()}
        missing = [BG_BULK_COLUMNS_MAP[k] for k in BG_BULK_REQUIRED if not cleaned.get(k)]
        if missing:
            errors.append({"row": r_i, "reason": f"Missing required: {', '.join(missing)}",
                           "data": preview_data}); continue
        if not cleaned["date_of_issuance"]:
            errors.append({"row": r_i, "reason": "Invalid Date of Issuance (use YYYY-MM-DD or DD/MM/YYYY)",
                           "data": preview_data}); continue
        if not cleaned["valid_till"]:
            errors.append({"row": r_i, "reason": "Invalid Valid Till (use YYYY-MM-DD or DD/MM/YYYY)",
                           "data": preview_data}); continue
        if not cleaned["bg_claim_expiry_date"]:
            errors.append({"row": r_i, "reason": "Invalid BG Claim Expiry Date (use YYYY-MM-DD or DD/MM/YYYY)",
                           "data": preview_data}); continue
        if cleaned["date_of_issuance"] > cleaned["bg_claim_expiry_date"]:
            errors.append({"row": r_i, "reason": "BG Claim Expiry must be after Date of Issuance",
                           "data": preview_data}); continue
        if cleaned["date_of_issuance"] > cleaned["valid_till"]:
            errors.append({"row": r_i, "reason": "Valid Till must be after Date of Issuance",
                           "data": preview_data}); continue
        if cleaned["amount"] is None or cleaned["amount"] <= 0:
            errors.append({"row": r_i, "reason": "Amount must be a positive number",
                           "data": preview_data}); continue
        # Center name → id resolution (optional field)
        cleaned["center_id"] = None
        if cleaned["center_name"]:
            cid = center_map.get(cleaned["center_name"].lower())
            if not cid:
                errors.append({"row": r_i, "reason": f"Center not found: '{cleaned['center_name']}' (check spelling)",
                               "data": preview_data}); continue
            cleaned["center_id"] = cid
        bg_key = cleaned["bg_number"].lower()
        if bg_key in seen_in_file:
            errors.append({"row": r_i, "reason": f"Duplicate BG Number in this file: {cleaned['bg_number']}",
                           "data": preview_data}); continue
        if bg_key in db_bg_numbers:
            errors.append({"row": r_i, "reason": f"BG Number already exists in system: {cleaned['bg_number']}",
                           "data": preview_data}); continue
        seen_in_file.add(bg_key)
        valid_rows.append({"row": r_i, "data": cleaned})
    return {"valid_rows": valid_rows, "errors": errors}


@api.get("/bank-guarantees/sample-excel")
async def bg_sample_excel(_=Depends(require_role(*BG_WRITE_ROLES))):
    """Download the BG bulk-upload template (headers + one example row)."""
    wb = Workbook()
    ws = wb.active
    ws.title = "BG-Bulk-Upload"
    header_font = Font(bold=True, color="FFFFFF")
    header_fill = PatternFill(start_color="1E4EAB", end_color="1E4EAB", fill_type="solid")
    for idx, (_key, header) in enumerate(BG_BULK_COLUMNS, start=1):
        c = ws.cell(row=1, column=idx, value=header)
        c.font = header_font; c.fill = header_fill
        c.alignment = Alignment(horizontal="center", vertical="center")
        ws.column_dimensions[c.column_letter].width = max(18, len(header) + 4)
    sample = [
        "Birsa 25-26",                                # FY
        "LOI001722/26/02/2026",                       # LoI
        "W002476/02/03/2026",                         # Work Order
        "Jharkhand Skill Development Mission",        # In Favour Of
        "Valeur Fabtex Pvt Ltd",                      # Applicant
        "ICICI Bank",                                 # Issued By
        "1353NDLG00068126",                           # BG Number
        174636,                                       # Amount
        "2026-03-07",                                 # Date of Issuance
        "2028-03-08",                                 # Valid Till
        "2028-03-08",                                 # Claim Expiry
        "Birsa Palojori",                             # Center (name — resolved to id)
        "Deoghar",                                    # Location
        "3% performance BG",                          # Remarks
    ]
    for i, v in enumerate(sample, start=1):
        ws.cell(row=2, column=i, value=v)
    ws.freeze_panes = "A2"
    buf = BytesIO(); wb.save(buf); buf.seek(0)
    return Response(
        content=buf.read(),
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": 'attachment; filename="bank_guarantee_bulk_upload_template.xlsx"'},
    )


async def _bg_read_uploaded_workbook(file: UploadFile) -> tuple:
    data_bytes = await file.read()
    if len(data_bytes) > 20 * 1024 * 1024:
        raise HTTPException(413, "File too large (max 20MB)")
    try:
        wb = load_workbook(BytesIO(data_bytes), data_only=True, read_only=True)
    except Exception as e:
        raise HTTPException(400, f"Invalid Excel file: {e}")
    ws = wb.active
    rows_iter = ws.iter_rows(values_only=True)
    try:
        header_row = next(rows_iter)
    except StopIteration:
        raise HTTPException(400, "Excel is empty")
    headers = [(_stringify_cell(h) if h is not None else "") for h in header_row]
    required_headers = {BG_BULK_COLUMNS_MAP[k] for k in BG_BULK_REQUIRED}
    missing = [h for h in required_headers if h not in headers]
    if missing:
        raise HTTPException(400, f"Missing required columns: {', '.join(sorted(missing))}")
    header_index = {h: i for i, h in enumerate(headers)}
    return list(rows_iter), header_index


@api.post("/bank-guarantees/bulk-preview")
async def bg_bulk_preview(
    file: UploadFile = File(...),
    _=Depends(require_role(*BG_WRITE_ROLES)),
):
    """Validate WITHOUT persisting. Returns per-row errors + parsed valid rows
    so the UI can render a preview table before the actual upload."""
    rows, header_index = await _bg_read_uploaded_workbook(file)
    result = await _bg_validate_bulk_rows(iter(rows), header_index)
    return {
        "total_rows": len(result["valid_rows"]) + len(result["errors"]),
        "valid": len(result["valid_rows"]),
        "failed": len(result["errors"]),
        "valid_rows": result["valid_rows"],
        "errors": result["errors"],
    }


@api.post("/bank-guarantees/bulk-upload")
async def bg_bulk_upload(
    file: UploadFile = File(...),
    user=Depends(require_role(*BG_WRITE_ROLES)),
):
    """Re-validate and INSERT valid rows. The BG numbers seen in-file plus in-DB
    at preview time are re-checked here to avoid TOCTOU duplicates."""
    rows, header_index = await _bg_read_uploaded_workbook(file)
    result = await _bg_validate_bulk_rows(iter(rows), header_index)
    now = datetime.now(timezone.utc).isoformat()
    to_insert: list = []
    inserted: list = []
    for vr in result["valid_rows"]:
        d = vr["data"]
        doc = {
            "id": str(uuid.uuid4()),
            "fy": d.get("fy") or None,
            "letter_of_intent_no": d.get("letter_of_intent_no") or None,
            "work_order_no": d.get("work_order_no") or None,
            "in_favour_of": d.get("in_favour_of") or None,
            "applicant": d.get("applicant") or None,
            "issued_by": d.get("issued_by") or "",
            "bg_number": d.get("bg_number") or "",
            "amount": float(d.get("amount") or 0),
            "date_of_issuance": d.get("date_of_issuance"),
            "valid_till": d.get("valid_till"),
            "bg_claim_expiry_date": d.get("bg_claim_expiry_date"),
            "center_id": d.get("center_id"),
            "location": d.get("location") or None,
            "remarks": d.get("remarks") or None,
            "attachment": None,
            "is_renewed": False,
            "is_deleted": False,
            "renews_bg_id": None,
            "renews_bg_number": None,
            "created_by": user["id"],
            "created_at": now,
            "updated_at": now,
        }
        to_insert.append(doc)
        inserted.append({"row": vr["row"], "bg_number": doc["bg_number"], "id": doc["id"]})
    if to_insert:
        await db.bank_guarantees.insert_many(to_insert)
    return {
        "total_rows": len(to_insert) + len(result["errors"]),
        "uploaded": len(to_insert),
        "failed": len(result["errors"]),
        "inserted": inserted,
        "errors": result["errors"],
    }




@api.get("/bank-guarantees")
async def list_bank_guarantees(
    search: Optional[str] = Query(None),
    center_id: Optional[str] = Query(None),
    include_deleted: bool = Query(False),
    include_renewed: bool = Query(True),
    _=Depends(require_role(*BG_ROLES)),
):
    q: dict = {}
    if not include_deleted:
        q["is_deleted"] = {"$ne": True}
    if not include_renewed:
        q["is_renewed"] = {"$ne": True}
    if center_id:
        q["center_id"] = center_id
    if search:
        s = search.strip()
        q["$or"] = [
            {"bg_number": {"$regex": s, "$options": "i"}},
            {"letter_of_intent_no": {"$regex": s, "$options": "i"}},
            {"work_order_no": {"$regex": s, "$options": "i"}},
            {"in_favour_of": {"$regex": s, "$options": "i"}},
            {"applicant": {"$regex": s, "$options": "i"}},
            {"issued_by": {"$regex": s, "$options": "i"}},
            {"location": {"$regex": s, "$options": "i"}},
            {"fy": {"$regex": s, "$options": "i"}},
        ]
    docs = await db.bank_guarantees.find(q, {"_id": 0}).sort("bg_claim_expiry_date", 1).to_list(1000)
    return docs


@api.get("/bank-guarantees/expiring-soon")
async def bg_expiring_soon(
    days: int = Query(30, ge=1, le=365),
    user=Depends(require_role(*BG_ROLES)),
):
    """Return BGs whose bg_claim_expiry_date falls within [today, today+days] and are
    not yet marked renewed. Used by the Dashboard alert popup.
    Center-scoped: admin/hr/manager/senior_manager/accountant see all BGs;
    partner/center_manager/center_staff only see BGs of their own centers."""
    from datetime import date as _date, timedelta as _td
    today = _date.today().isoformat()
    horizon = (_date.today() + _td(days=days)).isoformat()

    # Determine center scope. Admins + accounts get everything (line-item and
    # even BGs that aren't attached to a center are visible to them).
    await _enrich_user_with_associations(user)
    role = user.get("role")
    all_visible = role in ("admin", "hr", "manager", "senior_manager", "accountant")
    scope_center_ids = None
    if not all_visible:
        if role in ("center_manager", "center_staff"):
            scope_center_ids = list(user.get("assigned_center_ids") or [])
        elif role == "partner":
            scope_center_ids = list(user.get("_associated_center_ids") or [])
        else:
            scope_center_ids = []
        if not scope_center_ids:
            return {"expiring": [], "expired": [], "days": days, "today": today}

    q_base = {"is_deleted": {"$ne": True}, "is_renewed": {"$ne": True}}
    if not all_visible:
        q_base["center_id"] = {"$in": scope_center_ids}
    q = {**q_base, "bg_claim_expiry_date": {"$gte": today, "$lte": horizon}}
    docs = await db.bank_guarantees.find(q, {"_id": 0}).sort("bg_claim_expiry_date", 1).to_list(200)
    q_exp = {**q_base, "bg_claim_expiry_date": {"$lt": today}}
    expired = await db.bank_guarantees.find(q_exp, {"_id": 0}).sort("bg_claim_expiry_date", 1).to_list(200)
    return {"expiring": docs, "expired": expired, "days": days, "today": today}


@api.patch("/bank-guarantees/{bid}")
async def update_bank_guarantee(
    bid: str, payload: dict = Body(...),
    _=Depends(require_role(*BG_WRITE_ROLES)),
):
    existing = await db.bank_guarantees.find_one({"id": bid}, {"_id": 0})
    if not existing:
        raise HTTPException(404, "Bank guarantee not found")
    allowed = {"letter_of_intent_no", "work_order_no", "in_favour_of", "applicant", "issued_by",
               "bg_number", "amount", "date_of_issuance", "valid_till", "bg_claim_expiry_date",
               "center_id", "location", "remarks", "is_renewed", "fy"}
    upd = {k: v for k, v in payload.items() if k in allowed}
    if not upd:
        raise HTTPException(400, "No updatable fields provided")
    upd["updated_at"] = datetime.now(timezone.utc).isoformat()
    await db.bank_guarantees.update_one({"id": bid}, {"$set": upd})
    doc = await db.bank_guarantees.find_one({"id": bid}, {"_id": 0})
    return doc


@api.patch("/bank-guarantees/{bid}/renew")
async def renew_bank_guarantee(bid: str, _=Depends(require_role(*BG_WRITE_ROLES))):
    """Mark a bank guarantee as renewed — silences the dashboard expiry popup."""
    r = await db.bank_guarantees.update_one(
        {"id": bid, "is_deleted": {"$ne": True}},
        {"$set": {"is_renewed": True, "renewed_at": datetime.now(timezone.utc).isoformat()}},
    )
    if r.matched_count == 0:
        raise HTTPException(404, "Bank guarantee not found")
    return {"ok": True}


@api.delete("/bank-guarantees/{bid}", status_code=204)
async def delete_bank_guarantee(bid: str, user=Depends(require_role("admin", "hr"))):
    r = await db.bank_guarantees.update_one(
        {"id": bid, "is_deleted": {"$ne": True}},
        {"$set": {"is_deleted": True, "deleted_at": datetime.now(timezone.utc).isoformat(), "deleted_by": user["id"]}},
    )
    if r.matched_count == 0:
        raise HTTPException(404, "Bank guarantee not found")
    return None


@api.get("/bank-guarantees/{bid}/chain")
async def bg_renewal_chain(bid: str, _=Depends(require_role(*BG_ROLES))):
    """Walk backwards + forwards along `renews_bg_id`/`renewed_by_bg_id` links so
    HR can see the full audit history of renewals for a given BG."""
    seed = await db.bank_guarantees.find_one({"id": bid}, {"_id": 0})
    if not seed:
        raise HTTPException(404, "BG not found")
    chain = [seed]
    # Walk backwards through previous BGs this one renewed.
    cur = seed
    seen = {seed["id"]}
    while cur.get("renews_bg_id") and cur["renews_bg_id"] not in seen:
        prev = await db.bank_guarantees.find_one({"id": cur["renews_bg_id"]}, {"_id": 0})
        if not prev: break
        seen.add(prev["id"]); chain.insert(0, prev); cur = prev
    # Walk forwards through successors.
    cur = seed
    while cur.get("renewed_by_bg_id") and cur["renewed_by_bg_id"] not in seen:
        nxt = await db.bank_guarantees.find_one({"id": cur["renewed_by_bg_id"]}, {"_id": 0})
        if not nxt: break
        seen.add(nxt["id"]); chain.append(nxt); cur = nxt
    return {"count": len(chain), "chain": chain}


@api.post("/bank-guarantees/run-alerts")
async def bg_run_alerts(
    force: bool = Query(False, description="Send even if already sent today (idempotency bypass)"),
    _=Depends(require_role("admin")),
):
    """Send BG expiry email alerts for BGs at Day-30 / Day-15 / Day-7 / Day-0
    (and every day past due). Idempotent per (bg_id, day, date). Also called by
    the daily scheduler below."""
    return await _bg_dispatch_alerts(force=force)


async def _bg_alert_scheduler():
    """Runs forever — every 6 hours checks if 'today' hasn't already fired the
    BG expiry emails, and if not, sends them once. Idempotency comes from the
    `bg_alert_log` markers written by `_bg_dispatch_alerts`."""
    await asyncio.sleep(60)  # small warmup after boot
    while True:
        try:
            await _bg_dispatch_alerts(force=False)
        except Exception as e:  # noqa: BLE001
            logger.warning("BG alert scheduler tick failed: %s", e)
        await asyncio.sleep(6 * 3600)


async def _bg_dispatch_alerts(force: bool = False) -> dict:
    """Internal helper used by both the manual endpoint + daily scheduler."""
    from datetime import date as _date, timedelta as _td
    from email_utils import send_bg_expiry_alert  # local import — module already loaded elsewhere

    today = _date.today()
    tstr = today.isoformat()
    # Windows: Day-30, Day-15, Day-7, Day-0. Also always ping "expired" (past due) daily.
    milestone_days = [30, 15, 7, 0]
    q = {"is_deleted": {"$ne": True}, "is_renewed": {"$ne": True}}
    live = await db.bank_guarantees.find(q, {"_id": 0}).to_list(2000)
    # Filter to BGs whose bg_claim_expiry_date is either a milestone match or already past due.
    triggered: list = []
    days_left_map: dict = {}
    for bg in live:
        exp = bg.get("bg_claim_expiry_date")
        if not exp: continue
        try:
            expd = _date.fromisoformat(exp[:10])
        except Exception:
            continue
        delta = (expd - today).days
        if delta in milestone_days or delta < 0:
            triggered.append(bg); days_left_map[bg["id"]] = delta
    if not triggered:
        return {"sent": 0, "reason": "no_triggered_bgs", "today": tstr}
    # Idempotency — record (day-marker, bg_id) so we don't repeatedly ping the
    # same milestone in the same day. `force=True` bypasses this guard.
    dispatch_log_ids = []
    to_send_bgs = []
    for bg in triggered:
        d = days_left_map[bg["id"]]
        marker = f"{tstr}:{bg['id']}:{d}"
        if not force:
            existing = await db.bg_alert_log.find_one({"marker": marker}, {"_id": 0, "marker": 1})
            if existing: continue
        to_send_bgs.append(bg); dispatch_log_ids.append(marker)
    if not to_send_bgs:
        return {"sent": 0, "reason": "already_sent_today", "today": tstr, "triggered": len(triggered)}

    # ---------- Recipient resolution (center-scoped) ----------
    # Broadcast to every active admin + accountant globally.
    global_users = await db.users.find(
        {"role": {"$in": ["admin", "accountant"]}, "is_active": {"$ne": False},
         "email": {"$exists": True, "$ne": None}},
        {"_id": 0, "email": 1, "id": 1, "assigned_center_ids": 1, "role": 1, "mobile": 1, "name": 1},
    ).to_list(500)
    # For each unique center in triggered BGs, resolve center-linked users (partner
    # + accountant + center_manager assigned to that center).
    triggered_centers = {b.get("center_id") for b in to_send_bgs if b.get("center_id")}
    center_users_map: dict = {}  # center_id -> list of user rows
    for cid in triggered_centers:
        # (a) center-assigned users (center_manager, center_staff, accountant, partner
        # sometimes uses assigned_center_ids too)
        assigned = await db.users.find(
            {"assigned_center_ids": cid, "is_active": {"$ne": False},
             "email": {"$exists": True, "$ne": None}},
            {"_id": 0, "email": 1, "id": 1, "role": 1, "assigned_partner_id": 1, "mobile": 1, "name": 1},
        ).to_list(200)
        # (b) partners associated with the center via batches / transactions.
        center_partner_ids: set = set()
        async for _b in db.batches.find({"center_id": cid, "partner_ids": {"$exists": True, "$ne": []}},
                                        {"_id": 0, "partner_ids": 1}):
            for pid in (_b.get("partner_ids") or []):
                if pid: center_partner_ids.add(pid)
        if center_partner_ids:
            partner_users = await db.users.find(
                {"assigned_partner_id": {"$in": list(center_partner_ids)},
                 "role": "partner", "is_active": {"$ne": False},
                 "email": {"$exists": True, "$ne": None}},
                {"_id": 0, "email": 1, "id": 1, "role": 1, "mobile": 1, "name": 1},
            ).to_list(200)
            assigned.extend(partner_users)
        center_users_map[cid] = assigned

    # Filter out obvious test / seed / disposable emails.
    _bad = ("example.com", "example.org", "testfin.dev", "testfin.local",
            "test.local", "@x.com", "finance.app")
    def _clean_email(e: str) -> Optional[str]:
        e = (e or "").strip().lower()
        if not e or "@" not in e: return None
        if any(bad in e for bad in _bad): return None
        return e

    # Build recipient_email -> [bgs] map so each recipient gets one email with
    # only the BGs they're allowed to see.
    per_recipient: dict = {}
    for bg in to_send_bgs:
        recipients_for_bg: set = set()
        # Global admins + accountants get every triggered BG.
        for u in global_users:
            ce = _clean_email(u.get("email"))
            if ce: recipients_for_bg.add(ce)
        # Center-scoped users (partner / accountant / center_manager linked to
        # bg.center_id) get only this BG.
        cid = bg.get("center_id")
        if cid and cid in center_users_map:
            for u in center_users_map[cid]:
                ce = _clean_email(u.get("email"))
                if ce: recipients_for_bg.add(ce)
        for rcpt in recipients_for_bg:
            per_recipient.setdefault(rcpt, []).append(bg)

    if not per_recipient:
        return {"sent": 0, "reason": "no_valid_recipients", "today": tstr,
                "triggered": len(to_send_bgs)}

    portal_url = os.environ.get("CHECK_IN_URL") or os.environ.get("APP_URL") or "https://finance.masharaskills.com"
    portal_url = portal_url.rstrip("/")
    if portal_url.endswith("/check-in"):
        portal_url = portal_url[:-len("/check-in")]

    sends_ok = 0
    email_results = []
    for rcpt, bgs_for_user in per_recipient.items():
        r = await send_bg_expiry_alert([rcpt], bgs_for_user, days_left_map, portal_url)
        email_results.append({"to": rcpt, "count": len(bgs_for_user), "sent": r.get("sent"), "id": r.get("id"), "reason": r.get("reason")})
        if r.get("sent"): sends_ok += 1

    # ---------- Twilio fan-out (WhatsApp + SMS) ----------
    # Same recipient resolution reused: for every user we already collected (both
    # global admins/accountants and center-scoped users), send a Twilio message
    # if they have a `mobile` on file. WhatsApp attempted first; SMS is the
    # fallback so we always try to reach the person somehow.
    twilio_results: list = []
    if twilio_service.is_configured():
        # Build user_id -> {mobile, name, bgs[]} taking the union of global +
        # center-scoped users so we don't double-notify the same person.
        by_user: dict = {}
        for u in global_users:
            if not u.get("mobile"): continue
            by_user.setdefault(u["id"], {"mobile": u["mobile"], "name": u.get("name") or u.get("email"),
                                          "bgs": list(to_send_bgs)})
        for bg in to_send_bgs:
            cid = bg.get("center_id")
            for u in center_users_map.get(cid, []) if cid else []:
                if not u.get("mobile"): continue
                rec = by_user.setdefault(u["id"], {"mobile": u["mobile"], "name": u.get("name") or u.get("email"),
                                                    "bgs": []})
                if bg not in rec["bgs"]:
                    rec["bgs"].append(bg)

        for uid, ctx in by_user.items():
            # Compose one compact message per recipient — top 3 BGs so SMS stays
            # under the 160-char GSM-7 limit; email already carries the full detail.
            bgs = ctx["bgs"][:3]
            lines: list = []
            for bg in bgs:
                d = days_left_map.get(bg["id"])
                lbl = "EXPIRED" if (d is not None and d < 0) else f"in {d} days"
                lines.append(f"BG {bg.get('bg_number') or bg.get('id','?')[:8]} {lbl} ({bg.get('bg_claim_expiry_date','')[:10]})")
            more = len(ctx["bgs"]) - len(bgs)
            body = "🏦 Bank Guarantee Alert\n" + "\n".join(lines)
            if more > 0:
                body += f"\n(+{more} more)"
            body += f"\n{portal_url}/bank-guarantees"

            # WhatsApp first (richer channel — supports emoji + line breaks).
            wr = await twilio_service.send_message(
                db, channel="whatsapp", to=ctx["mobile"], body=body,
                event_type="bg_expiry", event_id=f"{tstr}:{uid}",
                sent_by_name="System (BG scheduler)",
            )
            # SMS fallback (shorter, GSM-7 safe subset).
            sr = await twilio_service.send_message(
                db, channel="sms", to=ctx["mobile"],
                body=body.replace("🏦 ", "").replace("\n", " | ")[:300],
                event_type="bg_expiry", event_id=f"{tstr}:{uid}:sms",
                sent_by_name="System (BG scheduler)",
            )
            twilio_results.append({
                "user_id": uid, "mobile": ctx["mobile"], "name": ctx["name"],
                "bgs": len(ctx["bgs"]),
                "whatsapp_ok": wr.get("ok"), "whatsapp_sid": wr.get("message_sid"),
                "whatsapp_error": wr.get("error"),
                "sms_ok": sr.get("ok"), "sms_sid": sr.get("message_sid"),
                "sms_error": sr.get("error"),
            })

    if sends_ok or any(r.get("whatsapp_ok") or r.get("sms_ok") for r in twilio_results):
        # Record markers to prevent re-sends today.
        for m in dispatch_log_ids:
            await db.bg_alert_log.insert_one({"marker": m, "sent_at": datetime.now(timezone.utc).isoformat()})
    return {
        "sent": sends_ok,
        "recipients": list(per_recipient.keys()),
        "email_results": email_results,
        "twilio_results": twilio_results,
        "twilio_sent_count": sum(1 for r in twilio_results if r.get("whatsapp_ok") or r.get("sms_ok")),
        "triggered_bgs": [{"id": b["id"], "bg_number": b.get("bg_number"),
                          "days_left": days_left_map[b["id"]], "center_id": b.get("center_id")}
                         for b in to_send_bgs],
        "today": tstr,
    }


async def _trial_dispatch_reminders(force: bool = False) -> dict:
    """Send WhatsApp/SMS + email reminders to companies whose 10-day free trial
    ends within the next 3 days (last 3 days of the trial). Idempotent per
    (company, days_left, date) via `trial_reminder_log`."""
    from datetime import timedelta as _td
    import math as _math
    from email_utils import send_trial_expiry_reminder

    now = datetime.now(timezone.utc)
    tstr = now.date().isoformat()
    horizon = (now + _td(days=3)).isoformat()
    trials = await db.company_trials.find(
        {"ends_at": {"$gt": now.isoformat(), "$lte": horizon}}, {"_id": 0},
    ).to_list(5000)
    if not trials:
        return {"sent": 0, "reason": "no_trials_in_window", "today": tstr}

    portal_url = (os.environ.get("CHECK_IN_URL") or os.environ.get("APP_URL") or "https://finance.masharaskills.com").rstrip("/")
    if portal_url.endswith("/check-in"):
        portal_url = portal_url[:-len("/check-in")]

    _bad = ("example.com", "example.org", "testfin.dev", "testfin.local",
            "test.local", "@x.com", "finance.app")
    def _clean_email(e: str) -> Optional[str]:
        e = (e or "").strip().lower()
        if not e or "@" not in e:
            return None
        if any(bad in e for bad in _bad):
            return None
        return e

    uproj = {"_id": 0, "id": 1, "email": 1, "mobile": 1, "name": 1, "role": 1}
    results: list = []
    total_sent = 0
    for tr in trials:
        cid = tr.get("company_id")
        if not cid:
            continue
        ends = datetime.fromisoformat(tr["ends_at"])
        days_left = max(1, _math.ceil((ends - now).total_seconds() / 86400))
        if days_left > 3:
            continue
        marker = f"{tstr}:{cid}:{days_left}"
        if not force and await db.trial_reminder_log.find_one({"marker": marker}, {"_id": 0, "marker": 1}):
            continue

        # Recipients = decision-makers of the company + whoever started the trial.
        # (Trial/subscription reminders shouldn't spam every staff member.)
        decision_roles = {"admin", "company_admin", "owner", "accountant",
                          "manager", "senior_manager", "partner", "reporting_authority"}
        uids: set = set()
        recip: list = []
        async for u in db.users.find(
            {"company_id": cid, "is_active": {"$ne": False}, "role": {"$in": list(decision_roles)}}, uproj,
        ):
            if u["id"] not in uids:
                uids.add(u["id"]); recip.append(u)
        # Company members (multi-company) with a decision role for THIS company.
        member_ids = [m["user_id"] async for m in db.user_companies.find(
            {"company_id": cid, "status": "active", "role": {"$in": list(decision_roles)}},
            {"_id": 0, "user_id": 1})]
        # Always include the person who started the trial.
        if tr.get("started_by"):
            member_ids.append(tr["started_by"])
        extra = [i for i in set(member_ids) if i not in uids]
        if extra:
            async for u in db.users.find({"id": {"$in": extra}, "is_active": {"$ne": False}}, uproj):
                if u["id"] not in uids:
                    uids.add(u["id"]); recip.append(u)

        company = await db.companies.find_one({"id": cid}, {"_id": 0, "name": 1})
        cname = (company or {}).get("name") or "your company"

        emails = list({e for e in (_clean_email(u.get("email")) for u in recip) if e})
        email_r = {"sent": False, "reason": "no_recipients"}
        if emails:
            # Resend caps `to` at 50 recipients — send in chunks.
            _ok = True
            _last_reason = None
            for i in range(0, len(emails), 50):
                chunk = emails[i:i + 50]
                r = await send_trial_expiry_reminder(chunk, cname, days_left, tr["ends_at"], portal_url)
                if not r.get("sent"):
                    _ok = False; _last_reason = r.get("reason")
            email_r = {"sent": _ok, "reason": _last_reason, "recipient_count": len(emails)}

        twilio_r: list = []
        if twilio_service.is_configured():
            body = (f"\u23f3 Mashara Finance: {cname} ka free trial {days_left} din me khatam ho raha hai "
                    f"({tr['ends_at'][:10]}). Access banaye rakhne ke liye subscribe karein: {portal_url}/subscription")
            seen_m: set = set()
            for u in recip:
                mob = u.get("mobile")
                if not mob or mob in seen_m:
                    continue
                seen_m.add(mob)
                wr = await twilio_service.send_message(
                    db, channel="whatsapp", to=mob, body=body,
                    event_type="trial_expiry", event_id=f"{tstr}:{u['id']}:{days_left}",
                    sent_by_name="System (Trial scheduler)")
                sr = await twilio_service.send_message(
                    db, channel="sms", to=mob, body=body.replace("\u23f3 ", "")[:300],
                    event_type="trial_expiry", event_id=f"{tstr}:{u['id']}:{days_left}:sms",
                    sent_by_name="System (Trial scheduler)")
                twilio_r.append({"user_id": u["id"], "mobile": mob,
                                 "whatsapp_ok": wr.get("ok"), "whatsapp_error": wr.get("error"),
                                 "sms_ok": sr.get("ok"), "sms_error": sr.get("error")})

        sent_any = bool(email_r.get("sent")) or any(r.get("whatsapp_ok") or r.get("sms_ok") for r in twilio_r)
        if sent_any and not force:
            await db.trial_reminder_log.insert_one({"marker": marker, "sent_at": now.isoformat()})
        if sent_any:
            total_sent += 1
        results.append({"company_id": cid, "company_name": cname, "days_left": days_left,
                        "email_recipients": emails, "email_sent": email_r.get("sent"),
                        "email_reason": email_r.get("reason"),
                        "twilio_sent": sum(1 for r in twilio_r if r.get("whatsapp_ok") or r.get("sms_ok")),
                        "twilio": twilio_r})
    return {"sent": total_sent, "today": tstr, "trials_in_window": len(trials), "results": results}


async def _trial_reminder_scheduler():
    """Runs forever — every 6h dispatches trial-expiry reminders (idempotent)."""
    await asyncio.sleep(90)  # warmup after boot
    while True:
        try:
            await _trial_dispatch_reminders(force=False)
        except Exception as e:  # noqa: BLE001
            logger.warning("Trial reminder scheduler tick failed: %s", e)
        await asyncio.sleep(6 * 3600)




# ============================================================================
# ============  JHARKHAND SKILLS  MIS  DASHBOARD  ============================
# ============================================================================
# Isolated module — new collections + endpoints, no interference with finance /
# HR / attendance / candidates / BG / etc. Prefix: /api/mis/*
#
# Collections & indexes (created lazily on startup):
#   mis_sip_centers      — SIP / Center Status (14 fields from Excel)
#   mis_project_summary  — Project Wise Summary (batch-level rows, 38 fields)
#   mis_jsdms            — JSDMS Project Summary (20 fields)
#   mis_mobilization     — Daily Mobilization Report (multi-location per row)
#
# RBAC mapping (per user request — reuse existing roles):
#   admin           -> Super Admin  (full read + write everywhere)
#   senior_manager  -> State Head   (full read; write allowed)
#   manager         -> Project Manager (full read; write allowed)
#   hr / accountant -> read + write
#   center_manager  -> read only (scoped to their assigned centers ideally)
#   staff           -> Mobilizer (read own + create mobilization reports)
#   partner         -> read only (no write)
# ============================================================================

MIS_READ_ROLES = ("admin", "hr", "manager", "senior_manager", "accountant",
                  "center_manager", "partner", "staff", "center_staff")
MIS_WRITE_ROLES = ("admin", "hr", "manager", "senior_manager", "accountant")


async def _ensure_mis_indexes():
    """Idempotent — create indexes for MIS collections on startup."""
    try:
        await db.mis_sip_centers.create_index("center_id_code", unique=False)
        await db.mis_sip_centers.create_index([("state", 1), ("status", 1)])
        await db.mis_sip_centers.create_index([("bg_validity_date", 1)])
        await db.mis_project_summary.create_index([("project", 1), ("center_name", 1)])
        await db.mis_project_summary.create_index([("batch_id", 1)])
        await db.mis_project_summary.create_index([("target_year", 1), ("status", 1)])
        await db.mis_jsdms.create_index([("center_name", 1), ("job_role", 1)])
        await db.mis_mobilization.create_index([("branch", 1), ("report_date", -1)])
        await db.mis_mobilization.create_index([("mobilizer_emp_id", 1), ("report_date", -1)])
        log.info("MIS indexes ensured")
    except Exception as e:  # noqa: BLE001
        log.warning("MIS index setup failed: %s", e)


# ---------- Helpers ----------
def _mis_norm(v) -> str:
    if v is None: return ""
    if isinstance(v, datetime): return v.date().isoformat()
    if hasattr(v, "isoformat"):
        try: return v.isoformat()
        except Exception: pass
    return str(v).strip()


def _mis_num(v) -> Optional[float]:
    if v is None or v == "": return None
    if isinstance(v, (int, float)): return float(v)
    try:
        s = str(v).strip().replace(",", "").replace("%", "")
        return float(s) if s else None
    except Exception:
        return None


def _mis_int(v) -> Optional[int]:
    n = _mis_num(v)
    return int(n) if n is not None else None


# ---------- SIP / Center Status ----------
SIP_FIELDS_MAP = [
    ("serial_no", "S.No."),
    ("center_name", "Center Name"),
    ("center_id_code", "Center ID"),
    ("state", "State"),
    ("accreditation_date", "Accreditation Date"),
    ("status", "Status"),
    ("last_inspection_date", "Last Inspection Date"),
    ("center_rating", "Center Rating"),
    ("work_order_value", "Value of Work Order"),
    ("bg_submitted_amount", "BG Submitted Total Amount"),
    ("bg_validity_date", "BG Validity"),
    ("branch_start_date", "Date of Branch Start"),
    ("job_role_on_caaf", "Job Role on CAAF"),
    ("job_role_to_be_added", "Job Role to be added"),
]


def _sip_from_payload(p: dict) -> dict:
    """Normalise a SIP row (from Excel or JSON) into our stored shape."""
    return {
        "serial_no": _mis_int(p.get("serial_no")),
        "center_name": _mis_norm(p.get("center_name")),
        "center_id_code": _mis_norm(p.get("center_id_code")).upper(),
        "state": _mis_norm(p.get("state")),
        "accreditation_date": _parse_excel_date(p.get("accreditation_date")),
        "status": _mis_norm(p.get("status")),
        "last_inspection_date": _parse_excel_date(p.get("last_inspection_date")),
        "center_rating": _mis_norm(p.get("center_rating")),
        "work_order_value": _mis_num(p.get("work_order_value")),
        "bg_submitted_amount": _mis_num(p.get("bg_submitted_amount")),
        "bg_validity_date": _parse_excel_date(p.get("bg_validity_date")),
        "branch_start_date": _parse_excel_date(p.get("branch_start_date")),
        "job_role_on_caaf": _mis_norm(p.get("job_role_on_caaf")),
        "job_role_to_be_added": _mis_norm(p.get("job_role_to_be_added")),
    }


@api.post("/mis/sip-centers", status_code=201)
async def mis_sip_create(payload: dict = Body(...), user=Depends(require_role(*MIS_WRITE_ROLES))):
    data = _sip_from_payload(payload)
    if not data["center_name"]:
        raise HTTPException(400, "Center Name is required")
    if not data["center_id_code"]:
        raise HTTPException(400, "Center ID is required")
    # Duplicate check on Center ID (case-insensitive)
    dup = await db.mis_sip_centers.find_one({"center_id_code": data["center_id_code"], "is_deleted": {"$ne": True}}, {"_id": 0, "id": 1})
    if dup:
        raise HTTPException(409, f"Center ID '{data['center_id_code']}' already exists")
    now = datetime.now(timezone.utc).isoformat()
    doc = {"id": str(uuid.uuid4()), **data, "is_deleted": False,
           "created_by": user["id"], "created_at": now, "updated_at": now}
    await db.mis_sip_centers.insert_one(doc)
    doc.pop("_id", None)
    return doc


@api.get("/mis/sip-centers")
async def mis_sip_list(
    search: Optional[str] = Query(None),
    status: Optional[str] = Query(None),
    state: Optional[str] = Query(None),
    _=Depends(require_role(*MIS_READ_ROLES)),
):
    q: dict = {"is_deleted": {"$ne": True}}
    if status and status != "all": q["status"] = {"$regex": f"^{status}$", "$options": "i"}
    if state and state != "all": q["state"] = {"$regex": f"^{state}$", "$options": "i"}
    if search:
        s = search.strip()
        q["$or"] = [
            {"center_name": {"$regex": s, "$options": "i"}},
            {"center_id_code": {"$regex": s, "$options": "i"}},
            {"state": {"$regex": s, "$options": "i"}},
            {"job_role_on_caaf": {"$regex": s, "$options": "i"}},
        ]
    docs = await db.mis_sip_centers.find(q, {"_id": 0}).sort("center_name", 1).to_list(2000)
    return docs


@api.patch("/mis/sip-centers/{sid}")
async def mis_sip_update(sid: str, payload: dict = Body(...), _=Depends(require_role(*MIS_WRITE_ROLES))):
    existing = await db.mis_sip_centers.find_one({"id": sid, "is_deleted": {"$ne": True}}, {"_id": 0})
    if not existing:
        raise HTTPException(404, "SIP Center not found")
    upd = _sip_from_payload({**existing, **payload})
    upd["updated_at"] = datetime.now(timezone.utc).isoformat()
    await db.mis_sip_centers.update_one({"id": sid}, {"$set": upd})
    doc = await db.mis_sip_centers.find_one({"id": sid}, {"_id": 0})
    return doc


@api.delete("/mis/sip-centers/{sid}", status_code=204)
async def mis_sip_delete(sid: str, _=Depends(require_role("admin", "hr"))):
    r = await db.mis_sip_centers.update_one({"id": sid}, {"$set": {"is_deleted": True,
        "deleted_at": datetime.now(timezone.utc).isoformat()}})
    if r.matched_count == 0:
        raise HTTPException(404, "SIP Center not found")
    return Response(status_code=204)


