@app.on_event("startup")
async def _invoice_module_startup():
    try:
        await db.invoices.create_index("invoice_no", unique=True)
        await db.invoices.create_index([("tsp_company_id", 1), ("created_at", -1)])
        await db.invoices.create_index([("center_id", 1), ("created_at", -1)])
        await db.invoices.create_index([("project_id", 1), ("created_at", -1)])
        await db.invoices.create_index([("batch_id", 1)])
        await db.invoices.create_index([("batch_payment_id", 1)])
        await db.invoice_audit.create_index([("invoice_id", 1), ("timestamp", -1)])
        await db.finance_settings.update_one(
            {"id": "aging"},
            {"$setOnInsert": DEFAULT_AGING},
            upsert=True,
        )
    except Exception as _e:
        logging.exception("invoice module startup failed: %s", _e)


# ============================================================================
# Milestone (batch_payments) ↔ Invoice Tracking Integration
# When a milestone bill status is updated on the Finance (Milestones) page,
# an Invoice record is auto-created (if not present) and advanced through the
# same 5-stage lifecycle. When a milestone is marked "received" via the
# existing `receive_batch_payment` endpoint, the linked invoice is auto-
# advanced to Stage 5 (Disbursed).
# ============================================================================

async def _ensure_invoice_for_bp(bp: dict, user: dict) -> dict:
    """Return the linked invoice for a batch_payment. Creates one if missing."""
    if bp.get("invoice_id"):
        inv = await db.invoices.find_one({"id": bp["invoice_id"]})
        if inv:
            return inv
    # Derive master IDs from the parent batch.
    batch = await db.batches.find_one({"id": bp.get("batch_id")}) or {}
    company_id = bp.get("company_id") or batch.get("company_id")
    center_id = batch.get("center_id")
    project_id = batch.get("project_id")
    # Batch code/name — used for invoice_no & UI.
    batch_code = batch.get("code") or batch.get("name") or (bp.get("batch_id") or "")[:8]
    milestone = bp.get("milestone") or "M?"
    # Generate a deterministic invoice_no. Collision-safe via unique index.
    base_no = f"MS-{batch_code}-{milestone}".strip("-")
    invoice_no = base_no
    attempt = 1
    while await db.invoices.find_one({"invoice_no": invoice_no}):
        attempt += 1
        invoice_no = f"{base_no}-{attempt}"
    # Money: use batch_payment.amount as amount_payable. On receive, we update
    # deduction + net_payable + disbursed_amount from the persisted BP fields.
    amount = float(bp.get("amount") or 0)
    stages = _stages_bootstrap()
    generated_ts = bp.get("created_at") or _now_ist_iso()
    stages["generated"] = {
        "timestamp": generated_ts,
        "remarks": f"Auto-linked from Milestone {milestone}",
        "completed_by_id": user.get("id"),
        "completed_by_name": user.get("name") or user.get("email"),
        "completed": True,
    }
    doc = {
        "id": str(uuid.uuid4()),
        "invoice_no": invoice_no,
        "invoice_type": "Milestone",
        "milestone_type": milestone,
        "tsp_company_id": company_id,
        "center_id": center_id,
        "project_id": project_id,
        "batch_id": bp.get("batch_id"),
        "batch_payment_id": bp.get("id"),
        "total_candidates": batch.get("num_candidates") or batch.get("total_candidates") or 0,
        "amount_payable": amount,
        "adjustment": 0.0,
        "gross_payment": amount,
        "deduction": 0.0,
        "net_payable": amount,
        "disbursed_amount": 0.0,
        "remarks": bp.get("description"),
        "stages": stages,
        "created_at": _now_ist_iso(),
        "created_by": user.get("id"),
        "created_by_name": user.get("name") or user.get("email"),
        "source": "milestone",
    }
    await db.invoices.insert_one(doc)
    await db.batch_payments.update_one({"id": bp["id"]}, {"$set": {"invoice_id": doc["id"]}})
    await _write_invoice_audit(doc["id"], "auto_create", 0, 1, user,
                                 f"Auto-linked from Milestone {milestone} on batch {batch_code}")
    return doc


class BillStatusIn(BaseModel):
    to_stage: int
    remarks: Optional[str] = None


@api.get("/batch-payments/{pid}/bill-status")
async def get_bp_bill_status(pid: str, user=Depends(require_finance_visible)):
    bp = await db.batch_payments.find_one({"id": pid}, {"_id": 0})
    if not bp:
        raise HTTPException(404, "Milestone not found")
    inv_id = bp.get("invoice_id")
    if not inv_id:
        return {"linked": False, "invoice_id": None, "current_stage": 0}
    inv = await db.invoices.find_one({"id": inv_id}, {"_id": 0})
    if not inv:
        return {"linked": False, "invoice_id": None, "current_stage": 0}
    stages = inv.get("stages") or {}
    cs = _compute_current_stage(stages)
    info = INVOICE_STAGE_BY_CODE.get(cs) if cs else None
    return {
        "linked": True,
        "invoice_id": inv_id,
        "invoice_no": inv.get("invoice_no"),
        "current_stage": cs,
        "current_stage_id": info["id"] if info else None,
        "current_stage_label": info["label"] if info else None,
        "current_stage_timestamp": (stages.get(info["id"]) if info else {} or {}).get("timestamp") if info else None,
    }


@api.post("/batch-payments/{pid}/advance-bill-status")
async def advance_bp_bill_status(pid: str, body: BillStatusIn,
                                   user=Depends(require_role("admin", "accountant", "senior_manager", "manager", "hr"))):
    """Advance the linked invoice's bill-status stage from the Milestones page.

    * Auto-creates the linked invoice on first call if it doesn't exist yet.
    * Enforces strict sequence via the existing invoice-advance rules.
    * If the milestone has already been received in the finance ledger and the
      target stage is 5, uses the persisted net_amount as disbursed_amount.
    """
    bp = await db.batch_payments.find_one({"id": pid})
    if not bp:
        raise HTTPException(404, "Milestone not found")
    inv = await _ensure_invoice_for_bp(bp, user)
    stages = inv.get("stages") or _stages_bootstrap()
    current = _compute_current_stage(stages)
    to_stage = int(body.to_stage)
    if to_stage not in INVOICE_STAGE_BY_CODE:
        raise HTTPException(400, "Invalid stage")
    if to_stage <= current:
        raise HTTPException(400, f"Invoice is already at stage {current}. Cannot go back or repeat.")
    if to_stage != current + 1:
        raise HTTPException(400, f"Stages must be completed in sequence. Expected {current + 1}, got {to_stage}.")

    target = INVOICE_STAGE_BY_CODE[to_stage]
    ts = _now_ist_iso()
    stages[target["id"]] = {
        "timestamp": ts,
        "remarks": body.remarks,
        "completed_by_id": user.get("id"),
        "completed_by_name": user.get("name") or user.get("email"),
        "completed": True,
    }
    patch = {"stages": stages, "updated_at": ts}

    # If advancing to Disbursed, source the amount from the batch_payment.
    if to_stage == 5:
        # If already received in finance, use net_amount; else fall back to amount.
        if bp.get("status") == "received":
            disbursed = float(bp.get("net_amount") or bp.get("amount") or 0)
            deduction = float((bp.get("tds_amount") or 0)
                              + (bp.get("recovery_amount") or 0)
                              + (bp.get("assessment_fee_total") or 0))
            patch["deduction"] = deduction
            gross = float(bp.get("amount") or 0)
            patch["gross_payment"] = gross
            patch["net_payable"] = max(0.0, gross - deduction)
        else:
            disbursed = float(bp.get("amount") or 0)
        patch["disbursed_amount"] = disbursed
        patch["payment_date"] = bp.get("received_date") or ts
        patch["payment_remarks"] = body.remarks

    await db.invoices.update_one({"id": inv["id"]}, {"$set": patch})
    await _write_invoice_audit(inv["id"], "advance", current, to_stage, user,
                                 body.remarks or f"Advanced from Milestones page to {target['label']}")
    updated = await db.invoices.find_one({"id": inv["id"]}, {"_id": 0})
    return await _hydrate_invoice(updated)


async def _sync_invoice_on_receive(bp: dict, user: dict):
    """Called after receive_batch_payment successfully commits. Best-effort —
    never fails the receive flow if the invoice sync errors out."""
    try:
        inv = await _ensure_invoice_for_bp(bp, user)
        stages = inv.get("stages") or _stages_bootstrap()
        current = _compute_current_stage(stages)
        if current >= 5:
            return  # already disbursed
        ts = _now_ist_iso()
        # Auto-advance through any missing stages up to 5, stamping each with the
        # receive timestamp so the timeline stays continuous even if the user
        # never used the manual UI.
        for code in range(current + 1, 6):
            sid = INVOICE_STAGE_BY_CODE[code]["id"]
            stages[sid] = {
                "timestamp": ts,
                "remarks": ("Auto-advanced on milestone receive"
                             if code < 5 else "Milestone received — auto disbursed"),
                "completed_by_id": user.get("id"),
                "completed_by_name": user.get("name") or user.get("email"),
                "completed": True,
            }
        disbursed = float(bp.get("net_amount") or bp.get("amount") or 0)
        deduction = float((bp.get("tds_amount") or 0)
                          + (bp.get("recovery_amount") or 0)
                          + (bp.get("assessment_fee_total") or 0))
        gross = float(bp.get("amount") or 0)
        patch = {
            "stages": stages,
            "updated_at": ts,
            "disbursed_amount": disbursed,
            "gross_payment": gross,
            "deduction": deduction,
            "net_payable": max(0.0, gross - deduction),
            "payment_date": bp.get("received_date") or ts,
            "payment_remarks": "Auto-synced from milestone receive",
        }
        await db.invoices.update_one({"id": inv["id"]}, {"$set": patch})
        await _write_invoice_audit(inv["id"], "advance", current, 5, user,
                                     "Milestone marked received — invoice auto-disbursed")
    except Exception as _e:
        logging.exception("invoice sync on receive failed: %s", _e)


# ---------- Register router + CORS ----------

# ============================================================================
# PHASE 48 — Staff Wise Financial History / Employee Payment History
# Aggregates existing payroll, reimbursement, advance, and manual staff_payments
# collections into a single per-employee ledger view. Uses source_module + source_id
# to guarantee no duplicates — this is a read-only aggregator on top of existing
# data, PLUS one new collection (`staff_payments`) for manual "Other Payments"
# that HR adds directly (bonus, incentive, arrear, final settlement, etc.).
# ============================================================================

STAFF_PAYMENT_TYPES = [
    "bonus", "incentive", "overtime", "arrear",
    "loan_payment", "final_settlement", "other_payment", "recovery",
]


class StaffPaymentIn(BaseModel):
    staff_id: str
    payment_type: str  # one of STAFF_PAYMENT_TYPES
    payment_date: str  # YYYY-MM-DD
    amount: float
    description: Optional[str] = None
    payment_mode: Optional[str] = None
    payment_reference: Optional[str] = None
    remarks: Optional[str] = None
    attachment_url: Optional[str] = None
    status: str = "paid"  # draft | paid | cancelled


def _staff_pay_month(d: str) -> str:
    try:
        return d[:7]  # YYYY-MM
    except (TypeError, ValueError):
        return ""


@api.post("/staff-payments", status_code=201)
async def create_staff_payment(body: StaffPaymentIn, user=Depends(require_role("admin", "hr", "accountant"))):
    if body.payment_type not in STAFF_PAYMENT_TYPES:
        raise HTTPException(400, f"Invalid payment_type. Must be one of: {STAFF_PAYMENT_TYPES}")
    if body.amount <= 0:
        raise HTTPException(400, "Amount must be > 0")
    doc = {
        "id": str(uuid.uuid4()),
        "staff_id": body.staff_id,
        "payment_type": body.payment_type,
        "payment_date": body.payment_date,
        "payment_month": _staff_pay_month(body.payment_date),
        "amount": float(body.amount),
        "description": body.description,
        "payment_mode": body.payment_mode,
        "payment_reference": body.payment_reference,
        "remarks": body.remarks,
        "attachment_url": body.attachment_url,
        "status": body.status,
        "created_by": user.get("id"),
        "created_by_name": user.get("name") or user.get("email"),
        "created_at": _now_ist_iso(),
    }
    await db.staff_payments.insert_one(doc)
    doc.pop("_id", None)
    return doc


@api.get("/staff-payments")
async def list_staff_payments(staff_id: Optional[str] = None,
                                _=Depends(require_role("admin", "hr", "accountant"))):
    q = {}
    if staff_id:
        q["staff_id"] = staff_id
    rows = await db.staff_payments.find(q, {"_id": 0}).sort("payment_date", -1).to_list(2000)
    return rows


@api.delete("/staff-payments/{pid}", status_code=204)
async def delete_staff_payment(pid: str, user=Depends(require_role("admin", "hr"))):
    rec = await db.staff_payments.find_one({"id": pid})
    if not rec:
        raise HTTPException(404, "Not found")
    # Soft cancel — preserve audit trail.
    await db.staff_payments.update_one({"id": pid}, {"$set": {
        "status": "cancelled",
        "cancelled_by": user.get("id"),
        "cancelled_by_name": user.get("name") or user.get("email"),
        "cancelled_at": _now_ist_iso(),
    }})
    return None


@api.get("/staff/{sid}/financial-history")
async def staff_financial_history(sid: str,
                                    date_from: Optional[str] = None,
                                    date_to: Optional[str] = None,
                                    payment_type: Optional[str] = None,
                                    status: Optional[str] = None,
                                    _=Depends(require_role("admin", "hr", "accountant"))):
    """Return every financial transaction (salary + reimbursement + advance +
    manual staff_payments) for a staff, with monthly totals + per-type totals.
    Only Paid transactions are included in the Grand Total.
    """
    staff = await db.staff.find_one({"id": sid}, {"_id": 0})
    if not staff:
        raise HTTPException(404, "Staff not found")

    def _in_range(dt_str):
        if not dt_str:
            return True
        d = dt_str[:10]
        if date_from and d < date_from:
            return False
        if date_to and d > date_to:
            return False
        return True

    txns = []

    # 1) Salary (payroll)
    payroll_rows = await db.payroll.find({"staff_id": sid}, {"_id": 0}).sort("year", -1).to_list(500)
    for p in payroll_rows:
        # Prefer paid_at, else month/year → last day
        pd = (p.get("paid_at") or "")[:10] or f"{p.get('year','0000')}-{int(p.get('month') or 1):02d}-01"
        if not _in_range(pd):
            continue
        txns.append({
            "id": f"payroll:{p.get('id')}",
            "source_module": "payroll",
            "source_id": p.get("id"),
            "payment_type": "salary",
            "date": pd,
            "month": f"{p.get('year','0000')}-{int(p.get('month') or 1):02d}",
            "reference": f"PAY-{p.get('year')}-{p.get('month')}-{(p.get('id') or '')[:8]}",
            "description": f"Salary {p.get('month')}/{p.get('year')}",
            "gross": float(p.get("gross") or 0),
            "deduction": float(p.get("deductions") or 0),
            "net": float(p.get("net") or 0),
            "status": p.get("status", "draft"),
            "payment_mode": "bank",
            "payment_reference": (p.get("txn_id") or ""),
            "remarks": p.get("remarks"),
            "paid_at": p.get("paid_at"),
        })

    # 2) Reimbursements — link via user_id or staff_id
    reimb_q = {"$or": [{"staff_id": sid}]}
    if staff.get("user_id"):
        reimb_q["$or"].append({"user_id": staff["user_id"]})
        reimb_q["$or"].append({"created_by": staff["user_id"]})
    reimb_rows = await db.reimbursements.find(reimb_q, {"_id": 0}).sort("created_at", -1).to_list(500)
    for r in reimb_rows:
        pd = (r.get("paid_at") or r.get("created_at") or "")[:10]
        if not _in_range(pd):
            continue
        txns.append({
            "id": f"reimb:{r.get('id')}",
            "source_module": "reimbursement",
            "source_id": r.get("id"),
            "payment_type": "reimbursement",
            "date": pd,
            "month": pd[:7] if pd else "",
            "reference": r.get("claim_no") or (r.get("id") or "")[:12],
            "description": r.get("purpose") or r.get("category") or "Reimbursement",
            "gross": float(r.get("amount") or 0),
            "deduction": 0.0,
            "net": float(r.get("amount") or 0),
            "status": r.get("status", "draft"),
            "payment_mode": r.get("payment_mode") or "bank",
            "payment_reference": r.get("payment_reference") or r.get("txn_id") or "",
            "remarks": r.get("remarks"),
            "paid_at": r.get("paid_at"),
        })

    # 3) Advances
    adv_q = {"$or": [{"staff_id": sid}]}
    if staff.get("user_id"):
        adv_q["$or"].append({"created_by": staff["user_id"]})
    adv_rows = await db.advance_requests.find(adv_q, {"_id": 0}).sort("created_at", -1).to_list(200)
    for a in adv_rows:
        pd = (a.get("released_at") or a.get("created_at") or "")[:10]
        if not _in_range(pd):
            continue
        st = a.get("status", "draft")
        txns.append({
            "id": f"advance:{a.get('id')}",
            "source_module": "advance",
            "source_id": a.get("id"),
            "payment_type": "salary_advance",
            "date": pd,
            "month": pd[:7] if pd else "",
            "reference": a.get("advance_no") or (a.get("id") or "")[:12],
            "description": a.get("purpose") or "Salary Advance",
            "gross": float(a.get("amount") or 0),
            "deduction": 0.0,
            "net": float(a.get("amount") or 0),
            "status": "paid" if st in ("released", "adjusting", "settled") else st,
            "payment_mode": a.get("payment_mode") or "bank",
            "payment_reference": a.get("txn_id") or "",
            "remarks": a.get("remarks"),
            "paid_at": a.get("released_at"),
        })

    # 4) Manual staff_payments (bonus/incentive/overtime/arrear/other/final_settlement)
    sp_rows = await db.staff_payments.find({"staff_id": sid}, {"_id": 0}).sort("payment_date", -1).to_list(500)
    for sp in sp_rows:
        pd = sp.get("payment_date")
        if not _in_range(pd):
            continue
        txns.append({
            "id": f"custom:{sp.get('id')}",
            "source_module": "custom",
            "source_id": sp.get("id"),
            "payment_type": sp.get("payment_type"),
            "date": pd,
            "month": sp.get("payment_month"),
            "reference": sp.get("payment_reference") or (sp.get("id") or "")[:12],
            "description": sp.get("description") or sp.get("payment_type"),
            "gross": float(sp.get("amount") or 0),
            "deduction": 0.0,
            "net": float(sp.get("amount") or 0),
            "status": sp.get("status", "paid"),
            "payment_mode": sp.get("payment_mode") or "cash",
            "payment_reference": sp.get("payment_reference"),
            "remarks": sp.get("remarks"),
            "paid_at": sp.get("payment_date"),
        })

    # Apply filters
    if payment_type:
        txns = [t for t in txns if t.get("payment_type") == payment_type]
    if status:
        txns = [t for t in txns if t.get("status") == status]

    # Sort descending by date
    txns.sort(key=lambda t: (t.get("date") or ""), reverse=True)

    # Aggregations — only Paid counts toward totals
    is_paid = lambda t: (t.get("status") or "").lower() in ("paid", "released", "adjusting", "settled")
    per_type = {}
    monthly = {}
    grand = 0.0
    total_deduction = 0.0
    for t in txns:
        if not is_paid(t):
            continue
        pt = t["payment_type"]
        per_type.setdefault(pt, 0.0)
        per_type[pt] += t["net"]
        m = t.get("month") or ""
        monthly.setdefault(m, {"salary": 0, "reimbursement": 0, "salary_advance": 0,
                                "bonus": 0, "incentive": 0, "overtime": 0,
                                "arrear": 0, "loan_payment": 0, "final_settlement": 0,
                                "other_payment": 0, "recovery": 0, "total": 0})
        if pt in monthly[m]:
            monthly[m][pt] += t["net"]
        else:
            monthly[m]["other_payment"] += t["net"]
        monthly[m]["total"] += t["net"]
        grand += t["net"]
        total_deduction += t["deduction"]

    # Format monthly summary as array sorted descending by month key
    monthly_arr = [{"month": m, **totals} for m, totals in monthly.items()]
    monthly_arr.sort(key=lambda x: x["month"], reverse=True)

    return {
        "staff": {
            "id": staff.get("id"),
            "name": staff.get("name"),
            "employee_code": staff.get("employee_code"),
            "designation": staff.get("designation"),
            "department": staff.get("department"),
            "joining_date": staff.get("joining_date"),
            "exit_date": staff.get("exit_date"),
            "active": staff.get("active", True),
            "monthly_salary": staff.get("monthly_salary"),
        },
        "summary": {
            "total_salary": round(per_type.get("salary", 0), 2),
            "total_reimbursement": round(per_type.get("reimbursement", 0), 2),
            "total_advance": round(per_type.get("salary_advance", 0), 2),
            "total_bonus": round(per_type.get("bonus", 0), 2),
            "total_incentive": round(per_type.get("incentive", 0), 2),
            "total_overtime": round(per_type.get("overtime", 0), 2),
            "total_arrear": round(per_type.get("arrear", 0), 2),
            "total_other": round(per_type.get("other_payment", 0) + per_type.get("final_settlement", 0), 2),
            "total_deductions": round(total_deduction, 2),
            "grand_total": round(grand, 2),
            "transaction_count": len(txns),
            "paid_count": sum(1 for t in txns if is_paid(t)),
        },
        "monthly": monthly_arr,
        "transactions": txns,
    }


@app.on_event("startup")
async def _fin_history_startup():
    try:
        await db.staff_payments.create_index([("staff_id", 1), ("payment_date", -1)])
        await db.staff_payments.create_index([("payment_type", 1)])
    except Exception as _e:
        logging.exception("staff_payments index init failed: %s", _e)


# ============================================================================
# ========================  TWILIO NOTIFICATIONS  ============================
# ============================================================================
# SMS + WhatsApp powered by Twilio. Endpoints are strictly RBAC-guarded:
#   POST /api/notifications/send       — admin/hr → send one message
#   POST /api/notifications/send-bulk  — admin/hr → broadcast to a list
#   GET  /api/notifications/logs       — admin/hr → audit trail
#   GET  /api/notifications/config     — admin    → status of Twilio creds
#   POST /api/webhooks/twilio/status   — PUBLIC   → Twilio delivery callback
import twilio_service  # noqa: E402
from fastapi.concurrency import run_in_threadpool  # noqa: E402


class NotifSendIn(BaseModel):
    channel: str  # "sms" | "whatsapp"
    recipient: str  # any phone format — auto E.164
    body: str
    event_type: Optional[str] = "manual"
    event_id: Optional[str] = None
    content_sid: Optional[str] = None
    content_variables: Optional[dict] = None


class NotifBulkIn(BaseModel):
    channel: str
    recipients: List[str]
    body: str
    event_type: Optional[str] = "bulk"


@api.get("/notifications/config")
async def notif_config(_=Depends(require_role("admin"))):
    """Report which Twilio senders are wired up — no secrets leaked."""
    # Refresh runtime overrides so a DB update from another instance is visible.
    await twilio_service.load_runtime_overrides(db)
    return {
        "configured": twilio_service.is_configured(),
        "sms_from": twilio_service.get_sms_from(),
        "whatsapp_from": twilio_service.get_whatsapp_from(),
        "sms_from_env": twilio_service.SMS_FROM,
        "whatsapp_from_env": twilio_service.WHATSAPP_FROM,
        "sms_override_active": bool(twilio_service._RUNTIME_SMS_FROM),
        "whatsapp_override_active": bool(twilio_service._RUNTIME_WHATSAPP_FROM),
        "public_base": twilio_service.PUBLIC_BASE,
    }


class NotifConfigUpdate(BaseModel):
    sms_from: Optional[str] = None       # empty string → clears override
    whatsapp_from: Optional[str] = None  # e.g. "whatsapp:+919999999999"


@api.patch("/notifications/config")
async def notif_config_update(
    body: NotifConfigUpdate,
    _=Depends(require_role("admin")),
):
    """Swap the SMS / WhatsApp sender number without touching env vars.

    Use this after registering a production WhatsApp Business Sender on
    Twilio (Console → Messaging → Senders → WhatsApp) — put the new number as
    `whatsapp:+919999999999`. Clear the field (empty string) to revert to the
    env-var default (sandbox).
    """
    # Validate: WhatsApp must be prefixed, SMS must be E.164.
    if body.whatsapp_from and body.whatsapp_from.strip():
        wa = body.whatsapp_from.strip()
        if not wa.startswith("whatsapp:+"):
            raise HTTPException(400, "whatsapp_from must be in the form 'whatsapp:+<E164>'")
    if body.sms_from and body.sms_from.strip():
        sf = body.sms_from.strip()
        if not sf.startswith("+"):
            raise HTTPException(400, "sms_from must be in E.164 format, e.g. +14155551234")
    effective = await twilio_service.save_runtime_overrides(
        db, sms_from=body.sms_from, whatsapp_from=body.whatsapp_from,
    )
    return {"ok": True, **effective}


@api.post("/notifications/send")
async def notif_send(
    body: NotifSendIn,
    user=Depends(require_role("admin", "hr", "accountant")),
):
    if not (body.body or "").strip() and not body.content_sid:
        raise HTTPException(400, "body (or content_sid) is required")
    result = await twilio_service.send_message(
        db,
        channel=body.channel,
        to=body.recipient,
        body=body.body,
        event_type=body.event_type or "manual",
        event_id=body.event_id,
        sent_by_user_id=user["id"],
        sent_by_name=user.get("name") or user.get("email"),
        content_sid=body.content_sid,
        content_variables=body.content_variables,
    )
    if not result.get("ok"):
        # 200 with error payload keeps UI simple — the log row is already persisted.
        raise HTTPException(400, result)
    return result


@api.post("/notifications/send-bulk")
async def notif_send_bulk(
    payload: NotifBulkIn,
    user=Depends(require_role("admin", "hr")),
):
    if not payload.recipients:
        raise HTTPException(400, "recipients list is empty")
    results = []
    for r in payload.recipients:
        results.append(await twilio_service.send_message(
            db, channel=payload.channel, to=r, body=payload.body,
            event_type=payload.event_type or "bulk",
            sent_by_user_id=user["id"], sent_by_name=user.get("name") or user.get("email"),
        ))
    return {"total": len(results),
            "success": sum(1 for r in results if r.get("ok")),
            "failed": sum(1 for r in results if not r.get("ok")),
            "results": results}


@api.get("/notifications/logs")
async def notif_logs(
    limit: int = 100, channel: Optional[str] = None,
    event_type: Optional[str] = None,
    _=Depends(require_role("admin", "hr", "accountant")),
):
    q: dict = {}
    if channel: q["channel"] = channel
    if event_type: q["event_type"] = event_type
    rows = await db.notification_logs.find(q, {"_id": 0}) \
        .sort("created_at", -1).to_list(min(limit, 500))
    return rows


@api.post("/notifications/sync-status")
async def notif_sync_status(_=Depends(require_role("admin", "hr", "accountant"))):
    """Pull fresh status from Twilio for every message that is still in a
    non-terminal state (queued / sending / sent) in our log. Terminal statuses
    (delivered / failed / undelivered / read) are skipped. Called on-demand
    from the UI so users always see the real state, even when the async
    delivery webhook doesn't reach us (e.g. production env mis-configured to
    point at preview)."""
    if not twilio_service.is_configured():
        raise HTTPException(400, "Twilio not configured")
    client = twilio_service.get_client()
    stale = await db.notification_logs.find(
        {"status": {"$in": ["queued", "sending", "sent", "accepted"]},
         "message_sid": {"$exists": True, "$ne": None}},
        {"_id": 0, "id": 1, "message_sid": 1},
    ).sort("created_at", -1).to_list(200)
    updated = 0
    errors = 0
    for row in stale:
        try:
            # Bind `row` explicitly to avoid late-binding closure bugs when
            # this is later awaited concurrently in loops.
            msg = await run_in_threadpool(lambda r=row: client.messages(r["message_sid"]).fetch())
            await db.notification_logs.update_one(
                {"id": row["id"]},
                {"$set": {
                    "status": msg.status,
                    "error_code": msg.error_code,
                    "error_message": msg.error_message,
                    "status_updated_at": datetime.now(timezone.utc).isoformat(),
                }},
            )
            updated += 1
        except Exception:  # noqa: BLE001
            errors += 1
    return {"synced": updated, "errors": errors, "scanned": len(stale)}


@app.post("/api/webhooks/twilio/status")
async def twilio_status_webhook(request: Request):
    """Twilio delivery-status callback — validates signature then updates the log."""
    form = await request.form()
    params = {str(k): str(v) for k, v in form.multi_items()}
    signature = request.headers.get("X-Twilio-Signature", "")
    # Validate signature — Twilio recomputes HMAC over the URL + form params.
    # SEC-004: strict fail-closed. Any error → 403; never accept unverified callbacks.
    from twilio.request_validator import RequestValidator
    validator = RequestValidator(os.environ.get("TWILIO_AUTH_TOKEN") or "")
    try:
        valid = validator.validate(str(request.url), params, signature)
    except Exception as exc:  # noqa: BLE001
        logger.warning("Twilio signature validator raised: %s", exc)
        raise HTTPException(status_code=403, detail="Invalid Twilio signature")
    if not valid:
        raise HTTPException(status_code=403, detail="Invalid Twilio signature")
    sid = params.get("MessageSid")
    status = params.get("MessageStatus")
    err = params.get("ErrorCode")
    if sid:
        await db.notification_logs.update_one(
            {"message_sid": sid},
            {"$set": {
                "status": status,
                "error_code": err,
                "status_updated_at": datetime.now(timezone.utc).isoformat(),
            }},
        )
    return {"received": True}


app.include_router(api)


# ============================================================================
# ================  SUBSCRIPTION & MODULE ENTITLEMENT (Phase 66)  ============
# ============================================================================
# Razorpay Orders API + signature-verified activation + entitlement middleware.
# See /app/backend/subscription_service.py for the SDK-side logic; this block
# owns the FastAPI routes + guard dependency.
import subscription_service  # noqa: E402

# Dedicated sub-router — attached to `app` at the end of this block so its
# routes actually get mounted (the primary `api` router was already
# `include_router`-ed before this block was added).
sub_api = APIRouter(prefix="/api")


def require_module_entitlement(module: str):
    """FastAPI dependency: returns 403 unless the current company has an
    active entitlement for `module`. Admins always pass."""
    async def _guard(user=Depends(get_current_user)):
        if user.get("role") == "admin" or module in subscription_service.FREE_MODULES:
            return user
        ents = await subscription_service.compute_entitled_modules(db, user)
        if module not in ents:
            await subscription_service.audit(db, "access_denied", user, extra={"module": module})
            raise HTTPException(
                status_code=403,
                detail={
                    "error": "module_not_subscribed",
                    "module": module,
                    "message": "Not Authorised For This Service. Please go through the Subscription & Billing Menu and complete the payment to access this service.",
                    "redirect": "/subscription",
                },
            )
        return user
    return _guard


@app.on_event("startup")
async def _migrate_role_names():
    """Phase 70 — normalize legacy `super_admin` role BACK to `admin` (the
    internal canonical value). We keep the string `admin` inside the DB so that
    the 100+ existing `require_role("admin")` checks and 30+ frontend
    `role === "admin"` conditionals keep working unchanged. The UI presents the
    role as "Super Admin" everywhere. Company Admin is a new distinct role."""
    try:
        res = await db.users.update_many({"role": "super_admin"}, {"$set": {"role": "admin"}})
        if res.modified_count:
            logger.info("Normalized %d 'super_admin' → 'admin' user(s) (internal canonical)", res.modified_count)
    except Exception as exc:  # noqa: BLE001
        logger.warning("Role normalization migration failed: %s", exc)


@app.on_event("startup")
async def _seed_subscription_catalog():
    try:
        await subscription_service.seed_catalog(db)
        await db.entitlements.create_index([("company_id", 1), ("module", 1)])
        await db.orders.create_index(
            "razorpay_order_id",
            unique=True,
            partialFilterExpression={"razorpay_order_id": {"$type": "string"}},
        )
        await db.orders.create_index(
            "razorpay_payment_id",
            unique=True,
            partialFilterExpression={"razorpay_payment_id": {"$type": "string"}},
        )
        await db.razorpay_events.create_index("event_id", unique=True, sparse=True)
        await db.coupons.create_index("code", unique=True)
        await db.company_licenses.create_index([("company_id", 1), ("role", 1)], unique=True)
        # Backfill: assign company_code to any company missing it (COMP-10001…).
        await _backfill_company_codes()
        # Backfill: link users to a company (best-effort via assigned_center → center.company_id).
        await _backfill_user_company_ids()
        # Centers + multi-company-user migration (codes, access, memberships).
        await _migrate_multicompany()
    except Exception as exc:  # noqa: BLE001
        logger.warning("Subscription seed failed: %s", exc)


async def _next_company_code() -> str:
    """Return the next sequential COMP-NNNNN code using a counter document."""
    doc = await db.counters.find_one_and_update(
        {"_id": "company_code_seq"},
        {"$inc": {"seq": 1}},
        upsert=True,
        return_document=True if hasattr(db.counters, "find_one_and_update") else None,
    )
    seq = (doc or {}).get("seq") or 10001
    if seq < 10001:
        # First-time bootstrap: rewrite to 10001 so codes start clean.
        await db.counters.update_one({"_id": "company_code_seq"}, {"$set": {"seq": 10001}}, upsert=True)
        seq = 10001
    return f"COMP-{seq}"


async def _backfill_company_codes():
    missing = await db.companies.find({"$or": [{"company_code": {"$exists": False}}, {"company_code": None}, {"company_code": ""}]}, {"_id": 0, "id": 1}).to_list(2000)
    for row in missing:
        code = await _next_company_code()
        await db.companies.update_one({"id": row["id"]}, {"$set": {"company_code": code}})
    if missing:
        logger.info("Backfilled %d company_code(s)", len(missing))
    try:
        await db.companies.create_index("company_code", unique=True, partialFilterExpression={"company_code": {"$type": "string"}})
    except Exception:  # noqa: BLE001
        pass


async def _backfill_user_company_ids():
    """Best-effort: assign company_id to legacy users so licensing can lock them.

    Rule: pick company_id from user.assigned_center_ids[0] → center.company_id.
    Falls back to the FIRST company in the system so nothing crashes.
    """
    missing = await db.users.find(
        {"$or": [{"company_id": {"$exists": False}}, {"company_id": None}]},
        {"_id": 0, "id": 1, "assigned_center_ids": 1, "role": 1},
    ).to_list(5000)
    if not missing:
        return
    default_company = await db.companies.find_one({}, {"_id": 0, "id": 1})
    fallback_cid = (default_company or {}).get("id")
    fixed = 0
    for u in missing:
        cid = None
        for ccid in (u.get("assigned_center_ids") or []):
            c = await db.centers.find_one({"id": ccid}, {"_id": 0, "company_id": 1})
            if c and c.get("company_id"):
                cid = c["company_id"]
                break
        cid = cid or fallback_cid
        if cid:
            await db.users.update_one({"id": u["id"]}, {"$set": {"company_id": cid}})
            fixed += 1
    logger.info("Backfilled company_id on %d/%d user(s)", fixed, len(missing))


# ============================================================================
# Multi-Company + Centers: random code generators + one-time migration
# ============================================================================
# Company code  → 6-char short code (e.g. "UXU7SO").
# Center code   → "{company_code}-XXXX" (e.g. "UXU7SO-A7K2").
# Ambiguous chars (0/O/1/I) are excluded so codes are easy to read + dictate.
_CODE_ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"


def _rand_code(n: int) -> str:
    return "".join(secrets.choice(_CODE_ALPHABET) for _ in range(n))


async def _new_company_code() -> str:
    """Unique 6-char company code (retry on the rare collision)."""
    for _ in range(50):
        code = _rand_code(6)
        if not await db.companies.find_one({"company_code": code}, {"_id": 1}):
            return code
    return _rand_code(8)


async def _new_center_code(company_code: Optional[str]) -> str:
    """Unique center code of the form `{company_code}-XXXX`."""
    prefix = (company_code or "CTR").strip().upper() or "CTR"
    for _ in range(50):
        code = f"{prefix}-{_rand_code(4)}"
        if not await db.centers.find_one({"center_code": code}, {"_id": 1}):
            return code
    return f"{prefix}-{_rand_code(6)}"


async def _migrate_multicompany():
    """Idempotent migration for the Centers + multi-company-user feature.

    1. Reformat legacy `COMP-NNNNN` company codes → short random codes (UXU7SO).
       Once random, they no longer match `^COMP-` so this is a one-shot no-op on
       subsequent boots. Also mirrors the new code onto users' snapshot field.
    2. Assign `center_code` + access defaults to every center missing them.
    3. Backfill `user_companies` (baseline single-company membership) from
       users.company_id — so existing users keep working; extra companies are
       added later via the UI.
    4. Backfill `user_centers` from users.assigned_center_ids.
    """
    now_iso = datetime.now(timezone.utc).isoformat()
    # ---- Indexes -----------------------------------------------------------
    try:
        await db.user_companies.create_index([("user_id", 1), ("company_id", 1)], unique=True)
        await db.user_companies.create_index([("company_id", 1)])
        await db.user_centers.create_index([("user_id", 1), ("center_id", 1)], unique=True)
        await db.user_centers.create_index([("user_id", 1), ("company_id", 1)])
        await db.centers.create_index("center_code", unique=True,
                                      partialFilterExpression={"center_code": {"$type": "string"}})
    except Exception:  # noqa: BLE001
        pass

    # ---- 1. Company code reformat -----------------------------------------
    try:
        comps = await db.companies.find(
            {"$or": [
                {"company_code": {"$regex": "^COMP-"}},
                {"company_code": {"$in": [None, ""]}},
                {"company_code": {"$exists": False}},
            ]},
            {"_id": 0, "id": 1},
        ).to_list(5000)
        for c in comps:
            code = await _new_company_code()
            await db.companies.update_one({"id": c["id"]}, {"$set": {"company_code": code}})
            await db.users.update_many({"company_id": c["id"]}, {"$set": {"company_code": code}})
        if comps:
            logger.info("Reformatted %d company code(s) to short format", len(comps))
    except Exception as exc:  # noqa: BLE001
        logger.warning("Company code reformat skipped: %s", exc)

    # ---- 2. Center codes + access defaults --------------------------------
    try:
        centers = await db.centers.find(
            {"$or": [
                {"center_code": {"$exists": False}},
                {"center_code": None},
                {"center_code": ""},
            ]},
            {"_id": 0, "id": 1, "company_id": 1},
        ).to_list(10000)
        for ct in centers:
            cc = None
            if ct.get("company_id"):
                comp = await db.companies.find_one({"id": ct["company_id"]}, {"_id": 0, "company_code": 1})
                cc = (comp or {}).get("company_code")
            code = await _new_center_code(cc)
            await db.centers.update_one({"id": ct["id"]}, {"$set": {"center_code": code}})
        if centers:
            logger.info("Assigned center_code to %d center(s)", len(centers))
        # Existing centers default to ENABLED so current users are never blocked.
        await db.centers.update_many({"access_status": {"$exists": False}},
                                     {"$set": {"access_status": "enabled", "access_type": "free"}})
        await db.centers.update_many({"center_status": {"$exists": False}},
                                     {"$set": {"center_status": "active"}})
    except Exception as exc:  # noqa: BLE001
        logger.warning("Center code/access backfill skipped: %s", exc)

    # ---- 3. Baseline user_companies ---------------------------------------
    try:
        users = await db.users.find(
            {"company_id": {"$nin": [None, ""]}},
            {"_id": 0, "id": 1, "company_id": 1, "role": 1},
        ).to_list(50000)
        for u in users:
            await db.user_companies.update_one(
                {"user_id": u["id"], "company_id": u["company_id"]},
                {"$setOnInsert": {
                    "id": str(uuid.uuid4()),
                    "user_id": u["id"],
                    "company_id": u["company_id"],
                    "role": u.get("role") or "viewer",
                    "status": "active",
                    "created_at": now_iso,
                    "source": "backfill",
                }},
                upsert=True,
            )
    except Exception as exc:  # noqa: BLE001
        logger.warning("user_companies backfill skipped: %s", exc)

    # ---- 4. Baseline user_centers -----------------------------------------
    try:
        users = await db.users.find(
            {"assigned_center_ids": {"$exists": True, "$ne": []}},
            {"_id": 0, "id": 1, "company_id": 1, "assigned_center_ids": 1},
        ).to_list(50000)
        for u in users:
            for cid in (u.get("assigned_center_ids") or []):
                await db.user_centers.update_one(
                    {"user_id": u["id"], "center_id": cid},
                    {"$setOnInsert": {
                        "id": str(uuid.uuid4()),
                        "user_id": u["id"],
                        "company_id": u.get("company_id"),
                        "center_id": cid,
                        "status": "active",
                        "created_at": now_iso,
                        "source": "backfill",
                    }},
                    upsert=True,
                )
    except Exception as exc:  # noqa: BLE001
        logger.warning("user_centers backfill skipped: %s", exc)


@app.on_event("startup")
async def _init_object_storage():
    """Fail-fast init for Emergent Object Storage.

    Any exception is logged but does NOT crash the app — file uploads will
    surface a clear 500 at request time via `_init_storage()` if the
    integration proxy is unreachable. `GET /api/files/health` returns the
    last state for ops visibility.
    """
    try:
        _init_storage()
        logger.info("Object storage initialised (%s, prefix=%s)", STORAGE_BASE, APP_STORAGE_PREFIX)
    except Exception as exc:  # noqa: BLE001
        logger.warning("Object storage init failed: %s (will retry on first upload)", exc)


@sub_api.get("/files/health")
async def files_health(_=Depends(require_role("admin"))):
    """Object storage health probe — admin only."""
    return {
        "storage_base": STORAGE_BASE,
        "prefix": APP_STORAGE_PREFIX,
        "initialised": bool(_storage_key),
        "last_error": _storage_last_error,
    }


@sub_api.get("/subscription/pricing")
async def sub_pricing(_=Depends(get_current_user)):
    """Full pricing catalog — plans (staff tiers) + features + addons + GST rate."""
    return await subscription_service.get_pricing_catalog(db)


@sub_api.get("/subscription/me")
async def sub_me(user=Depends(get_current_user)):
    """Effective entitlements + current active subscription bundle for this user."""
    entitled = await subscription_service.compute_entitled_modules(db, user)
    company_id = subscription_service._company_id_for(user)
    # Latest captured order → the "current subscription".
    latest = await db.orders.find_one(
        {"company_id": company_id, "status": "captured"},
        {"_id": 0}, sort=[("captured_at", -1)],
    )
    ents = await db.entitlements.find(
        {"company_id": company_id, "status": "active"},
        {"_id": 0},
    ).to_list(50)
    return {
        "company_id": company_id,
        "entitled_modules": list(entitled.keys()),
        "active_entitlements": ents,
        "current_bundle": latest,
        "is_admin": user.get("role") == "admin",
        "trial": await _trial_status(user),
    }


@sub_api.post("/subscription/start-trial")
async def sub_start_trial(user=Depends(get_current_user)):
    """Start a one-time 10-day free trial that unlocks ALL modules for the
    user's company. Any authenticated member of a company can start it."""
    company_id = subscription_service._company_id_for(user)
    if not company_id:
        raise HTTPException(400, "No company is associated with your account")
    res = await subscription_service.start_trial(db, company_id, user)
    if res["already_used"]:
        raise HTTPException(409, "A trial has already been used for this company")
    await subscription_service.audit(db, "trial_started", user, target={"company_id": company_id})
    return {"ok": True, "trial": res["trial"], "status": await _trial_status(user)}


@sub_api.post("/subscription/trials/dispatch-reminders")
async def sub_dispatch_trial_reminders(force: bool = False, current=Depends(require_role("admin"))):
    """Manually trigger trial-expiry reminders (Super Admin). `force=true`
    bypasses the once-per-day idempotency guard for testing."""
    return await _trial_dispatch_reminders(force=force)


